INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000002', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Lanjut Hiragana (S–N), Salam & Menunjuk Benda', 'Kenali huruf baris S, T, dan N, ucapkan salam sehari-hari, serta tunjuk benda di dekatmu.', 'curriculum', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000003', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Lanjut Hiragana (H–Y) & Memperkenalkan Diri', 'Pelajari huruf baris H, M, dan Y agar bisa menyebut nama sendiri dan memperkenalkan diri dengan sopan.', 'curriculum', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000004', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Tuntas 46 Hiragana, Negara & Kewarganegaraan', 'Tuntaskan seluruh 46 huruf dasar Hiragana sambil belajar menyebut asal negara dan menunjuk benda jauh.', 'curriculum', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000005', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Bunyi Variasi Hiragana, Kalimat Tanya & Ujian Tahap 1', 'Kuasai tanda bunyi ganda dan gabungan Hiragana, buat kalimat tanya dan sangkal, lalu taklukkan Ujian Tahap 1.', 'curriculum', 5, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000001-0000-0000-0000-000000000001', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Benda Sekitar, Menunjuk Barang & Kepemilikan', 'Kenali 5 Kanji benda yang paling sering ditemui serta cara menyebut barang milik sendiri atau orang lain.', 'curriculum', 6, '2026-11-16T14:02:48.07742+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000007', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Keluarga, Profesi & Panggilan Sopan', 'Pelajari cara mengenalkan anggota keluarga dan membedakan panggilan untuk keluarga sendiri maupun orang lain.', 'curriculum', 7, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000008', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Katakana Dasar, Nama Negara & Angka 1–100', 'Mulai membaca huruf Katakana untuk kata serapan asing sekaligus menyebut nama negara, usia, dan angka 1–100.', 'curriculum', 8, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000009', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Angka Besar, Harga Belanja & Cara Hitung Benda', 'Pahami angka ratusan hingga puluhan ribu agar bisa menanyakan harga barang dan menghitung jumlah benda.', 'curriculum', 9, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000010', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Jam, Hari, Jadwal Harian & Ujian Tahap 2', 'Sebutkan jam, menit, nama hari dalam seminggu, dan rentang jadwal kerja lalu ikuti Ujian Tahap 2.', 'curriculum', 10, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000001-0000-0000-0000-000000000003', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Lanjut Katakana, Menu Kafe & Memesan Makanan', 'Baca daftar menu kafe berbahasa Katakana dan gunakan penanda objek agar lancar memesan makan serta minum.', 'curriculum', 11, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000012', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Rutinitas Harian & Aktivitas Sehari-hari', 'Ceritakan kegiatan harianmu dari bangun tidur hingga malam, baik yang dilakukan maupun yang tidak dilakukan.', 'curriculum', 12, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000013', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Tempat Aktivitas, Alat & Bahasa Sehari-hari', 'Jelaskan di mana kamu beraktivitas, alat apa yang digunakan, serta dalam bahasa apa kamu berkomunikasi.', 'curriculum', 13, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000014', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Mengajak Teman, Menawarkan Bantuan & Kata Sambung', 'Ajak teman atau rekan kerja melakukan sesuatu dengan sopan, tawarkan bantuan, dan sambung kalimatmu agar mengalir.', 'curriculum', 14, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000001-0000-0000-0000-000000000004', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Transportasi, Arah Pergi, Rute & Ujian Tahap 3', 'Ceritakan cara berangkat naik transportasi, tujuan pergi, bersama siapa, dan ikuti Ujian Tahap 3.', 'curriculum', 15, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000001-0000-0000-0000-000000000005', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Katakana Fasilitas Kota & Menyatakan Keberadaan', 'Baca nama fasilitas kota dalam Katakana dan nyatakan ada atau tidak adanya benda serta makhluk hidup.', 'curriculum', 16, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000017', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Letak Benda di Ruangan & Menyebutkan Daftar', 'Jelaskan posisi benda secara detail seperti di atas, bawah, atau sebelah, dan sebutkan beberapa barang sekaligus.', 'curriculum', 17, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000001-0000-0000-0000-000000000006', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Tuntas 46 Katakana & Menggambarkan Benda (Sifat-I)', 'Selesaikan seluruh 46 huruf Katakana tanpa tertukar huruf mirip sambil belajar menggambarkan sifat benda.', 'curriculum', 18, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000019', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Belanja Baju, Warna & Cara Memakai Pakaian', 'Sebutkan warna serta jenis pakaian, pahami kata kerja memakai baju atau topi yang berbeda, dan tanyakan pilihan barang.', 'curriculum', 19, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000020', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Ngobrolin Cuaca, Kesukaan, Perbandingan & Ujian Tahap 4', 'Ceritakan cuaca dan 4 musim, ungkapkan hal favorit serta perbandingan dua hal, lalu hadapi Ujian Tahap 4.', 'curriculum', 20, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000001-0000-0000-0000-000000000007', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Minta Tolong dengan Sopan & Menanyakan Arah Jalan', 'Pelajari cara mengubah kata kerja menjadi bentuk sambung untuk meminta tolong dan memberi petunjuk jalan.', 'curriculum', 21, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000022', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Urutan Aktivitas & Kegiatan yang Sedang Berlangsung', 'Ceritakan dua kegiatan berurutan dan jelaskan apa yang sedang kamu lakukan atau kondisi yang sedang berlangsung.', 'curriculum', 22, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000023', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Meminta Izin, Rambu Larangan & Aturan Umum', 'Tanyakan apakah sesuatu diperbolehkan, pahami larangan di tempat umum, dan minta seseorang agar tidak melakukan hal tertentu.', 'curriculum', 23, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000024', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Bagian Tubuh, Berobat di Klinik & Kewajiban', 'Sebutkan keluhan sakit dan bagian tubuh saat berobat di klinik serta sampaikan hal yang wajib atau boleh tidak dilakukan.', 'curriculum', 24, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000025', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Menyambung Sifat, Perubahan Keadaan & Ujian Tahap 5', 'Gabungkan dua kata sifat dalam satu kalimat, ceritakan hal yang mulai berubah, lalu tuntaskan Ujian Tahap 5.', 'curriculum', 25, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000001-0000-0000-0000-000000000008', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Cerita Masa Lampau, Akhir Pekan & Pengalaman', 'Ceritakan kegiatan yang sudah kamu lakukan, contoh aktivitas akhir pekan, dan pengalaman berkesan selama hidup.', 'curriculum', 26, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000027', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Bentuk Kamus, Hobi, Bakat & Urutan Waktu', 'Gunakan bentuk dasar kata kerja untuk berbicara tentang hobi, hal yang kamu bisa lakukan, serta momen ''sebelum'' dan ''saat''.', 'curriculum', 27, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
