INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('a0000026-0000-0000-0000-000000000029', '13e386c2-6c43-4b71-afde-61b263c5fe8b', 'Mengungkapkan Keinginan, Tujuan & Saling Membantu', 'Sampaikan keinginanmu serta tujuan pergi, sebutkan alasan, dan pahami budaya saling memberi dalam bahasa Jepang.', 'curriculum', 29, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
