INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b5727a28-8d3f-44aa-aff1-75c111d4e66d', 'b0000001-0000-0000-0000-000000000001', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'writing', 'sentence_builder', 'Susun balok kata berikut menjadi kalimat: "Saya adalah seorang insinyur."', '{"romaji":"Watashi wa enjinia desu.","tokens":["わたし","は","エンジニア","です","がくせい","ではありません"],"target_translation":"Saya adalah seorang insinyur."}'::jsonb, '["わたし","は","エンジニア","です"]'::jsonb, '[["私","は","エンジニア","です"],["わたし","は","えんじにあ","です"]]'::jsonb, '{"がくせい":"Kamu memilih kata yang berarti mahasiswa/pelajar, bukan insinyur.","ではありません":"Bentuk ini merupakan akhiran negatif, sedangkan kalimat yang diminta adalah deklaratif positif."}'::jsonb, 'Dalam bahasa Jepang, partikel は (wa) diletakkan setelah topik/subjek (わたし), diikuti predikat (エンジニア), dan diakhiri kopula formal です (desu).', 1, '2026-11-16T14:02:48.07742+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('57712de7-3e70-4385-87ac-0bb580745cc1', 'b0000001-0000-0000-0000-000000000001', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'listening', 'listening_choice', 'Dengarkan audio penutur asli berikut dan pilih arti kalimat yang tepat.', '{"options":[{"id":"opt_1","text":"Saya adalah orang Jepang."},{"id":"opt_2","text":"Saya sedang pergi ke Jepang."},{"id":"opt_3","text":"Apakah kamu orang Jepang?"},{"id":"opt_4","text":"Saya bukan orang Jepang."}],"furigana":[{"kana":"わたし","kanji":"私"},{"kana":"にほんじん","kanji":"日本人"}],"audio_text":"わたしはにほんじんです"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Perhatikan bahwa kalimat tidak menggunakan kata kerja perpindahan (ikimasu), melainkan kopula です.","opt_3":"Kalimat ini tidak diakhiri partikel tanya か (ka).","opt_4":"Bentuk kalimat ini adalah positif, bukan bentuk negatif (dewa arimasen)."}'::jsonb, 'Frasa 「わたしはにほんじんです」(Watashi wa nihonjin desu) secara harfiah berarti "Saya adalah orang Jepang".', 2, '2026-11-16T14:02:48.07742+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3814cecc-9973-4c34-9067-a0ed4d2de24f', 'b0000001-0000-0000-0000-000000000001', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat perkenalan profesi ("Perkenalkan, saya adalah insinyur.") berikut dengan artikulasi yang jelas.', '{"romaji":"Hajimemashite, watashi wa enjinia desu.","furigana":[{"kana":"はじめまして","kanji":"初めまして"},{"kana":"わたし","kanji":"私"}],"translation":"Perkenalkan, saya adalah insinyur.","display_text":"はじめまして、わたしはエンジニアです","phonetic_breakdown":["ha-ji-me-ma-shi-te","wa-ta-shi","wa","en-ji-ni-a","de-su"]}'::jsonb, '{"expected_transcript":"はじめましてわたしはエンジニアです"}'::jsonb, '[["初めまして、私はエンジニアです"],["はじめまして、エンジニアです"]]'::jsonb, NULL, 'Ucapkan salam pembuka 「はじめまして」 dengan nada ramah, diikuti nama profesi dan penutup kopula formal 「です」.', 3, '2026-11-16T14:02:48.119454+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6e1df185-bd48-4b05-8464-4dcbc4862162', 'b0000001-0000-0000-0000-000000000001', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'reading', 'fill_blank', 'Lengkapi kalimat pertukaran kartu nama di tempat kerja: これは わたし ___ めいし です。', '{"options":["の","は","を","に"],"furigana":[{"kana":"めいし","kanji":"名刺"}],"translation":"Ini adalah kartu nama saya.","sentence_template":"これは わたし [blank] めいし です。"}'::jsonb, '{"selected":"の"}'::jsonb, NULL, '{"に":"Partikel に menunjukkan waktu atau tempat tujuan.","は":"Partikel は digunakan untuk topik utama kalimat, bukan kepemilikan benda.","を":"Partikel を menandai objek penderita kata kerja transitif."}'::jsonb, 'Partikel の (no) berfungsi menghubungkan dua kata benda untuk menyatakan kepemilikan: わたし (saya) + の + めいし (kartu nama) = "kartu nama saya".', 4, '2026-11-16T14:02:48.119454+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000010', 'b0000001-0000-0000-0000-000000000001', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'reading', 'fill_blank', 'Lengkapi partikel topik pada perkenalan nama: わたし [blank] アガム です。', '{"options":["は","を","に","で"],"translation":"Saya adalah Agam.","sentence_template":"わたし [blank] アガム です。"}'::jsonb, '{"selected":"は"}'::jsonb, NULL, '{"を":"を dipakai untuk objek kata kerja."}'::jsonb, 'Partikel は (wa) menandai subjek/topik kalimat nominal.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-030005000006', 'b0000001-0000-0000-0000-000000000001', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat identitas ''Saya adalah Budi'':', '{"options":["です","ます","でした","ました"],"translation":"Saya Budi","sentence_template":"わたし は ブディ [blank]"}'::jsonb, '{"selected":"です"}'::jsonb, NULL, NULL, 'Pola nominal diakhiri です (desu).', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-030005000007', 'b0000001-0000-0000-0000-000000000001', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Ini buku saya":', '{"romaji":"Kore wa watashi no hon desu","tokens":["これ","は","わたし","の","ほん","です"],"target_translation":"Ini buku saya"}'::jsonb, '["これ","は","わたし","の","ほん","です"]'::jsonb, NULL, NULL, 'Kore wa watashi no hon desu.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-030005000008', 'b0000001-0000-0000-0000-000000000001', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat ''わたし は がくせい です'' (Saya murid):', '{"romaji":"watashi wa gakusei desu","audio_text":"わたし は がくせい です","display_text":"わたし は がくせい です"}'::jsonb, '{"expected_transcript":"わたし は がくせい です"}'::jsonb, NULL, NULL, 'Lafalkan dengan intonasi jelas.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d4428dea-9392-4d19-897f-d8962307c9af', 'b0000001-0000-0000-0000-000000000002', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'reading', 'fill_blank', 'Lengkapi bagian kosong dengan partikel yang tepat: 田中さん ___ 先生です。', '{"options":["は","が","を","に"],"translation":"Tanaka-san adalah seorang guru.","sentence_template":"田中さん [blank] 先生です。"}'::jsonb, '{"selected":"は"}'::jsonb, NULL, '{"が":"Partikel が digunakan untuk penekanan subjek gramatikal, namun untuk topik perkenalan umum yang netral digunakan は.","に":"Partikel に digunakan untuk tujuan tempat atau waktu spesifik.","を":"Partikel を digunakan sebagai penanda objek langsung penderita kata kerja transitif."}'::jsonb, 'Dalam struktur kalimat sederhana "A adalah B", partikel topik は (wa) digunakan setelah subjek 田中さん.', 1, '2026-11-16T14:02:48.07742+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e167bd35-12f9-43f8-9a9a-9fc29262599c', 'b0000001-0000-0000-0000-000000000002', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'writing', 'sentence_builder', 'Susun kalimat: "Tanaka-san adalah orang Jepang."', '{"romaji":"Tanaka-san wa nihonjin desu.","tokens":["たなかさん","は","にほんじん","です","アメリカじん"],"target_translation":"Tanaka-san adalah orang Jepang."}'::jsonb, '["たなかさん","は","にほんじん","です"]'::jsonb, '[["田中さん","は","日本人","です"]]'::jsonb, '{"アメリカじん":"Amerika-jin berarti orang Amerika, bukan orang Jepang (nihonjin)."}'::jsonb, 'Akhiran じん (jin) ditambahkan setelah nama negara untuk menyatakan warga negara: にほん (Jepang) + じん = orang Jepang.', 2, '2026-11-16T14:02:48.119454+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4038d5b8-f735-46c3-bfa3-a041492fb309', 'b0000001-0000-0000-0000-000000000002', NULL, 'listening', 'listening_choice', 'Dengarkan dialog singkat berikut dan tentukan profesi pembicara.', '{"options":[{"id":"opt_1","text":"Insinyur (Bukan dokter)"},{"id":"opt_2","text":"Dokter (Bukan insinyur)"},{"id":"opt_3","text":"Guru"},{"id":"opt_4","text":"Mahasiswa"}],"furigana":[{"kana":"いしゃ","kanji":"医者"}],"audio_text":"わたしはいしゃではありません。エンジニアです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Perhatikan bentuk negatif ではありません setelah kata isha (dokter), yang berarti bukan dokter."}'::jsonb, 'Pembicara menyatakan 「いしゃではありません」(bukan dokter) lalu menegaskan identitasnya 「エンジニアです」(adalah insinyur).', 3, '2026-11-16T14:02:48.119454+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1cdcf9bc-2ff7-45ef-b10a-83df336224fa', 'b0000001-0000-0000-0000-000000000002', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat persetujuan: "Saya juga orang Indonesia."', '{"romaji":"Watashi mo indonesiajin desu.","display_text":"わたしもインドネシアじんです","phonetic_breakdown":["wa-ta-shi","mo","in-do-ne-shi-a-jin","de-su"]}'::jsonb, '{"expected_transcript":"わたしもインドネシアじんです"}'::jsonb, '[["私もインドネシア人です"],["わたしもインドネシア人です"]]'::jsonb, NULL, 'Partikel も (mo) menggantikan partikel は ketika ingin menyatakan kesamaan arti: "juga / pun".', 4, '2026-11-16T14:02:48.119454+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000011', 'b0000001-0000-0000-0000-000000000002', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'writing', 'sentence_builder', 'Susun kalimat negatif sopan: "Saya bukan mahasiswa."', '{"romaji":"Watashi wa gakusei dewa arimasen.","tokens":["わたし","は","がくせい","ではありません","です"],"target_translation":"Saya bukan mahasiswa."}'::jsonb, '["わたし","は","がくせい","ではありません"]'::jsonb, NULL, NULL, 'Bentuk negatif nominal memakai akhiran ～ではありません.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-050005000006', 'b0000001-0000-0000-0000-000000000002', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat sanggahan ''Bukan, itu bukan tas'':', '{"options":["ありません","あります","です","でした"],"translation":"Dewa arimasen","sentence_template":"いいえ、かばん では [blank]"}'::jsonb, '{"selected":"ありません"}'::jsonb, NULL, NULL, 'では ありません menyatakan negasi formal.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-050005000007', 'b0000001-0000-0000-0000-000000000002', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Ini pensil":', '{"romaji":"Kore wa enpitsu desu","tokens":["これ","は","えんぴつ","です"],"target_translation":"Ini pensil"}'::jsonb, '["これ","は","えんぴつ","です"]'::jsonb, NULL, NULL, 'Kore wa enpitsu desu.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-050005000008', 'b0000001-0000-0000-0000-000000000002', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat penyangkalan ''わたし は せんせい では ありません'':', '{"romaji":"watashi wa sensei dewa arimasen","audio_text":"わたし は せんせい では ありません","display_text":"わたし は せんせい では ありません"}'::jsonb, '{"expected_transcript":"わたし は せんせい では ありません"}'::jsonb, NULL, NULL, 'Lafalkan dengan intonasi lancar.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a80857ce-4733-4d4c-b23a-31fb4310bda8', 'b0000001-0000-0000-0000-000000000003', NULL, 'reading', 'fill_blank', '[SEKSI KOSAKATA] Pilih cara baca Hiragana yang benar untuk kanji berikut: 日本人', '{"options":["にほんじん","にぽんじん","にほんびと","にほんひと"],"target_word":"日本人"}'::jsonb, '{"selected":"にほんじん"}'::jsonb, NULL, '{"にほんびと":"Kanji 人 jika dilekatkan pada nama negara dibaca jin, bukan hito/bito."}'::jsonb, 'Kombinasi kanji 日本 (Nihon = Jepang) dan 人 (jin = orang) dibaca secara resmi sebagai にほんじん (nihonjin).', 1, '2026-11-16T14:02:48.119454+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0f72bd27-182a-48e0-a602-f837911f35f5', 'b0000001-0000-0000-0000-000000000003', '84296601-2071-4b58-a093-e916c1f4abac', 'writing', 'sentence_builder', '[SEKSI TATA BAHASA] Susun kalimat penolakan sopan: "Bukan, dia bukan mahasiswa."', '{"romaji":"Iie, kare wa gakusei dewa arimasen.","tokens":["いいえ","かれ","は","がくせい","ではありません","です"],"target_translation":"Bukan, dia bukan mahasiswa."}'::jsonb, '["いいえ","かれ","は","がくせい","ではありません"]'::jsonb, '[["いいえ","彼","は","学生","ではありません"]]'::jsonb, '{"です":"Bentuk です adalah afirmatif positif, bertentangan dengan kata sanggahan いいえ (bukan)."}'::jsonb, 'Jawaban negatif formal diawali kata いいえ (iie) dan diakhiri bentuk negasi ではありません (dewa arimasen).', 2, '2026-11-16T14:02:48.119454+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e495a128-37c9-4b87-8426-5995e948cdeb', 'b0000001-0000-0000-0000-000000000003', NULL, 'reading', 'fill_blank', '[SEKSI BACAAN] Baca kartu nama berikut:\n【東京テクノロジー株式会社 / システムエンジニア / 佐藤 健】\nApa profesi Sato Ken?', '{"options":["Sistem Insinyur (SE)","Dokter Umum","Guru Bahasa","Akuntan"],"passage":"佐藤 健 (Sato Ken) adalah karyawan di Tokyo Technology."}'::jsonb, '{"selected":"Sistem Insinyur (SE)"}'::jsonb, NULL, '{"Guru Bahasa":"Pada kartu tertulis システムエンジニア (System Engineer)."}'::jsonb, 'Kata serapan katakana システムエンジニア (shisutemu enjinia) berarti System Engineer.', 3, '2026-11-16T14:02:48.119454+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ca07b031-e23f-4cea-bfd4-799482962bc4', 'b0000001-0000-0000-0000-000000000003', NULL, 'listening', 'listening_choice', '[SEKSI MENDENGARKAN] Dengarkan percakapan sambutan kantor dan pilih intisari yang benar.', '{"options":[{"id":"opt_1","text":"Sato dan Smith saling berkenalan di tempat kerja"},{"id":"opt_2","text":"Sato berpamitan pulang kepada Smith"},{"id":"opt_3","text":"Smith menolak bekerja sama dengan Sato"},{"id":"opt_4","text":"Sato meminta maaf karena datang terlambat"}],"audio_text":"A: はじめまして、サトウです。どうぞよろしく。\nB: スミスです。こちらこそよろしくおねがいします。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_4":"Tidak ada ungkapan permohonan maaf (sumimasen) dalam audio."}'::jsonb, 'Frasa 「こちらこそよろしくおねがいします」(Kochira koso yoroshiku onegaishimasu) adalah balasan standar ketika seseorang diajak berkenalan pertama kali.', 4, '2026-11-16T14:02:48.119454+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9b5de5e7-98b6-4229-972a-8eed776489ea', 'b0000001-0000-0000-0000-000000000003', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'writing', 'sentence_builder', '[SEKSI SINTESIS] Susun kalimat utuh: "Saya adalah orang Indonesia, bukan orang Jepang."', '{"romaji":"Watashi wa indonesiajin desu. Nihonjin dewa arimasen.","tokens":["わたし","は","インドネシアじん","です","にほんじん","ではありません"],"target_translation":"Saya adalah orang Indonesia, bukan orang Jepang."}'::jsonb, '["わたし","は","インドネシアじん","です","にほんじん","ではありません"]'::jsonb, '[["私","は","インドネシア人","です","日本人","ではありません"]]'::jsonb, NULL, 'Struktur kalimat memadukan deklarasi afirmatif identitas diri (... desu) dengan negasi pembeda (... dewa arimasen).', 5, '2026-11-16T14:02:48.119454+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000015-0000-0000-0000-000000000005', 'b0000001-0000-0000-0000-000000000003', NULL, 'writing', 'sentence_builder', 'Susun kalimat permintaan sopan berikut: "Tolong lihat dokumen ini."', '{"romaji":"Kono shiryou o mite kudasai.","tokens":["この","しりょう","を","みて","ください","みません"],"target_translation":"Tolong lihat dokumen ini."}'::jsonb, '["この","しりょう","を","みて","ください"]'::jsonb, '[["この","資料","を","見て","ください"]]'::jsonb, '{"みません":"Akhiran ～ません berarti tidak melihat, bukan permintaan sopan ～てください."}'::jsonb, 'Gunakan bentuk-TE 「みて」 ditambah 「ください」 untuk meminta seseorang melihat sesuatu secara sopan.', 6, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000015-0000-0000-0000-000000000006', 'b0000001-0000-0000-0000-000000000003', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman lokasi berikut. Di mana letak toilet?', '{"options":[{"id":"opt_1","text":"Di sebelah lift"},{"id":"opt_2","text":"Di depan pintu masuk"},{"id":"opt_3","text":"Di lantai tiga"},{"id":"opt_4","text":"Di luar gedung"}],"audio_text":"トイレは エレベーターの となりに あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Di depan adalah まえ (mae), bukan となり (tonari = sebelah)."}'::jsonb, 'Kata 「エレベーターの となり」 berarti di sebelah lift.', 7, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000015-0000-0000-0000-000000000007', 'b0000001-0000-0000-0000-000000000003', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan ucapkan kalimat berikut: "Saya ingin bekerja di Jepang."', '{"romaji":"Nihon de hatarakitai desu.","display_text":"にほんではたらきたいです","phonetic_breakdown":["ni-hon","de","ha-ta-ra-ki-tai","de-su"]}'::jsonb, '{"expected_transcript":"にほんではたらきたいです"}'::jsonb, '[["日本で働きたいです"]]'::jsonb, NULL, 'Pola ～たいです menyatakan keinginan melakukan tindakan di lokasi yang ditandai partikel で.', 8, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('022d55e5-8718-49b9-a9ba-1b2ee0aecce1', 'b0000001-0000-0000-0000-000000000004', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'writing', 'sentence_builder', 'Susun kalimat: "Setiap pagi saya makan nasi."', '{"romaji":"Maiasa gohan o tabemasu.","tokens":["まいあさ","ごはん","を","たべます","パン","のみます"],"furigana":[{"kana":"まいあさ","kanji":"毎朝"},{"kana":"ごはん","kanji":"ご飯"},{"kana":"たべます","kanji":"食べます"}],"target_translation":"Setiap pagi saya makan nasi."}'::jsonb, '["まいあさ","ごはん","を","たべます"]'::jsonb, '[["毎朝","ご飯","を","食べます"],["毎朝","ごはん","を","たべます"]]'::jsonb, '{"パン":"Pan berarti roti, sedangkan kalimat meminta nasi (gohan).","のみます":"Nomimasu berarti minum, sedangkan untuk makanan padat digunakan tabemasu (makan)."}'::jsonb, 'Keterangan waktu frekuensi (まいあさ) diletakkan di awal kalimat, diikuti objek makanan (ごはん), partikel penderita (を), dan verba aksi (たべます).', 1, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('83b8278b-962b-4d15-8e68-66767b08563c', 'b0000001-0000-0000-0000-000000000004', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'listening', 'listening_choice', 'Dengarkan audio penutur asli berikut dan tentukan di mana pembicara minum kopi.', '{"options":[{"id":"opt_1","text":"Di rumah"},{"id":"opt_2","text":"Di kafe"},{"id":"opt_3","text":"Di kantor"},{"id":"opt_4","text":"Di stasiun"}],"furigana":[{"kana":"うち","kanji":"家"}],"audio_text":"わたしは うちで コーヒーを のみます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Pembicara menyebutkan kata うち (uchi = rumah), bukan kafe.","opt_3":"Kantor adalah かいしゃ (kaisha)."}'::jsonb, 'Partikel で (de) setelah kata うち (rumah) menunjukkan lokasi di mana aktivitas minum kopi berlangsung.', 2, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('14c6a7fe-aae1-4b3d-8a53-38bf7965ef48', 'b0000001-0000-0000-0000-000000000004', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya minum air mineral."', '{"romaji":"Mizu o nomimasu.","furigana":[{"kana":"みず","kanji":"水"},{"kana":"のみます","kanji":"飲みます"}],"display_text":"みずをのみます","phonetic_breakdown":["mi-zu","o","no-mi-ma-su"]}'::jsonb, '{"expected_transcript":"みずをのみます"}'::jsonb, '[["水を飲みます"],["みずを飲みます"]]'::jsonb, NULL, 'Ucapkan partikel を sebagai vokal bulat "o" yang mengalir halus antara kata mizu dan nomimasu.', 3, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000024', 'b0000001-0000-0000-0000-000000000004', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'reading', 'fill_blank', 'Lengkapi objek makan: まいあさ パン [blank] たべます。', '{"options":["を","に","で","へ"],"translation":"Setiap pagi makan roti.","sentence_template":"まいあさ パン [blank] たべます。"}'::jsonb, '{"selected":"を"}'::jsonb, NULL, '{"は":"は menandai topik, sedangkan パン adalah objek kata kerja たべます."}'::jsonb, 'Partikel を (o) menandai objek langsung dari kata kerja aksi.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000025', 'b0000001-0000-0000-0000-000000000004', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'writing', 'sentence_builder', 'Susun kalimat: "Saya minum air dingin."', '{"romaji":"Watashi wa tsumetai mizu o nomimasu.","tokens":["わたし","は","つめたい","みず","を","のみます"],"target_translation":"Saya minum air dingin."}'::jsonb, '["わたし","は","つめたい","みず","を","のみます"]'::jsonb, NULL, NULL, 'Objek 水（みず） diikuti partikel を sebelum kata kerja のみます.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000026', 'b0000001-0000-0000-0000-000000000004', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa yang dilakukan setiap pagi?', '{"options":[{"id":"opt_1","text":"Minum kopi"},{"id":"opt_2","text":"Minum teh hijau"},{"id":"opt_3","text":"Makan nasi"},{"id":"opt_4","text":"Makan ikan"}],"audio_text":"まいあさ コーヒーを のみます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'コーヒーを のみます berarti minum kopi.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-110002000007', 'b0000001-0000-0000-0000-000000000004', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat membeli barang ''Beli buku'':', '{"options":["かいます","のみます","たべます","よみます"],"translation":"Kaimasu","sentence_template":"ほん を [blank] (Membeli)"}'::jsonb, '{"selected":"かいます"}'::jsonb, NULL, NULL, 'かいます (kaimasu) berarti membeli.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-110002000008', 'b0000001-0000-0000-0000-000000000004', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Membeli buku":', '{"romaji":"Hon o kaimasu","tokens":["ほん","を","かいます"],"target_translation":"Membeli buku"}'::jsonb, '["ほん","を","かいます"]'::jsonb, NULL, NULL, 'Hon o kaimasu.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('39ff84dc-4b08-434a-907f-b27eddcc4512', 'b0000001-0000-0000-0000-000000000005', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'reading', 'fill_blank', 'Lengkapi kalimat saat memesan barang di toko/kafe: すみません、これ ___ ください。', '{"options":["を","は","に","で"],"translation":"Permisi, tolong berikan yang ini.","sentence_template":"すみません、これ [blank] ください。"}'::jsonb, '{"selected":"を"}'::jsonb, NULL, '{"で":"Partikel で digunakan untuk sarana atau lokasi tindakan.","に":"Partikel に digunakan untuk tujuan waktu atau tempat.","は":"Partikel は digunakan untuk penanda topik pembicaraan."}'::jsonb, 'Frasa 「これ を ください」(Kore o kudasai) adalah ungkapan standar transaksi di Jepang untuk meminta barang yang ditunjuk kepada kasir.', 1, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5da67170-7608-45d8-88b7-5014810f96fb', 'b0000001-0000-0000-0000-000000000005', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan di konbini berikut. Berapa total belanjaan pelanggan?', '{"options":[{"id":"opt_1","text":"300 Yen"},{"id":"opt_2","text":"500 Yen"},{"id":"opt_3","text":"3000 Yen"},{"id":"opt_4","text":"100 Yen"}],"audio_text":"店員: ありがとうございます。ぜんぶで さんびゃくえん です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"500 Yen adalah gohyaku-en.","opt_3":"3000 Yen adalah sanzen-en (ribuan)."}'::jsonb, 'Kata さんびゃく (sanbyaku) berarti 300, dan えん (en) adalah mata uang Yen Jepang.', 2, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000015-0000-0000-0000-000000000003', 'b0000001-0000-0000-0000-000000000005', NULL, 'reading', 'fill_blank', 'Lengkapi pertanyaan harga di kasir: この コーヒー ___ いくら ですか。', '{"options":["は","を","で","に"],"translation":"Berapa harga kopi ini?","sentence_template":"この コーヒー [blank] いくら ですか。"}'::jsonb, '{"selected":"は"}'::jsonb, NULL, '{"で":"Partikel で menandai tempat aksi atau alat.","を":"Partikel を dipakai untuk objek kata kerja transitif, bukan kata tanya nominal です."}'::jsonb, 'Topik benda yang ditanyakan harganya ditandai dengan partikel は sebelum kata tanya いくらですか.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000027', 'b0000001-0000-0000-0000-000000000005', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'reading', 'fill_blank', 'Lengkapi sarana/tempat aksi belanja: スーパー [blank] やさい を かいます。', '{"options":["で","を","へ","の"],"translation":"Membeli sayuran di supermarket.","sentence_template":"スーパー [blank] やさい を かいます。"}'::jsonb, '{"selected":"で"}'::jsonb, NULL, '{"へ":"へ hanya menunjukkan arah tujuan perpindahan."}'::jsonb, 'Partikel で menandai lokasi terjadinya tindakan aktif (membeli).', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000028', 'b0000001-0000-0000-0000-000000000005', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'writing', 'sentence_builder', 'Susun kalimat memesan di kafe: "Tolong satu jus jeruk."', '{"romaji":"Orenji juusu o hitotsu kudasai.","tokens":["オレンジジュース","を","ひとつ","ください","に"],"target_translation":"Tolong satu jus jeruk."}'::jsonb, '["オレンジジュース","を","ひとつ","ください"]'::jsonb, NULL, NULL, 'Gunakan pola [Benda] + を + [Jumlah] + ください saat memesan.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000029', 'b0000001-0000-0000-0000-000000000005', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'listening', 'listening_choice', 'Dengarkan pesanan restoran ini. Apa yang dipesan?', '{"options":[{"id":"opt_1","text":"Air putih"},{"id":"opt_2","text":"Nasi goreng"},{"id":"opt_3","text":"Teh panas"},{"id":"opt_4","text":"Kopi susu"}],"audio_text":"すみません、おみずを ください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'おみず (omizu) adalah air putih/air minum.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-110005000007', 'b0000001-0000-0000-0000-000000000005', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tanya kafe ''Berapa harga kopi ini?'':', '{"options":["いくら","なんじ","どこ","だれ"],"translation":"Ikura","sentence_template":"この コーヒー は [blank] ですか"}'::jsonb, '{"selected":"いくら"}'::jsonb, NULL, NULL, 'いくら ですか.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-110005000008', 'b0000001-0000-0000-0000-000000000005', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Roti ini berapa?":', '{"romaji":"Kono pan wa ikura desu ka","tokens":["この","パン","は","いくら","ですか"],"target_translation":"Roti ini berapa?"}'::jsonb, '["この","パン","は","いくら","ですか"]'::jsonb, NULL, NULL, 'Kono pan wa ikura desu ka.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b34627e9-00e8-4f6b-a174-227ab653e415', 'b0000001-0000-0000-0000-000000000006', '79e54427-faad-401e-b423-a97ff3e695d8', 'reading', 'fill_blank', 'Lengkapi kalimat waktu bangun pagi: まいあさ ７じ ___ おきます。', '{"options":["に","で","を","は"],"furigana":[{"kana":"まいあさ","kanji":"毎朝"},{"kana":"しちじ","kanji":"７時"},{"kana":"おきます","kanji":"起きます"}],"translation":"Setiap pagi saya bangun pada jam 7.","sentence_template":"まいあさ ７じ [blank] おきます。"}'::jsonb, '{"selected":"に"}'::jsonb, NULL, '{"で":"Partikel で tidak digunakan untuk titik waktu jam.","を":"Partikel を adalah penanda objek langsung penderita verba."}'::jsonb, 'Partikel に (ni) wajib digunakan setelah angka waktu jam pasti (７じ に) untuk menandai momen terjadinya tindakan bangun (おきます).', 1, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('17956bc6-6c25-4604-b6f2-26b7f95b23ff', 'b0000001-0000-0000-0000-000000000006', '79e54427-faad-401e-b423-a97ff3e695d8', 'writing', 'sentence_builder', 'Susun jam kerja kantor: "Bekerja dari jam 9 sampai jam 5."', '{"romaji":"Kuji kara goji made hatarakimasu.","tokens":["９じ","から","５じ","まで","はたらきます","やすみます"],"furigana":[{"kana":"くじ","kanji":"９時"},{"kana":"ごじ","kanji":"５時"},{"kana":"はたらきます","kanji":"働きます"}],"target_translation":"Bekerja dari jam 9 sampai jam 5."}'::jsonb, '["９じ","から","５じ","まで","はたらきます"]'::jsonb, '[["9時","から","5時","まで","働きます"],["９時","から","５時","まで","はたらきます"]]'::jsonb, '{"やすみます":"Yasumimasu berarti istirahat/libur, sedangkan kalimat meminta bekerja (hatarakimasu)."}'::jsonb, 'Kombinasi partikel から (kara = dari) dan まで (made = sampai) menunjukkan rentang waktu kerja kantor di Jepang.', 2, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000015-0000-0000-0000-000000000004', 'b0000001-0000-0000-0000-000000000006', NULL, 'listening', 'listening_choice', 'Dengarkan jadwal harian berikut. Jam berapa pembicara tidur setiap malam?', '{"options":[{"id":"opt_1","text":"Jam 11 malam"},{"id":"opt_2","text":"Jam 7 pagi"},{"id":"opt_3","text":"Jam 9 malam"},{"id":"opt_4","text":"Jam 1 siang"}],"audio_text":"まいばん １１じに ねます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Jam 7 adalah しちじ (7じ).","opt_3":"Jam 9 adalah くじ (9じ)."}'::jsonb, '「まいばん」(setiap malam) + 「１１じに」(jam 11) + 「ねます」(tidur).', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000044', 'b0000001-0000-0000-0000-000000000006', '79e54427-faad-401e-b423-a97ff3e695d8', 'reading', 'fill_blank', 'Lengkapi penanda waktu spesifik: まいあさ ６じ [blank] おきます。', '{"options":["に","を","で","は"],"translation":"Setiap pagi bangun jam 6.","sentence_template":"まいあさ ６じ [blank] おきます。"}'::jsonb, '{"selected":"に"}'::jsonb, NULL, '{"で":"で tidak dipakai untuk menunjukkan titik jam."}'::jsonb, 'Partikel に mengikuti angka jam atau hari spesifik kapan aksi terjadi.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000045', 'b0000001-0000-0000-0000-000000000006', '79e54427-faad-401e-b423-a97ff3e695d8', 'writing', 'sentence_builder', 'Susun kalimat jadwal kerja: "Perusahaan buka dari jam 9."', '{"romaji":"Kaisha wa kuji kara desu.","tokens":["かいしゃ","は","９じ","から","です"],"target_translation":"Perusahaan mulai dari jam 9."}'::jsonb, '["かいしゃ","は","９じ","から","です"]'::jsonb, NULL, NULL, 'Partikel から menyatakan titik mulai waktu ("dari jam ...").', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000046', 'b0000001-0000-0000-0000-000000000006', '79e54427-faad-401e-b423-a97ff3e695d8', 'listening', 'listening_choice', 'Dengarkan jam istirahat makan siang berikut. Jam berapakah istirahatnya?', '{"options":[{"id":"opt_1","text":"Dari jam 12"},{"id":"opt_2","text":"Dari jam 11"},{"id":"opt_3","text":"Dari jam 1"},{"id":"opt_4","text":"Dari jam 2"}],"audio_text":"ひるやすみは １２じからです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '１２じから berarti mulai dari jam 12.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-100002000007', 'b0000001-0000-0000-0000-000000000006', NULL, 'reading', 'fill_blank', 'Kanji 今 berarti ''sekarang'' yang dibaca:', '{"options":["いま","きょう","あした","きのう"],"translation":"Ima (sekarang)","sentence_template":"Kanji 今: [blank]"}'::jsonb, '{"selected":"いま"}'::jsonb, NULL, NULL, 'Kanji 今 dibaca いま (ima) = sekarang.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-100002000008', 'b0000001-0000-0000-0000-000000000006', NULL, 'listening', 'listening_choice', 'Dengarkan waktu siang hari ini:', '{"options":[{"id":"opt_1","text":"Pukul 12"},{"id":"opt_2","text":"Pukul 11"},{"id":"opt_3","text":"Pukul 10"},{"id":"opt_4","text":"Pukul 01.00"}],"audio_text":"じゅうにじ"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'じゅうにじ = pukul 12.00.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-100002000009', 'b0000001-0000-0000-0000-000000000006', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Pukul 12":', '{"romaji":"Juuni-ji","tokens":["十二","時"],"target_translation":"Pukul 12"}'::jsonb, '["十二","時"]'::jsonb, NULL, NULL, '十二時.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-100002000010', 'b0000001-0000-0000-0000-000000000006', NULL, 'speaking', 'speaking_repeat', 'Ucapkan ''いま じゅうにじ です'' (Sekarang pukul 12):', '{"romaji":"ima juuni-ji desu","audio_text":"いま じゅうにじ です","display_text":"いま じゅうにじ です"}'::jsonb, '{"expected_transcript":"いま じゅうにじ です"}'::jsonb, NULL, NULL, 'Lafalkan ima juuni-ji desu.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-100002000011', 'b0000001-0000-0000-0000-000000000006', NULL, 'reading', 'fill_blank', 'Lengkapi kata ''pagi hari'' (asa):', '{"options":["あさ","ひる","よる","ばん"],"translation":"Asa"}'::jsonb, '{"selected":"あさ"}'::jsonb, NULL, NULL, 'あさ (asa) = pagi.', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b0d9847-9059-446c-b985-70a8a2422f19', 'b0000001-0000-0000-0000-000000000007', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'writing', 'sentence_builder', 'Susun kalimat mobilitas: "Pergi ke stasiun naik bus."', '{"romaji":"Basu de eki e ikimasu.","tokens":["バス","で","えき","へ","いきます","かえります"],"furigana":[{"kana":"えき","kanji":"駅"},{"kana":"いきます","kanji":"行きます"}],"target_translation":"Pergi ke stasiun naik bus."}'::jsonb, '["バス","で","えき","へ","いきます"]'::jsonb, '[["バス","で","駅","へ","行きます"],["バス","で","えき","に","いきます"]]'::jsonb, '{"かえります":"Kaerimasu berarti pulang (ke rumah/negara asal), bukan pergi (ikimasu)."}'::jsonb, 'Sarana transportasi menggunakan partikel で (バス で), tempat tujuan menggunakan partikel へ atau に (えき へ), dan kata kerja arah (いきます).', 1, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7616c966-c63a-42e2-81c5-b49e50fb6452', 'b0000001-0000-0000-0000-000000000007', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman kereta komuter stasiun Tokyo berikut. Menuju ke stasiun manakah kereta ini?', '{"options":[{"id":"opt_1","text":"Menuju Shibuya & Shinjuku"},{"id":"opt_2","text":"Menuju Bandara Haneda"},{"id":"opt_3","text":"Menuju Yokohama"},{"id":"opt_4","text":"Kereta terakhir tidak beroperasi"}],"audio_text":"まもなく、２ばんせんに しぶや・しんじゅくほうめん いきの でんしゃが まいります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Tidak ada penyebutan bandara (kuukou) dalam audio pengumuman."}'::jsonb, 'Pengumuman stasiun menggunakan frasa 「しぶや・しんじゅくほうめん いき」(arah tujuan Shibuya & Shinjuku).', 2, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('44058bb9-30d5-41c1-a813-4cda1bdd794b', 'b0000001-0000-0000-0000-000000000007', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat komuter kerja: "Saya pergi naik kereta listrik."', '{"romaji":"Densha de ikimasu.","furigana":[{"kana":"でんしゃ","kanji":"電車"},{"kana":"いきます","kanji":"行きます"}],"display_text":"でんしゃでいきます","phonetic_breakdown":["den-sha","de","i-ki-ma-su"]}'::jsonb, '{"expected_transcript":"でんしゃでいきます"}'::jsonb, '[["電車で行きます"],["でんしゃで行きます"]]'::jsonb, NULL, 'Kata でんしゃ (densha = kereta listrik komuter) dipadukan dengan partikel sarana で (de) dan verba いき (iki).', 3, '2026-11-16T14:02:48.199664+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000047', 'b0000001-0000-0000-0000-000000000007', '05ca9c23-60a3-4eb9-bc58-259bbf0033c9', 'reading', 'fill_blank', 'Lengkapi arah perjalanan ke kota: らいしゅう おおさか [blank] いきます。', '{"options":["へ","で","を","の"],"translation":"Minggu depan pergi ke Osaka.","sentence_template":"らいしゅう おおさか [blank] いきます。"}'::jsonb, '{"selected":"へ"}'::jsonb, NULL, '{"を":"を tidak dipakai untuk tujuan kata kerja pergi/datang."}'::jsonb, 'Partikel へ (dibaca e) menunjukkan arah atau tempat tujuan.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000048', 'b0000001-0000-0000-0000-000000000007', '05ca9c23-60a3-4eb9-bc58-259bbf0033c9', 'writing', 'sentence_builder', 'Susun kalimat komuter: "Saya pergi ke kantor naik kereta."', '{"romaji":"Densha de kaisha e ikimasu.","tokens":["でんしゃ","で","かいしゃ","へ","いきます"],"target_translation":"Saya pergi ke kantor naik kereta."}'::jsonb, '["でんしゃ","で","かいしゃ","へ","いきます"]'::jsonb, NULL, NULL, 'Sarana transportasi ditandai dengan で (でんしゃで), dan tujuan dengan へ atau に.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000049', 'b0000001-0000-0000-0000-000000000007', '05ca9c23-60a3-4eb9-bc58-259bbf0033c9', 'listening', 'listening_choice', 'Dengarkan pernyataan komuter berikut. Ia pulang ke negara mana?', '{"options":[{"id":"opt_1","text":"Indonesia"},{"id":"opt_2","text":"Jepang"},{"id":"opt_3","text":"Korea"},{"id":"opt_4","text":"Singapura"}],"audio_text":"らいげつ インドネシアへ かえります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'かえります (kaerimasu) berarti pulang ke kampung halaman atau negara asal.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-150001000007', 'b0000001-0000-0000-0000-000000000007', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Datang ke Jepang'':', '{"options":["き","いき","かえり","おき"],"translation":"Kimashita","sentence_template":"にほん へ [blank] ました (Sudah datang)"}'::jsonb, '{"selected":"き"}'::jsonb, NULL, NULL, 'きました (kimashita) = sudah datang.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-150001000008', 'b0000001-0000-0000-0000-000000000007', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Tahun lalu datang ke Jepang":', '{"romaji":"Kyonen Nihon e kimashita","tokens":["きょねん","日本","へ","来ました"],"target_translation":"Tahun lalu datang ke Jepang"}'::jsonb, '["きょねん","日本","へ","来ました"]'::jsonb, NULL, NULL, 'Kyonen Nihon e kimashita.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-150001000009', 'b0000001-0000-0000-0000-000000000007', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kata ''来ました'' (sudah datang):', '{"romaji":"Nihon e kimashita","audio_text":"日本 へ 来ました","display_text":"日本 へ 来ました"}'::jsonb, '{"expected_transcript":"日本 へ 来ました"}'::jsonb, NULL, NULL, 'Lafalkan Nihon e kimashita.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2b63ddd7-3031-42e9-a141-fbe7564a073e', 'b0000001-0000-0000-0000-000000000008', NULL, 'reading', 'fill_blank', 'Pilih huruf Hiragana yang dibaca "ka":', '{"options":["か","き","く","け"],"translation":"Wajah (kao)","sentence_template":"[blank] お"}'::jsonb, '{"selected":"か"}'::jsonb, NULL, '{"さ":"Huruf さ dibaca sa.","た":"Huruf た dibaca ta."}'::jsonb, 'Huruf か mewakili bunyi "ka", sehingga かさ dibaca kasa (payung).', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('beefe423-7e82-440c-b5d2-450a66771823', 'b0000001-0000-0000-0000-000000000008', NULL, 'writing', 'sentence_builder', 'Susun huruf menjadi kata "Merah (akai)":', '{"romaji":"Akai","tokens":["あ","か","い","き","こ"],"target_translation":"Merah (akai)"}'::jsonb, '["あ","か","い"]'::jsonb, '[["魚"]]'::jsonb, '{"た":"Suku kata た dibaca ta, tidak ada pada kata sakana."}'::jsonb, 'Gabungan さ (sa) + か (ka) + な (na) membentuk kata さかな (ikan).', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b7a5b3ed-131f-48d2-bfc3-a50013a04a3a', 'b0000001-0000-0000-0000-000000000008', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kata sapaan terima kasih singkat: "ありがとうございます".', '{"romaji":"Arigatou gozaimasu","display_text":"ありがとうございます","phonetic_breakdown":["a-ri-ga-tou","go-za-i-ma-su"]}'::jsonb, '{"expected_transcript":"ありがとうございます"}'::jsonb, '[["有り難うございます"]]'::jsonb, NULL, 'Ungkapan sopan standar untuk berterima kasih di Jepang.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000005', 'b0000001-0000-0000-0000-000000000008', NULL, 'reading', 'fill_blank', 'Pilih ungkapan sopan yang berarti "Permisi / Maaf" untuk melengkapi kalimat:', '{"romaji":"Sumimasen","options":[{"id":"すみません","text":"すみません (Sumimasen)"},{"id":"さようなら","text":"さようなら (Sayounara)"},{"id":"おやすみ","text":"おやすみ (Oyasumi)"},{"id":"はい","text":"はい (Hai)"}],"translation":"Permisi, di mana stasiun?","sentence_template":"[blank]、えきは どこですか。(Sumimasen, eki wa doko desu ka?)"}'::jsonb, '{"selected":"すみません"}'::jsonb, NULL, '{"さようなら":"さようなら berarti selamat tinggal."}'::jsonb, 'すみません sangat sering dipakai sebagai pembuka sopan berarti "permisi" atau "maaf".', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000006', 'b0000001-0000-0000-0000-000000000008', NULL, 'reading', 'fill_blank', 'Pilih huruf Hiragana yang dibaca "ku":', '{"options":["く","か","き","け"],"translation":"Mendengar (kiku)","sentence_template":"き [blank]"}'::jsonb, '{"selected":"く"}'::jsonb, NULL, '{"さ":"さ dibaca sa.","し":"し dibaca shi."}'::jsonb, 'き (ki) + く (ku) = きく (mendengar). Huruf く berada di deret か-き-く-け-こ.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-010005000006', 'b0000001-0000-0000-0000-000000000008', NULL, 'reading', 'fill_blank', 'Lengkapi sapaan pendek ''iya/benar'':', '{"options":["え","あ","い","お"],"translation":"Iya (ee)","sentence_template":"[blank] え"}'::jsonb, '{"selected":"え"}'::jsonb, NULL, NULL, 'ええ (ee) digunakan dalam percakapan kasual untuk ''iya''.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-010005000007', 'b0000001-0000-0000-0000-000000000008', NULL, 'writing', 'sentence_builder', 'Susun huruf menjadi kata "Tidak / bukan (iie)":', '{"romaji":"Iie","tokens":["い","い","え","あ"],"target_translation":"Tidak / bukan (iie)"}'::jsonb, '["い","い","え"]'::jsonb, NULL, NULL, 'い + い + え = いいえ (iie).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-010005000008', 'b0000001-0000-0000-0000-000000000008', NULL, 'speaking', 'speaking_repeat', 'Ucapkan penegasan sopan ''いいえ'' (tidak):', '{"romaji":"iie","audio_text":"いいえ","display_text":"いいえ"}'::jsonb, '{"expected_transcript":"いいえ"}'::jsonb, NULL, NULL, 'Lafalkan i-i-e dengan intonasi sopan.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6555aa90-892f-4eea-8ca6-485d175b8e36', 'b0000001-0000-0000-0000-000000000009', NULL, 'reading', 'fill_blank', 'Lengkapi kata pinjaman Katakana untuk "kopi": コー [blank] ー', '{"options":["ヒ","シ","ツ","ン"],"translation":"Kopi (koohii)","sentence_template":"コー [blank] ー"}'::jsonb, '{"selected":"ヒ"}'::jsonb, NULL, '{"シ":"Huruf シ dibaca shi, bukan hi."}'::jsonb, 'Kata pinjaman ditulis memakai Katakana: コーヒー (koohii = kopi).', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cd476e2a-6562-4518-9bb0-bca3f6ea22b6', 'b0000001-0000-0000-0000-000000000009', NULL, 'listening', 'listening_choice', 'Dengarkan pelafalan angka berikut. Angka berapakah yang diucapkan?', '{"options":[{"id":"opt_1","text":"5 (Lima)"},{"id":"opt_2","text":"3 (Tiga)"},{"id":"opt_3","text":"8 (Delapan)"},{"id":"opt_4","text":"10 (Sepuluh)"}],"audio_text":"ご"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Angka 3 dibaca san (さん)."}'::jsonb, 'Dalam sistem bilangan dasar: いち(1), に(2), さん(3), よん(4), ご(5).', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('35035cd6-b9a3-409e-937a-207a6a28953e', 'b0000001-0000-0000-0000-000000000009', NULL, 'writing', 'sentence_builder', 'Susun angka berurutan satu, dua, tiga dalam Hiragana.', '{"romaji":"Ichi, ni, san","tokens":["いち","に","さん","よん","ご"],"target_translation":"Satu, dua, tiga"}'::jsonb, '["いち","に","さん"]'::jsonb, NULL, '{"よん":"よん adalah angka empat."}'::jsonb, 'Urutan tiga angka pertama adalah いち (1), に (2), さん (3).', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000007', 'b0000001-0000-0000-0000-000000000009', NULL, 'writing', 'sentence_builder', 'Susun kata Hiragana untuk "kasa" (payung).', '{"romaji":"Kasa","tokens":["か","さ","た","な"],"target_translation":"Payung (kasa)"}'::jsonb, '["か","さ"]'::jsonb, NULL, NULL, 'Gabungan か (ka) dan さ (sa) membentuk kata かさ (payung).', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000008', 'b0000001-0000-0000-0000-000000000009', NULL, 'listening', 'listening_choice', 'Dengarkan angka berikut. Berapa yang disebutkan?', '{"options":[{"id":"opt_1","text":"9 (Sembilan)"},{"id":"opt_2","text":"6 (Enam)"},{"id":"opt_3","text":"4 (Empat)"},{"id":"opt_4","text":"7 (Tujuh)"}],"audio_text":"きゅう"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'きゅう (kyuu) adalah angka 9.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000009', 'b0000001-0000-0000-0000-000000000009', NULL, 'reading', 'fill_blank', 'Lengkapi kata Katakana untuk "televisi": テ [blank] ビ', '{"options":["レ","リ","ル","ラ"],"translation":"Televisi (terebi)","sentence_template":"テ [blank] ビ"}'::jsonb, '{"selected":"レ"}'::jsonb, NULL, '{"リ":"リ dibaca ri."}'::jsonb, 'Kata serapan televisi ditulis dengan Katakana: テレビ (terebi).', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-080005000007', 'b0000001-0000-0000-0000-000000000009', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat asal negara ''Saya orang Amerika'':', '{"options":["じん","ご","さん","くん"],"translation":"Amerika-jin","sentence_template":"わたし は アメリカ[blank] です"}'::jsonb, '{"selected":"じん"}'::jsonb, NULL, NULL, 'Nama negara Katakana + じん = kewarganegaraan.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-080005000008', 'b0000001-0000-0000-0000-000000000009', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Mike orang Amerika":', '{"romaji":"Maiku-san wa Amerika-jin desu","tokens":["マイクさん","は","アメリカじん","です"],"target_translation":"Mike orang Amerika"}'::jsonb, '["マイクさん","は","アメリカじん","です"]'::jsonb, NULL, NULL, 'Maiku-san wa Amerika-jin desu.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('816cdd5f-94f6-4b24-a36e-bd0e149de42e', 'b0000001-0000-0000-0000-000000000010', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'reading', 'fill_blank', 'Pilih kata tunjuk untuk benda yang berada dekat dengan pembicara: ___ は ほん です。', '{"options":["これ","それ","あれ","どれ"],"translation":"Ini adalah buku.","sentence_template":"[blank] は ほん です。"}'::jsonb, '{"selected":"これ"}'::jsonb, NULL, '{"それ":"それ dipakai untuk benda yang dekat dengan lawan bicara."}'::jsonb, 'これ menunjuk benda dekat pembicara, それ dekat lawan bicara, dan あれ jauh dari keduanya.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3f315e3e-086a-422a-828d-0a0d63f4c725', 'b0000001-0000-0000-0000-000000000010', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'writing', 'sentence_builder', 'Susun kalimat kepemilikan: "Itu adalah tas milik Yamada."', '{"romaji":"Sore wa Yamada-san no kaban desu.","tokens":["それ","は","やまださん","の","かばん","です","これ"],"target_translation":"Itu adalah tas milik Yamada."}'::jsonb, '["それ","は","やまださん","の","かばん","です"]'::jsonb, '[["それは山田さんのかばんです"]]'::jsonb, '{"これ":"これ berarti ini, sedangkan kalimat meminta kata tunjuk itu (それ)."}'::jsonb, 'Pemilik diikuti partikel の lalu kata bendanya: やまださんの かばん.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('310a96aa-8975-4f3b-9b30-5b17d5a26b82', 'b0000001-0000-0000-0000-000000000010', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan kepemilikan berikut: "Apakah ini buku catatan Anda?"', '{"romaji":"Kore wa anata no nooto desu ka.","display_text":"これはあなたのノートですか","phonetic_breakdown":["ko-re","wa","a-na-ta","no","noo-to","de-su","ka"]}'::jsonb, '{"expected_transcript":"これはあなたのノートですか"}'::jsonb, NULL, NULL, 'Tambahkan partikel か di akhir kalimat untuk mengubah pernyataan menjadi pertanyaan.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000012', 'b0000001-0000-0000-0000-000000000010', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'listening', 'listening_choice', 'Dengarkan kalimat perkenalan berikut. Berapa umur pembicara?', '{"options":[{"id":"opt_1","text":"25 tahun"},{"id":"opt_2","text":"20 tahun"},{"id":"opt_3","text":"15 tahun"},{"id":"opt_4","text":"35 tahun"}],"audio_text":"わたしは にじゅうごさい です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'にじゅうごさい (nijuu-go-sai) berarti 25 tahun.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000013', 'b0000001-0000-0000-0000-000000000010', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'reading', 'fill_blank', 'Pilih kosakata bahasa Jepang untuk "insinyur/teknisi":', '{"options":["エンジニア","いしゃ","きょうし","かいしゃいん"],"translation":"Saya adalah seorang insinyur.","sentence_template":"わたしは [blank] です。"}'::jsonb, '{"selected":"エンジニア"}'::jsonb, NULL, '{"いしゃ":"いしゃ berarti dokter."}'::jsonb, 'エンジニア (enjinia) adalah kata serapan untuk engineer / insinyur.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000014', 'b0000001-0000-0000-0000-000000000010', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'reading', 'fill_blank', 'Lengkapi kepemilikan bahasa Jepang: [blank] は にほんご の ほん です。', '{"options":["これ","だれ","どこ","いつ"],"translation":"Ini adalah buku bahasa Jepang.","sentence_template":"[blank] は にほんご の ほん です。"}'::jsonb, '{"selected":"これ"}'::jsonb, NULL, '{"どこ":"どこ menanyakan tempat."}'::jsonb, 'これ dipakai untuk menunjuk benda yang dekat dengan pembicara.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-060002000007', 'b0000001-0000-0000-0000-000000000010', NULL, 'reading', 'fill_blank', 'Pilih kata penunjuk mandiri lawan bicara (itu):', '{"options":["それ","その","そこ","そう"],"translation":"Sore","sentence_template":"[blank] は わたし の じしょ です (Itu kamus saya)"}'::jsonb, '{"selected":"それ"}'::jsonb, NULL, NULL, 'それ berdiri sendiri sebagai kata ganti tunjuk.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-060002000008', 'b0000001-0000-0000-0000-000000000010', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Ini kamus":', '{"romaji":"Kore wa jisho desu","tokens":["これ","は","じしょ","です"],"target_translation":"Ini kamus"}'::jsonb, '["これ","は","じしょ","です"]'::jsonb, NULL, NULL, 'Kore wa jisho desu.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f900a92c-a477-40a3-b5bf-a8e1ed38ede1', 'b0000001-0000-0000-0000-000000000011', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'reading', 'fill_blank', 'Lengkapi pertanyaan asal negara: おくに は ___ ですか。', '{"options":["どちら","だれ","なんさい","いくら"],"translation":"Anda berasal dari negara mana?","sentence_template":"おくに は [blank] ですか。"}'::jsonb, '{"selected":"どちら"}'::jsonb, NULL, '{"だれ":"だれ menanyakan siapa (orang), bukan asal tempat/negara."}'::jsonb, '「どちら」 adalah bentuk sopan dari どこ (mana) untuk menanyakan asal negara atau perusahaan.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3970a4cb-2ec2-4b7c-b30f-13aac5356208', 'b0000001-0000-0000-0000-000000000011', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'listening', 'listening_choice', 'Dengarkan dialog perkenalan ini. Siapakah nama pembicara?', '{"options":[{"id":"opt_1","text":"Sato"},{"id":"opt_2","text":"Tanaka"},{"id":"opt_3","text":"Suzuki"},{"id":"opt_4","text":"Takahashi"}],"audio_text":"わたしの なまえは さとう です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Tanaka tidak disebutkan pada rekaman."}'::jsonb, 'Frasa 「わたしの なまえは 〜 です」 digunakan untuk menyebutkan nama diri.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('87fd5c92-037d-4d10-ac3d-4abf20b7fa30', 'b0000001-0000-0000-0000-000000000011', '84296601-2071-4b58-a093-e916c1f4abac', 'writing', 'sentence_builder', 'Susun kalimat negasi lampau: "Kemarin bukan hari kerja."', '{"romaji":"Kinou wa shigoto dewa arimasen deshita.","tokens":["きのう","は","しごと","ではありませんでした","です"],"target_translation":"Kemarin bukan hari kerja."}'::jsonb, '["きのう","は","しごと","ではありませんでした"]'::jsonb, '[["昨日は仕事ではありませんでした"]]'::jsonb, '{"です":"です adalah kalimat positif saat ini, bukan bentuk lampau negatif."}'::jsonb, 'Gunakan ではありませんでした untuk menyatakan "dulu bukan" pada kata benda.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000015', 'b0000001-0000-0000-0000-000000000011', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'writing', 'sentence_builder', 'Susun frasa: "Kunci milik teman".', '{"romaji":"Tomodachi no kagi","tokens":["ともだち","の","かぎ","は"],"target_translation":"Kunci milik teman"}'::jsonb, '["ともだち","の","かぎ"]'::jsonb, NULL, NULL, 'Partikel の menghubungkan pemilik (ともだち) dengan benda (かぎ).', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000016', 'b0000001-0000-0000-0000-000000000011', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'listening', 'listening_choice', 'Dengarkan dialog ini. Buku itu milik siapa?', '{"options":[{"id":"opt_1","text":"Milik Guru"},{"id":"opt_2","text":"Milik Mahasiswa"},{"id":"opt_3","text":"Milik Karyawan"},{"id":"opt_4","text":"Milik Adik"}],"audio_text":"これは せんせい の ほんです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'せんせいの ほん berarti buku milik guru.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000017', 'b0000001-0000-0000-0000-000000000011', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'reading', 'fill_blank', 'Pilih kata tanya yang tepat: あの ひと は [blank] ですか。', '{"options":["だれ","なに","どれ","どこ"],"translation":"Orang itu siapa?","sentence_template":"あの ひと は [blank] ですか。"}'::jsonb, '{"selected":"だれ"}'::jsonb, NULL, '{"なに":"なに menanyakan benda/apa."}'::jsonb, 'だれ dipakai untuk menanyakan siapa (orang).', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-060005000007', 'b0000001-0000-0000-0000-000000000011', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat asal daerah ''Saya berasal dari Jakarta'':', '{"options":["から","まで","に","で"],"translation":"Kara kimashita","sentence_template":"わたし は ジャカルタ [blank] きました"}'::jsonb, '{"selected":"から"}'::jsonb, NULL, NULL, '～から きました berarti ''datang dari / berasal dari''.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-060005000008', 'b0000001-0000-0000-0000-000000000011', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Datang dari Indonesia":', '{"romaji":"Indoneshia kara kimashita","tokens":["インドネシア","から","きました"],"target_translation":"Datang dari Indonesia"}'::jsonb, '["インドネシア","から","きました"]'::jsonb, NULL, NULL, 'Indoneshia kara kimashita.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('02d0495a-18e2-484b-b47b-8a8cf1ba0548', 'b0000001-0000-0000-0000-000000000012', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'reading', 'fill_blank', 'Lengkapi kalimat aktivitas rumah: いえで おんがく ___ ききます。', '{"options":["を","が","に","へ"],"translation":"Saya mendengarkan musik di rumah.","sentence_template":"いえで おんがく [blank] ききます。"}'::jsonb, '{"selected":"を"}'::jsonb, NULL, '{"に":"ききます (mendengarkan musik) memakai partikel objek を."}'::jsonb, 'Kata benda objek dari tindakan aktif seperti mendengarkan atau menonton memakai partikel を.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6d945288-e2f4-4bc1-b4a9-90478a46ab22', 'b0000001-0000-0000-0000-000000000012', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'writing', 'sentence_builder', 'Susun kalimat: "Di kamar saya membaca buku."', '{"romaji":"Heya de hon o yomimasu.","tokens":["へや","で","ほん","を","よみます","かきます"],"target_translation":"Di kamar saya membaca buku."}'::jsonb, '["へや","で","ほん","を","よみます"]'::jsonb, '[["部屋で本を読みます"]]'::jsonb, '{"かきます":"かきます berarti menulis, sedangkan soal meminta membaca (よみます)."}'::jsonb, 'Lokasi tempat aktivitas menggunakan で (へやで), dan objeknya menggunakan を (ほんを).', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f148d473-c167-4896-8bcd-37364dded259', 'b0000001-0000-0000-0000-000000000012', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'speaking', 'speaking_repeat', 'Ucapkan kalimat berikut: "Setiap malam saya menonton berita."', '{"romaji":"Maiban nyuusu o mimasu.","display_text":"まいばんニュースをみます","phonetic_breakdown":["mai-ban","nyuu-su","o","mi-ma-su"]}'::jsonb, '{"expected_transcript":"まいばんニュースをみます"}'::jsonb, '[["毎晩ニュースを見ます"]]'::jsonb, NULL, 'Kata kerja みます berarti melihat atau menonton.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000030', 'b0000001-0000-0000-0000-000000000012', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'reading', 'fill_blank', 'Pilih kata kerja yang tepat untuk membaca buku: としょかん で ほん を [blank]。', '{"options":["よみます","ききます","みます","かきます"],"translation":"Membaca buku di perpustakaan.","sentence_template":"としょかん で ほん を [blank]。"}'::jsonb, '{"selected":"よみます"}'::jsonb, NULL, '{"みます":"みます berarti melihat/menonton, bukan membaca."}'::jsonb, 'よみます (yomimasu) berarti membaca.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000031', 'b0000001-0000-0000-0000-000000000012', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'writing', 'sentence_builder', 'Susun kalimat hobi: "Saya mendengarkan musik Jepang."', '{"romaji":"Nihon no ongaku o kikimasu.","tokens":["にほん","の","おんがく","を","ききます"],"target_translation":"Saya mendengarkan musik Jepang."}'::jsonb, '["にほん","の","おんがく","を","ききます"]'::jsonb, NULL, NULL, 'にほんの おんがく berarti musik Jepang, dipasangkan dengan ききます (mendengarkan).', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000032', 'b0000001-0000-0000-0000-000000000012', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa yang dia tonton malam ini?', '{"options":[{"id":"opt_1","text":"Menonton film"},{"id":"opt_2","text":"Membaca koran"},{"id":"opt_3","text":"Menulis surat"},{"id":"opt_4","text":"Memasak ikan"}],"audio_text":"こんばん えいがを みます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'えいが (eiga) adalah film dan みます (mimasu) berarti menonton.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-120002000007', 'b0000001-0000-0000-0000-000000000012', NULL, 'reading', 'fill_blank', 'Lengkapi kata ''kemarin'' (kinou):', '{"options":["きのう","きょう","あした","おととい"],"translation":"Kemarin"}'::jsonb, '{"selected":"きのう"}'::jsonb, NULL, NULL, 'きのう (kinou) = kemarin.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-120002000008', 'b0000001-0000-0000-0000-000000000012', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Kemarin belajar":', '{"romaji":"Kinou benkyoushimashita","tokens":["きのう","べんきょうしました"],"target_translation":"Kemarin belajar"}'::jsonb, '["きのう","べんきょうしました"]'::jsonb, NULL, NULL, 'Kinou benkyoushimashita.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('84c270c8-d7d6-41a1-92d6-1b23c0dc2a05', 'b0000001-0000-0000-0000-000000000013', 'a830983b-40e2-4080-a8a5-416276586f1a', 'reading', 'fill_blank', 'Pilih akhiran ajakan sopan kepada rekan kerja: いっしょに ひるごはんを たべ ___ か。', '{"options":["ません","ます","ました","ませんでし"],"translation":"Maukah makan siang bersama?","sentence_template":"いっしょに ひるごはんを たべ [blank] か。"}'::jsonb, '{"selected":"ません"}'::jsonb, NULL, '{"ます":"たべますか hanya bertanya apakah makan, bukan mengajak secara sopan."}'::jsonb, 'Bentuk 「～ませんか」 dipakai untuk mengajak orang lain dengan penuh pertimbangan.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c6010ca6-6a15-4e3d-bebc-0ff698e20d3b', 'b0000001-0000-0000-0000-000000000013', 'a830983b-40e2-4080-a8a5-416276586f1a', 'writing', 'sentence_builder', 'Susun kalimat ajakan langsung: "Mari kita minum kopi sebentar."', '{"romaji":"Chotto koohii o nomimashou.","tokens":["ちょっと","コーヒー","を","のみましょう","のみません"],"target_translation":"Mari kita minum kopi sebentar."}'::jsonb, '["ちょっと","コーヒー","を","のみましょう"]'::jsonb, '[["ちょっとコーヒーを飲みましょう"]]'::jsonb, '{"のみません":"のみません berarti tidak minum, bukan ajakan のみましょう."}'::jsonb, 'Akhiran ～ましょう ("mari kita...") menyatakan ajakan yang disepakati bersama.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3b8af466-b47a-4ac0-a8a1-bd14b97f67f5', 'b0000001-0000-0000-0000-000000000013', 'a830983b-40e2-4080-a8a5-416276586f1a', 'listening', 'listening_choice', 'Dengarkan ajakan berikut. Apa yang diajak lakukan?', '{"options":[{"id":"opt_1","text":"Pulang bersama"},{"id":"opt_2","text":"Makan malam di kantor"},{"id":"opt_3","text":"Berangkat pagi"},{"id":"opt_4","text":"Minum teh hijau"}],"audio_text":"いっしょに かえりませんか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Verba yang diucapkan adalah かえり (pulang), bukan たべ (makan)."}'::jsonb, '「いっしょに かえりませんか」 berarti "Maukah pulang bersama?"', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000033', 'b0000001-0000-0000-0000-000000000013', 'a830983b-40e2-4080-a8a5-416276586f1a', 'reading', 'fill_blank', 'Lengkapi kalimat ajakan sopan: いっしょ に ひるごはん を たべ [blank]。', '{"options":["ませんか","ます","ません","ました"],"translation":"Maukah makan siang bersama?","sentence_template":"いっしょ に ひるごはん を たべ [blank]。"}'::jsonb, '{"selected":"ませんか"}'::jsonb, NULL, '{"ません":"～ません berarti tidak makan; tambah か untuk mengajak."}'::jsonb, 'Akhiran ～ませんか dipakai untuk mengajak seseorang secara halus.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000034', 'b0000001-0000-0000-0000-000000000013', 'a830983b-40e2-4080-a8a5-416276586f1a', 'writing', 'sentence_builder', 'Susun ajakan positif: "Ayo minum kopi."', '{"romaji":"Koohii o nomimashou.","tokens":["コーヒー","を","のみましょう","のみません"],"target_translation":"Ayo minum kopi."}'::jsonb, '["コーヒー","を","のみましょう"]'::jsonb, NULL, NULL, 'Akhiran ～ましょう berarti "ayo / mari kita ...".', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000035', 'b0000001-0000-0000-0000-000000000013', 'a830983b-40e2-4080-a8a5-416276586f1a', 'listening', 'listening_choice', 'Dengarkan ajakan berikut. Ke mana pembicara mengajak pergi?', '{"options":[{"id":"opt_1","text":"Ke kafe"},{"id":"opt_2","text":"Ke stasiun"},{"id":"opt_3","text":"Ke rumah sakit"},{"id":"opt_4","text":"Ke perpustakaan"}],"audio_text":"いっしょに カフェへ いきませんか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'カフェへ いきませんか berarti "Maukah pergi ke kafe bersama?".', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000036', 'b0000001-0000-0000-0000-000000000013', 'a830983b-40e2-4080-a8a5-416276586f1a', 'reading', 'fill_blank', 'Pilih kata kerja menulis laporan: わたし は レポート を [blank]。', '{"options":["かきます","よみます","のみます","きます"],"translation":"Saya menulis laporan.","sentence_template":"わたし は レポート を [blank]。"}'::jsonb, '{"selected":"かきます"}'::jsonb, NULL, NULL, 'かきます (kakimasu) berarti menulis.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140005000008', 'b0000001-0000-0000-0000-000000000013', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tawar menolong membawa barang:', '{"options":["もち","あけ","つけ","よび"],"translation":"Mochi","sentence_template":"にもつ を [blank] ましょうか"}'::jsonb, '{"selected":"もち"}'::jsonb, NULL, NULL, 'もちます = membawa/memegang.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140005000009', 'b0000001-0000-0000-0000-000000000013', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Bolehkah saya pinjamkan payung?":', '{"romaji":"Kasa o kashimashou ka","tokens":["かさ","を","かしましょうか"],"target_translation":"Bolehkah saya pinjamkan payung?"}'::jsonb, '["かさ","を","かしましょうか"]'::jsonb, NULL, NULL, 'Kasa o kashimashou ka.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a6a40787-ca2e-4e57-9607-58fb31dc02bd', 'b0000001-0000-0000-0000-000000000014', '79e54427-faad-401e-b423-a97ff3e695d8', 'reading', 'fill_blank', 'Lengkapi jadwal rapat mingguan: げつようび ___ かいぎ が あります。', '{"options":["に","を","へ","で"],"translation":"Hari Senin ada rapat.","sentence_template":"げつようび [blank] かいぎ が あります。"}'::jsonb, '{"selected":"に"}'::jsonb, NULL, '{"を":"Hari dalam seminggu bukan objek verba transitif."}'::jsonb, 'Nama hari spesifik seperti げつようび (Senin) diikuti partikel waktu に.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b8bdd0bf-d850-418a-9def-336e63aa6eb9', 'b0000001-0000-0000-0000-000000000014', '79e54427-faad-401e-b423-a97ff3e695d8', 'writing', 'sentence_builder', 'Susun kalimat: "Besok pergi ke Tokyo."', '{"romaji":"Ashita Toukyou e ikimasu.","tokens":["あした","とうきょう","へ","いきます","きのう"],"target_translation":"Besok pergi ke Tokyo."}'::jsonb, '["あした","とうきょう","へ","いきます"]'::jsonb, '[["明日東京へ行きます"],["あしたとうきょうにいきます"]]'::jsonb, '{"きのう":"きのう berarti kemarin, tidak cocok untuk verba bentuk non-lampau いきます."}'::jsonb, 'Kata keterangan waktu relatif seperti あした (besok) dan きょう (hari ini) tidak memerlukan partikel に.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d90fc5b4-93a0-46e0-b0e8-50e6a12224e7', 'b0000001-0000-0000-0000-000000000014', '79e54427-faad-401e-b423-a97ff3e695d8', 'speaking', 'speaking_repeat', 'Ucapkan hari libur akhir pekan: "Sabtu dan Minggu adalah hari libur."', '{"romaji":"Doyoubi to nichiyoubi wa yasumi desu.","display_text":"どようびとにちようびはやすみです","phonetic_breakdown":["do-you-bi","to","ni-chi-you-bi","wa","ya-su-mi","de-su"]}'::jsonb, '{"expected_transcript":"どようびとにちようびはやすみです"}'::jsonb, '[["土曜日と日曜日は休みです"]]'::jsonb, NULL, 'どようび adalah Sabtu dan にちようび adalah Minggu.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000050', 'b0000001-0000-0000-0000-000000000014', '79e54427-faad-401e-b423-a97ff3e695d8', 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan nama hari "Rabu" dalam bahasa Jepang:', '{"options":["すいようび","げつようび","きんようび","にちようび"],"translation":"Hari ini adalah hari Rabu.","sentence_template":"きょうは [blank] です。"}'::jsonb, '{"selected":"すいようび"}'::jsonb, NULL, '{"げつようび":"げつようび adalah hari Senin."}'::jsonb, 'Urutan hari: げつ(Senin), か(Selasa), すい(Rabu), もく(Kamis), きん(Jumat), ど(Sabtu), にち(Minggu).', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000051', 'b0000001-0000-0000-0000-000000000014', '79e54427-faad-401e-b423-a97ff3e695d8', 'writing', 'sentence_builder', 'Susun kalimat rencana hari libur: "Hari Minggu saya tidak pergi ke kantor."', '{"romaji":"Nichiyoubi wa kaisha e ikimasen.","tokens":["にちようび","は","かいしゃ","へ","いきません"],"target_translation":"Hari Minggu tidak pergi ke kantor."}'::jsonb, '["にちようび","は","かいしゃ","へ","いきません"]'::jsonb, NULL, NULL, 'Gunakan bentuk negatif いきません untuk menyatakan tidak pergi.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000052', 'b0000001-0000-0000-0000-000000000014', '79e54427-faad-401e-b423-a97ff3e695d8', 'listening', 'listening_choice', 'Dengarkan jadwal rapat berikut. Hari apakah rapat diadakan?', '{"options":[{"id":"opt_1","text":"Hari Jumat"},{"id":"opt_2","text":"Hari Selasa"},{"id":"opt_3","text":"Hari Kamis"},{"id":"opt_4","text":"Hari Sabtu"}],"audio_text":"かいぎは きんようび に あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'きんようび (kinyoubi) berarti hari Jumat.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-100001000007', 'b0000001-0000-0000-0000-000000000014', NULL, 'reading', 'fill_blank', 'Kanji 時 melambangkan satuan jam yang dibaca:', '{"options":["じ","ふん","はん","ひ"],"translation":"Ji (jam)","sentence_template":"Kanji 時 dibaca: [blank]"}'::jsonb, '{"selected":"じ"}'::jsonb, NULL, NULL, 'Kanji 時 dibaca じ (ji) = jam/pukul.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-100001000008', 'b0000001-0000-0000-0000-000000000014', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Sekarang jam berapa?":', '{"romaji":"Ima nanji desu ka","tokens":["いま","何時","ですか"],"target_translation":"Sekarang jam berapa?"}'::jsonb, '["いま","何時","ですか"]'::jsonb, NULL, NULL, 'Ima nanji desu ka.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-100001000009', 'b0000001-0000-0000-0000-000000000014', NULL, 'speaking', 'speaking_repeat', 'Tanyakan waktu ''いま なんじ ですか'':', '{"romaji":"ima nanji desu ka","audio_text":"いま なんじ ですか","display_text":"いま なんじ ですか"}'::jsonb, '{"expected_transcript":"いま なんじ ですか"}'::jsonb, NULL, NULL, 'Lafalkan ima nanji desu ka.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('461007c5-71d4-4a6e-a9d0-32bbcb944e3b', 'b0000001-0000-0000-0000-000000000015', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'reading', 'fill_blank', 'Lengkapi kalimat durasi komuter: えきまで あるいて １０ぷん ___ かかります。', '{"options":["くらい","から","より","しか"],"translation":"Jalan kaki ke stasiun memakan waktu sekitar 10 menit.","sentence_template":"えきまで あるいて １０ぷん [blank] かかります。"}'::jsonb, '{"selected":"くらい"}'::jsonb, NULL, '{"から":"から berarti dari/karena, bukan perkiraan durasi."}'::jsonb, 'Kata 「くらい」(atau ぐらい) setelah durasi waktu berarti "kira-kira / sekitar".', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8e7d764a-a1fb-4895-afdf-7901612572d0', 'b0000001-0000-0000-0000-000000000015', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'writing', 'sentence_builder', 'Susun kalimat: "Dari asrama ke kantor naik sepeda."', '{"romaji":"Ryou kara kaisha made jitensha de ikimasu.","tokens":["りょう","から","かいしゃ","まで","じてんしゃ","で","いきます"],"target_translation":"Dari asrama ke kantor naik sepeda."}'::jsonb, '["りょう","から","かいしゃ","まで","じてんしゃ","で","いきます"]'::jsonb, '[["寮から会社まで自転車で行きます"]]'::jsonb, NULL, 'Gunakan から (dari), まで (sampai), dan で (dengan sarana) dalam satu kalimat terstruktur.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('22a50257-8a20-42ee-b98c-54266a5fcb09', 'b0000001-0000-0000-0000-000000000015', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'listening', 'listening_choice', 'Dengarkan keterangan perjalanan berikut. Berapa lama waktu naik kereta ke Shinjuku?', '{"options":[{"id":"opt_1","text":"30 menit"},{"id":"opt_2","text":"15 menit"},{"id":"opt_3","text":"1 jam"},{"id":"opt_4","text":"5 menit"}],"audio_text":"しんじゅくまで でんしゃで ３０ぷん かかります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Waktu yang disebutkan adalah さんじゅっぷん (30 menit)."}'::jsonb, 'Kata kerja 「かかります」 berarti memakan waktu (atau biaya).', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000053', 'b0000001-0000-0000-0000-000000000015', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'reading', 'fill_blank', 'Lengkapi partikel durasi & akhir rentang: うち から えき [blank] １０ぷん かかります。', '{"options":["まで","を","に","と"],"translation":"Dari rumah sampai stasiun memakan waktu 10 menit.","sentence_template":"うち から えき [blank] １０ぷん かかります。"}'::jsonb, '{"selected":"まで"}'::jsonb, NULL, '{"から":"から adalah titik awal; titik akhir adalah まで."}'::jsonb, 'Pasangan ～から ～まで berarti "dari ... sampai ...".', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000054', 'b0000001-0000-0000-0000-000000000015', '05ca9c23-60a3-4eb9-bc58-259bbf0033c9', 'writing', 'sentence_builder', 'Susun kalimat perjalanan: "Saya pergi bersama teman ke stasiun."', '{"romaji":"Tomodachi to eki e ikimasu.","tokens":["ともだち","と","えき","へ","いきます"],"target_translation":"Pergi bersama teman ke stasiun."}'::jsonb, '["ともだち","と","えき","へ","いきます"]'::jsonb, NULL, NULL, 'Partikel と setelah orang berarti "bersama ...".', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000055', 'b0000001-0000-0000-0000-000000000015', '05ca9c23-60a3-4eb9-bc58-259bbf0033c9', 'listening', 'listening_choice', 'Dengarkan informasi transit ini. Naik apakah pembicara dari stasiun ke bandara?', '{"options":[{"id":"opt_1","text":"Bus"},{"id":"opt_2","text":"Kereta listrik"},{"id":"opt_3","text":"Taksi"},{"id":"opt_4","text":"Sepeda"}],"audio_text":"えきから バスで くうこうへ いきます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'バスで berarti menggunakan bus sebagai transportasi.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000056', 'b0000001-0000-0000-0000-000000000015', '79e54427-faad-401e-b423-a97ff3e695d8', 'reading', 'fill_blank', 'Lengkapi ungkapan bersama-sama: わたし は ひとりで [blank]。', '{"options":["いきます","あります","います","たべます"],"translation":"Saya pergi sendirian.","sentence_template":"わたし は ひとりで [blank]。"}'::jsonb, '{"selected":"いきます"}'::jsonb, NULL, NULL, 'ひとりで (hitori de) berarti melakukan aksi sendirian tanpa pendamping.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
