INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('351eb0a3-f2d0-4959-a712-cb63b371e291', 'b0000001-0000-0000-0000-000000000016', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Pilih kata kerja keberadaan untuk komputer (benda mati): つくえの うえに パソコンが ___。', '{"options":["あります","います","いきます","します"],"translation":"Di atas meja ada komputer.","sentence_template":"つくえの うえに パソコンが [blank]。"}'::jsonb, '{"selected":"あります"}'::jsonb, NULL, '{"います":"います hanya digunakan untuk manusia dan hewan."}'::jsonb, 'Komputer (パソコン) adalah benda mati sehingga wajib menggunakan あります.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('84745a2e-2d00-4494-b0f7-337c9e35e3b8', 'b0000001-0000-0000-0000-000000000016', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat keberadaan orang: "Di ruang rapat ada Pak Tanaka."', '{"romaji":"Kaigishitsu ni Tanaka-san ga imasu.","tokens":["かいぎしつ","に","たなかさん","が","います","あります"],"target_translation":"Di ruang rapat ada Pak Tanaka."}'::jsonb, '["かいぎしつ","に","たなかさん","が","います"]'::jsonb, '[["会議室に田中さんがいます"]]'::jsonb, '{"あります":"Pak Tanaka adalah manusia sehingga memakai います, bukan あります."}'::jsonb, 'Tempat lokasi keberadaan ditandai partikel に, dan subjek orang memakai partikel が + います.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('670a8669-75ed-4bf1-8bb7-cf9590fe6b81', 'b0000001-0000-0000-0000-000000000016', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan: "Apakah ada minimarket di dekat stasiun?"', '{"romaji":"Eki no chikaku ni konbini ga arimasu ka.","display_text":"えきのちかくにコンビニがありますか","phonetic_breakdown":["e-ki","no","chi-ka-ku","ni","kon-bi-ni","ga","a-ri-ma-su","ka"]}'::jsonb, '{"expected_transcript":"えきのちかくにコンビニがありますか"}'::jsonb, '[["駅の近くにコンビニがありますか"]]'::jsonb, NULL, 'Frasa 「えきの ちかくに」 berarti di dekat stasiun.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000071', 'b0000001-0000-0000-0000-000000000016', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Pilih kata kerja keberadaan untuk benda mati: つくえ の うえ に ほん が [blank]。', '{"options":["あります","います","いきます","します"],"translation":"Di atas meja ada buku.","sentence_template":"つくえ の うえ に ほん が [blank]。"}'::jsonb, '{"selected":"あります"}'::jsonb, NULL, '{"います":"います hanya untuk makhluk hidup (orang/hewan)."}'::jsonb, 'Benda mati memakai あります (arimasu), sedangkan manusia/hewan memakai います.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000072', 'b0000001-0000-0000-0000-000000000016', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Pilih kata kerja keberadaan untuk orang/hewan: へや に ねこ が [blank]。', '{"options":["います","あります","みます","きます"],"translation":"Di dalam kamar ada kucing.","sentence_template":"へや に ねこ が [blank]。"}'::jsonb, '{"selected":"います"}'::jsonb, NULL, '{"あります":"Kucing adalah makhluk hidup sehingga memakai います."}'::jsonb, 'Makhluk hidup yang bergerak sendiri selalu memakai います (imasu).', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000073', 'b0000001-0000-0000-0000-000000000016', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat keberadaan benda: "Di taman tidak ada toko."', '{"romaji":"Kouen ni mise wa arimasen.","tokens":["こうえん","に","みせ","は","ありません"],"target_translation":"Di taman tidak ada toko."}'::jsonb, '["こうえん","に","みせ","は","ありません"]'::jsonb, NULL, NULL, 'Bentuk negatif dari あります adalah ありません.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000074', 'b0000001-0000-0000-0000-000000000016', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan kalimat keberadaan ini. Siapakah yang ada di kantor?', '{"options":[{"id":"opt_1","text":"Tuan Tanaka"},{"id":"opt_2","text":"Buku laporan"},{"id":"opt_3","text":"Komputer"},{"id":"opt_4","text":"Kursi baru"}],"audio_text":"じむしょに たなかさんが います。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'たなかさんが います menyatakan keberadaan Tuan Tanaka di kantor.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-160005000008', 'b0000001-0000-0000-0000-000000000016', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Di taman ada banyak orang'':', '{"options":["います","あります","します","きます"],"translation":"Imasu","sentence_template":"こうえん に ひと が たくさん [blank]"}'::jsonb, '{"selected":"います"}'::jsonb, NULL, NULL, 'Orang (hito) bernyawa -> います.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-160005000009', 'b0000001-0000-0000-0000-000000000016', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Ada banyak orang":', '{"romaji":"Hito ga takusan imasu","tokens":["ひと","が","たくさん","います"],"target_translation":"Ada banyak orang"}'::jsonb, '["ひと","が","たくさん","います"]'::jsonb, NULL, NULL, 'Hito ga takusan imasu.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5ea27046-f1a9-4792-92e5-e48939267f8b', 'b0000001-0000-0000-0000-000000000017', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Lengkapi kata posisi yang berarti "di dalam tas": かばんの ___ に かぎが あります。', '{"options":["なか","うえ","した","そと"],"translation":"Di dalam tas ada kunci.","sentence_template":"かばんの [blank] に かぎが あります。"}'::jsonb, '{"selected":"なか"}'::jsonb, NULL, '{"うえ":"うえ berarti di atas, bukan di dalam.","した":"した berarti di bawah."}'::jsonb, 'Kosakata posisi: なか (dalam), うえ (atas), した (bawah), まえ (depan), うしろ (belakang).', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('972ff89e-f97f-458f-bcef-7ad590833ec9', 'b0000001-0000-0000-0000-000000000017', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat posisi: "Bank ada di depan stasiun."', '{"romaji":"Ginkou wa eki no mae ni arimasu.","tokens":["ぎんこう","は","えき","の","まえ","に","あります"],"target_translation":"Bank ada di depan stasiun."}'::jsonb, '["ぎんこう","は","えき","の","まえ","に","あります"]'::jsonb, '[["銀行は駅の前にあります"]]'::jsonb, NULL, 'Saat menjadi topik, letak benda ditulis di pola: [Benda] は [Patokan] の [Posisi] に あります.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fbc1e241-582b-478c-b838-8d080f146b5a', 'b0000001-0000-0000-0000-000000000017', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan petunjuk posisi berikut. Di manakah posisi ATM?', '{"options":[{"id":"opt_1","text":"Di sebelah kantor pos"},{"id":"opt_2","text":"Di belakang rumah sakit"},{"id":"opt_3","text":"Di lantai dua bank"},{"id":"opt_4","text":"Di dalam restoran"}],"audio_text":"ＡＴＭは ゆうびんきょくの となりに あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"ゆうびんきょく berarti kantor pos, bukan rumah sakit (びょういん)."}'::jsonb, '「ゆうびんきょくの となり」 berarti di sebelah kantor pos.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000075', 'b0000001-0000-0000-0000-000000000017', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Lengkapi kata posisi "di dalam": かばん の [blank] に かぎ が あります。', '{"options":["なか","うえ","そと","まえ"],"translation":"Di dalam tas ada kunci.","sentence_template":"かばん の [blank] に かぎ が あります。"}'::jsonb, '{"selected":"なか"}'::jsonb, NULL, '{"うえ":"うえ berarti di atas."}'::jsonb, 'なか (naka) berarti di dalam; pattern: [Wadah] の なかに.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000076', 'b0000001-0000-0000-0000-000000000017', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat posisi benda: "Kucing ada di bawah kursi."', '{"romaji":"Isu no shita ni neko ga imasu.","tokens":["いす","の","した","に","ねこ","が","います"],"target_translation":"Kucing ada di bawah kursi."}'::jsonb, '["いす","の","した","に","ねこ","が","います"]'::jsonb, NULL, NULL, 'した (shita) berarti di bawah; makhluk hidup memakai います.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000077', 'b0000001-0000-0000-0000-000000000017', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan letak benda ini. Di manakah HP berada?', '{"options":[{"id":"opt_1","text":"Di depan TV"},{"id":"opt_2","text":"Di belakang TV"},{"id":"opt_3","text":"Di atas lemari"},{"id":"opt_4","text":"Di dalam laci"}],"audio_text":"スマホは テレビの まえに あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'テレビの まえ berarti di depan televisi.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000078', 'b0000001-0000-0000-0000-000000000017', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Kata posisi "di sebelah" adalah:', '{"options":["となり","した","なか","うしろ"],"translation":"Kantor pos ada di sebelah bank.","sentence_template":"ゆうびんきょく は ぎんこう の [blank] です。"}'::jsonb, '{"selected":"となり"}'::jsonb, NULL, '{"うしろ":"うしろ berarti di belakang."}'::jsonb, 'となり (tonari) berarti tepat di sebelah / berdampingan.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-170002000008', 'b0000001-0000-0000-0000-000000000017', NULL, 'reading', 'fill_blank', 'Kanji 下 dibaca ''shita'' yang berarti:', '{"options":["bawah","atas","kiri","kanan"],"sentence_template":"Kanji 下: [blank]"}'::jsonb, '{"selected":"bawah"}'::jsonb, NULL, NULL, 'Kanji 下 berarti bawah (shita, ka).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
