INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4e5f1d0a-ad9a-4f54-9cee-5372b21a0af5', 'b0000001-0000-0000-0000-000000000018', 'dd9fe2c9-ae3f-438c-9f46-0fdd53524078', 'reading', 'fill_blank', 'Pilih partikel daftar sebagian contoh (seperti ..., ..., dan lain-lain): つくえの うえに ペン ___ ノートなどが あります。', '{"options":["や","と","も","の"],"translation":"Di atas meja ada pulpen, buku catatan, dan lain-lain.","sentence_template":"つくえの うえに ペン [blank] ノートなどが あります。"}'::jsonb, '{"selected":"や"}'::jsonb, NULL, '{"と":"Partikel と menyebut semua item tanpa kata など (dll.)."}'::jsonb, 'Kombinasi 「[A] や [B] など」 digunakan saat menyebut beberapa contoh benda.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f524154f-4bc1-43b4-bb29-507c1395e925', 'b0000001-0000-0000-0000-000000000018', 'dd9fe2c9-ae3f-438c-9f46-0fdd53524078', 'writing', 'sentence_builder', 'Susun pesanan jumlah benda: "Tolong dua buah roti."', '{"romaji":"Pan o futatsu kudasai.","tokens":["パン","を","ふたつ","ください","ふたり"],"target_translation":"Tolong dua buah roti."}'::jsonb, '["パン","を","ふたつ","ください"]'::jsonb, NULL, '{"ふたり":"ふたり dipakai untuk menghitung 2 orang, sedangkan 2 buah benda adalah ふたつ."}'::jsonb, 'Kata bantu bilangan benda umum: ひとつ (1 buah), ふたつ (2 buah), みっつ (3 buah).', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b2ba65a-302a-487a-b1ca-7e085cead82a', 'b0000001-0000-0000-0000-000000000018', 'dd9fe2c9-ae3f-438c-9f46-0fdd53524078', 'speaking', 'speaking_repeat', 'Ucapkan kalimat berikut: "Saya membeli buku catatan dan pensil."', '{"romaji":"Nooto to enpitsu o kaimasu.","display_text":"ノートとえんぴつをかいます","phonetic_breakdown":["noo-to","to","en-pi-tsu","o","ka-i-ma-su"]}'::jsonb, '{"expected_transcript":"ノートとえんぴつをかいます"}'::jsonb, '[["ノートと鉛筆を買います"]]'::jsonb, NULL, 'Gunakan と untuk menggabungkan dua benda secara lengkap.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000079', 'b0000001-0000-0000-0000-000000000018', 'dd9fe2c9-ae3f-438c-9f46-0fdd53524078', 'reading', 'fill_blank', 'Lengkapi partikel untuk menyebutkan sebagian contoh benda: へや に テーブル [blank] いす など が あります。', '{"options":["や","と","を","に"],"translation":"Di kamar ada meja, kursi, dan lain-lain.","sentence_template":"へや に テーブル [blank] いす など が あります。"}'::jsonb, '{"selected":"や"}'::jsonb, NULL, '{"と":"と untuk daftar lengkap, sedangkan や dipasangkan dengan など untuk contoh saja."}'::jsonb, 'Pola [A] や [B] など menyebutkan contoh tidak lengkap ("A, B, dan lain-lain").', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000080', 'b0000001-0000-0000-0000-000000000018', 'dd9fe2c9-ae3f-438c-9f46-0fdd53524078', 'writing', 'sentence_builder', 'Susun daftar lengkap: "Di dalam kotak ada pensil dan penghapus."', '{"romaji":"Hako no naka ni enpitsu to keshigomu ga arimasu.","tokens":["はこ","の","なかに","えんぴつ","と","けしゴム","が","あります"],"target_translation":"Ada pensil dan penghapus di kotak."}'::jsonb, '["はこ","の","なかに","えんぴつ","と","けしゴム","が","あります"]'::jsonb, NULL, NULL, 'Partikel と menyambungkan semua benda yang disebutkan secara lengkap.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000081', 'b0000001-0000-0000-0000-000000000018', 'dd9fe2c9-ae3f-438c-9f46-0fdd53524078', 'listening', 'listening_choice', 'Dengarkan jumlah benda berikut. Berapa buah jeruk yang dibeli?', '{"options":[{"id":"opt_1","text":"3 buah"},{"id":"opt_2","text":"1 buah"},{"id":"opt_3","text":"5 buah"},{"id":"opt_4","text":"8 buah"}],"audio_text":"みかんを みっつ かいました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Hitungan umum benda: ひとつ(1), ふたつ(2), みっつ(3), よっつ(4).', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000082', 'b0000001-0000-0000-0000-000000000018', 'dd9fe2c9-ae3f-438c-9f46-0fdd53524078', 'reading', 'fill_blank', 'Satuan hitung umum untuk "2 buah benda" adalah:', '{"options":["ふたつ","ひとつ","みっつ","いつつ"],"translation":"Tolong dua potong kue.","sentence_template":"ケーキ を [blank] ください。"}'::jsonb, '{"selected":"ふたつ"}'::jsonb, NULL, NULL, 'ふたつ (futatsu) berarti dua buah untuk benda umum.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
