INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-090002000012', 'b0000001-0000-0000-0000-000000000018', NULL, 'reading', 'fill_blank', 'Lengkapi kata ''toko / kedai'' (mise):', '{"options":["みせ","まち","えき","へや"],"translation":"Toko","sentence_template":"お [blank]"}'::jsonb, '{"selected":"みせ"}'::jsonb, NULL, NULL, 'おみせ (omise) = toko.', 12, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c41d80c4-b792-47ba-937d-508fe45cc438', 'b0000001-0000-0000-0000-000000000019', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Lengkapi pertanyaan lokasi ruangan: じむしょは ___ ですか。', '{"options":["どこ","いつ","だれ","いくつ"],"translation":"Di manakah ruang kantor administrasi?","sentence_template":"じむしょは [blank] ですか。"}'::jsonb, '{"selected":"どこ"}'::jsonb, NULL, '{"いつ":"いつ menanyakan waktu (kapan), bukan lokasi."}'::jsonb, 'Kata tanya lokasi standar adalah どこ (di mana), atau bentuk sopannya どちら.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f38c178a-48bc-435a-92df-45d1e85a3ce5', 'b0000001-0000-0000-0000-000000000019', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan arahan staf berikut. Di mana letak ruang istirahat?', '{"options":[{"id":"opt_1","text":"Di lantai 2"},{"id":"opt_2","text":"Di lantai 1"},{"id":"opt_3","text":"Di basement (B1)"},{"id":"opt_4","text":"Di gedung sebelah"}],"audio_text":"きゅうけいしつは ２かいに あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Lantai 1 adalah いっかい (1かい), sedangkan yang terdengar adalah にかい (2かい)."}'::jsonb, 'Akhiran かい/がい digunakan untuk lantai gedung: 1かい (ikkai), 2かい (nikai), 3がい (sangai).', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c6769e4f-1b89-4ae7-9069-ea4912997fdf', 'b0000001-0000-0000-0000-000000000019', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun pertanyaan lokasi sopan: "Permisi, di manakah stasiun?"', '{"romaji":"Sumimasen, eki wa doko desu ka.","tokens":["すみません","えき","は","どこ","ですか","だれ"],"target_translation":"Permisi, di manakah stasiun?"}'::jsonb, '["すみません","えき","は","どこ","ですか"]'::jsonb, '[["すみません駅はどこですか"]]'::jsonb, '{"だれ":"だれ berarti siapa."}'::jsonb, 'Awali pertanyaan di tempat umum dengan 「すみません」 agar terdengar santun.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000083', 'b0000001-0000-0000-0000-000000000019', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Lengkapi pertanyaan lokasi: トイレ は [blank] に ありますか。', '{"options":["どこ","だれ","いつ","いくつ"],"translation":"Toilet ada di mana?","sentence_template":"トイレ は [blank] に ありますか。"}'::jsonb, '{"selected":"どこ"}'::jsonb, NULL, NULL, 'どこ menanyakan tempat ("di mana").', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000084', 'b0000001-0000-0000-0000-000000000019', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat keberadaan fasilitas: "Di depan stasiun ada toko buku."', '{"romaji":"Eki no mae ni honya ga arimasu.","tokens":["えき","の","まえ","に","ほんや","が","あります"],"target_translation":"Di depan stasiun ada toko buku."}'::jsonb, '["えき","の","まえ","に","ほんや","が","あります"]'::jsonb, NULL, NULL, 'Lokasi ditandai に dan benda mati yang ada ditandai dengan が あります.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000085', 'b0000001-0000-0000-0000-000000000019', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan petunjuk lokasi berikut. Apa yang ada di lantai dua?', '{"options":[{"id":"opt_1","text":"Ruang rapat"},{"id":"opt_2","text":"Kantin"},{"id":"opt_3","text":"Kamar mandi"},{"id":"opt_4","text":"Resepsionis"}],"audio_text":"にかいに かいぎしつが あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'かいぎしつ (kaigishitsu) adalah ruang rapat, にかい adalah lantai 2.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000086', 'b0000001-0000-0000-0000-000000000019', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Tempat untuk mengirim surat dan paket adalah:', '{"options":["ゆうびんきょく","びょういん","がっこう","くうこう"],"translation":"Membeli perangko di kantor pos.","sentence_template":"[blank] で きって を かいます。"}'::jsonb, '{"selected":"ゆうびんきょく"}'::jsonb, NULL, NULL, 'ゆうびんきょく (yuubinkyoku) berarti kantor pos.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000087', 'b0000001-0000-0000-0000-000000000019', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Kata untuk menyebut "ruang kerja / kantor" di dalam gedung adalah:', '{"options":["じむしょ","だいどころ","げんかん","にわ"],"translation":"Komputer ada di ruang kerja kantor.","sentence_template":"パソコン は [blank] に あります。"}'::jsonb, '{"selected":"じむしょ"}'::jsonb, NULL, NULL, 'じむしょ (jimusho) adalah kantor atau ruang administrasi.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-160002000009', 'b0000001-0000-0000-0000-000000000019', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Di meja ada komputer'':', '{"options":["あります","います","します","です"],"sentence_template":"つくえ に パソコン が [blank]"}'::jsonb, '{"selected":"あります"}'::jsonb, NULL, NULL, 'Komputer adalah benda mati -> あります.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-160002000010', 'b0000001-0000-0000-0000-000000000019', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Ada komputer":', '{"romaji":"Pasokon ga arimasu","tokens":["パソコン","が","あります"],"target_translation":"Ada komputer"}'::jsonb, '["パソコン","が","あります"]'::jsonb, NULL, NULL, 'Pasokon ga arimasu.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cff60a04-bc22-49ad-8267-2d70d6ff7181', 'b0000001-0000-0000-0000-000000000020', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Ubah kata sifat 「たかい」(mahal) ke bentuk negatif sopan: この へやは たか ___ です。', '{"options":["くない","じゃありません","い","かった"],"translation":"Kamar ini tidak mahal.","sentence_template":"この へやは たか [blank] です。"}'::jsonb, '{"selected":"くない"}'::jsonb, NULL, '{"じゃありません":"Adjektiva-I memakai akhiran ～くないです, bukan じゃありません."}'::jsonb, 'Hilangkan akhiran い pada たかい lalu tambahkan くないです → たかくないです.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f1c4ff50-3c41-44af-9ffd-4d0aa7ca4e44', 'b0000001-0000-0000-0000-000000000020', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'writing', 'sentence_builder', 'Susun kalimat deskripsi: "Hari ini sangat panas."', '{"romaji":"Kyou wa totemo atsui desu.","tokens":["きょう","は","とても","あつい","です","あつくない"],"target_translation":"Hari ini sangat panas."}'::jsonb, '["きょう","は","とても","あつい","です"]'::jsonb, '[["今日はとても暑いです"]]'::jsonb, '{"あつくない":"Kalimat meminta pernyataan positif (panas), bukan tidak panas."}'::jsonb, 'Kata keterangan penguat 「とても」 ("sangat") digunakan bersama kalimat adjektiva positif.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ec078b3e-2677-4e1e-9fee-3d634dae60c9', 'b0000001-0000-0000-0000-000000000020', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'speaking', 'speaking_repeat', 'Ucapkan kalimat berikut: "Makanan restoran ini enak."', '{"romaji":"Kono mise no ryouri wa oishii desu.","display_text":"このみせのりょうりはおいしいです","phonetic_breakdown":["ko-no","mi-se","no","ryou-ri","wa","o-i-shii","de-su"]}'::jsonb, '{"expected_transcript":"このみせのりょうりはおいしいです"}'::jsonb, '[["この店の料理はおいしいです"]]'::jsonb, NULL, 'Adjektiva-I tetap mempertahankan huruf い di depan です pada kalimat positif kini.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000104', 'b0000001-0000-0000-0000-000000000020', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Bentuk negatif yang benar dari kata sifat-i "おおきい" (besar) adalah:', '{"options":["おおきくない","おおきいじゃない","おおきいくない","おおきでした"],"translation":"Kamar saya tidak besar.","sentence_template":"わたし の へや は [blank] です。"}'::jsonb, '{"selected":"おおきくない"}'::jsonb, NULL, '{"おおきいじゃない":"Kata sifat-i tidak memakai じゃない, melainkan buang い lalu tambah くない."}'::jsonb, 'Aturan kata sifat-i: hapus huruf い terakhir, ganti dengan くないです.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000105', 'b0000001-0000-0000-0000-000000000020', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Kata sifat-i "いい" (bagus/baik) jika diubah menjadi negatif menjadi:', '{"options":["よくない","いくない","いいじゃない","よかった"],"translation":"Hari ini cuacanya tidak bagus.","sentence_template":"きょう は てんき が [blank] です。"}'::jsonb, '{"selected":"よくない"}'::jsonb, NULL, NULL, 'いい memiliki konjugasi khusus memakai akar よ → よくない (tidak bagus).', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000106', 'b0000001-0000-0000-0000-000000000020', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'writing', 'sentence_builder', 'Susun kalimat: "Kereta Jepang sangat cepat dan praktis."', '{"romaji":"Nihon no densha wa hayai desu.","tokens":["にほん","の","でんしゃ","は","はやい","です"],"target_translation":"Kereta Jepang cepat."}'::jsonb, '["にほん","の","でんしゃ","は","はやい","です"]'::jsonb, NULL, NULL, 'はやい (hayai) adalah kata sifat-i yang berarti cepat.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000107', 'b0000001-0000-0000-0000-000000000020', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'listening', 'listening_choice', 'Dengarkan deskripsi makanan ini. Bagaimana rasanya?', '{"options":[{"id":"opt_1","text":"Sedikit pedas"},{"id":"opt_2","text":"Sangat manis"},{"id":"opt_3","text":"Agak asin"},{"id":"opt_4","text":"Terlalu pahit"}],"audio_text":"この カレーは すこし からいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'からい (karai) berarti pedas dan すこし (sukoshi) berarti sedikit.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180005000008', 'b0000001-0000-0000-0000-000000000020', NULL, 'reading', 'fill_blank', 'Kata sifat-I yang memodifikasi langsung kata benda ditempatkan [blank] nomina:', '{"options":["di depan","di belakang","setelah partikel","di akhir kalimat"],"sentence_template":"Posisi atributif sifat-I: [blank] kata benda"}'::jsonb, '{"selected":"di depan"}'::jsonb, NULL, NULL, 'Sifat-I menempel langsung di depan nomina: 高い 本 (buku yang mahal).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180005000009', 'b0000001-0000-0000-0000-000000000020', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Rumah besar":', '{"romaji":"Ookii ie","tokens":["大きい","家"],"target_translation":"Rumah besar"}'::jsonb, '["大きい","家"]'::jsonb, NULL, NULL, '大きい 家.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('17414462-daf5-451f-aedc-fb9f60ffebb2', 'b0000001-0000-0000-0000-000000000021', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'reading', 'fill_blank', 'Lengkapi penghubung kata sifat-Na sebelum kata benda: きょうとは ___ まち です。', '{"options":["しずかな","しずかい","しずか","しずかに"],"translation":"Kyoto adalah kota yang tenang.","sentence_template":"きょうとは [blank] まち です。"}'::jsonb, '{"selected":"しずかな"}'::jsonb, NULL, '{"しずか":"Saat menerangkan kata benda (まち) di depannya, wajib menambahkan な."}'::jsonb, 'Kata sifat-Na (seperti しずか, べんり, きれい) membutuhkan な sebelum nomina.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ce51a2c7-1071-4eac-aeb7-dcf501586166', 'b0000001-0000-0000-0000-000000000021', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'writing', 'sentence_builder', 'Susun kalimat: "Kereta Tokyo praktis."', '{"romaji":"Toukyou no densha wa benri desu.","tokens":["とうきょう","の","でんしゃ","は","べんり","です","べんりな"],"target_translation":"Kereta Tokyo praktis."}'::jsonb, '["とうきょう","の","でんしゃ","は","べんり","です"]'::jsonb, '[["東京の電車は便利です"]]'::jsonb, '{"べんりな":"Di akhir kalimat sebelum です, な tidak dipakai."}'::jsonb, 'Saat menjadi predikat sebelum です, adjektiva-Na langsung diikuti です tanpa な.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ade385ae-fadf-475b-80f1-d595a79bbd19', 'b0000001-0000-0000-0000-000000000021', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'listening', 'listening_choice', 'Dengarkan penilaian berikut. Apa pendapat pembicara tentang kota asalnya?', '{"options":[{"id":"opt_1","text":"Tenang dan bersih/indah"},{"id":"opt_2","text":"Ramai dan mahal"},{"id":"opt_3","text":"Kecil dan tidak praktis"},{"id":"opt_4","text":"Dingin dan jauh"}],"audio_text":"わたしの まちは しずかで きれいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Kata yang diucapkan adalah しずか (tenang) dan きれい (indah/bersih)."}'::jsonb, 'Dua kata sifat-Na disambungkan menggunakan partikel で: しずかで きれいです.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000108', 'b0000001-0000-0000-0000-000000000021', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'reading', 'fill_blank', 'Kata sifat-na sebelum kata benda WAJIB disambungkan dengan:', '{"options":["にぎやかな","にぎやか","にぎやかい","にぎやかくない"],"translation":"Tokyo adalah kota yang ramai.","sentence_template":"トーキョー は [blank] まち です。"}'::jsonb, '{"selected":"にぎやかな"}'::jsonb, NULL, '{"にぎやか":"Sebelum kata benda まち, kata sifat-na wajib memakai な."}'::jsonb, 'Pola modifikasi benda: [Kata Sifat-Na] + な + [Kata Benda].', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000109', 'b0000001-0000-0000-0000-000000000021', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'reading', 'fill_blank', 'Bentuk negatif sopan kata sifat-na "ひま" (senggang) adalah:', '{"options":["ひま ではありません","ひまくない です","ひま な ありません","ひま ました"],"translation":"Hari ini saya tidak senggang.","sentence_template":"きょう は [blank]。"}'::jsonb, '{"selected":"ひま ではありません"}'::jsonb, NULL, NULL, 'Kata sifat-na dinegasikan sama seperti kata benda: ～ではありません / ～じゃありません.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000110', 'b0000001-0000-0000-0000-000000000021', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'writing', 'sentence_builder', 'Susun kalimat pujian kerja: "Senior saya sangat ramah dan pintar."', '{"romaji":"Senpai wa totemo shinsetsu desu.","tokens":["せんぱい","は","とても","しんせつ","です"],"target_translation":"Senior sangat ramah."}'::jsonb, '["せんぱい","は","とても","しんせつ","です"]'::jsonb, NULL, NULL, 'しんせつ (shinsetsu) berarti ramah / suka menolong (kata sifat-na).', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000111', 'b0000001-0000-0000-0000-000000000021', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'listening', 'listening_choice', 'Dengarkan penilaian berikut. Kota seperti apakah Kyoto?', '{"options":[{"id":"opt_1","text":"Tenang dan indah"},{"id":"opt_2","text":"Ramai dan mahal"},{"id":"opt_3","text":"Panas dan berisik"},{"id":"opt_4","text":"Baru dan modern"}],"audio_text":"きょうとは しずかで きれいな まちです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'しずかで (tenang dan ...) + きれいな (indah).', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-200001000008', 'b0000001-0000-0000-0000-000000000021', NULL, 'reading', 'fill_blank', 'Kata sifat-Na yang berarti ''terkenal'' adalah:', '{"options":["ゆうめいな","しずかな","きれいな","ひまな"],"translation":"Yuumei"}'::jsonb, '{"selected":"ゆうめいな"}'::jsonb, NULL, NULL, 'ゆうめいな (yuumeina) = terkenal.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-200001000009', 'b0000001-0000-0000-0000-000000000021', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Orang terkenal":', '{"romaji":"Yuumeina hito","tokens":["有名","な","人"],"target_translation":"Orang terkenal"}'::jsonb, '["有名","な","人"]'::jsonb, NULL, NULL, '有名 な 人.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-200001000010', 'b0000001-0000-0000-0000-000000000021', NULL, 'speaking', 'speaking_repeat', 'Ucapkan frasa ''有名 な 人'':', '{"romaji":"yuumeina hito","audio_text":"有名 な 人","display_text":"有名 な 人"}'::jsonb, '{"expected_transcript":"有名 な 人"}'::jsonb, NULL, NULL, 'Lafalkan yuumeina hito.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('610cf3f9-85dd-4d9f-948f-0ce45e6de4e7', 'b0000001-0000-0000-0000-000000000022', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Ubah 「たのしい」(menyenangkan) menjadi bentuk lampau: きのうの パーティーは たのし ___ です。', '{"options":["かった","い","くない","でした"],"translation":"Pesta kemarin menyenangkan.","sentence_template":"きのうの パーティーは たのし [blank] です。"}'::jsonb, '{"selected":"かった"}'::jsonb, NULL, '{"でした":"Untuk adjektiva-I, bentuk lampau bukan たのしいでした melainkan たのしかったです."}'::jsonb, 'Bentuk lampau adjektiva-I dibentuk dengan mengganti い menjadi かったです.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7530426b-cc7b-45ff-9f7e-563224f9672e', 'b0000001-0000-0000-0000-000000000022', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'writing', 'sentence_builder', 'Susun kalimat lampau adjektiva-Na: "Minggu lalu tidak sibuk (senggang)."', '{"romaji":"Senshuu wa hima deshita.","tokens":["せんしゅう","は","ひま","でした","ではありませんでした"],"target_translation":"Minggu lalu senggang."}'::jsonb, '["せんしゅう","は","ひま","でした"]'::jsonb, '[["先週は暇でした"]]'::jsonb, '{"ではありませんでした":"Bentuk ini berarti tidak senggang."}'::jsonb, 'Adjektiva-Na dan nomina memakai でした untuk bentuk lampau positif.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eced376e-4875-4648-8398-245599fecafd', 'b0000001-0000-0000-0000-000000000022', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'speaking', 'speaking_repeat', 'Ucapkan kalimat berikut: "Ujian kemarin agak sulit."', '{"romaji":"Kinou no shiken wa sukoshi muzukashikatta desu.","display_text":"きのうのしけんはすこしむずかしかったです","phonetic_breakdown":["ki-nou","no","shi-ken","wa","su-ko-shi","mu-zu-ka-shi-kat-ta","de-su"]}'::jsonb, '{"expected_transcript":"きのうのしけんはすこしむずかしかったです"}'::jsonb, '[["昨日の試験は少し難しかったです"]]'::jsonb, NULL, 'むずかしい → むずかしかったです (dulu sulit).', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000112', 'b0000001-0000-0000-0000-000000000022', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Bentuk lampau positif dari kata sifat-i "たのしい" (menyenangkan) adalah:', '{"options":["たのしかった","たのしいでした","たのしくなかった","たのしだ"],"translation":"Pesta kemarin sangat menyenangkan.","sentence_template":"きのう の パーティー は [blank] です。"}'::jsonb, '{"selected":"たのしかった"}'::jsonb, NULL, NULL, 'Lampau positif kata sifat-i: hapus い terakhir lalu tambahkan かった.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000113', 'b0000001-0000-0000-0000-000000000022', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'writing', 'sentence_builder', 'Susun kalimat lampau negatif: "Cuaca kemarin tidak dingin."', '{"romaji":"Kinou wa samukunakatta desu.","tokens":["きのう","は","さむくなかった","です"],"target_translation":"Kemarin tidak dingin."}'::jsonb, '["きのう","は","さむくなかった","です"]'::jsonb, NULL, NULL, 'Lampau negatif kata sifat-i: ubah い menjadi くなかったです.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000114', 'b0000001-0000-0000-0000-000000000022', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'listening', 'listening_choice', 'Dengarkan pengalaman wisata ini. Bagaimana suhu di Hokkaido kemarin?', '{"options":[{"id":"opt_1","text":"Sangat dingin"},{"id":"opt_2","text":"Sangat panas"},{"id":"opt_3","text":"Sejuk nyaman"},{"id":"opt_4","text":"Hangat cerah"}],"audio_text":"ほっかいどうは とても さむかったです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'さむかった (bentuk lampau さむい) berarti dulu dingin.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000115', 'b0000001-0000-0000-0000-000000000022', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'reading', 'fill_blank', 'Bentuk lampau kata sifat-na "べんり" (praktis) adalah:', '{"options":["べんり でした","べんり かった です","べんり な です","べんり くない"],"translation":"Rumah sebelumnya praktis.","sentence_template":"まえ の いえ は [blank]。"}'::jsonb, '{"selected":"べんり でした"}'::jsonb, NULL, NULL, 'Kata sifat-na bentuk lampau positif memakai akhiran ～でした.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-200002000008', 'b0000001-0000-0000-0000-000000000022', NULL, 'reading', 'fill_blank', 'Kata sifat-Na yang berarti ''sehat / ceria / bersemangat'' adalah:', '{"options":["げんきな","べんりな","しんせつな","たいへんな"],"translation":"Genki"}'::jsonb, '{"selected":"げんきな"}'::jsonb, NULL, NULL, 'げんきな (genkina / Kanji 元気) = sehat/bersemangat.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-200002000009', 'b0000001-0000-0000-0000-000000000022', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Apa kabar?":', '{"romaji":"Ogenki desu ka","tokens":["お元気","ですか"],"target_translation":"Apa kabar?"}'::jsonb, '["お元気","ですか"]'::jsonb, NULL, NULL, 'Ogenki desu ka.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0ce221d-5e43-4223-bc21-c24bf44c7bf7', 'b0000001-0000-0000-0000-000000000023', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'reading', 'fill_blank', 'Lengkapi kalimat perbandingan: でんしゃは バス ___ はやいです。', '{"options":["より","ほど","いちばん","から"],"translation":"Kereta lebih cepat daripada bus.","sentence_template":"でんしゃは バス [blank] はやいです。"}'::jsonb, '{"selected":"より"}'::jsonb, NULL, '{"いちばん":"いちばん dipakai untuk superlatif (paling), bukan membandingkan A dan B."}'::jsonb, 'Partikel より ditempatkan setelah pembanding B: [A] は [B] より [Adjektiva] です.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0b27fb94-647d-4cb0-a665-67acb5cc250c', 'b0000001-0000-0000-0000-000000000023', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'writing', 'sentence_builder', 'Susun kalimat superlatif: "Di Jepang, musim semi yang paling saya sukai."', '{"romaji":"Nihon de haru ga ichiban suki desu.","tokens":["にほん","で","はる","が","いちばん","すき","です"],"target_translation":"Di antara musim, saya paling suka musim semi di Jepang."}'::jsonb, '["にほん","で","はる","が","いちばん","すき","です"]'::jsonb, '[["日本で春が一番好きです"]]'::jsonb, NULL, 'Gunakan 「〜が いちばん [Adjektiva] です」 untuk menyatakan hal nomor satu / paling.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e3776fec-92d3-428a-97fe-140cdc080864', 'b0000001-0000-0000-0000-000000000023', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'listening', 'listening_choice', 'Dengarkan pertanyaan perbandingan berikut. Apa yang ditanyakan?', '{"options":[{"id":"opt_1","text":"Antara kopi dan teh, mana yang lebih disukai?"},{"id":"opt_2","text":"Berapa harga kopi dan teh?"},{"id":"opt_3","text":"Di mana membeli kopi dan teh?"},{"id":"opt_4","text":"Apakah kopi lebih panas dari teh?"}],"audio_text":"コーヒーと おちゃと どちらが すきですか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Tidak ada kata tanya harga (いくら) dalam kalimat."}'::jsonb, 'Pola 「[A] と [B] と どちらが 〜 ですか」 menanyakan pilihan di antara dua hal.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000116', 'b0000001-0000-0000-0000-000000000023', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'reading', 'fill_blank', 'Partikel pembanding "dibandingkan dengan" adalah:', '{"options":["より","いちばん","ほど","と"],"translation":"Pesawat lebih cepat dibanding Shinkansen.","sentence_template":"ひこうき は しんかんせん [blank] はやい です。"}'::jsonb, '{"selected":"より"}'::jsonb, NULL, '{"いちばん":"いちばん dipakai untuk superlatif (\"paling\"), bukan membandingkan dua hal."}'::jsonb, 'Pola perbandingan A lebih ... daripada B memakai A は B より [Sifat] です.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000117', 'b0000001-0000-0000-0000-000000000023', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'writing', 'sentence_builder', 'Susun kalimat superlatif: "Di kelas, saya paling suka musim gugur."', '{"romaji":"Aki ga ichiban suki desu.","tokens":["あき","が","いちばん","すき","です"],"target_translation":"Musim gugur yang paling disukai."}'::jsonb, '["あき","が","いちばん","すき","です"]'::jsonb, NULL, NULL, 'いちばん berarti nomor satu / paling; dipasangkan dengan が untuk hal yang disukai.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000118', 'b0000001-0000-0000-0000-000000000023', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'listening', 'listening_choice', 'Dengarkan perbandingan ini. Buah manakah yang lebih disukai?', '{"options":[{"id":"opt_1","text":"Apel"},{"id":"opt_2","text":"Jeruk"},{"id":"opt_3","text":"Pisang"},{"id":"opt_4","text":"Melon"}],"audio_text":"みかんより りんごの ほうが すきです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Pola [A] より [B] のほうが berarti "B lebih ... daripada A".', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000119', 'b0000001-0000-0000-0000-000000000023', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'reading', 'fill_blank', 'Memilih satu dari dua pilihan menggunakan kata tanya:', '{"options":["どちら","だれ","いつ","いくら"],"translation":"Kopi atau teh, mana yang lebih Anda pilih?","sentence_template":"コーヒー と おちゃ と [blank] が いいですか。"}'::jsonb, '{"selected":"どちら"}'::jsonb, NULL, NULL, 'Untuk memilih antara dua hal (A と B と), kata tanyanya wajib どちら.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000120', 'b0000001-0000-0000-0000-000000000023', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Kata untuk warna "biru" dalam bentuk kata sifat-i adalah:', '{"options":["あおい","あかい","しろい","くろい"],"translation":"Saya melihat laut biru yang indah.","sentence_template":"きれいな [blank] うみ を みました。"}'::jsonb, '{"selected":"あおい"}'::jsonb, NULL, '{"あかい":"あかい berarti merah."}'::jsonb, 'Empat warna kata sifat-i dasar: あかい(merah), あおい(biru), しろい(putih), くろい(hitam).', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-200005000009', 'b0000001-0000-0000-0000-000000000023', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kesukaan ''Saya suka buah apel'':', '{"options":["すき","きらい","じょうず","へた"],"translation":"Suki","sentence_template":"わたし は りんご が [blank] です"}'::jsonb, '{"selected":"すき"}'::jsonb, NULL, NULL, 'Objek kesukaan ditandai partikel が + すき です.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-200005000010', 'b0000001-0000-0000-0000-000000000023', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Suka film Jepang":', '{"romaji":"Nihon no eiga ga suki desu","tokens":["日本","の","映画","が","好きです"],"target_translation":"Suka film Jepang"}'::jsonb, '["日本","の","映画","が","好きです"]'::jsonb, NULL, NULL, 'Nihon no eiga ga suki desu.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eb9b6efe-fdb2-4042-8030-b8b237c5240c', 'b0000001-0000-0000-0000-000000000024', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Lengkapi permintaan sopan di kantor: ここに なまえを ___ ください。', '{"options":["かいて","かきます","かいた","かないで"],"translation":"Tolong tulis nama Anda di sini.","sentence_template":"ここに なまえを [blank] ください。"}'::jsonb, '{"selected":"かいて"}'::jsonb, NULL, '{"かきます":"Sebelum ください harus berbentuk-TE (かいて), bukan bentuk-MASU."}'::jsonb, 'Verba かきます (menulis) diubah ke bentuk-TE menjadi かいて + ください.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6cb19320-7e89-4e61-8d1e-4e2ab67c5827', 'b0000001-0000-0000-0000-000000000024', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat instruksi santun: "Tolong bicara perlahan."', '{"romaji":"Sumimasen, yukkuri hanashite kudasai.","tokens":["すみません","ゆっくり","はなして","ください","はなします"],"target_translation":"Permisi, tolong bicara perlahan."}'::jsonb, '["すみません","ゆっくり","はなして","ください"]'::jsonb, '[["すみませんゆっくり話してください"]]'::jsonb, '{"はなします":"Bentuk-TE dari はなします adalah はなして."}'::jsonb, 'Ungkapan 「ゆっくり はなしてください」 sangat berguna saat belum menangkap ucapan lawan bicara.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dbd242a2-a7e5-475e-a498-74290bdfae1e', 'b0000001-0000-0000-0000-000000000024', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'speaking', 'speaking_repeat', 'Ucapkan permohonan bantuan ini: "Tolong ajari saya kalimat ini."', '{"romaji":"Oshiete kudasai.","display_text":"おしえてください","phonetic_breakdown":["o-shi-e-te","ku-da-sai"]}'::jsonb, '{"expected_transcript":"おしえてください"}'::jsonb, '[["教えてください"]]'::jsonb, NULL, 'おしえます (mengajar/memberi tahu) → おしえてください (tolong ajari / beri tahu).', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000137', 'b0000001-0000-0000-0000-000000000024', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Bentuk-TE yang benar dari verba "かきます" (menulis) adalah:', '{"options":["かいて","かきって","かいで","かきて"],"translation":"Tolong tulis nama di sini.","sentence_template":"ここ に なまえ を [blank] ください。"}'::jsonb, '{"selected":"かいて"}'::jsonb, NULL, '{"かいで":"き berubah menjadi いて (かいて), sedangkan ぎ menjadi いで."}'::jsonb, 'Verba berakhiran きimasu berubah menjadi ～いて dalam bentuk-TE (かきます → かいて).', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000138', 'b0000001-0000-0000-0000-000000000024', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Bentuk-TE pengecualian dari verba "いきます" (pergi) adalah:', '{"options":["いって","いいて","いきって","いんで"],"translation":"Saya pergi sebentar ke toko lalu kembali.","sentence_template":"ちょっと みせ へ [blank] きます。"}'::jsonb, '{"selected":"いって"}'::jsonb, NULL, NULL, 'いきます adalah pengecualian grup I: bentuk-TE-nya adalah いって, bukan いいて.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000139', 'b0000001-0000-0000-0000-000000000024', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat instruksi kantor: "Tolong nyalakan lampu ruangan."', '{"romaji":"Heya no denki o tsukete kudasai.","tokens":["へや","の","でんき","を","つけて","ください"],"target_translation":"Tolong nyalakan lampu ruangan."}'::jsonb, '["へや","の","でんき","を","つけて","ください"]'::jsonb, NULL, NULL, 'つけます (menyalakan) menjadi つけて + ください.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000140', 'b0000001-0000-0000-0000-000000000024', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan permintaan atasan ini. Apa yang diminta untuk dilakukan?', '{"options":[{"id":"opt_1","text":"Menutup pintu"},{"id":"opt_2","text":"Membuka jendela"},{"id":"opt_3","text":"Mematikan AC"},{"id":"opt_4","text":"Mencetak dokumen"}],"audio_text":"ドアを しめて ください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ドアを しめて ください berarti tolong tutup pintunya.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000141', 'b0000001-0000-0000-0000-000000000024', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Bentuk-TE yang benar dari "よびます" (memanggil) adalah:', '{"options":["よんで","よびて","よんて","よって"],"translation":"Tolong panggilkan Tuan Tanaka.","sentence_template":"たなかさん を [blank] ください。"}'::jsonb, '{"selected":"よんで"}'::jsonb, NULL, NULL, 'Akar び/み/に pada verba grup I berubah menjadi ～んで (よびます → よんで).', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210001000009', 'b0000001-0000-0000-0000-000000000024', NULL, 'reading', 'fill_blank', 'Bentuk-TE dari verba はなします (berbicara) adalah:', '{"options":["はなして","はなちて","はなって","はなしてで"],"translation":"Hanashite","sentence_template":"はなします -> [blank]"}'::jsonb, '{"selected":"はなして"}'::jsonb, NULL, NULL, 'Konsonan shi -> して: はなして.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210001000010', 'b0000001-0000-0000-0000-000000000024', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Bicara pelan-pelan":', '{"romaji":"Yukkuri hanashite kudasai","tokens":["ゆっくり","話して","ください"],"target_translation":"Bicara pelan-pelan"}'::jsonb, '["ゆっくり","話して","ください"]'::jsonb, NULL, NULL, 'Yukkuri hanashite kudasai.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210001000011', 'b0000001-0000-0000-0000-000000000024', NULL, 'speaking', 'speaking_repeat', 'Ucapkan permintaan penting saat belajar ''もう一度 言って ください'' (Tolong sekali lagi):', '{"romaji":"mou ichido itte kudasai","audio_text":"もう一度 言って ください","display_text":"もう一度 言って ください"}'::jsonb, '{"expected_transcript":"もう一度 言って ください"}'::jsonb, NULL, NULL, 'Lafalkan mou ichido itte kudasai.', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('44dc7398-1d61-4b7c-a95c-9472dbe1874c', 'b0000001-0000-0000-0000-000000000025', '713b3950-cd77-436e-9e0e-d131b205008e', 'reading', 'fill_blank', 'Lengkapi kalimat status tempat tinggal: わたしは いま おおさかに ___ います。', '{"options":["すんで","すみます","すんだ","すまない"],"translation":"Saya sekarang tinggal di Osaka.","sentence_template":"わたしは いま おおさかに [blank] います。"}'::jsonb, '{"selected":"すんで"}'::jsonb, NULL, '{"すみます":"Sebelum います harus verba bentuk-TE (すんで)."}'::jsonb, 'Menyatakan tempat tinggal saat ini memakai pola tetap 「[Tempat] に すんでいます」.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1b15e71f-1b35-4fb7-a6aa-373b196be493', 'b0000001-0000-0000-0000-000000000025', '713b3950-cd77-436e-9e0e-d131b205008e', 'writing', 'sentence_builder', 'Susun kalimat aksi berlangsung: "Sekarang sedang hujan."', '{"romaji":"Ima ame ga futte imasu.","tokens":["いま","あめ","が","ふって","います","ふります"],"target_translation":"Sekarang sedang hujan."}'::jsonb, '["いま","あめ","が","ふって","います"]'::jsonb, '[["今雨が降っています"]]'::jsonb, '{"ふります":"ふっています menyatakan hujan yang sedang turun saat ini."}'::jsonb, 'Verba ふります (turun hujan/salju) menjadi ふっています untuk kejadian sekarang.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d070277-421e-4501-b945-0e27c49e8a92', 'b0000001-0000-0000-0000-000000000025', '713b3950-cd77-436e-9e0e-d131b205008e', 'listening', 'listening_choice', 'Dengarkan keterangan berikut. Apa yang sedang dilakukan Satou-san sekarang?', '{"options":[{"id":"opt_1","text":"Sedang menelepon"},{"id":"opt_2","text":"Sedang menulis email"},{"id":"opt_3","text":"Sedang pulang ke rumah"},{"id":"opt_4","text":"Sedang minum kopi"}],"audio_text":"さとうさんは いま でんわを かけています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"でんわを かけています berarti sedang menelepon."}'::jsonb, 'Frasa 「でんわを かけます」 diubah ke ～ています menjadi sedang menelepon.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000142', 'b0000001-0000-0000-0000-000000000025', '713b3950-cd77-436e-9e0e-d131b205008e', 'reading', 'fill_blank', 'Pola aksi yang sedang berlangsung saat ini menggunakan akhiran:', '{"options":["かけて います","かけて ください","かけて ました","かけ ません"],"translation":"Sekarang Sdri. Sato sedang menelepon.","sentence_template":"いま さとうさん は でんわ を [blank]。"}'::jsonb, '{"selected":"かけて います"}'::jsonb, NULL, NULL, 'Bentuk-TE + います (~ています) menandakan aksi sedang berlangsung sekarang.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000143', 'b0000001-0000-0000-0000-000000000025', '713b3950-cd77-436e-9e0e-d131b205008e', 'writing', 'sentence_builder', 'Susun kalimat kondisi status: "Saya sekarang tinggal di Osaka."', '{"romaji":"Watashi wa Oosaka ni sunde imasu.","tokens":["わたし","は","おおさか","に","すんで","います"],"target_translation":"Saya tinggal di Osaka."}'::jsonb, '["わたし","は","おおさか","に","すんで","います"]'::jsonb, NULL, NULL, 'すみます (tinggal) memakai ～ています untuk menyatakan status domisili saat ini.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000144', 'b0000001-0000-0000-0000-000000000025', '713b3950-cd77-436e-9e0e-d131b205008e', 'listening', 'listening_choice', 'Dengarkan dialog ini. Sedang apakah Pak Suzuki sekarang?', '{"options":[{"id":"opt_1","text":"Sedang makan siang"},{"id":"opt_2","text":"Sedang rapat penting"},{"id":"opt_3","text":"Sedang dalam perjalanan"},{"id":"opt_4","text":"Sedang menelepon klien"}],"audio_text":"すずきさんは いま ひるごはんを たべています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'たべています berarti sedang makan.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000145', 'b0000001-0000-0000-0000-000000000025', '713b3950-cd77-436e-9e0e-d131b205008e', 'reading', 'fill_blank', 'Cara menyatakan status "sudah menikah" yang masih berlaku adalah:', '{"options":["けっこん しています","けっこん します","けっこん して ください","けっこん しましょう"],"translation":"Kakak perempuan saya sudah menikah.","sentence_template":"あね は [blank]。"}'::jsonb, '{"selected":"けっこん しています"}'::jsonb, NULL, NULL, 'けっこん しています menyatakan kondisi status pernikahan sekarang.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000146', 'b0000001-0000-0000-0000-000000000025', '713b3950-cd77-436e-9e0e-d131b205008e', 'writing', 'sentence_builder', 'Susun kalimat: "Di luar sekarang sedang turun hujan."', '{"romaji":"Soto wa ima ame ga futte imasu.","tokens":["そと","は","いま","あめ","が","ふって","います"],"target_translation":"Sekarang sedang turun hujan."}'::jsonb, '["そと","は","いま","あめ","が","ふって","います"]'::jsonb, NULL, NULL, 'ふります (turun hujan/salju) menjadi ふっています untuk hujan yang sedang turun.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220005000009', 'b0000001-0000-0000-0000-000000000025', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Setelah minum obat, tidur'':', '{"options":["から","まで","ので","のに"],"sentence_template":"くすり を のんで [blank]、ねます"}'::jsonb, '{"selected":"から"}'::jsonb, NULL, NULL, 'のんでから = setelah minum.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220005000010', 'b0000001-0000-0000-0000-000000000025', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Setelah minum obat tidur":', '{"romaji":"Kusuri o nonde kara nemasu","tokens":["薬を","飲んでから","寝ます"],"target_translation":"Setelah minum obat tidur"}'::jsonb, '["薬を","飲んでから","寝ます"]'::jsonb, NULL, NULL, 'Kusuri o nonde kara nemasu.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bc21f6d1-3c03-4733-813d-a2af4dbe9687', 'b0000001-0000-0000-0000-000000000026', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Lengkapi kalimat meminta izin: ここで しゃしんを ___ もいいですか。', '{"options":["とって","とります","とる","とらない"],"translation":"Bolehkah mengambil foto di sini?","sentence_template":"ここで しゃしんを [blank] もいいですか。"}'::jsonb, '{"selected":"とって"}'::jsonb, NULL, '{"とります":"Pola izin memakai bentuk-TE + もいいですか."}'::jsonb, 'Bentuk 「[Verba-TE] もいいですか」 digunakan untuk meminta izin melakukan sesuatu.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('993e1c8d-92c3-43b8-b828-250f4a267a9a', 'b0000001-0000-0000-0000-000000000026', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat larangan: "Tidak boleh masuk ke ruangan ini."', '{"romaji":"Kono heya ni haitte wa ikemasen.","tokens":["この","へや","に","はいって","はいけません","もいいです"],"target_translation":"Tidak boleh masuk ke ruangan ini."}'::jsonb, '["この","へや","に","はいって","はいけません"]'::jsonb, '[["この部屋に入ってはいけません"]]'::jsonb, '{"もいいです":"～もいいです berarti boleh, sedangkan kalimat meminta larangan (dilarang)."}'::jsonb, 'Pola larangan resmi adalah 「[Verba-TE] は いけません」.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('351e28fb-40a0-493b-b8df-ac09f1166f36', 'b0000001-0000-0000-0000-000000000026', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan meminta izin berikut: "Bolehkah saya memakai komputer ini?"', '{"romaji":"Kono pasokon o tsukatte mo ii desu ka.","display_text":"このパソコンをつかってもいいですか","phonetic_breakdown":["ko-no","pa-so-kon","o","tsu-kat-te","mo","ii","de-su","ka"]}'::jsonb, '{"expected_transcript":"このパソコンをつかってもいいですか"}'::jsonb, '[["このパソコンを使ってもいいですか"]]'::jsonb, NULL, 'つかいます (memakai) → つかってもいいですか (bolehkah memakai?).', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000147', 'b0000001-0000-0000-0000-000000000026', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Pola sopan untuk meminta izin melakukan sesuatu ("bolehkah saya...") adalah:', '{"options":["ても いい ですか","ては いけません","て ください","て います"],"translation":"Bolehkah saya duduk di sini?","sentence_template":"ここ に すわっ [blank]。"}'::jsonb, '{"selected":"ても いい ですか"}'::jsonb, NULL, '{"てはいけません":"～てはいけません berarti dilarang / tidak boleh."}'::jsonb, '～てもいいですか dipakai untuk menanyakan izin secara sopan.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000148', 'b0000001-0000-0000-0000-000000000026', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Pola larangan tegas untuk aturan tempat kerja/umum adalah:', '{"options":["ては いけません","ても いいです","て ください","て います"],"translation":"Tidak boleh mengambil foto di museum.","sentence_template":"びじゅつかん で しゃしん を とっ [blank]。"}'::jsonb, '{"selected":"ては いけません"}'::jsonb, NULL, NULL, '～てはいけません menyatakan larangan ("tidak boleh / dilarang").', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000149', 'b0000001-0000-0000-0000-000000000026', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun pertanyaan izin di kantor: "Bolehkah saya meminjam pulpen ini?"', '{"romaji":"Kono pen o karitemo ii desu ka.","tokens":["この","ペン","を","かりても","いい","ですか"],"target_translation":"Bolehkah meminjam pulpen ini?"}'::jsonb, '["この","ペン","を","かりても","いい","ですか"]'::jsonb, NULL, NULL, 'かります (meminjam) menjadi かりて + もいいですか.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000150', 'b0000001-0000-0000-0000-000000000026', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan pengumuman aturan ini. Apa yang dilarang dilakukan di ruang rapat?', '{"options":[{"id":"opt_1","text":"Dilarang merokok"},{"id":"opt_2","text":"Dilarang makan kue"},{"id":"opt_3","text":"Dilarang membawa tas"},{"id":"opt_4","text":"Dilarang keluar masuk"}],"audio_text":"ここで タバコを すっては いけません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'タバコを すってはいけません berarti dilarang merokok di sini.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000151', 'b0000001-0000-0000-0000-000000000026', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun aturan laboratorium: "Dilarang menyentuh mesin ini."', '{"romaji":"Kono kikai ni sawatte wa ikemasen.","tokens":["この","きかい","に","さわっては","いけません"],"target_translation":"Dilarang menyentuh mesin ini."}'::jsonb, '["この","きかい","に","さわっては","いけません"]'::jsonb, NULL, NULL, 'さわります (menyentuh) berbentuk-TE さわって + はいけません.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-230002000009', 'b0000001-0000-0000-0000-000000000026', NULL, 'reading', 'fill_blank', 'Lengkapi izin ''Bolehkah saya menggunakan pulpen ini?'':', '{"options":["いい","だめ","ない","いけません"],"sentence_template":"この ペン を つかって も [blank] ですか"}'::jsonb, '{"selected":"いい"}'::jsonb, NULL, NULL, 'つかっても いいですか.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-230002000010', 'b0000001-0000-0000-0000-000000000026', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Bolehkah pakai?":', '{"romaji":"Tsukatte mo ii desu ka","tokens":["使っても","いいですか"],"target_translation":"Bolehkah pakai?"}'::jsonb, '["使っても","いいですか"]'::jsonb, NULL, NULL, 'Tsukatte mo ii desu ka.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5e1b3557-a3f5-46e5-b05b-04c64eee60e4', 'b0000001-0000-0000-0000-000000000027', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Sambungkan dua kegiatan berurutan: あさ おきて、コーヒーを ___。', '{"options":["のみます","のんで","のみませんでし","のむ"],"translation":"Pagi hari bangun tidur, lalu minum kopi.","sentence_template":"あさ おきて、コーヒーを [blank]。"}'::jsonb, '{"selected":"のみます"}'::jsonb, NULL, '{"のんで":"Verba terakhir di akhir kalimat tetap memakai bentuk sopan ～ます."}'::jsonb, 'Saat menyambung urutan tindakan: aksi sebelumnya pakai bentuk-TE (おきて), aksi terakhir menentukan tense kalimat (のみます).', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('602bee54-7d7f-41fc-b1c8-cabf0450b711', 'b0000001-0000-0000-0000-000000000027', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat berurutan: "Setelah bekerja, lalu pulang ke rumah."', '{"romaji":"Shigoto o shite, uchi e kaerimasu.","tokens":["しごと","を","して","うち","へ","かえります"],"target_translation":"Bekerja lalu pulang ke rumah."}'::jsonb, '["しごと","を","して","うち","へ","かえります"]'::jsonb, '[["仕事をしてうちへ帰ります"]]'::jsonb, NULL, 'Verba します (melakukan) memiliki bentuk-TE tak beraturan yakni して.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('73cc7a1c-6d66-4c5e-b73d-254fafad5939', 'b0000001-0000-0000-0000-000000000027', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan urutan kegiatan akhir pekan berikut. Apa yang dilakukan setelah berbelanja?', '{"options":[{"id":"opt_1","text":"Menonton film"},{"id":"opt_2","text":"Makan ramen"},{"id":"opt_3","text":"Belajar Kanji"},{"id":"opt_4","text":"Tidur siang"}],"audio_text":"かいものを して、えいがを みました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Kegiatan kedua adalah えいがを みました (menonton film)."}'::jsonb, '「かいものを して」(berbelanja), lalu 「えいがを みました」(menonton film).', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000152', 'b0000001-0000-0000-0000-000000000027', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Menyambungkan dua aksi berurutan memakai bentuk-TE:', '{"options":["て","ます","ました","ない"],"translation":"Pagi bangun tidur, lalu mencuci muka.","sentence_template":"あさ おき [blank]、かお を あらいます。"}'::jsonb, '{"selected":"て"}'::jsonb, NULL, NULL, 'Bentuk-TE menyambungkan urutan tindakan kronologis ("lalu/kemudian").', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000153', 'b0000001-0000-0000-0000-000000000027', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun urutan aktivitas: "Saya minum kopi lalu pergi ke kantor."', '{"romaji":"Koohii o nonde kaisha e ikimasu.","tokens":["コーヒー","を","のんで","かいしゃ","へ","いきます"],"target_translation":"Minum kopi lalu pergi ke kantor."}'::jsonb, '["コーヒー","を","のんで","かいしゃ","へ","いきます"]'::jsonb, NULL, NULL, 'のみます (minum) diubah ke bentuk-TE のんで untuk aksi pertama.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000154', 'b0000001-0000-0000-0000-000000000027', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan urutan rutinitas berikut. Apa yang pembicara lakukan setelah pulang ke rumah?', '{"options":[{"id":"opt_1","text":"Mandi shower"},{"id":"opt_2","text":"Langsung tidur"},{"id":"opt_3","text":"Menonton berita"},{"id":"opt_4","text":"Memasak makan malam"}],"audio_text":"うちへ かえって、シャワーを あびます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'かえって (pulang lalu) + シャワーを あびます (mandi shower).', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000155', 'b0000001-0000-0000-0000-000000000027', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Urutan mengakhiri waktu kerja: しごと を おわっ [blank]、スーパー へ いきます。', '{"options":["てから","ても","ては","ながら"],"translation":"Setelah selesai bekerja, saya pergi ke supermarket.","sentence_template":"しごと を おわっ [blank]、スーパー へ いきます。"}'::jsonb, '{"selected":"てから"}'::jsonb, NULL, NULL, '～てから menegaskan arti "setelah selesai melakukan ..., baru ...".', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000156', 'b0000001-0000-0000-0000-000000000027', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat: "Setelah makan malam, saya membaca buku."', '{"romaji":"Bangohan o tabetekara hon o yomimasu.","tokens":["ばんごはん","を","たべてから","ほん","を","よみます"],"target_translation":"Setelah makan malam, membaca buku."}'::jsonb, '["ばんごはん","を","たべてから","ほん","を","よみます"]'::jsonb, NULL, NULL, 'たべて + から menyatakan urutan aksi yang selesai terlebih dahulu.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220002000009', 'b0000001-0000-0000-0000-000000000027', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Mengenal Tanaka-san'':', '{"options":["しって","すんで","もって","みて"],"translation":"Shitte","sentence_template":"たなかさん を [blank] います"}'::jsonb, '{"selected":"しって"}'::jsonb, NULL, NULL, 'しっています = mengenal / mengetahui.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220002000010', 'b0000001-0000-0000-0000-000000000027', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Mengenal Tanaka":', '{"romaji":"Tanaka-san o shitte imasu","tokens":["田中さん","を","知って","います"],"target_translation":"Mengenal Tanaka"}'::jsonb, '["田中さん","を","知って","います"]'::jsonb, NULL, NULL, 'Tanaka-san o shitte imasu.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a1223fd6-15af-48bf-95fc-530cdaa29009', 'b0000001-0000-0000-0000-000000000028', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Lengkapi ungkapan keinginan melakukan aksi: にほんごを じょうずに はなし ___ です。', '{"options":["たい","ほしい","ます","ながら"],"translation":"Saya ingin berbicara bahasa Jepang dengan mahir.","sentence_template":"にほんごを じょうずに はなし [blank] です。"}'::jsonb, '{"selected":"たい"}'::jsonb, NULL, '{"ほしい":"ほしい dipakai setelah kata benda (ingin barang), bukan setelah akar verba."}'::jsonb, 'Tambahkan たいです setelah akar kata kerja (はなします → はなし + たいです).', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('61955520-a958-49a4-a921-64be15066539', 'b0000001-0000-0000-0000-000000000028', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat keinginan barang: "Saya ingin kamus baru."', '{"romaji":"Watashi wa atarashii jisho ga hoshii desu.","tokens":["わたし","は","あたらしい","じしょ","が","ほしい","です"],"target_translation":"Saya ingin kamus baru."}'::jsonb, '["わたし","は","あたらしい","じしょ","が","ほしい","です"]'::jsonb, '[["私は新しい辞書がほしいです"]]'::jsonb, NULL, 'Untuk menginginkan sebuah benda, gunakan pola 「[Benda] が ほしいです」.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('972911a0-f17e-46b3-9ab3-a1c4c4686464', 'b0000001-0000-0000-0000-000000000028', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'speaking', 'speaking_repeat', 'Ucapkan target belajarmu: "Saya ingin pergi ke Kyoto tahun depan."', '{"romaji":"Rainen Kyouto e ikitai desu.","display_text":"らいねんきょうとへいきたいです","phonetic_breakdown":["rai-nen","kyou-to","e","i-ki-tai","de-su"]}'::jsonb, '{"expected_transcript":"らいねんきょうとへいきたいです"}'::jsonb, '[["来年京都へ行きたいです"]]'::jsonb, NULL, 'いきます (pergi) → いきたいです (ingin pergi).', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000184', 'b0000001-0000-0000-0000-000000000028', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Menyatakan keinginan melakukan tindakan menggunakan akhiran ～たい pada stem verba:', '{"options":["うけたい です","うけて ください","うけない で","うけましょう"],"translation":"Tahun depan saya ingin mengikuti ujian JLPT.","sentence_template":"らいねん 日本語能力試験（JLPT）を [blank]。"}'::jsonb, '{"selected":"うけたい です"}'::jsonb, NULL, NULL, 'うけます → stem うけ + たいです = ingin mengikuti/menerima ujian.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000185', 'b0000001-0000-0000-0000-000000000028', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Menyatakan keinginan memiliki suatu Benda memakai:', '{"options":["ほしい","たい","すき","じょうず"],"translation":"Saya ingin memiliki laptop baru.","sentence_template":"わたし は 新しい パソコン が [blank] です。"}'::jsonb, '{"selected":"ほしい"}'::jsonb, NULL, '{"たい":"～たい hanya menempel pada kata kerja (verba), sedangkan benda memakai が ほしい."}'::jsonb, 'Benda yang diinginkan memakai pola [Benda] が ほしいです.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000186', 'b0000001-0000-0000-0000-000000000028', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat keinginan: "Hari libur ini saya ingin istirahat di rumah."', '{"romaji":"Konshuumatsu wa ie de yasumitai desu.","tokens":["こんしゅうまつ","は","いえ","で","やすみたい","です"],"target_translation":"Akhir pekan ini ingin istirahat di rumah."}'::jsonb, '["こんしゅうまつ","は","いえ","で","やすみたい","です"]'::jsonb, NULL, NULL, 'やすみます → やすみたいです (ingin beristirahat).', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000187', 'b0000001-0000-0000-0000-000000000028', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan target karir pembicara ini. Apa cita-citanya?', '{"options":[{"id":"opt_1","text":"Ingin bekerja di perusahaan Jepang"},{"id":"opt_2","text":"Ingin membuka restoran di Bali"},{"id":"opt_3","text":"Ingin menjadi pilot pesawat"},{"id":"opt_4","text":"Ingin kuliah kedokteran"}],"audio_text":"しょうらい 日本の かいしゃで はたらきたいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'はたらきたいです berarti ingin bekerja.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000188', 'b0000001-0000-0000-0000-000000000028', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Bentuk negatif dari keinginan ("tidak ingin makan") adalah:', '{"options":["たべたくない です","たべたい じゃありません","たべません たいです","たべて いいです"],"translation":"Karena sudah kenyang, saya tidak ingin makan apa pun.","sentence_template":"おなか が いっぱい ですから、なにも [blank]。"}'::jsonb, '{"selected":"たべたくない です"}'::jsonb, NULL, NULL, '～たい dikonjugasikan persis seperti kata sifat-i: ～たい → ～たくないです.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-290001000009', 'b0000001-0000-0000-0000-000000000028', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Tidak ingin pergi ke mana-mana'':', '{"options":["いきたくない","いきたい","いかない","いかなかった"],"translation":"Ikitakunai","sentence_template":"どこ へ も [blank] です"}'::jsonb, '{"selected":"いきたくない"}'::jsonb, NULL, NULL, 'どこ へ も いきたくない です (Tidak ingin ke mana pun).', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-290001000010', 'b0000001-0000-0000-0000-000000000028', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Tidak ingin ke mana-mana":', '{"romaji":"Doko e mo ikitakunai desu","tokens":["どこへも","行きたくない","です"],"target_translation":"Tidak ingin ke mana-mana"}'::jsonb, '["どこへも","行きたくない","です"]'::jsonb, NULL, NULL, 'Doko e mo ikitakunai desu.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-290001000011', 'b0000001-0000-0000-0000-000000000028', NULL, 'speaking', 'speaking_repeat', 'Ucapkan keengganan ''きょう は 何も したくない です'':', '{"romaji":"kyou wa nanimo shitakunai desu","audio_text":"きょう は 何も したくない です","display_text":"きょう は 何も したくない です"}'::jsonb, '{"expected_transcript":"きょう は 何も したくない です"}'::jsonb, NULL, NULL, 'Lafalkan kyou wa nanimo shitakunai desu.', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e12b153f-37aa-4727-9a97-24ec7000bb15', 'b0000001-0000-0000-0000-000000000029', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Lengkapi kalimat tujuan kepergian: スーパーへ やさいを かい ___ いきます。', '{"options":["に","を","で","から"],"translation":"Saya pergi ke supermarket untuk membeli sayuran.","sentence_template":"スーパーへ やさいを かい [blank] いきます。"}'::jsonb, '{"selected":"に"}'::jsonb, NULL, '{"で":"Menunjukkan tujuan setelah akar verba memakai partikel に."}'::jsonb, 'Akar verba かい (dari かいます) + に + いきます menyatakan maksud kepergian.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b2e8cbe9-ca4e-420c-a36b-bef53db81397', 'b0000001-0000-0000-0000-000000000029', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat alasan: "Karena sibuk, hari ini tidak menonton film."', '{"romaji":"Isogashii kara, kyou wa eiga o mimasen.","tokens":["いそがしい","から","きょう","は","えいが","を","みません"],"target_translation":"Karena sibuk, hari ini saya tidak menonton film."}'::jsonb, '["いそがしい","から","きょう","は","えいが","を","みません"]'::jsonb, '[["忙しいから今日は映画を見ません"]]'::jsonb, NULL, 'Kata sambung 「から」 di akhir klausa menyatakan sebab/alasan ("karena...").', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8786ba15-d9aa-462c-916f-a2de599742f6', 'b0000001-0000-0000-0000-000000000029', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan alasan berikut. Mengapa pembicara tidak minum kopi malam ini?', '{"options":[{"id":"opt_1","text":"Karena sudah larut malam"},{"id":"opt_2","text":"Karena kopinya terlalu mahal"},{"id":"opt_3","text":"Karena kafe sudah tutup"},{"id":"opt_4","text":"Karena tidak suka kopi"}],"audio_text":"もう おそいですから、コーヒーを のみません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"おそいです berarti sudah terlambat/larut malam, bukan mahal (たかいです)."}'::jsonb, 'Kalimat sopan menyatakan alasan dengan 「〜ます / 〜ですから」.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000189', 'b0000001-0000-0000-0000-000000000029', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Partikel tujuan setelah stem kata kerja sebelum "いきます" (pergi untuk melakukan...) adalah:', '{"options":["に","を","で","と"],"translation":"Pergi ke taman untuk jalan-jalan.","sentence_template":"こうえん へ さんぽ [blank] いきます。"}'::jsonb, '{"selected":"に"}'::jsonb, NULL, '{"を":"Tujuan pergi melakukan aksi memakai [Stem / Kata Benda] + に いきます."}'::jsonb, 'Pola [Kata Kerja Stem / Kata Benda Aksi] + に いきます berarti "pergi untuk melakukan ...".', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000190', 'b0000001-0000-0000-0000-000000000029', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat tujuan: "Saya pergi ke Tokyo untuk belajar teknologi."', '{"romaji":"Watashi wa gijutsu no benkyou ni Toukyou e ikimasu.","tokens":["わたし","は","ぎじゅつ","の","べんきょう","に","とうきょう","へ","いきます"],"target_translation":"Ke Tokyo untuk belajar teknologi."}'::jsonb, '["わたし","は","ぎじゅつ","の","べんきょう","に","とうきょう","へ","いきます"]'::jsonb, NULL, NULL, 'べんきょう (belajar) diikuti に sebelum いきます.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000191', 'b0000001-0000-0000-0000-000000000029', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan alasan berikut. Mengapa pembicara tidak ikut makan siang?', '{"options":[{"id":"opt_1","text":"Karena masih ada pekerjaan"},{"id":"opt_2","text":"Karena dompetnya tertinggal"},{"id":"opt_3","text":"Karena sedang sakit demam"},{"id":"opt_4","text":"Karena sudah makan lebih dulu"}],"audio_text":"まだ しごとが ありますから、いきません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Partikel ～から di akhir klausa menyatakan alasan ("karena ...").', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000192', 'b0000001-0000-0000-0000-000000000029', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat alasan: "Karena besok libur, mari tidur lebih lama."', '{"romaji":"Ashita wa yasumi desu kara yukkuri nemashou.","tokens":["あした","は","やすみ","ですから","ゆっくり","ねましょう"],"target_translation":"Karena besok libur, ayo tidur santai."}'::jsonb, '["あした","は","やすみ","ですから","ゆっくり","ねましょう"]'::jsonb, NULL, NULL, 'Tambahkan から setelah です atau verba ～ます untuk menjelaskan alasan.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000193', 'b0000001-0000-0000-0000-000000000029', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Melengkapi tujuan belanja: スーパー へ やさい を [blank] いきます。', '{"options":["かいに","かうに","かってに","かわに"],"translation":"Pergi ke supermarket untuk membeli sayuran.","sentence_template":"スーパー へ やさい を [blank] いきます。"}'::jsonb, '{"selected":"かいに"}'::jsonb, NULL, NULL, 'かいます → hapus ます menjadi かい + に いきます.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-290002000009', 'b0000001-0000-0000-0000-000000000029', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Ingin punya mobil'':', '{"options":["ほしい","たい","すき","いい"],"translation":"Hoshii","sentence_template":"車 が [blank] です"}'::jsonb, '{"selected":"ほしい"}'::jsonb, NULL, NULL, 'くるま が ほしい です.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-290002000010', 'b0000001-0000-0000-0000-000000000029', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Ingin punya mobil":', '{"romaji":"Kuruma ga hoshii desu","tokens":["車が","ほしい","です"],"target_translation":"Ingin punya mobil"}'::jsonb, '["車が","ほしい","です"]'::jsonb, NULL, NULL, 'Kuruma ga hoshii desu.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('357a1df9-514a-46b4-a8e2-f1d310c83696', 'b0000001-0000-0000-0000-000000000030', '713b3950-cd77-436e-9e0e-d131b205008e', 'reading', 'fill_blank', 'Lengkapi ungkapan pengalaman hidup: すしを ___ ことが あります。', '{"options":["たべた","たべます","たべて","たべない"],"translation":"Saya pernah makan sushi.","sentence_template":"すしを [blank] ことが あります。"}'::jsonb, '{"selected":"たべた"}'::jsonb, NULL, '{"たべて":"Pola pernah melakukan sesuatu memakai bentuk-TA (たべた) + ことがあります."}'::jsonb, 'Gunakan verba bentuk lampau pendek (Bentuk-TA) sebelum 「ことがあります」 untuk menyatakan pengalaman.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7f3d77e8-43e4-41d9-b6ac-d101a1afcd9a', 'b0000001-0000-0000-0000-000000000030', '713b3950-cd77-436e-9e0e-d131b205008e', 'writing', 'sentence_builder', 'Susun kalimat pengalaman: "Saya pernah naik Shinkansen."', '{"romaji":"Shinkansen ni notta koto ga arimasu.","tokens":["しんかんせん","に","のった","こと","が","あります","のります"],"target_translation":"Saya pernah naik Shinkansen."}'::jsonb, '["しんかんせん","に","のった","こと","が","あります"]'::jsonb, '[["新幹線に乗ったことがあります"]]'::jsonb, '{"のります":"Di depan ことがあります wajib menggunakan bentuk-TA yakni のった."}'::jsonb, 'のります (naik) → bentuk-TA のった + ことがあります = pernah naik.', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('58d4f6c2-3eed-4f9f-9566-f8ccda140a15', 'b0000001-0000-0000-0000-000000000030', '713b3950-cd77-436e-9e0e-d131b205008e', 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan pengalaman berikut: "Apakah Anda pernah pergi ke Jepang?"', '{"romaji":"Nihon e itta koto ga arimasu ka.","display_text":"にほんへいったことがありますか","phonetic_breakdown":["ni-hon","e","it-ta","ko-to","ga","a-ri-ma-su","ka"]}'::jsonb, '{"expected_transcript":"にほんへいったことがありますか"}'::jsonb, '[["日本へ行ったことがありますか"]]'::jsonb, NULL, 'いきます (pergi) memiliki bentuk-TA khusus yaitu いった.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000194', 'b0000001-0000-0000-0000-000000000030', '84296601-2071-4b58-a093-e916c1f4abac', 'reading', 'fill_blank', 'Menyatakan pengalaman pernah melakukan sesuatu memakai pola:', '{"options":["いった こと が","いって こと が","いく こと が","いかない こと が"],"translation":"Saya pernah pergi ke Tokyo.","sentence_template":"わたし は とうきょう へ [blank] あります。"}'::jsonb, '{"selected":"いった こと が"}'::jsonb, NULL, '{"いったことが":"Sudah benar memakai bentuk-TA!"}'::jsonb, 'Pola pengalaman adalah [Verba Bentuk-TA] + こと が あります.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000195', 'b0000001-0000-0000-0000-000000000030', '84296601-2071-4b58-a093-e916c1f4abac', 'reading', 'fill_blank', 'Bentuk negasi pengalaman ("belum pernah...") adalah:', '{"options":["ありません","います","いません","です"],"translation":"Saya belum pernah makan sushi.","sentence_template":"わたし は まだ すし を たべた こと が [blank]。"}'::jsonb, '{"selected":"ありません"}'::jsonb, NULL, NULL, 'Belum pernah memakai akhiran ことが ありません (atau いちども ～ことがありません).', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000196', 'b0000001-0000-0000-0000-000000000030', '84296601-2071-4b58-a093-e916c1f4abac', 'writing', 'sentence_builder', 'Susun kalimat pengalaman: "Saya pernah naik Shinkansen satu kali."', '{"romaji":"Shinkansen ni notta koto ga arimasu.","tokens":["しんかんせん","に","のった","こと","が","あります"],"target_translation":"Pernah naik Shinkansen."}'::jsonb, '["しんかんせん","に","のった","こと","が","あります"]'::jsonb, NULL, NULL, 'のります (naik kendaraan) bentuk-TA-nya adalah のった.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000197', 'b0000001-0000-0000-0000-000000000030', '84296601-2071-4b58-a093-e916c1f4abac', 'listening', 'listening_choice', 'Dengarkan percakapan pengalaman ini. Apakah pembicara pernah mendaki Gunung Fuji?', '{"options":[{"id":"opt_1","text":"Belum pernah mendaki"},{"id":"opt_2","text":"Sudah dua kali mendaki"},{"id":"opt_3","text":"Akan mendaki bulan depan"},{"id":"opt_4","text":"Sedang berada di Gunung Fuji"}],"audio_text":"いいえ、まだ のぼったことが ありません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'のぼったことが ありません berarti belum pernah mendaki.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000198', 'b0000001-0000-0000-0000-000000000030', '84296601-2071-4b58-a093-e916c1f4abac', 'writing', 'sentence_builder', 'Susun kalimat tanya pengalaman: "Apakah kamu pernah melihat salju?"', '{"romaji":"Yuki o mita koto ga arimasu ka.","tokens":["ゆき","を","みた","こと","が","ありますか"],"target_translation":"Pernah melihat salju?"}'::jsonb, '["ゆき","を","みた","こと","が","ありますか"]'::jsonb, NULL, NULL, 'みます bentuk-TA-nya みた + ことがありますか.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000199', 'b0000001-0000-0000-0000-000000000030', '84296601-2071-4b58-a093-e916c1f4abac', 'listening', 'listening_choice', 'Dengarkan pernyataan ini. Makanan apa yang sudah pernah dia coba?', '{"options":[{"id":"opt_1","text":"Belut panggang Jepang"},{"id":"opt_2","text":"Ramen kuah pedas"},{"id":"opt_3","text":"Tempura udang"},{"id":"opt_4","text":"Sashimi ikan tuna"}],"audio_text":"うなぎを たべたことが あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'うなぎ (unagi) adalah belut air tawar khas Jepang.', 9, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260005000010', 'b0000001-0000-0000-0000-000000000030', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Pernahkah melihat bunga sakura?'':', '{"options":["あります","います","します","です"],"sentence_template":"さくら を みた こと が [blank] か"}'::jsonb, '{"selected":"あります"}'::jsonb, NULL, NULL, 'みた ことが ありますか.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260005000011', 'b0000001-0000-0000-0000-000000000030', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Pernah lihat sakura":', '{"romaji":"Sakura o mita koto ga arimasu","tokens":["桜を","見たことが","あります"],"target_translation":"Pernah lihat sakura"}'::jsonb, '["桜を","見たことが","あります"]'::jsonb, NULL, NULL, 'Sakura o mita koto ga arimasu.', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8fe0f09a-d9f6-43ef-bb60-3c82010eba44', 'b0000001-0000-0000-0000-000000000031', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Lengkapi penutup percakapan bisnis saat menitipkan pesan: よろしく ___ します。', '{"options":["おねがい","ありがとう","すみません","失礼"],"translation":"Mohon kerja samanya / Salam hangat.","sentence_template":"よろしく [blank] します。"}'::jsonb, '{"selected":"おねがい"}'::jsonb, NULL, '{"ありがとう":"Kalimat tetapnya adalah よろしく おねがいします."}'::jsonb, 'Frasa 「よろしくお願いします」 digunakan saat memulai kerja sama maupun menitip salam.', 1, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('42cc42bd-178a-4ab3-8466-d89bf19ed88f', 'b0000001-0000-0000-0000-000000000031', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat lengkap persiapan wawancara: "Saya belajar bahasa Jepang setiap hari karena ingin bekerja di Tokyo."', '{"romaji":"Toukyou de hatarakitai kara, mainichi nihongo o benkyou shite imasu.","tokens":["とうきょう","で","はたらきたい","から","まいにち","にほんご","を","べんきょうしています"],"target_translation":"Karena ingin bekerja di Tokyo, saya belajar bahasa Jepang setiap hari."}'::jsonb, '["とうきょう","で","はたらきたい","から","まいにち","にほんご","を","べんきょうしています"]'::jsonb, '[["東京で働きたいから毎日日本語を勉強しています"]]'::jsonb, NULL, 'Kalimat ini menggabungkan ～たい (ingin), から (alasan), dan ～ています (kebiasaan rutin saat ini).', 2, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1c28ec77-4f3b-4180-9ee9-f5035dedc83e', 'b0000001-0000-0000-0000-000000000031', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan pesan singkat rekan kerja berikut. Kapan laporan harus diserahkan?', '{"options":[{"id":"opt_1","text":"Paling lambat besok jam 5 sore"},{"id":"opt_2","text":"Hari ini jam 9 pagi"},{"id":"opt_3","text":"Minggu depan hari Senin"},{"id":"opt_4","text":"Kemarin malam"}],"audio_text":"この レポートは あしたの ごご５じまでに おねがいします。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Deadline yang diucapkan adalah あしたの ごご５じまでに (sebelum besok jam 5 sore)."}'::jsonb, 'Partikel gabungan 「までに」 berarti tenggat waktu ("paling lambat sebelum...").', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000200', 'b0000001-0000-0000-0000-000000000031', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Jika teman berkata akan berpergian, ungkapan "hati-hati di jalan" adalah:', '{"options":["いってらっしゃい","おかえりなさい","ただいま","いただきます"],"translation":"Hati-hati / Selamat jalan!","sentence_template":"[blank]。"}'::jsonb, '{"selected":"いってらっしゃい"}'::jsonb, NULL, '{"ただいま":"ただいま diucapkan oleh orang yang baru tiba pulang ke rumah."}'::jsonb, 'Orang yang pergi mengucapkan いってきます, dan yang melepas menjawab いってらっしゃい.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000201', 'b0000001-0000-0000-0000-000000000031', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat: "Bapak manajer akan mengunjungi pabrik besok."', '{"romaji":"Buchou wa ashita koujou e ikimasu.","tokens":["ぶちょう","は","あした","こうじょう","へ","いきます"],"target_translation":"Manajer besok ke pabrik."}'::jsonb, '["ぶちょう","は","あした","こうじょう","へ","いきます"]'::jsonb, NULL, NULL, 'ぶちょう = Kepala Bagian / Manajer, こうじょう = Pabrik.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000202', 'b0000001-0000-0000-0000-000000000031', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan salam kepulangan ini. Apa balasan yang tepat ketika teman berkata "ただいま"?', '{"options":[{"id":"opt_1","text":"おかえりなさい (Selamat datang kembali)"},{"id":"opt_2","text":"おやすみなさい (Selamat tidur)"},{"id":"opt_3","text":"ごちそうさま (Terima kasih makanannya)"},{"id":"opt_4","text":"はじめまして (Salam kenal)"}],"audio_text":"ただいま。きょうも つかれました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Ucapan ただいま (saya pulang) selalu dibalas dengan おかえりなさい (selamat datang kembali).', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000203', 'b0000001-0000-0000-0000-000000000031', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat sopan permohonan ulang: "Tolong katakan sekali lagi perlahan."', '{"romaji":"Mou ichido yukkuri itte kudasai.","tokens":["もういちど","ゆっくり","いって","ください"],"target_translation":"Tolong ucapkan sekali lagi perlahan."}'::jsonb, '["もういちど","ゆっくり","いって","ください"]'::jsonb, NULL, NULL, 'もういちど = sekali lagi, ゆっくり = pelan-pelan.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000204', 'b0000001-0000-0000-0000-000000000031', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan dialog resepsionis kantor ini. Tamu diminta menunggu di mana?', '{"options":[{"id":"opt_1","text":"Tunggu di lobi sekitar 5 menit"},{"id":"opt_2","text":"Masuk langsung ke ruang 201"},{"id":"opt_3","text":"Isi formulir di meja samping"},{"id":"opt_4","text":"Datang lagi pukul 3 sore"}],"audio_text":"ロビーで ５ふんくらい まって ください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ロビーで まってください berarti silakan tunggu di lobi.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000205', 'b0000001-0000-0000-0000-000000000031', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Kata tanya sopan saat tidak mengerti maksud perkataan lawan bicara:', '{"options":["わかりません","しりません","みえません","ききません"],"translation":"Maaf, saya kurang mengerti.","sentence_template":"すみません、よく [blank]。"}'::jsonb, '{"selected":"わかりません"}'::jsonb, NULL, NULL, 'わかりません berarti tidak mengerti / kurang jelas.', 9, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-300002000010', 'b0000001-0000-0000-0000-000000000031', NULL, 'reading', 'fill_blank', 'Lengkapi antonim ''Panas'' (atsui) lawan katanya adalah ''Dingin'' (samui untuk cuaca, [blank] untuk benda):', '{"options":["つめたい","さむい","ぬるい","あたたかい"],"translation":"Tsumetai","sentence_template":"Benda dingin: [blank]"}'::jsonb, '{"selected":"つめたい"}'::jsonb, NULL, NULL, 'つめたい (tsumetai) = dingin saat disentuh/diminum.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-300002000011', 'b0000001-0000-0000-0000-000000000031', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Air dingin":', '{"romaji":"Tsumetai mizu","tokens":["冷たい","水"],"target_translation":"Air dingin"}'::jsonb, '["冷たい","水"]'::jsonb, NULL, NULL, '冷たい 水.', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0c6fbed7-fd53-4faf-9b80-d8cbc1d2e5c7', 'b0000002-0000-0000-0000-000000000001', NULL, 'reading', 'fill_blank', 'Manakah huruf Hiragana yang berbunyi vokal "A"?', '{"romaji":"a","options":["あ","い","う","お"]}'::jsonb, '{"selected":"あ"}'::jsonb, NULL, '{"い":"Karakter ini dibaca \"i\".","う":"Karakter ini dibaca \"u\".","お":"Karakter ini dibaca \"o\"."}'::jsonb, 'Karakter あ adalah huruf pertama dalam urutan gojuuon Hiragana dan dilafalkan sebagai vokal murni "a".', 1, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('db2e7584-4f8b-401f-9d89-69ac7663da70', 'b0000002-0000-0000-0000-000000000001', NULL, 'listening', 'listening_choice', 'Dengarkan audio penutur asli dan tentukan arti salam sapaan berikut.', '{"options":[{"id":"opt_1","text":"Selamat pagi"},{"id":"opt_2","text":"Selamat malam"},{"id":"opt_3","text":"Sampai jumpa"},{"id":"opt_4","text":"Terima kasih banyak"}],"audio_text":"おはようございます"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Konbanwa diucapkan saat menyapa di waktu malam hari.","opt_3":"Sayounara diucapkan saat berpisah/berpamitan.","opt_4":"Arigatou gozaimasu adalah ungkapan terima kasih."}'::jsonb, 'Frasa 「おはようございます」(Ohayou gozaimasu) adalah sapaan sopan standar di pagi hari, khususnya di lingkungan kantor atau sekolah.', 2, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3467f0fb-6b83-4444-a226-c3f3b4d621f5', 'b0000002-0000-0000-0000-000000000001', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'writing', 'sentence_builder', 'Susun balok kata berikut menjadi kalimat: "Saya adalah seorang siswa."', '{"romaji":"Watashi wa gakusei desu.","tokens":["わたし","は","がくせい","です","せんせい"],"target_translation":"Saya adalah seorang siswa."}'::jsonb, '["わたし","は","がくせい","です"]'::jsonb, '[["私","は","学生","です"]]'::jsonb, '{"せんせい":"Sensei berarti guru/pengajar, bukan siswa (gakusei)."}'::jsonb, 'Subjek perkenalan diri (わたし) diikuti penanda topik は (wa), predikat (がくせい), dan diakhiri kopula formal です (desu).', 3, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d58d439f-5e71-4fd1-95ba-e149ee1b1ab4', 'b0000002-0000-0000-0000-000000000001', NULL, 'reading', 'fill_blank', 'Pilih kata penunjuk tempat yang berarti "Di sini": ___ は きょうしつ です。', '{"options":["ここ","そこ","あそこ","どこ"],"translation":"Di sini adalah ruang kelas.","sentence_template":"[blank] は きょうしつ です。"}'::jsonb, '{"selected":"ここ"}'::jsonb, NULL, '{"そこ":"Soko berarti lokasi dekat lawan bicara (\"di situ\").","どこ":"Doko adalah kata tanya penunjuk (\"di mana\").","あそこ":"Asoko berarti lokasi jauh dari pembicara dan lawan bicara (\"di sana\")."}'::jsonb, 'Kata penunjuk posisi ruangan Jepang mengikuti pola ko-so-a-do: ここ (koko) selalu merujuk pada area dekat pembicara ("di sini").', 4, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3d9a1be1-fb4a-4810-8be6-de1728f0ace7', 'b0000002-0000-0000-0000-000000000001', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'writing', 'sentence_builder', 'Susun kalimat: "Minum air."', '{"romaji":"Mizu o nomimasu.","tokens":["みず","を","のみます","たべます"],"target_translation":"Minum air."}'::jsonb, '["みず","を","のみます"]'::jsonb, '[["水","を","飲みます"]]'::jsonb, '{"たべます":"Tabemasu berarti makan makanan padat. Untuk air (mizu) gunakan nomimasu (minum)."}'::jsonb, 'Partikel を (wo) menghubungkan kata benda objek penderita (みず) dengan verba transitif (のみます).', 5, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c9d60182-b86a-46f5-b4f2-63a05868a83a', 'b0000002-0000-0000-0000-000000000001', '84296601-2071-4b58-a093-e916c1f4abac', 'reading', 'fill_blank', 'Lengkapi kalimat dengan bentuk lampau negatif formal: きのう べんきょう___。', '{"options":["しませんでした","します","しません","しました"],"translation":"Kemarin saya tidak belajar.","sentence_template":"きのう べんきょう[blank]。"}'::jsonb, '{"selected":"しませんでした"}'::jsonb, NULL, '{"します":"Bentuk positif sekarang/kebiasaan.","しました":"Bentuk positif lampau (sudah belajar).","しません":"Bentuk negatif sekarang (tidak akan belajar)."}'::jsonb, 'Keterangan waktu lampau きのう (kemarin) dipadukan dengan verba lampau negatif formal 〜ませんでした (shimasen deshita).', 6, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b21e1078-4a3f-4d1a-b3fd-6c47ac6b39e2', 'b0000002-0000-0000-0000-000000000001', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan instruksi kerja penutur asli berikut dan pilih arti yang tepat.', '{"options":[{"id":"opt_1","text":"Tolong dengarkan baik-baik"},{"id":"opt_2","text":"Tolong tulis di sini"},{"id":"opt_3","text":"Tolong baca buku ini"},{"id":"opt_4","text":"Tolong bicara lebih keras"}],"audio_text":"よくきいてください"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Instruksi menulis adalah kaite kudasai.","opt_3":"Instruksi membaca adalah yonde kudasai."}'::jsonb, 'Bentuk 〜てください (-te kudasai) berasal dari verba bentuk-te + kudasai yang berfungsi menyampaikan instruksi atau permohonan santun.', 7, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ef86b744-b2d6-4d15-b863-aaaa2b270258', 'b0000002-0000-0000-0000-000000000001', '713b3950-cd77-436e-9e0e-d131b205008e', 'writing', 'sentence_builder', 'Susun kalimat: "Sekarang sedang membaca buku."', '{"romaji":"Ima hon o yonde imasu.","tokens":["いま","ほん","を","よんで","います","みます"],"target_translation":"Sekarang sedang membaca buku."}'::jsonb, '["いま","ほん","を","よんで","います"]'::jsonb, '[["今","本","を","読んで","います"]]'::jsonb, '{"みます":"Mimasu berarti melihat/menonton. Untuk membaca buku (hon), gunakan yomimasu -> yonde imasu."}'::jsonb, 'Pola verba bentuk-Te + います menyatakan aktivitas yang sedang berlangsung pada saat pembicaraan berlangsung.', 8, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('96a17a2f-9137-40cc-a3da-b4abee1c4a4c', 'b0000002-0000-0000-0000-000000000001', NULL, 'reading', 'fill_blank', 'Pilih partikel alasan sebab-akibat yang tepat: あめが ふっています ___、タクシーで いきます。', '{"options":["から","けど","でも","なら"],"translation":"Karena hujan turun, saya pergi naik taksi.","sentence_template":"あめが ふっています [blank]、タクシーで いきます。"}'::jsonb, '{"selected":"から"}'::jsonb, NULL, '{"けど":"Kedo menandai pertentangan (tetapi / meskipun).","でも":"Demo adalah kata sambung pengantar di awal kalimat baru.","なら":"Nara digunakan untuk topik bersyarat."}'::jsonb, 'Partikel から (kara) diletakkan di akhir klausa penyebab untuk menghubungkan alasan dengan keputusan/tindakan yang diambil.', 9, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5fb8ffc5-6236-4e5c-9756-086f0380ac33', 'b0000002-0000-0000-0000-000000000001', 'cb4acb75-471c-4397-a72b-1df038d3176a', 'writing', 'sentence_builder', 'Susun kalimat kewajiban kerja: "Besok harus pergi ke kantor."', '{"romaji":"Ashita kaisha e ikanakereba narimasen.","tokens":["あした","かいしゃ","へ","いかなければ","なりません","いきたいです"],"target_translation":"Besok harus pergi ke kantor."}'::jsonb, '["あした","かいしゃ","へ","いかなければ","なりません"]'::jsonb, '[["明日","会社","へ","行かなければ","なりません"]]'::jsonb, '{"いきたいです":"Ikitai desu menyatakan keinginan subjek (ingin pergi), bukan keharusan tugas (harus pergi)."}'::jsonb, 'Pola 〜なければなりません (-nakereba narimasen) adalah ekspresi formal standar dalam dunia profesional untuk menyatakan kewajiban mutlak.', 10, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('69d24ca1-43fc-487a-ae4f-7f72e4aee15b', 'b0000002-0000-0000-0000-000000000002', NULL, 'reading', 'fill_blank', 'Pilih huruf Hiragana yang memiliki pelafalan bunyi vokal "E":', '{"romaji":"e","options":["え","あ","い","う"]}'::jsonb, '{"selected":"え"}'::jsonb, NULL, '{"あ":"Huruf ini dibaca \"a\".","い":"Huruf ini dibaca \"i\".","う":"Huruf ini dibaca \"u\"."}'::jsonb, 'Huruf え dibaca "e" seperti dalam kata "enak".', 1, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('391f7a5b-309f-45fd-9fed-ee7d488f0b6b', 'b0000002-0000-0000-0000-000000000002', NULL, 'listening', 'listening_choice', 'Dengarkan suara berikut dan pilih huruf Hiragana yang sesuai.', '{"options":[{"id":"opt_1","text":"い"},{"id":"opt_2","text":"あ"},{"id":"opt_3","text":"う"},{"id":"opt_4","text":"お"}],"audio_text":"い"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Suara tersebut melafalkan huruf vokal i, bukan a."}'::jsonb, 'Huruf い terdiri dari dua coretan vertikal melengkung yang melambangkan vokal "i".', 2, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000015-0000-0000-0000-000000000001', 'b0000002-0000-0000-0000-000000000002', NULL, 'speaking', 'speaking_repeat', 'Ucapkan lima huruf vokal dasar Hiragana secara berurutan: "a, i, u, e, o".', '{"romaji":"A I U E O","display_text":"あいうえお","phonetic_breakdown":["a","i","u","e","o"]}'::jsonb, '{"expected_transcript":"あいうえお"}'::jsonb, '[["あ い う え お"]]'::jsonb, NULL, 'Kelima vokal あ・い・う・え・お menjadi fondasi pelafalan seluruh suku kata bahasa Jepang.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000001', 'b0000002-0000-0000-0000-000000000002', NULL, 'reading', 'fill_blank', 'Pilih huruf Hiragana yang dibaca "u":', '{"options":["う","あ","え","お"],"translation":"Vokal U dalam Hiragana","sentence_template":"い [blank] え (urutannya a-i-u-e-o)"}'::jsonb, '{"selected":"う"}'::jsonb, NULL, '{"あ":"あ dibaca a.","お":"お dibaca o."}'::jsonb, 'Huruf う dibaca "u", berada di urutan ketiga deret vokal.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000002', 'b0000002-0000-0000-0000-000000000002', NULL, 'listening', 'listening_choice', 'Dengarkan kata berikut dan pilih artinya yang tepat:', '{"options":[{"id":"opt_1","text":"Rumah"},{"id":"opt_2","text":"Air"},{"id":"opt_3","text":"Kopi"},{"id":"opt_4","text":"Buku"}],"audio_text":"いえ"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'いえ (ie) berarti rumah dalam bahasa Jepang.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-010001000006', 'b0000002-0000-0000-0000-000000000002', NULL, 'listening', 'listening_choice', 'Dengarkan vokal berurutan ini:', '{"options":[{"id":"opt_1","text":"Urutan 5 vokal"},{"id":"opt_2","text":"Deret K"},{"id":"opt_3","text":"Deret S"},{"id":"opt_4","text":"Kata salam"}],"audio_text":"あいうえお"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Audio melafalkan urutan 5 vokal standar: a-i-u-e-o.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-010001000007', 'b0000002-0000-0000-0000-000000000002', NULL, 'writing', 'sentence_builder', 'Susun huruf menjadi kata "Cinta / kasih (ai)":', '{"romaji":"Ai","tokens":["あ","い","う","え"],"target_translation":"Cinta / kasih (ai)"}'::jsonb, '["あ","い"]'::jsonb, NULL, NULL, 'あ (a) + い (i) = あい (ai).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-010001000008', 'b0000002-0000-0000-0000-000000000002', NULL, 'speaking', 'speaking_repeat', 'Lafalkan 5 vokal utama bahasa Jepang dengan runtut:', '{"romaji":"a-i-u-e-o","audio_text":"あいうえお","display_text":"あいうえお"}'::jsonb, '{"expected_transcript":"あいうえお"}'::jsonb, NULL, NULL, 'Ucapkan lima vokal dasar dengan tempo stabil.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f78afc74-519d-4b51-97aa-ef3c822fca38', 'b0000002-0000-0000-0000-000000000003', NULL, 'writing', 'sentence_builder', 'Susun salam perkenalan lengkap: "Senang bertemu pertama kali, mohon bantuannya."', '{"romaji":"Hajimemashite, douzo yoroshiku onegaishimasu.","tokens":["はじめまして","どうぞ","よろしく","おねがいします"],"target_translation":"Senang bertemu pertama kali, mohon bantuannya."}'::jsonb, '["はじめまして","どうぞ","よろしく","おねがいします"]'::jsonb, '[["初めまして","どうぞ","よろしく","おねがいします"],["はじめまして","よろしく","おねがいします"]]'::jsonb, NULL, '「はじめまして、どうぞよろしくおねがいします」(Hajimemashite, douzo yoroshiku onegaishimasu) adalah salam perkenalan sopan yang paling umum di Jepang.', 1, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('36e471de-83bd-44ea-bf93-52fc9de40923', 'b0000002-0000-0000-0000-000000000003', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan ungkapan santun perkenalan ("Mohon bantuannya / Senang berkenalan dengan Anda") berikut dengan pelafalan yang jelas.', '{"romaji":"Douzo yoroshiku onegaishimasu","translation":"Mohon bantuannya / Senang berkenalan dengan Anda","display_text":"どうぞよろしくおねがいします","phonetic_breakdown":["dou-zo","yo-ro-shi-ku","o-ne-gai-shi-ma-su"]}'::jsonb, '{"expected_transcript":"どうぞよろしくおねがいします"}'::jsonb, '[["どうぞよろしくお願いします"],["よろしくおねがいします"]]'::jsonb, NULL, 'Ungkapan ini adalah penutup wajib perkenalan diri dalam kultur kerja Jepang yang bermakna "Mohon kerja sama dan bimbingan baiknya".', 2, '2026-11-16T14:02:48.021082+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000015-0000-0000-0000-000000000002', 'b0000002-0000-0000-0000-000000000003', NULL, 'listening', 'listening_choice', 'Dengarkan sapaan pagi yang sopan berikut. Apa arti ungkapan tersebut?', '{"options":[{"id":"opt_1","text":"Selamat pagi (sopan)"},{"id":"opt_2","text":"Selamat malam"},{"id":"opt_3","text":"Terima kasih"},{"id":"opt_4","text":"Sampai jumpa"}],"audio_text":"おはようございます"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, '{"opt_2":"Selamat malam adalah こんばんは (konbanwa).","opt_3":"Terima kasih adalah ありがとうございます."}'::jsonb, '「おはようございます」 adalah salam pagi formal yang diucapkan kepada rekan kerja dan atasan.', 3, '2026-11-18T11:46:30.450543+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000003', 'b0000002-0000-0000-0000-000000000003', NULL, 'reading', 'fill_blank', 'Pilih huruf Hiragana yang dibaca "o":', '{"options":["お","あ","う","え"],"translation":"Uang (o-ka-ne)","sentence_template":"[blank] かね"}'::jsonb, '{"selected":"お"}'::jsonb, NULL, '{"あ":"あ dibaca a."}'::jsonb, 'Huruf お dibaca "o", membentuk kata おかね (uang).', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000004', 'b0000002-0000-0000-0000-000000000003', NULL, 'listening', 'listening_choice', 'Dengarkan sapaan malam ini. Apa artinya?', '{"options":[{"id":"opt_1","text":"Selamat malam"},{"id":"opt_2","text":"Selamat pagi"},{"id":"opt_3","text":"Selamat siang"},{"id":"opt_4","text":"Selamat tidur"}],"audio_text":"こんばんは"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'こんばんは (konbanwa) diucapkan untuk menyapa saat malam hari.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-020005000006', 'b0000002-0000-0000-0000-000000000003', NULL, 'reading', 'fill_blank', 'Lengkapi frasa tunjuk ''Ini sushi'':', '{"options":["すし","いぬ","ねこ","くつ"],"translation":"Ini adalah sushi","sentence_template":"これ は [blank] です"}'::jsonb, '{"selected":"すし"}'::jsonb, NULL, NULL, 'これ は すし です.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-020005000007', 'b0000002-0000-0000-0000-000000000003', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Itu adalah anjing":', '{"romaji":"Sore wa inu desu","tokens":["それ","は","いぬ","です"],"target_translation":"Itu adalah anjing"}'::jsonb, '["それ","は","いぬ","です"]'::jsonb, NULL, NULL, 'Sore wa inu desu.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-020005000008', 'b0000002-0000-0000-0000-000000000003', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat ''これ は ねこ です'' (Ini kucing):', '{"romaji":"kore wa neko desu","audio_text":"これ は ねこ です","display_text":"これ は ねこ です"}'::jsonb, '{"expected_transcript":"これ は ねこ です"}'::jsonb, NULL, NULL, 'Lafalkan dengan intonasi wajar.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000018', 'b0000018-0000-0000-0000-000000000001', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'reading', 'fill_blank', 'Lengkapi pertanyaan benda: あなた の かばん は [blank] ですか。', '{"options":["どれ","だれ","どこ","いつ"],"translation":"Tas milikmu yang mana?","sentence_template":"あなた の かばん は [blank] ですか。"}'::jsonb, '{"selected":"どれ"}'::jsonb, NULL, '{"これ":"これ adalah jawaban (ini), bukan kata tanya."}'::jsonb, 'どれ dipakai saat memilih "yang mana" di antara tiga benda atau lebih.', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000019', 'b0000018-0000-0000-0000-000000000001', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'writing', 'sentence_builder', 'Susun kalimat: "Tuan Tanaka adalah orang Jepang."', '{"romaji":"Tanaka-san wa nihonjin desu.","tokens":["たなかさん","は","にほんじん","です","インドネシアじん"],"target_translation":"Tuan Tanaka orang Jepang."}'::jsonb, '["たなかさん","は","にほんじん","です"]'::jsonb, NULL, NULL, 'Tambahkan じん (jin) setelah nama negara untuk menyatakan kewarganegaraan.', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000020', 'b0000018-0000-0000-0000-000000000001', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'reading', 'fill_blank', 'Pilih kata bahasa Jepang untuk "ayah (milik sendiri)":', '{"options":["ちち","はは","あに","あね"],"translation":"Ayah saya karyawan perusahaan.","sentence_template":"[blank] は かいしゃいん です。"}'::jsonb, '{"selected":"ちち"}'::jsonb, NULL, '{"はは":"はは berarti ibu."}'::jsonb, 'ちち (chichi) digunakan saat menyebut ayah kandung sendiri kepada orang lain.', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000021', 'b0000018-0000-0000-0000-000000000001', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'writing', 'sentence_builder', 'Susun kalimat: "Ibu saya adalah guru."', '{"romaji":"Watashi no haha wa kyoushi desu.","tokens":["わたし","の","はは","は","きょうし","です"],"target_translation":"Ibu saya adalah guru."}'::jsonb, '["わたし","の","はは","は","きょうし","です"]'::jsonb, NULL, NULL, 'わたしのはは berarti ibu saya, dan きょうし berarti guru/pengajar.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000022', 'b0000018-0000-0000-0000-000000000001', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'listening', 'listening_choice', 'Dengarkan kalimat keluarga berikut. Siapa yang disebutkan?', '{"options":[{"id":"opt_1","text":"Kakak laki-laki saya"},{"id":"opt_2","text":"Kakak perempuan saya"},{"id":"opt_3","text":"Adik laki-laki saya"},{"id":"opt_4","text":"Ibu saya"}],"audio_text":"わたしの あには トーキョーに います。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'あに (ani) berarti kakak laki-laki sendiri.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000023', 'b0000018-0000-0000-0000-000000000001', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'reading', 'fill_blank', 'Akhiran sopan standar setelah nama orang lain adalah:', '{"options":["さん","くん","ちゃん","わたし"],"translation":"Tuan/Nona Suzuki baik hati.","sentence_template":"スズキ [blank] は 親切（しんせつ）です。"}'::jsonb, '{"selected":"さん"}'::jsonb, NULL, NULL, '～さん adalah panggilan hormat netral untuk menyapa orang lain.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-070002000007', 'b0000018-0000-0000-0000-000000000001', NULL, 'reading', 'fill_blank', 'Kanji 子 (ko) memiliki arti:', '{"options":["anak","ibu","ayah","saudara"],"sentence_template":"Kanji 子: [blank]"}'::jsonb, '{"selected":"anak"}'::jsonb, NULL, NULL, 'Kanji 子 berarti anak (kodomo, ko).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-070002000008', 'b0000018-0000-0000-0000-000000000001', NULL, 'listening', 'listening_choice', 'Dengarkan sebutan keluarga ini:', '{"options":[{"id":"opt_1","text":"Keluarga"},{"id":"opt_2","text":"Teman"},{"id":"opt_3","text":"Kakak"},{"id":"opt_4","text":"Tetangga"}],"audio_text":"かぞく"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'かぞく (kazoku) berarti keluarga.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
