INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-070002000011', 'b0000018-0000-0000-0000-000000000001', NULL, 'reading', 'fill_blank', 'Lengkapi kata ''teman'' (tomodachi):', '{"options":["も","ま","め","み"],"translation":"Teman","sentence_template":"と [blank] だ ち (teman)"}'::jsonb, '{"selected":"も"}'::jsonb, NULL, NULL, 'と + も + だ + ち = ともだち (teman).', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000037', 'b0000018-0000-0000-0000-000000000002', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'reading', 'fill_blank', 'Lengkapi kata keterangan frekuensi "sering": わたし は [blank] スポーツ を します。', '{"options":["よく","あまり","ぜんぜん","いつ"],"translation":"Saya sering berolahraga.","sentence_template":"わたし は [blank] スポーツ を します。"}'::jsonb, '{"selected":"よく"}'::jsonb, NULL, '{"あまり":"あまり dipakai dengan kalimat negatif (jarang)."}'::jsonb, 'よく (yoku) berarti sering/dengan baik dalam kalimat positif.', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000038', 'b0000018-0000-0000-0000-000000000002', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'reading', 'fill_blank', 'Lengkapi kalimat negatif: わたし は あまり テレビ を [blank]。', '{"options":["みません","みます","みましょう","みました"],"translation":"Saya jarang menonton TV.","sentence_template":"わたし は あまり テレビ を [blank]。"}'::jsonb, '{"selected":"みません"}'::jsonb, NULL, '{"みます":"あまり selalu berpasangan dengan bentuk negatif ～ません."}'::jsonb, 'Kata keterangan あまり (tidak terlalu/jarang) wajib berpasangan dengan verba negatif ～ません.', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000039', 'b0000018-0000-0000-0000-000000000002', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'writing', 'sentence_builder', 'Susun kalimat kebiasaan: "Setiap hari saya belajar bahasa Jepang."', '{"romaji":"Mainichi nihongo o benkyou shimasu.","tokens":["まいにち","にほんご","を","べんきょうします"],"target_translation":"Setiap hari saya belajar bahasa Jepang."}'::jsonb, '["まいにち","にほんご","を","べんきょうします"]'::jsonb, NULL, NULL, 'まいにち (setiap hari) diletakkan di awal kalimat atau sebelum objek.', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000040', 'b0000018-0000-0000-0000-000000000002', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'listening', 'listening_choice', 'Dengarkan kebiasaan berikut. Kapan pembicara menonton film?', '{"options":[{"id":"opt_1","text":"Kadang-kadang"},{"id":"opt_2","text":"Setiap hari"},{"id":"opt_3","text":"Tidak pernah"},{"id":"opt_4","text":"Setiap pagi"}],"audio_text":"ときどき えいがを みます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ときどき (tokidoki) berarti kadang-kadang.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000041', 'b0000018-0000-0000-0000-000000000002', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'reading', 'fill_blank', 'Pilih pasangan yang tepat untuk ぜんぜん (sama sekali tidak): おさけ を ぜんぜん [blank]。', '{"options":["のみません","のみます","のみましょう","のんで"],"translation":"Saya sama sekali tidak minum alkohol.","sentence_template":"おさけ を ぜんぜん [blank]。"}'::jsonb, '{"selected":"のみません"}'::jsonb, NULL, NULL, 'ぜんぜん selalu berpasangan dengan bentuk negatif ～ません.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000042', 'b0000018-0000-0000-0000-000000000002', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'writing', 'sentence_builder', 'Susun kalimat: "Kadang-kadang saya makan siang di taman."', '{"romaji":"Tokidoki kouen de hirugohan o tabemasu.","tokens":["ときどき","こうえん","で","ひるごはん","を","たべます"],"target_translation":"Kadang-kadang makan siang di taman."}'::jsonb, '["ときどき","こうえん","で","ひるごはん","を","たべます"]'::jsonb, NULL, NULL, 'Tempat aktivitas memakai で (こうえんで) dan objek memakai を (ひるごはんを).', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000043', 'b0000018-0000-0000-0000-000000000002', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'listening', 'listening_choice', 'Dengarkan pernyataan ini. Seberapa sering ia membaca buku?', '{"options":[{"id":"opt_1","text":"Selalu di malam hari"},{"id":"opt_2","text":"Kadang di pagi hari"},{"id":"opt_3","text":"Tidak pernah membaca"},{"id":"opt_4","text":"Hanya hari Minggu"}],"audio_text":"いつも よる ほんを よみます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'いつも (itsumo) berarti selalu, dan よる (yoru) berarti malam hari.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-120005000008', 'b0000018-0000-0000-0000-000000000002', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Besok saya akan belajar'':', '{"options":["べんきょうし","たべ","のみ","み"],"translation":"Benkyoushimasu","sentence_template":"あした [blank] ます"}'::jsonb, '{"selected":"べんきょうし"}'::jsonb, NULL, NULL, 'べんきょうします = belajar.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-120005000009', 'b0000018-0000-0000-0000-000000000002', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Besok belajar bahasa Jepang":', '{"romaji":"Ashita nihongo o benkyoushimasu","tokens":["あした","にほんご","を","べんきょうします"],"target_translation":"Besok belajar bahasa Jepang"}'::jsonb, '["あした","にほんご","を","べんきょうします"]'::jsonb, NULL, NULL, 'Ashita nihongo o benkyoushimasu.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000057', 'b0000018-0000-0000-0000-000000000003', '79e54427-faad-401e-b423-a97ff3e695d8', 'reading', 'fill_blank', 'Bulan April dalam bahasa Jepang dibaca:', '{"options":["しがつ","さんがつ","ごがつ","いちがつ"],"translation":"Bunga sakura mekar di bulan April.","sentence_template":"さくらは [blank] に さきます。"}'::jsonb, '{"selected":"しがつ"}'::jsonb, NULL, '{"さんがつ":"さんがつ adalah bulan Maret (bulan ke-3)."}'::jsonb, 'April adalah bulan ke-4 dan dibaca しがつ (shigatsu), bukan よんがつ.', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000058', 'b0000018-0000-0000-0000-000000000003', '79e54427-faad-401e-b423-a97ff3e695d8', 'reading', 'fill_blank', 'Tanggal 1 tiap bulan dibaca khusus sebagai:', '{"options":["ついたち","ふつか","みっか","いちにち"],"translation":"Ulang tahunnya tanggal 1 Mei.","sentence_template":"たんじょうびは ５がつ [blank] です。"}'::jsonb, '{"selected":"ついたち"}'::jsonb, NULL, '{"ふつか":"ふつか adalah tanggal 2."}'::jsonb, 'Tanggal 1–10 punya bacaan khusus: ついたち(1), ふつか(2), みっか(3).', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000059', 'b0000018-0000-0000-0000-000000000003', '79e54427-faad-401e-b423-a97ff3e695d8', 'writing', 'sentence_builder', 'Susun kalimat jadwal: "Bulan depan tanggal 5 saya akan datang ke Tokyo."', '{"romaji":"Raigetsu itsuka ni Toukyou e kimasu.","tokens":["らいげつ","いつか","に","とうきょう","へ","きます"],"target_translation":"Bulan depan tgl 5 datang ke Tokyo."}'::jsonb, '["らいげつ","いつか","に","とうきょう","へ","きます"]'::jsonb, NULL, NULL, 'Tanggal spesifik diikuti partikel に (いつかに = pada tanggal 5).', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000060', 'b0000018-0000-0000-0000-000000000003', '79e54427-faad-401e-b423-a97ff3e695d8', 'listening', 'listening_choice', 'Dengarkan tanggal penting berikut. Bulan dan tanggal berapakah yang disebutkan?', '{"options":[{"id":"opt_1","text":"10 Oktober"},{"id":"opt_2","text":"10 Agustus"},{"id":"opt_3","text":"20 Oktober"},{"id":"opt_4","text":"5 September"}],"audio_text":"にほんへ １０がつ とおか に いきます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '１０がつ (Oktober) + とおか (tanggal 10).', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000061', 'b0000018-0000-0000-0000-000000000003', '79e54427-faad-401e-b423-a97ff3e695d8', 'reading', 'fill_blank', 'Bulan Juli (bulan ke-7) dibaca sebagai:', '{"options":["しちがつ","くがつ","ろくがつ","はちがつ"],"translation":"Libur musim panas mulai bulan Juli.","sentence_template":"なつやすみは [blank] から です。"}'::jsonb, '{"selected":"しちがつ"}'::jsonb, NULL, NULL, 'Juli (bulan ke-7) dibaca しちがつ (shichigatsu), bukan なながつ.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000062', 'b0000018-0000-0000-0000-000000000003', '79e54427-faad-401e-b423-a97ff3e695d8', 'reading', 'fill_blank', 'Kata tanya untuk menanyakan kapan suatu acara berlangsung adalah:', '{"options":["いつ","どこ","だれ","いくら"],"translation":"Kapan ujiannya?","sentence_template":"しけん は [blank] ですか。"}'::jsonb, '{"selected":"いつ"}'::jsonb, NULL, NULL, 'いつ berarti "kapan", dan tidak perlu ditambah partikel に.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000063', 'b0000018-0000-0000-0000-000000000003', '79e54427-faad-401e-b423-a97ff3e695d8', 'writing', 'sentence_builder', 'Susun kalimat: "Ulang tahun saya tanggal 20 September."', '{"romaji":"Watashi no tanjoubi wa kugatsu hatsuka desu.","tokens":["わたし","の","たんじょうび","は","くがつ","はつか","です"],"target_translation":"Ulang tahun saya 20 September."}'::jsonb, '["わたし","の","たんじょうび","は","くがつ","はつか","です"]'::jsonb, NULL, NULL, 'September adalah くがつ dan tanggal 20 dibaca khusus はつか (hatsuka).', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-100005000008', 'b0000018-0000-0000-0000-000000000003', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat jam bangun tidur ''Bangun jam 6'':', '{"options":["おき","ね","いき","き"],"translation":"Okimasu","sentence_template":"６時 に [blank] ます (Bangun)"}'::jsonb, '{"selected":"おき"}'::jsonb, NULL, NULL, 'おきます (okimasu) = bangun tidur.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-100005000009', 'b0000018-0000-0000-0000-000000000003', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Setiap pagi bangun jam 6":', '{"romaji":"Maiasa roku-ji ni okimasu","tokens":["まいあさ","六時","に","おきます"],"target_translation":"Setiap pagi bangun jam 6"}'::jsonb, '["まいあさ","六時","に","おきます"]'::jsonb, NULL, NULL, 'Maiasa roku-ji ni okimasu.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000064', 'b0000018-0000-0000-0000-000000000004', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'reading', 'fill_blank', 'Lengkapi sarana transportasi jalan kaki: えき まで [blank] いきます。', '{"options":["あるいて","バスで","タクシーで","くるまで"],"translation":"Pergi ke stasiun dengan berjalan kaki.","sentence_template":"えき まで [blank] いきます。"}'::jsonb, '{"selected":"あるいて"}'::jsonb, NULL, '{"バスで":"バスで berarti naik bus."}'::jsonb, 'あるいて (aruite) adalah bentuk untuk menyatakan "berjalan kaki" tanpa partikel で.', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000065', 'b0000018-0000-0000-0000-000000000004', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'writing', 'sentence_builder', 'Susun rentang jam kerja: "Saya bekerja dari jam 8 sampai jam 5."', '{"romaji":"Hachiji kara goji made hatarakimasu.","tokens":["８じ","から","５じ","まで","はたらきます"],"target_translation":"Bekerja dari jam 8 sampai jam 5."}'::jsonb, '["８じ","から","５じ","まで","はたらきます"]'::jsonb, NULL, NULL, 'Gunakan pola [Mulai] から [Selesai] まで + verba.', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000066', 'b0000018-0000-0000-0000-000000000004', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'listening', 'listening_choice', 'Dengarkan rute perjalanan berikut. Berapa lama waktu tempuhnya?', '{"options":[{"id":"opt_1","text":"20 menit dengan kereta bawah tanah"},{"id":"opt_2","text":"10 menit dengan bus"},{"id":"opt_3","text":"30 menit berjalan kaki"},{"id":"opt_4","text":"15 menit dengan taksi"}],"audio_text":"ちかてつで ２０ぷん かかります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ちかてつ (chikatetsu) = kereta bawah tanah, ２０ぷん (nijuppun) = 20 menit.', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000067', 'b0000018-0000-0000-0000-000000000004', '05ca9c23-60a3-4eb9-bc58-259bbf0033c9', 'reading', 'fill_blank', 'Kata bahasa Jepang untuk "kereta cepat Shinkansen" adalah:', '{"options":["しんかんせん","じてんしゃ","ひこうき","ふね"],"translation":"Pergi ke Kyoto naik Shinkansen.","sentence_template":"[blank] で きょうとへ いきます。"}'::jsonb, '{"selected":"しんかんせん"}'::jsonb, NULL, '{"ひこうき":"ひこうき berarti pesawat terbang."}'::jsonb, 'しんかんせん adalah kereta peluru cepat antarkota di Jepang.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000068', 'b0000018-0000-0000-0000-000000000004', '05ca9c23-60a3-4eb9-bc58-259bbf0033c9', 'writing', 'sentence_builder', 'Susun kalimat tujuan pulang: "Setiap hari saya pulang ke rumah jam 6."', '{"romaji":"Mainichi rokuji ni uchi e kaerimasu.","tokens":["まいにち","６じ","に","うち","へ","かえります"],"target_translation":"Setiap hari pulang jam 6."}'::jsonb, '["まいにち","６じ","に","うち","へ","かえります"]'::jsonb, NULL, NULL, 'うちへ かえります berarti pulang ke rumah.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000069', 'b0000018-0000-0000-0000-000000000004', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'listening', 'listening_choice', 'Dengarkan informasi jam tutup toko ini. Toko buka sampai jam berapa?', '{"options":[{"id":"opt_1","text":"Sampai jam 9 malam"},{"id":"opt_2","text":"Sampai jam 5 sore"},{"id":"opt_3","text":"Mulai jam 9 pagi"},{"id":"opt_4","text":"Buka 24 jam"}],"audio_text":"このみせは よる ９じまで です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '～まで berarti "sampai", よる ９じ berarti jam 9 malam.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000070', 'b0000018-0000-0000-0000-000000000004', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'reading', 'fill_blank', 'Partikel untuk menyatakan alat transportasi adalah:', '{"options":["で","を","の","と"],"translation":"Saya datang ke Jepang naik pesawat.","sentence_template":"ひこうき [blank] にほんへ きました。"}'::jsonb, '{"selected":"で"}'::jsonb, NULL, NULL, 'Partikel で menandai sarana transportasi yang digunakan.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-150005000008', 'b0000018-0000-0000-0000-000000000004', NULL, 'reading', 'fill_blank', 'Lengkapi rentang jarak/waktu ''Dari stasiun sampai kantor'':', '{"options":["まで","から","へ","に"],"sentence_template":"えき から かいしゃ [blank]"}'::jsonb, '{"selected":"まで"}'::jsonb, NULL, NULL, 'から～まで = dari... sampai...', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-150005000009', 'b0000018-0000-0000-0000-000000000004', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Dari Tokyo sampai Osaka":', '{"romaji":"Toukyou kara Oosaka made","tokens":["とうきょう","から","おおさか","まで"],"target_translation":"Dari Tokyo sampai Osaka"}'::jsonb, '["とうきょう","から","おおさか","まで"]'::jsonb, NULL, NULL, 'Toukyou kara Oosaka made.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000088', 'b0000018-0000-0000-0000-000000000005', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat denah benda: "Di dekat jendela ada meja kerja."', '{"romaji":"Mado no chikaku ni tsukue ga arimasu.","tokens":["まど","の","ちかく","に","つくえ","が","あります"],"target_translation":"Di dekat jendela ada meja."}'::jsonb, '["まど","の","ちかく","に","つくえ","が","あります"]'::jsonb, NULL, NULL, 'ちかく (chikaku) berarti dekat / di sekitar.', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000089', 'b0000018-0000-0000-0000-000000000005', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan situasi ruangan ini. Di mana letak mesin cetak (printer)?', '{"options":[{"id":"opt_1","text":"Di sebelah mesin fotokopi"},{"id":"opt_2","text":"Di dalam lemari arsip"},{"id":"opt_3","text":"Di bawah meja direktur"},{"id":"opt_4","text":"Di lantai satu"}],"audio_text":"プリンターは コピーきの となりに あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'となり berarti tepat di sebelah.', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000090', 'b0000018-0000-0000-0000-000000000005', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Pasangan kata posisi "di belakang" adalah:', '{"options":["うしろ","まえ","うえ","した"],"translation":"Di belakang toko buku ada taman.","sentence_template":"ほんや の [blank] に こうえん が あります。"}'::jsonb, '{"selected":"うしろ"}'::jsonb, NULL, '{"まえ":"まえ berarti di depan."}'::jsonb, 'うしろ (ushiro) adalah lawan kata dari まえ (depan).', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000091', 'b0000018-0000-0000-0000-000000000005', 'dd9fe2c9-ae3f-438c-9f46-0fdd53524078', 'reading', 'fill_blank', 'Menanyakan jumlah orang di dalam ruangan memakai kata tanya:', '{"options":["なんにん","なんじ","いくつ","いくら"],"translation":"Ada berapa orang siswa di kelas?","sentence_template":"きょうしつ に がくせい が [blank] いますか。"}'::jsonb, '{"selected":"なんにん"}'::jsonb, NULL, NULL, 'なんにん (nannin) menanyakan jumlah orang.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000092', 'b0000018-0000-0000-0000-000000000005', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat keberadaan staf: "Di ruang istirahat ada tiga karyawan."', '{"romaji":"Kyuukeishitsu ni shain ga sannin imasu.","tokens":["きゅうけいしつ","に","しゃいん","が","さんにん","います"],"target_translation":"Di ruang istirahat ada 3 karyawan."}'::jsonb, '["きゅうけいしつ","に","しゃいん","が","さんにん","います"]'::jsonb, NULL, NULL, 'Jumlah orang diletakkan tepat sebelum います (さんにん います).', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000093', 'b0000018-0000-0000-0000-000000000005', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan deskripsi ruangan ini. Benda apakah yang ada di atas meja?', '{"options":[{"id":"opt_1","text":"Kamera"},{"id":"opt_2","text":"Sepeda"},{"id":"opt_3","text":"Payung"},{"id":"opt_4","text":"Jaket"}],"audio_text":"つくえの うえに カメラが あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'カメラ (kamera) berarti kamera.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000094', 'b0000018-0000-0000-0000-000000000005', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Pilih kata benda yang tepat untuk "pintu masuk gedung":', '{"options":["げんかん","まど","てんじょう","ほんだな"],"translation":"Melepas sepatu di pintu masuk (genkan).","sentence_template":"[blank] で くつ を ぬぎます。"}'::jsonb, '{"selected":"げんかん"}'::jsonb, NULL, NULL, 'げんかん (genkan) adalah area pintu masuk tradisional di rumah/gedung Jepang.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000095', 'b0000018-0000-0000-0000-000000000005', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Kata arah "belok kanan" dalam bahasa Jepang adalah:', '{"options":["みぎ","ひだり","まっすぐ","うえ"],"translation":"Tolong belok ke kanan di persimpangan berikutnya.","sentence_template":"つぎの かどを [blank] へ まがってください。"}'::jsonb, '{"selected":"みぎ"}'::jsonb, NULL, '{"ひだり":"ひだり berarti kiri."}'::jsonb, 'みぎ (migi) = kanan, ひだり (hidari) = kiri, まっすぐ (massugu) = lurus.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-170005000009', 'b0000018-0000-0000-0000-000000000005', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Di samping rumah ada pohon'':', '{"options":["あります","います","します","です"],"sentence_template":"いえ の よこ に き が [blank]"}'::jsonb, '{"selected":"あります"}'::jsonb, NULL, NULL, 'Pohon adalah tumbuhan -> あります.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-170005000010', 'b0000018-0000-0000-0000-000000000005', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Di samping rumah ada pohon":', '{"romaji":"Ie no yoko ni ki ga arimasu","tokens":["いえ","の","よこ","に","木が","あります"],"target_translation":"Di samping rumah ada pohon"}'::jsonb, '["いえ","の","よこ","に","木が","あります"]'::jsonb, NULL, NULL, 'Ie no yoko ni ki ga arimasu.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000096', 'b0000018-0000-0000-0000-000000000006', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat petunjuk jalan: "Jalan terus lurus di jalan ini."', '{"romaji":"Kono michi o massugu itte kudasai.","tokens":["この","みち","を","まっすぐ","いってください"],"target_translation":"Jalan lurus terus di jalan ini."}'::jsonb, '["この","みち","を","まっすぐ","いってください"]'::jsonb, NULL, NULL, 'Untuk jalan yang dilalui lurus, gunakan partikel を sebelum まっすぐ.', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000097', 'b0000018-0000-0000-0000-000000000006', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan petunjuk arah ini. Belok ke mana di lampu merah?', '{"options":[{"id":"opt_1","text":"Belok ke kiri"},{"id":"opt_2","text":"Belok ke kanan"},{"id":"opt_3","text":"Jalan lurus saja"},{"id":"opt_4","text":"Putar balik"}],"audio_text":"しんごうを ひだりへ まがります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'しんごう (lampu lalu lintas) + ひだりへ まがります (belok kiri).', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000098', 'b0000018-0000-0000-0000-000000000006', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Kata untuk menyebut "perempatan persimpangan" adalah:', '{"options":["こうさてん","ちゅうしゃじょう","こうばん","はし"],"translation":"Belok ke kanan di perempatan itu.","sentence_template":"あの [blank] を みぎへ まがります。"}'::jsonb, '{"selected":"こうさてん"}'::jsonb, NULL, NULL, 'こうさてん (kousaten) berarti persimpangan jalan.', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000099', 'b0000018-0000-0000-0000-000000000006', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun petunjuk letak pos polisi: "Pos polisi ada di antara bank dan sekolah."', '{"romaji":"Kouban wa ginkou to gakkou no aida ni arimasu.","tokens":["こうばん","は","ぎんこう","と","がっこう","の","あいだ","に","あります"],"target_translation":"Pos polisi di antara bank & sekolah."}'::jsonb, '["こうばん","は","ぎんこう","と","がっこう","の","あいだ","に","あります"]'::jsonb, NULL, NULL, 'Pola [A] と [B] の あいだ berarti "di antara A dan B".', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000100', 'b0000018-0000-0000-0000-000000000006', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan arahan staf stasiun ini. Di mana pintu keluar timur?', '{"options":[{"id":"opt_1","text":"Di depan tangga"},{"id":"opt_2","text":"Di samping eskalator"},{"id":"opt_3","text":"Di lantai bawah tanah"},{"id":"opt_4","text":"Di ujung peron 3"}],"audio_text":"ひがしぐちは かいだんの まえです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'かいだんの まえ berarti di depan tangga.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000101', 'b0000018-0000-0000-0000-000000000006', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Lawan kata "timur (ひがし)" adalah "barat", yaitu:', '{"options":["にし","きた","みなみ","ひがし"],"translation":"Halte bus ada di pintu keluar barat.","sentence_template":"バスていは [blank] ぐち に あります。"}'::jsonb, '{"selected":"にし"}'::jsonb, NULL, NULL, 'Empat arah mata angin: きた(Utara), みなみ(Selatan), ひがし(Timur), にし(Barat).', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000102', 'b0000018-0000-0000-0000-000000000006', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat petunjuk: "Tolong menyeberangi jembatan itu."', '{"romaji":"Ano hashi o watatte kudasai.","tokens":["あの","はし","を","わたって","ください"],"target_translation":"Tolong seberangi jembatan itu."}'::jsonb, '["あの","はし","を","わたって","ください"]'::jsonb, NULL, NULL, 'はし berarti jembatan dan わたる (bentuk-te わたって) berarti menyeberangi.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000103', 'b0000018-0000-0000-0000-000000000006', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan informasi arah ini. Di sebelah mana apotek itu berada?', '{"options":[{"id":"opt_1","text":"Di seberang toko bunga"},{"id":"opt_2","text":"Di atas klinik"},{"id":"opt_3","text":"Di sebelah kantor pos"},{"id":"opt_4","text":"Di dalam mal"}],"audio_text":"くすりやは はなやの むかいに あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'むかい (mukai) berarti berhadapan / tepat di seberang jalan.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210005000009', 'b0000018-0000-0000-0000-000000000006', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat petunjuk jalan ''Ada di sebelah kanan'':', '{"options":["あります","います","します","です"],"sentence_template":"みぎがわ に [blank]"}'::jsonb, '{"selected":"あります"}'::jsonb, NULL, NULL, 'Gedung di sebelah kanan -> あります.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210005000010', 'b0000018-0000-0000-0000-000000000006', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Ada di kiri":', '{"romaji":"Hidari ni arimasu","tokens":["左","に","あります"],"target_translation":"Ada di kiri"}'::jsonb, '["左","に","あります"]'::jsonb, NULL, NULL, 'Hidari ni arimasu.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000121', 'b0000018-0000-0000-0000-000000000007', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'writing', 'sentence_builder', 'Susun kalimat belanja: "Tolong perlihatkan baju putih itu."', '{"romaji":"Ano shiroi shatsu o misete kudasai.","tokens":["あの","しろい","シャツ","を","みせて","ください"],"target_translation":"Tolong perlihatkan kemeja putih itu."}'::jsonb, '["あの","しろい","シャツ","を","みせて","ください"]'::jsonb, NULL, NULL, 'しろい (putih) menerangkan シャツ sebelum objek を みせてください.', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000122', 'b0000018-0000-0000-0000-000000000007', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'listening', 'listening_choice', 'Dengarkan percakapan kasir ini. Berapa harga jaket hitamnya?', '{"options":[{"id":"opt_1","text":"5.000 Yen"},{"id":"opt_2","text":"500 Yen"},{"id":"opt_3","text":"1.500 Yen"},{"id":"opt_4","text":"10.000 Yen"}],"audio_text":"くろい ジャケットは ごせんえん です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ごせんえん (gosen-en) berarti 5.000 yen.', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000123', 'b0000018-0000-0000-0000-000000000007', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Lawan kata "あたらしい" (baru) adalah:', '{"options":["ふるい","たかい","やすい","ながい"],"translation":"Sepeda ini agak tua/lama.","sentence_template":"この じてんしゃ は すこし [blank] です。"}'::jsonb, '{"selected":"ふるい"}'::jsonb, NULL, NULL, 'ふるい (furui) berarti tua/lama (khusus benda, bukan umur manusia).', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000124', 'b0000018-0000-0000-0000-000000000007', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Lawan kata "おもい" (berat) untuk barang bawaan adalah:', '{"options":["かるい","つよい","ひろい","みじかい"],"translation":"Barang bawaan ini sangat ringan.","sentence_template":"この にもつ は とても [blank] です。"}'::jsonb, '{"selected":"かるい"}'::jsonb, NULL, NULL, 'かるい (karui) berarti ringan, kebalikan dari おもい (berat).', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000125', 'b0000018-0000-0000-0000-000000000007', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'writing', 'sentence_builder', 'Susun keluhan belanja: "Sepatu ini agak kecil dan mahal."', '{"romaji":"Kono kutsu wa chiisakute takai desu.","tokens":["この","くつ","は","ちいさくて","たかい","です"],"target_translation":"Sepatu ini kecil dan mahal."}'::jsonb, '["この","くつ","は","ちいさくて","たかい","です"]'::jsonb, NULL, NULL, 'Menyambungkan dua kata sifat-i memakai bentuk ～くて (ちいさくて).', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000126', 'b0000018-0000-0000-0000-000000000007', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'listening', 'listening_choice', 'Dengarkan komentar pembeli berikut. Mengapa ia tidak membeli mantel itu?', '{"options":[{"id":"opt_1","text":"Agak mahal"},{"id":"opt_2","text":"Ukurannya kebesaran"},{"id":"opt_3","text":"Warnanya kusam"},{"id":"opt_4","text":"Bahannya tipis"}],"audio_text":"ちょっと たかい ですね。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ちょっと たかい ですね berarti "agak mahal ya".', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000127', 'b0000018-0000-0000-0000-000000000007', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'reading', 'fill_blank', 'Jika warna tidak berakhir -い (misal: 緑/hijau), menyambung ke kata benda memakai:', '{"options":["みどり","あかい","しろい","あおい"],"translation":"Saya membeli payung hijau.","sentence_template":"[blank] の かさ を かいました。"}'::jsonb, '{"selected":"みどり"}'::jsonb, NULL, NULL, 'Warna kata benda seperti みどり (hijau) memakai partikel の sebelum kata benda.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000128', 'b0000018-0000-0000-0000-000000000007', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'writing', 'sentence_builder', 'Susun kalimat: "Tas merah ini sangat murah dan ringan."', '{"romaji":"Kono akai kaban wa yasukute karui desu.","tokens":["この","あかい","かばん","は","やすくて","かるい","です"],"target_translation":"Tas merah ini murah dan ringan."}'::jsonb, '["この","あかい","かばん","は","やすくて","かるい","です"]'::jsonb, NULL, NULL, 'やすい disambung dengan kata sifat berikutnya menjadi やすくて.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-190005000009', 'b0000018-0000-0000-0000-000000000007', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat pakaian ''Memakai jaket mantel'':', '{"options":["きます","はきます","かぶります","かけます"],"translation":"Kimasu","sentence_template":"コート を [blank]"}'::jsonb, '{"selected":"きます"}'::jsonb, NULL, NULL, 'Pakaian mantel = きます.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-190005000010', 'b0000018-0000-0000-0000-000000000007', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Memakai mantel":', '{"romaji":"Kooto o kimasu","tokens":["コート","を","着ます"],"target_translation":"Memakai mantel"}'::jsonb, '["コート","を","着ます"]'::jsonb, NULL, NULL, 'Kooto o kimasu.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000129', 'b0000018-0000-0000-0000-000000000008', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Musim ketika bunga sakura bermekaran di Jepang adalah:', '{"options":["はる","なつ","あき","ふゆ"],"translation":"Musim semi sakuranya indah.","sentence_template":"[blank] は さくら が きれい です。"}'::jsonb, '{"selected":"はる"}'::jsonb, NULL, NULL, 'Empat musim Jepang: はる(Semi), なつ(Panas), あき(Gugur), ふゆ(Dingin).', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000130', 'b0000018-0000-0000-0000-000000000008', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Kata benda untuk "salju" yang turun saat musim dingin adalah:', '{"options":["ゆき","あめ","かぜ","くも"],"translation":"Pada musim dingin turun salju.","sentence_template":"ふゆ に [blank] が ふります。"}'::jsonb, '{"selected":"ゆき"}'::jsonb, NULL, '{"あめ":"あめ berarti hujan air."}'::jsonb, 'ゆき (yuki) berarti salju, menggunakan kata kerja ふります (turun).', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000131', 'b0000018-0000-0000-0000-000000000008', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'writing', 'sentence_builder', 'Susun kalimat suasana musim: "Di musim panas udaranya panas tapi pemandangannya indah."', '{"romaji":"Natsu wa atsui desu ga keshiki ga kirei desu.","tokens":["なつ","は","あつい","ですが","けしき","が","きれい","です"],"target_translation":"Musim panas panas tapi pemandangannya indah."}'::jsonb, '["なつ","は","あつい","ですが","けしき","が","きれい","です"]'::jsonb, NULL, NULL, '～ですが berfungsi sebagai kata hubung "tetapi" dengan sopan.', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000132', 'b0000018-0000-0000-0000-000000000008', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'listening', 'listening_choice', 'Dengarkan laporan cuaca berikut. Bagaimana cuaca hari ini?', '{"options":[{"id":"opt_1","text":"Cerah tapi anginnya kencang"},{"id":"opt_2","text":"Hujan lebat sepanjang hari"},{"id":"opt_3","text":"Berawan dan dingin"},{"id":"opt_4","text":"Turun salju di sore hari"}],"audio_text":"きょうは はれですが、かぜが つよいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'はれ (cerah) + かぜが つよい (anginnya kencang).', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000133', 'b0000018-0000-0000-0000-000000000008', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'reading', 'fill_blank', 'Kata sifat-na untuk menggambarkan suasana "tenang dan damai" adalah:', '{"options":["しずか","にぎやか","ゆうめい","げんき"],"translation":"Taman ini sangat tenang.","sentence_template":"この こうえん は とても [blank] です。"}'::jsonb, '{"selected":"しずか"}'::jsonb, NULL, NULL, 'しずか (shizuka) berarti tenang/sunyi.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000134', 'b0000018-0000-0000-0000-000000000008', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'writing', 'sentence_builder', 'Susun kalimat kekaguman tempat: "Gunung Fuji adalah gunung terkenal di Jepang."', '{"romaji":"Fujisan wa yuumeina yama desu.","tokens":["ふじさん","は","ゆうめいな","やま","です"],"target_translation":"Gunung Fuji adalah gunung terkenal."}'::jsonb, '["ふじさん","は","ゆうめいな","やま","です"]'::jsonb, NULL, NULL, 'ゆうめい adalah kata sifat-na sehingga wajib memakai な sebelum やま (gunung).', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000135', 'b0000018-0000-0000-0000-000000000008', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'listening', 'listening_choice', 'Dengarkan percakapan musim berikut. Musim apakah yang paling tidak disukai pembicara?', '{"options":[{"id":"opt_1","text":"Musim dingin karena dingin"},{"id":"opt_2","text":"Musim panas karena lembap"},{"id":"opt_3","text":"Musim hujan karena becek"},{"id":"opt_4","text":"Musim gugur karena sepi"}],"audio_text":"ふゆは さむいから きらいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ふゆ (musim dingin) + さむいから (karena dingin) + きらい (tidak suka).', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000136', 'b0000018-0000-0000-0000-000000000008', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Kata untuk "daun musim gugur" yang berwarna merah di Jepang adalah:', '{"options":["もみじ","さくら","ゆき","海"],"translation":"Di musim gugur daun momiji indah.","sentence_template":"あき に [blank] が きれい です。"}'::jsonb, '{"selected":"もみじ"}'::jsonb, NULL, NULL, 'もみじ (momiji) adalah dedaunan merah khas musim gugur di Jepang.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-200007000009', 'b0000018-0000-0000-0000-000000000008', NULL, 'reading', 'fill_blank', 'Ujian Tahap 4 (Soal 9): Bentuk lampau dari kata sifat-I いい (bagus) adalah:', '{"options":["よかったです","いかったです","いくなかった","いいでした"],"sentence_template":"いい (bagus) -> lampau: [blank]"}'::jsonb, '{"selected":"よかったです"}'::jsonb, NULL, NULL, 'いい berubah dari basis よい -> よかったです.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-200007000010', 'b0000018-0000-0000-0000-000000000008', NULL, 'speaking', 'speaking_repeat', 'Ujian Tahap 4 (Soal 10): Lafalkan perbandingan komprehensif ''しんかんせん は バス より はやい です が、たかい です'':', '{"romaji":"shinkansen wa basu yori hayai desu ga, takai desu","audio_text":"しんかんせん は バス より はやい です が、たかい です","display_text":"しんかんせん は バス より はやい です が、たかい です"}'::jsonb, '{"expected_transcript":"しんかんせん は バス より はやい です が、たかい です"}'::jsonb, NULL, NULL, 'Lafalkan kalimat pamungkas Tahap 4 dengan sempurna.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000157', 'b0000018-0000-0000-0000-000000000009', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'reading', 'fill_blank', 'Bentuk lampau sopan dari kata kerja "いきます" (pergi) adalah:', '{"options":["いきました","いきます","いきましょう","いって"],"translation":"Kemarin pergi ke bioskop bersama teman.","sentence_template":"きのう ともだち と えいがかん へ [blank]。"}'::jsonb, '{"selected":"いきました"}'::jsonb, NULL, NULL, 'Akhiran ～ます diubah menjadi ～ました untuk waktu lampau.', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000158', 'b0000018-0000-0000-0000-000000000009', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'reading', 'fill_blank', 'Bentuk lampau negatif sopan dari "たべます" (tidak makan) adalah:', '{"options":["たべませんでした","たべません","たべました","たべなかった"],"translation":"Tadi pagi saya tidak sarapan.","sentence_template":"けさ あさごはん を [blank]。"}'::jsonb, '{"selected":"たべませんでした"}'::jsonb, NULL, NULL, 'Negatif lampau sopan selalu memakai ～ませんでした.', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000159', 'b0000018-0000-0000-0000-000000000009', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'writing', 'sentence_builder', 'Susun kalimat lampau: "Minggu lalu saya membeli sepatu baru."', '{"romaji":"Senshuu atarashii kutsu o kaimashita.","tokens":["せんしゅう","あたらしい","くつ","を","かいました"],"target_translation":"Minggu lalu membeli sepatu baru."}'::jsonb, '["せんしゅう","あたらしい","くつ","を","かいました"]'::jsonb, NULL, NULL, 'かいます (membeli) menjadi かいました (sudah membeli).', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000160', 'b0000018-0000-0000-0000-000000000009', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'listening', 'listening_choice', 'Dengarkan percakapan kemarin ini. Apa yang dilakukan di rumah?', '{"options":[{"id":"opt_1","text":"Belajar bahasa Jepang"},{"id":"opt_2","text":"Menonton film action"},{"id":"opt_3","text":"Menulis email kerja"},{"id":"opt_4","text":"Menelepon keluarga"}],"audio_text":"きのうの よる、にほんごを べんきょうしました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'べんきょうしました berarti sudah belajar.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000161', 'b0000018-0000-0000-0000-000000000009', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'reading', 'fill_blank', 'Kata waktu untuk "pekan lalu / minggu lalu" adalah:', '{"options":["せんしゅう","らいしゅう","こんしゅう","まいしゅう"],"translation":"Minggu lalu saya dinas luar kota ke Kobe.","sentence_template":"[blank] こうべ へ しゅっちょう しました。"}'::jsonb, '{"selected":"せんしゅう"}'::jsonb, NULL, '{"らいしゅう":"らいしゅう berarti minggu depan."}'::jsonb, 'せんしゅう = minggu lalu, こんしゅう = minggu ini, らいしゅう = minggu depan.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000162', 'b0000018-0000-0000-0000-000000000009', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'writing', 'sentence_builder', 'Susun kalimat tanya lampau: "Tadi pagi apakah kamu sudah minum kopi?"', '{"romaji":"Kesa koohii o nomimashita ka.","tokens":["けさ","コーヒー","を","のみましたか"],"target_translation":"Tadi pagi sudah minum kopi?"}'::jsonb, '["けさ","コーヒー","を","のみましたか"]'::jsonb, NULL, NULL, 'Tambahkan か di akhir verba lampau ～ました untuk bertanya hal yang sudah lewat.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000163', 'b0000018-0000-0000-0000-000000000009', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'listening', 'listening_choice', 'Dengarkan jawaban berikut. Apakah dia datang ke pesta kemarin?', '{"options":[{"id":"opt_1","text":"Tidak pergi karena sibuk"},{"id":"opt_2","text":"Pergi sebentar lalu pulang"},{"id":"opt_3","text":"Datang terlambat 1 jam"},{"id":"opt_4","text":"Lupa jadwal pestanya"}],"audio_text":"いいえ、いそがしかったから いきませんでした。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'いきませんでした adalah negatif lampau dari いきます (tidak pergi).', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000164', 'b0000018-0000-0000-0000-000000000009', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'reading', 'fill_blank', 'Kata untuk "tadi pagi" adalah:', '{"options":["けさ","きのう","あした","こんや"],"translation":"Tadi pagi bangun jam 6.","sentence_template":"[blank] ６じ に おきました。"}'::jsonb, '{"selected":"けさ"}'::jsonb, NULL, NULL, 'けさ (kesa) khusus berarti pagi ini / tadi pagi.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000165', 'b0000018-0000-0000-0000-000000000009', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'writing', 'sentence_builder', 'Susun kalimat lampau negatif: "Bulan lalu saya tidak membaca koran."', '{"romaji":"Sengetsu shinbun o yomimasen deshita.","tokens":["せんげつ","しんぶん","を","よみませんでした"],"target_translation":"Bulan lalu tidak membaca koran."}'::jsonb, '["せんげつ","しんぶん","を","よみませんでした"]'::jsonb, NULL, NULL, 'よみます (membaca) bentuk negatif lampaunya adalah よみませんでした.', 9, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260001000010', 'b0000018-0000-0000-0000-000000000009', NULL, 'reading', 'fill_blank', 'Bentuk-TA dari verba 買います (membeli) adalah:', '{"options":["かった","かいた","かんだ","かて"],"translation":"Katta","sentence_template":"かいます -> [blank]"}'::jsonb, '{"selected":"かった"}'::jsonb, NULL, NULL, 'Verba i/chi/ri -> った: 買った (katta).', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260001000011', 'b0000018-0000-0000-0000-000000000009', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Membeli baju baru":', '{"romaji":"Atarashii fuku o kaimashita","tokens":["新しい","服を","買いました"],"target_translation":"Membeli baju baru"}'::jsonb, '["新しい","服を","買いました"]'::jsonb, NULL, NULL, 'Atarashii fuku o kaimashita.', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260001000012', 'b0000018-0000-0000-0000-000000000009', NULL, 'speaking', 'speaking_repeat', 'Ucapkan pembelian lampau ''きのう 本 を 買いました'':', '{"romaji":"kinou hon o kaimashita","audio_text":"きのう 本 を 買いました","display_text":"きのう 本 を 買いました"}'::jsonb, '{"expected_transcript":"きのう 本 を 買いました"}'::jsonb, NULL, NULL, 'Lafalkan kinou hon o kaimashita.', 12, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000166', 'b0000018-0000-0000-0000-000000000010', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Menyebutkan contoh beberapa kegiatan akhir pekan memakai pola:', '{"options":["たり / たり","て / て","ながら / ながら","から / まで"],"translation":"Hari Minggu saya bersih-bersih, belanja, dan lainnya.","sentence_template":"にちようび は 掃除（そうじ）し [blank]、かいものし [blank] します。"}'::jsonb, '{"selected":"たり / たり"}'::jsonb, NULL, NULL, 'Pola ～たり ～たり します menyebutkan aktivitas perwakilan tanpa urutan kaku.', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000167', 'b0000018-0000-0000-0000-000000000010', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat akhir pekan: "Di akhir pekan saya menonton film dan membaca buku."', '{"romaji":"Eiga o mitari hon o yondari shimasu.","tokens":["えいが","を","みたり","ほん","を","よんだり","します"],"target_translation":"Menonton film, baca buku, dll."}'::jsonb, '["えいが","を","みたり","ほん","を","よんだり","します"]'::jsonb, NULL, NULL, 'Bentuk-TA + り diakhiri します menggabungkan contoh kegiatan.', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000168', 'b0000018-0000-0000-0000-000000000010', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan rencana libur berikut. Apa saja kegiatannya?', '{"options":[{"id":"opt_1","text":"Mencuci baju dan memasak"},{"id":"opt_2","text":"Tidur dan mendaki gunung"},{"id":"opt_3","text":"Belanja dan berenang"},{"id":"opt_4","text":"Belajar dan bekerja lembur"}],"audio_text":"やすみは せんたくしたり、料理（りょうり）したり します。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'せんたく (mencuci pakaian) + りょうり (memasak).', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000169', 'b0000018-0000-0000-0000-000000000010', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat: "Hari Sabtu kadang saya bermain tenis lalu beristirahat."', '{"romaji":"Doyoubi wa tenisu o shitari yasundari shimasu.","tokens":["どようび","は","テニス","を","したり","やすんだり","します"],"target_translation":"Hari Sabtu main tenis, istirahat, dll."}'::jsonb, '["どようび","は","テニス","を","したり","やすんだり","します"]'::jsonb, NULL, NULL, 'やすみます → やすんだ → やすんだり.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000170', 'b0000018-0000-0000-0000-000000000010', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan cerita liburan ini. Aktivitas apa yang dilakukan bersama keluarga?', '{"options":[{"id":"opt_1","text":"Pergi ke pemandian air panas dan makan enak"},{"id":"opt_2","text":"Menonton konser musik klasik"},{"id":"opt_3","text":"Berkemah di pantai"},{"id":"opt_4","text":"Membersihkan gudang rumah"}],"audio_text":"かぞくと おんせんへ いったり、おいしいものを たべたり しました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'おんせん (onsen) berarti pemandian air panas.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000171', 'b0000018-0000-0000-0000-000000000010', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Bentuk-TA yang benar untuk pola ～たり dari "のみます" adalah:', '{"options":["のんだり","のみたり","のんでり","のったり"],"translation":"Ngopi dan mengobrol bersama teman.","sentence_template":"ともだち と コーヒー を [blank] しました。"}'::jsonb, '{"selected":"のんだり"}'::jsonb, NULL, NULL, 'のみます berbentuk lampau のんだ, sehingga menjadi のんだり.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000172', 'b0000018-0000-0000-0000-000000000010', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat cerita lampau: "Kemarin saya mendengarkan musik dan menulis catatan."', '{"romaji":"Ongaku o kiitari memo o kaitari shimashita.","tokens":["おんがく","を","きいたり","メモ","を","かいたり","しました"],"target_translation":"Kemarin dengar musik & tulis catatan."}'::jsonb, '["おんがく","を","きいたり","メモ","を","かいたり","しました"]'::jsonb, NULL, NULL, 'Jika kegiatannya terjadi di masa lalu, akhiri dengan しました.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000173', 'b0000018-0000-0000-0000-000000000010', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan ringkasan hari libur ini. Berapa aktivitas utama yang disebutkan?', '{"options":[{"id":"opt_1","text":"Jalan santai dan mengambil foto"},{"id":"opt_2","text":"Membaca novel dan menggambar"},{"id":"opt_3","text":"Bersepeda ke gunung"},{"id":"opt_4","text":"Mencuci mobil di halaman"}],"audio_text":"こうえんで さんぽしたり、しゃしんを とったり しました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'さんぽします (jalan santai) dan しゃしんを とります (memotret).', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000174', 'b0000018-0000-0000-0000-000000000010', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Untuk menyampaikan "tolong JANGAN lakukan ..." secara sopan dipakai pola:', '{"options":["ないで ください","て ください","ても いいです","ては いきます"],"translation":"Tolong jangan parkir mobil di sini.","sentence_template":"ここ に 車（くるま）を とめ [blank]。"}'::jsonb, '{"selected":"ないで ください"}'::jsonb, NULL, '{"てください":"～てください meminta untuk melakukan, bukan melarang halus."}'::jsonb, 'Bentuk-NAI + で ください (~ないでください) berarti "tolong jangan ...".', 9, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260002000010', 'b0000018-0000-0000-0000-000000000010', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Setelah selesai makan malam, belajar'':', '{"options":["あとで","まえに","ときに","から"],"translation":"Ato de","sentence_template":"ばんごはん を たべた [blank]、べんきょうします"}'::jsonb, '{"selected":"あとで"}'::jsonb, NULL, NULL, 'たべた あとで = setelah makan.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260002000011', 'b0000018-0000-0000-0000-000000000010', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Setelah makan jalan santai":', '{"romaji":"Tabeta ato de sanposhimasu","tokens":["食べたあとで","散歩します"],"target_translation":"Setelah makan jalan santai"}'::jsonb, '["食べたあとで","散歩します"]'::jsonb, NULL, NULL, 'Tabeta ato de sanposhimasu.', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000175', 'b0000018-0000-0000-0000-000000000011', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Bentuk-NAI (negatif kamus) dari "わすれます" (lupa) adalah:', '{"options":["わすれない","わすれるない","わすれくない","わすれたい"],"translation":"Tolong jangan lupa dokumennya.","sentence_template":"しりょう を [blank] で ください。"}'::jsonb, '{"selected":"わすれない"}'::jsonb, NULL, NULL, 'Verba grup II (e-masu): hapus ます lalu tambahkan ない (わすれます → わすれない).', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000176', 'b0000018-0000-0000-0000-000000000011', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat pengingat sopan: "Tolong jangan terlambat rapat."', '{"romaji":"Kaigi ni okurenaide kudasai.","tokens":["かいぎ","に","おくれないで","ください"],"target_translation":"Tolong jangan terlambat rapat."}'::jsonb, '["かいぎ","に","おくれないで","ください"]'::jsonb, NULL, NULL, 'おくれます (terlambat) menjadi おくれない + でください.', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000177', 'b0000018-0000-0000-0000-000000000011', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan pesan rekan kerja berikut. Apa yang diminta untuk tidak dilakukan?', '{"options":[{"id":"opt_1","text":"Jangan beri tahu orang lain"},{"id":"opt_2","text":"Jangan kirim email sekarang"},{"id":"opt_3","text":"Jangan matikan komputer"},{"id":"opt_4","text":"Jangan keluar ruangan"}],"audio_text":"このことを ほかのひとに いわないで ください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'いいます → いわないでください berarti "tolong jangan katakan".', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000178', 'b0000018-0000-0000-0000-000000000011', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Bentuk-NAI dari verba grup I "話します" (berbicara) adalah:', '{"options":["はなさない","はなしない","はなせない","はなすない"],"translation":"Di perpustakaan tolong jangan berbicara dengan suara keras.","sentence_template":"図書館（としょかん）で 大きな こえ で [blank] で ください。"}'::jsonb, '{"selected":"はなさない"}'::jsonb, NULL, NULL, 'Verba grup I berakhir し (し → さ) menjadi はなさない.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000179', 'b0000018-0000-0000-0000-000000000011', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat sopan di rumah sakit: "Tolong jangan khawatir."', '{"romaji":"Douka shinpai shinaide kudasai.","tokens":["どうか","しんぱい","しないで","ください"],"target_translation":"Tolong jangan khawatir."}'::jsonb, '["どうか","しんぱい","しないで","ください"]'::jsonb, NULL, NULL, 'します menjadi しない dalam bentuk-NAI.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000180', 'b0000018-0000-0000-0000-000000000011', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan himbauan ini. Apa yang diminta di ruang tunggu?', '{"options":[{"id":"opt_1","text":"Tolong jangan memakai ponsel"},{"id":"opt_2","text":"Tolong antre di sebelah kanan"},{"id":"opt_3","text":"Tolong isi formulir biru"},{"id":"opt_4","text":"Tolong pakai masker"}],"audio_text":"ここで けいたいでんわを つかわないで ください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'つかいます (memakai) → つかわないでください (jangan memakai).', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000181', 'b0000018-0000-0000-0000-000000000011', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Bentuk-NAI yang benar untuk "みます" (melihat) adalah:', '{"options":["みない","みらない","みわない","みくない"],"translation":"Tolong jangan melihat jawabannya.","sentence_template":"こたえ を [blank] で ください。"}'::jsonb, '{"selected":"みない"}'::jsonb, NULL, NULL, 'みます adalah pengecualian grup II (み + ない = みない).', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000182', 'b0000018-0000-0000-0000-000000000011', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat larangan halus: "Tolong jangan membuang sampah di taman."', '{"romaji":"Kouen ni gomi o sutenaide kudasai.","tokens":["こうえん","に","ゴミ","を","すてないで","ください"],"target_translation":"Tolong jangan buang sampah di taman."}'::jsonb, '["こうえん","に","ゴミ","を","すてないで","ください"]'::jsonb, NULL, NULL, 'すてます (membuang) → すてないでください.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000183', 'b0000018-0000-0000-0000-000000000011', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Jika diminta melakukan sesuatu, kita jawab sopan: "はい、[blank] ました。"', '{"options":["わかり","しり","み","きき"],"translation":"Baik, saya mengerti.","sentence_template":"はい、[blank] ました。"}'::jsonb, '{"selected":"わかり"}'::jsonb, NULL, NULL, 'はい、わかりました (Hai, wakarimashita) = Baik, saya paham.', 9, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-230005000010', 'b0000018-0000-0000-0000-000000000011', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Jangan masuk ke ruangan ini'':', '{"options":["ない","ず","ぬ","ん"],"sentence_template":"この へや に はいら [blank] で ください"}'::jsonb, '{"selected":"ない"}'::jsonb, NULL, NULL, 'はいらないで ください.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-230005000011', 'b0000018-0000-0000-0000-000000000011', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Jangan masuk":', '{"romaji":"Hairanaide kudasai","tokens":["入らないで","ください"],"target_translation":"Jangan masuk"}'::jsonb, '["入らないで","ください"]'::jsonb, NULL, NULL, 'Hairanaide kudasai.', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000206', 'b0000018-0000-0000-0000-000000000012', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Kata kerja untuk "memberi (dari saya kepada orang lain)" adalah:', '{"options":["あげます","もらいます","かします","かります"],"translation":"Saya memberi oleh-oleh kepada teman.","sentence_template":"わたし は ともだち に おみやげ を [blank]。"}'::jsonb, '{"selected":"あげます"}'::jsonb, NULL, '{"もらいます":"もらいます berarti menerima dari orang lain."}'::jsonb, 'あげます = memberi; penerima diikuti partikel に.', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000207', 'b0000018-0000-0000-0000-000000000012', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Kata kerja untuk "menerima (dari orang lain)" adalah:', '{"options":["もらいました","あげました","かしました","おしえました"],"translation":"Saat ulang tahun saya menerima jam tangan dari ibu.","sentence_template":"たんじょうび に はは から とけい を [blank]。"}'::jsonb, '{"selected":"もらいました"}'::jsonb, NULL, NULL, 'もらいます = menerima; pemberi memakai partikel に atau から.', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000208', 'b0000018-0000-0000-0000-000000000012', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat memberi: "Saya meminjamkan buku kepada adik."', '{"romaji":"Watashi wa otouto ni hon o kashimasu.","tokens":["わたし","は","おとうと","に","ほん","を","かします"],"target_translation":"Saya meminjamkan buku pada adik."}'::jsonb, '["わたし","は","おとうと","に","ほん","を","かします"]'::jsonb, NULL, NULL, 'かします = meminjamkan (memberi pinjam); かります = meminjam.', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000209', 'b0000018-0000-0000-0000-000000000012', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan cerita kado berikut. Siapakah yang memberi dompet?', '{"options":[{"id":"opt_1","text":"Kakak perempuan"},{"id":"opt_2","text":"Adik laki-laki"},{"id":"opt_3","text":"Teman kantor"},{"id":"opt_4","text":"Ibu"}],"audio_text":"あねに さいふを もらいました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'あねに もらいました berarti menerima dari kakak perempuan.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000210', 'b0000018-0000-0000-0000-000000000012', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Pola untuk "mengajarkan kepada seseorang": やまださん に インドネシアご を [blank]。', '{"options":["おしえます","ならいます","もらいます","かります"],"translation":"Saya mengajarkan bahasa Indonesia kepada Yamada.","sentence_template":"やまださん に インドネシアご を [blank]。"}'::jsonb, '{"selected":"おしえます"}'::jsonb, NULL, NULL, 'おしえます = mengajarkan / memberi tahu; ならいます = belajar dari seseorang.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000211', 'b0000018-0000-0000-0000-000000000012', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat: "Saya belajar kaligrafi Jepang dari Ibu Tanaka."', '{"romaji":"Tanaka-san ni shodou o naraimashita.","tokens":["たなかさん","に","しょどう","を","ならいました"],"target_translation":"Belajar kaligrafi dari Bu Tanaka."}'::jsonb, '["たなかさん","に","しょどう","を","ならいました"]'::jsonb, NULL, NULL, 'ならいます menyatakan belajar keterampilan langsung dari guru/orang lain.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000212', 'b0000018-0000-0000-0000-000000000012', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan percakapan ini. Barang apa yang dipinjam oleh pembicara?', '{"options":[{"id":"opt_1","text":"Payung"},{"id":"opt_2","text":"Kamus kanji"},{"id":"opt_3","text":"Sepeda lipat"},{"id":"opt_4","text":"Kamera digital"}],"audio_text":"ともだちに かさを かりました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'かさを かりました berarti meminjam payung.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000213', 'b0000018-0000-0000-0000-000000000012', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Lawan kata "かします" (meminjamkan) adalah:', '{"options":["かりました","かしました","あげました","おくりました"],"translation":"Saya meminjam kamus dari guru.","sentence_template":"せんせい に じしょ を [blank]。"}'::jsonb, '{"selected":"かりました"}'::jsonb, NULL, NULL, 'かります = meminjam dari orang lain.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000214', 'b0000018-0000-0000-0000-000000000012', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Menyatakan kemampuan melakukan sesuatu memakai pola:', '{"options":["できます","あります","います","わかります"],"translation":"Saya bisa membaca Kanji.","sentence_template":"わたし は かんじ を よむ こと が [blank]。"}'::jsonb, '{"selected":"できます"}'::jsonb, NULL, NULL, '[Kamus Verba] + こと が できます berarti "bisa / mampu melakukan ...".', 9, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-290005000010', 'b0000018-0000-0000-0000-000000000012', NULL, 'reading', 'fill_blank', 'Lengkapi kata sambung alasan pada kalimat "Karena capek, ingin istirahat":', '{"options":["から","まで","ので","のに"],"translation":"Karena capek, ingin istirahat","sentence_template":"つかれました [blank]、やすみたい です"}'::jsonb, '{"selected":"から"}'::jsonb, NULL, NULL, '～から menyatakan alasan logis (karena).', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-290005000011', 'b0000018-0000-0000-0000-000000000012', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Karena capek pulang":', '{"romaji":"Tsukareta kara kaerimasu","tokens":["疲れたから","帰ります"],"target_translation":"Karena capek pulang"}'::jsonb, '["疲れたから","帰ります"]'::jsonb, NULL, NULL, 'Tsukareta kara kaerimasu.', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000215', 'b0000018-0000-0000-0000-000000000013', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Jika kemampuan memakai kata benda langsung (mis. bahasa Jepang), polanya:', '{"options":["が","を","で","へ"],"translation":"Tuan Suzuki bisa berbahasa Jepang.","sentence_template":"すずきさん は にほんご [blank] できます。"}'::jsonb, '{"selected":"が"}'::jsonb, NULL, NULL, '[Kata Benda Kemahiran] + が できます.', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000216', 'b0000018-0000-0000-0000-000000000013', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat kemampuan: "Saya bisa menyetir mobil."', '{"romaji":"Kuruma o untensuru koto ga dekimasu.","tokens":["くるま","を","うんてんする","こと","が","できます"],"target_translation":"Saya bisa menyetir mobil."}'::jsonb, '["くるま","を","うんてんする","こと","が","できます"]'::jsonb, NULL, NULL, 'Gunakan bentuk kamus うんてんする sebelum こと が できます.', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000217', 'b0000018-0000-0000-0000-000000000013', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan rencana berikut. Apa rencana pembicara tahun depan?', '{"options":[{"id":"opt_1","text":"Berencana kuliah/studi ke Jepang"},{"id":"opt_2","text":"Berencana pindah rumah ke Surabaya"},{"id":"opt_3","text":"Berencana membeli rumah baru"},{"id":"opt_4","text":"Berencana pensiun lebih awal"}],"audio_text":"らいねん 日本へ りゅうがくする つもりです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '[Verba Kamus] + つもりです menyatakan rencana atau niat pribadi.', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000218', 'b0000018-0000-0000-0000-000000000013', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat niat/rencana: "Minggu ini saya berencana tidak lembur."', '{"romaji":"Konshuu wa zangyou shinai tsumori desu.","tokens":["こんしゅう","は","ざんぎょうしない","つもり","です"],"target_translation":"Minggu ini berencana tidak lembur."}'::jsonb, '["こんしゅう","は","ざんぎょうしない","つもり","です"]'::jsonb, NULL, NULL, 'Rencana untuk tidak melakukan memakai bentuk-NAI + つもりです.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000219', 'b0000018-0000-0000-0000-000000000013', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan hobi berikut. Apa kemahiran pembicara?', '{"options":[{"id":"opt_1","text":"Bisa bermain piano"},{"id":"opt_2","text":"Bisa bernyanyi opera"},{"id":"opt_3","text":"Bisa melukis cat air"},{"id":"opt_4","text":"Bisa memasak sushi"}],"audio_text":"ピアノを ひくことが できます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ピアノを ひく (bermain piano) + ことができます (bisa).', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000220', 'b0000018-0000-0000-0000-000000000013', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Kata untuk menyebut "kemampuan berbahasa Inggris" adalah:', '{"options":["えいご","にほんご","かんじ","りょうり"],"translation":"Saya bisa bahasa Inggris sedikit.","sentence_template":"[blank] が すこし できます。"}'::jsonb, '{"selected":"えいご"}'::jsonb, NULL, NULL, 'えいご (eigo) = bahasa Inggris.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000221', 'b0000018-0000-0000-0000-000000000013', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat niat: "Saya berniat menabung setiap bulan."', '{"romaji":"Maitsuki chokin suru tsumori desu.","tokens":["まいつき","ちょきんする","つもり","です"],"target_translation":"Saya berniat menabung setiap bulan."}'::jsonb, '["まいつき","ちょきんする","つもり","です"]'::jsonb, NULL, NULL, 'ちょきんします (menabung) bentuk kamusnya ちょきんする.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000222', 'b0000018-0000-0000-0000-000000000013', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan target berikut. Kapan pembicara ingin pergi ke Hokkaido?', '{"options":[{"id":"opt_1","text":"Saat liburan musim panas"},{"id":"opt_2","text":"Saat tahun baru Januari"},{"id":"opt_3","text":"Saat musim semi April"},{"id":"opt_4","text":"Bulan depan"}],"audio_text":"なつやすみに ほっかいどうへ いくつもりです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'なつやすみ berarti liburan musim panas.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000223', 'b0000018-0000-0000-0000-000000000013', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Untuk menyatakan perubahan bertahap ("menjadi lebih mahir") dipakai:', '{"options":["なりました","しました","できました","いきました"],"translation":"Karena berlatih tiap hari, bahasa Jepangku jadi mahir.","sentence_template":"毎日 練習して、日本語 が じょうず に [blank]。"}'::jsonb, '{"selected":"なりました"}'::jsonb, NULL, NULL, '[Kata Sifat-Na] + に なります menyatakan perubahan menjadi sesuatu.', 9, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000224', 'b0000018-0000-0000-0000-000000000013', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'reading', 'fill_blank', 'Pilih kalimat yang tepat secara tata bahasa N5:', '{"options":["みる","みます","みて","みた"],"translation":"Besok berencana menonton film bersama teman.","sentence_template":"あした ともだち と えいが を [blank] つもりです。"}'::jsonb, '{"selected":"みる"}'::jsonb, NULL, '{"みます":"Sebelum つもり wajib menggunakan bentuk kamus (みる), bukan ます."}'::jsonb, 'Pola ～つもりです wajib didahului bentuk biasa/kamus (みる).', 10, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270001000011', 'b0000018-0000-0000-0000-000000000013', NULL, 'reading', 'fill_blank', 'Bentuk kamus dari verba 読みます (membaca) adalah:', '{"options":["よむ","よめる","よない","よんだ"],"translation":"Yomu","sentence_template":"よみます -> [blank]"}'::jsonb, '{"selected":"よむ"}'::jsonb, NULL, NULL, 'Grup 1: 読みます -> 読む (yomu).', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270001000012', 'b0000018-0000-0000-0000-000000000013', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Membaca buku":', '{"romaji":"Hon o yomu","tokens":["本","を","読む"],"target_translation":"Membaca buku"}'::jsonb, '["本","を","読む"]'::jsonb, NULL, NULL, 'Hon o yomu.', 12, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270001000013', 'b0000018-0000-0000-0000-000000000013', NULL, 'speaking', 'speaking_repeat', 'Ucapkan verba kamus ''日本語 を 話す'':', '{"romaji":"nihongo o hanasu","audio_text":"日本語 を 話す","display_text":"日本語 を 話す"}'::jsonb, '{"expected_transcript":"日本語 を 話す"}'::jsonb, NULL, NULL, 'Lafalkan nihongo o hanasu.', 13, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000225', 'b0000018-0000-0000-0000-000000000014', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Perubahan negatif dari kata kerja "かいます" (membeli) untuk bentuk ～ないで adalah:', '{"options":["かわない","かいない","かうない","かった"],"translation":"Hari ini pulang tanpa membeli apa-apa.","sentence_template":"きょう は なにも [blank] で かえります。"}'::jsonb, '{"selected":"かわない"}'::jsonb, NULL, NULL, 'Verba akhir う/います menjadi わ dalam bentuk-NAI (かいます → かわない).', 1, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000226', 'b0000018-0000-0000-0000-000000000014', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat sopan di tempat kerja: "Bolehkah saya pulang lebih dulu hari ini?"', '{"romaji":"Kyou wa osaki ni kaettemo ii desu ka.","tokens":["きょう","は","おさきに","かえっても","いい","ですか"],"target_translation":"Bolehkah saya pulang duluan?"}'::jsonb, '["きょう","は","おさきに","かえっても","いい","ですか"]'::jsonb, NULL, NULL, 'かえります menjadi かえって + もいいですか; おさきに = duluan.', 2, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000227', 'b0000018-0000-0000-0000-000000000014', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan dialog konfirmasi ruang rapat. Di mana letak ruang Sakura?', '{"options":[{"id":"opt_1","text":"Di lantai 3 sebelah kanan"},{"id":"opt_2","text":"Di lantai 2 sebelah kiri"},{"id":"opt_3","text":"Di lantai 1 dekat lobi"},{"id":"opt_4","text":"Di lantai 4 paling ujung"}],"audio_text":"さくらのかいぎしつは ３がいの みぎがわに あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '３がい (lantai 3) + みぎがわ (sebelah kanan).', 3, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000228', 'b0000018-0000-0000-0000-000000000014', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'reading', 'fill_blank', 'Partikel yang menunjukkan alat/bahasa yang digunakan saat menulis adalah:', '{"options":["で","を","に","と"],"translation":"Menulis laporan dengan bahasa Jepang.","sentence_template":"にほんご [blank] レポート を かきます。"}'::jsonb, '{"selected":"で"}'::jsonb, NULL, NULL, 'Bahasa dan alat tulis memakai partikel で.', 4, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000229', 'b0000018-0000-0000-0000-000000000014', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat gabungan sebab-akibat: "Karena macet, saya naik kereta bawah tanah."', '{"romaji":"Michi ga konde imasu kara chikatetsu de ikimasu.","tokens":["みち","が","こんでいますから","ちかてつ","で","いきます"],"target_translation":"Karena macet, naik kereta bawah tanah."}'::jsonb, '["みち","が","こんでいますから","ちかてつ","で","いきます"]'::jsonb, NULL, NULL, 'こんでいます (sedang macet) + から menjelaskan alasan.', 5, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000230', 'b0000018-0000-0000-0000-000000000014', '713b3950-cd77-436e-9e0e-d131b205008e', 'listening', 'listening_choice', 'Dengarkan kabar berikut. Apa yang sedang dipelajari oleh pembicara?', '{"options":[{"id":"opt_1","text":"Tata bahasa Jepang"},{"id":"opt_2","text":"Masakan tradisional"},{"id":"opt_3","text":"Kaligrafi kuas"},{"id":"opt_4","text":"Ekonomi internasional"}],"audio_text":"いま 日本語の 文法（ぶんぽう）を ならっています。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ぶんぽう (bunpou) berarti tata bahasa / grammar.', 6, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000231', 'b0000018-0000-0000-0000-000000000014', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'reading', 'fill_blank', 'Kata sifat-i "せまい" (sempit) jika diubah menjadi "menjadi tidak sempit" / negatif:', '{"options":["せまくない","せまいじゃない","せまな","せまかった"],"translation":"Kantor baru sama sekali tidak sempit.","sentence_template":"新しい オフィス は まったく [blank] です。"}'::jsonb, '{"selected":"せまくない"}'::jsonb, NULL, NULL, 'せまい → hapus い + くない = せまくない.', 7, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000232', 'b0000018-0000-0000-0000-000000000014', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat pengingat akhir sesi: "Jangan lupa periksa kartu flashcard setiap hari."', '{"romaji":"Mainichi furasshukaado o mite kudasai.","tokens":["まいにち","フラッシュカード","を","みてください"],"target_translation":"Lihat flashcard setiap hari."}'::jsonb, '["まいにち","フラッシュカード","を","みてください"]'::jsonb, NULL, NULL, 'Verba みます + てください = tolong lihat / pelajari.', 8, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000233', 'b0000018-0000-0000-0000-000000000014', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan kalimat penutup N5 ini. Apa kesiapan pembicara?', '{"options":[{"id":"opt_1","text":"Bertekad berjuang di ujian N5"},{"id":"opt_2","text":"Sudah menyerah ikut ujian"},{"id":"opt_3","text":"Baru mendaftar minggu depan"},{"id":"opt_4","text":"Sedang menunggu pengumuman lulus"}],"audio_text":"N5の しけんを がんばる つもりです！"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'がんばる つもりです berarti bertekad berusaha keras.', 9, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000018-0000-0000-0000-000000000234', 'b0000018-0000-0000-0000-000000000014', 'a830983b-40e2-4080-a8a5-416276586f1a', 'reading', 'fill_blank', 'Menutup sesi belajar dengan mengajak beristirahat bersama:', '{"options":["やすみ","やすむ","やすんで","やすめ"],"translation":"Mari kita beristirahat sebentar.","sentence_template":"ちょっと [blank] ましょうか。"}'::jsonb, '{"selected":"やすみ"}'::jsonb, NULL, NULL, '～ましょう menempel pada bentuk stem ます (やすみます → やすみ).', 10, '2026-11-19T11:16:23.16441+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-300005000011', 'b0000018-0000-0000-0000-000000000014', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kesiapan N5 ''Saya sudah siap menghadapi ujian N5'':', '{"options":["でき","し","なり","いき"],"translation":"Deki","sentence_template":"JLPT N5 の じゅんび が [blank] ました"}'::jsonb, '{"selected":"でき"}'::jsonb, NULL, NULL, 'じゅんび が できました = persiapannya sudah siap/selesai.', 11, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-300005000012', 'b0000018-0000-0000-0000-000000000014', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Persiapan selesai":', '{"romaji":"Junbi ga dekimashita","tokens":["準備が","できました"],"target_translation":"Persiapan selesai"}'::jsonb, '["準備が","できました"]'::jsonb, NULL, NULL, 'Junbi ga dekimashita.', 12, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000010201', 'b0000026-0000-0000-0000-000000000102', NULL, 'reading', 'fill_blank', 'Dari huruf あ–こ, pilih vokal yang tepat untuk menyusun kata "rumah" (ie):', '{"options":["え","あ","お","う"],"translation":"Rumah (ie)","sentence_template":"い [blank]"}'::jsonb, '{"selected":"え"}'::jsonb, NULL, NULL, 'い (i) + え (e) = いえ (rumah).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000010202', 'b0000026-0000-0000-0000-000000000102', NULL, 'listening', 'listening_choice', 'Dengarkan kata yang tersusun dari huruf あ–こ ini:', '{"options":[{"id":"opt_1","text":"Wajah"},{"id":"opt_2","text":"Biru"},{"id":"opt_3","text":"Musim gugur"},{"id":"opt_4","text":"Atas"}],"audio_text":"かお"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'か (ka) + お (o) = かお (wajah).', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000010203', 'b0000026-0000-0000-0000-000000000102', NULL, 'writing', 'sentence_builder', 'Susun huruf menjadi kata "Biru (aoi)":', '{"romaji":"Aoi","tokens":["あ","お","い","か"],"target_translation":"Biru (aoi)"}'::jsonb, '["あ","お","い"]'::jsonb, NULL, NULL, 'Gabungan tiga vokal あ + お + い menghasilkan あおい (biru).', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
