INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-020006000006', 'b0000026-0000-0000-0000-000000000204', NULL, 'listening', 'listening_choice', 'Dengarkan dialog singkat ini:', '{"options":[{"id":"opt_1","text":"Ini apa?"},{"id":"opt_2","text":"Itu siapa?"},{"id":"opt_3","text":"Di mana rumahmu?"},{"id":"opt_4","text":"Kucing siapa ini?"}],"audio_text":"これ は なん ですか"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'これ は なん ですか (kore wa nan desu ka) berarti ''Ini apa?'' (sebelum です, 何 dibaca なん).', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
