INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-030002000007', 'b0000026-0000-0000-0000-000000000302', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kata ''あめ'' (hujan):', '{"romaji":"ame","audio_text":"あめ","display_text":"あめ"}'::jsonb, '{"expected_transcript":"あめ"}'::jsonb, NULL, NULL, 'Lafalkan a-me.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-030002000008', 'b0000026-0000-0000-0000-000000000302', NULL, 'reading', 'fill_blank', 'Lengkapi kata ''hari esok / besok'' (ashita):', '{"options":["し","ち","す","つ"],"translation":"Besok (ashita)","sentence_template":"あ [blank] た"}'::jsonb, '{"selected":"し"}'::jsonb, NULL, NULL, 'あ + し + た = あした (besok).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000030401', 'b0000026-0000-0000-0000-000000000304', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'reading', 'fill_blank', 'Dalam pola kalimat [Subjek] は [Identitas] です, huruf は dibaca sebagai:', '{"options":["は (wa)","を (o)","あ (a)","ほ (ho)"],"translation":"Ini adalah bunga.","sentence_template":"これ [blank] はな です。"}'::jsonb, '{"selected":"は (wa)"}'::jsonb, NULL, NULL, 'Partikel topik selalu ditulis memakai huruf は namun wajib dibaca "wa".', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000030402', 'b0000026-0000-0000-0000-000000000304', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'listening', 'listening_choice', 'Dengarkan perkenalan diri berikut:', '{"options":[{"id":"opt_1","text":"Salam kenal, saya Tanaka."},{"id":"opt_2","text":"Ini adalah sushi."},{"id":"opt_3","text":"Terima kasih banyak."},{"id":"opt_4","text":"Apakah itu bunga?"}],"audio_text":"はじめまして、わたしは たなか です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Pola dasar perkenalan: はじめまして + わたしは [Nama] です.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000030403', 'b0000026-0000-0000-0000-000000000304', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'writing', 'sentence_builder', 'Susun kalimat: "Ini adalah bunga."', '{"romaji":"Kore wa hana desu.","tokens":["これ","は","はな","です","それ"],"target_translation":"Ini adalah bunga."}'::jsonb, '["これ","は","はな","です"]'::jsonb, NULL, NULL, 'Menggabungkan これ (Unit 2) + は + はな + です (Unit 3).', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000030404', 'b0000026-0000-0000-0000-000000000304', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'speaking', 'speaking_repeat', 'Ucapkan perkenalan singkat: "わたしは たなかです" (Saya Tanaka):', '{"romaji":"watashi wa tanaka desu","audio_text":"わたしは たなかです","display_text":"わたしは たなかです"}'::jsonb, '{"expected_transcript":"わたしは たなかです"}'::jsonb, NULL, NULL, 'Pastikan は setelah わたし dilafalkan "wa", bukan "ha".', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-030006000005', 'b0000026-0000-0000-0000-000000000304', NULL, 'reading', 'fill_blank', 'Pilih respon salam yang tepat saat seseorang menyapa ''Konnichiwa'':', '{"options":["こんにちは","さようなら","おやすみ","ありがとう"],"translation":"Konnichiwa","sentence_template":"A: こんにちは! -> B: [blank]!"}'::jsonb, '{"selected":"こんにちは"}'::jsonb, NULL, NULL, 'Balas sapaan siang dengan こんにちは juga.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-030006000006', 'b0000026-0000-0000-0000-000000000304', NULL, 'listening', 'listening_choice', 'Dengarkan perkenalan sopan ini:', '{"options":[{"id":"opt_1","text":"Senang berkenalan dengan Anda"},{"id":"opt_2","text":"Selamat pagi"},{"id":"opt_3","text":"Sampai jumpa besok"},{"id":"opt_4","text":"Terima kasih banyak"}],"audio_text":"はじめまして"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'はじめまして diucapkan saat pertama kali berkenalan.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-030006000007', 'b0000026-0000-0000-0000-000000000304', NULL, 'writing', 'sentence_builder', 'Susun huruf menjadi kata "Senang berkenalan (hajimemashite)":', '{"romaji":"Hajimemashite","tokens":["は","じ","め","ま","し","て"],"target_translation":"Senang berkenalan (hajimemashite)"}'::jsonb, '["は","じ","め","ま","し","て"]'::jsonb, NULL, NULL, 'Hajimemashite.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-030006000008', 'b0000026-0000-0000-0000-000000000304', NULL, 'speaking', 'speaking_repeat', 'Ucapkan dengan membungkuk sopan ''はじめまして'' (Hajimemashite):', '{"romaji":"hajimemashite","audio_text":"はじめまして","display_text":"はじめまして"}'::jsonb, '{"expected_transcript":"はじめまして"}'::jsonb, NULL, NULL, 'Lafalkan hajimemashite dengan ramah.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000040101', 'b0000026-0000-0000-0000-000000000401', NULL, 'reading', 'fill_blank', 'Review あ–よ + Deret R-W-N: huruf pembuka kata "saya" (watashi) adalah:', '{"options":["わ","れ","ね","ぬ"],"translation":"Saya (watashi)","sentence_template":"[blank] たし"}'::jsonb, '{"selected":"わ"}'::jsonb, NULL, NULL, 'わ melengkung bulat lembut masuk ke dalam (watashi), sedangkan れ mencuat ke luar.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000040102', 'b0000026-0000-0000-0000-000000000401', NULL, 'listening', 'listening_choice', 'Dengarkan kata yang memakai huruf sengau ん:', '{"options":[{"id":"opt_1","text":"Buku"},{"id":"opt_2","text":"Jepang"},{"id":"opt_3","text":"Malam"},{"id":"opt_4","text":"Langit"}],"audio_text":"ほん"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ほ (ho) + ん (n) = ほん (buku).', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000040103', 'b0000026-0000-0000-0000-000000000401', NULL, 'writing', 'sentence_builder', 'Susun huruf menjadi kata "Malam (yoru)":', '{"romaji":"Yoru","tokens":["よ","る","ろ","ら"],"target_translation":"Malam (yoru)"}'::jsonb, '["よ","る"]'::jsonb, NULL, NULL, 'る menutup melingkar di ujung bawah, sedangkan ろ tetap terbuka.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-040001000004', 'b0000026-0000-0000-0000-000000000401', NULL, 'reading', 'fill_blank', 'Lengkapi deret R: ら, り, [blank], れ, ろ:', '{"options":["る","ろ","ら","れ"],"sentence_template":"Huruf RU: [blank]"}'::jsonb, '{"selected":"る"}'::jsonb, NULL, NULL, 'Urutan deret R adalah ra, ri, ru, re, ro.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-040001000005', 'b0000026-0000-0000-0000-000000000401', NULL, 'listening', 'listening_choice', 'Dengarkan pelafalan huruf tunggal ini:', '{"options":[{"id":"opt_1","text":"Re"},{"id":"opt_2","text":"Ru"},{"id":"opt_3","text":"Ro"},{"id":"opt_4","text":"Ra"}],"audio_text":"れ"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Audio melafalkan れ (re).', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
