INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000040301', 'b0000026-0000-0000-0000-000000000403', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'reading', 'fill_blank', 'Benda berada jauh dari pembicara dan lawan bicara (mis. gunung). Kata tunjuknya adalah:', '{"options":["あれ","これ","それ","ここ"],"translation":"Itu (jauh) adalah gunung.","sentence_template":"[blank] は やま です。"}'::jsonb, '{"selected":"あれ"}'::jsonb, NULL, NULL, 'これ = dekat saya; それ = dekat kamu; あれ = jauh dari kita berdua.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000040302', 'b0000026-0000-0000-0000-000000000403', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'listening', 'listening_choice', 'Dengarkan kalimat perkenalan kewarganegaraan:', '{"options":[{"id":"opt_1","text":"Tuan Yamada adalah orang Jepang."},{"id":"opt_2","text":"Saya belajar bahasa Jepang."},{"id":"opt_3","text":"Itu adalah gunung."},{"id":"opt_4","text":"Apakah itu buku guru?"}],"audio_text":"やまださんは にほんじん です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '[Nama]さんは [Negara]じん です menyatakan kewarganegaraan.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000040303', 'b0000026-0000-0000-0000-000000000403', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'writing', 'sentence_builder', 'Susun kalimat triad penunjuk jauh: "Itu (jauh) adalah gunung."', '{"romaji":"Are wa yama desu.","tokens":["あれ","は","やま","です","これ"],"target_translation":"Itu (jauh) adalah gunung."}'::jsonb, '["あれ","は","やま","です"]'::jsonb, NULL, NULL, 'あれ digunakan untuk objek jauh dari kedua pembicara.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-040005000004', 'b0000026-0000-0000-0000-000000000403', NULL, 'reading', 'fill_blank', 'Lengkapi pertanyaan ''Apakah itu di sana buku?'':', '{"options":["ですか","です","でした","ますか"],"translation":"Apakah itu buku?","sentence_template":"あれ は ほん [blank]"}'::jsonb, '{"selected":"ですか"}'::jsonb, NULL, NULL, 'Pertanyaan diakhiri partikel tanya か (ka).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-040005000005', 'b0000026-0000-0000-0000-000000000403', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Ini buku siapa?":', '{"romaji":"Kore wa dare no hon desu ka","tokens":["これ","は","だれ","の","ほん","ですか"],"target_translation":"Ini buku siapa?"}'::jsonb, '["これ","は","だれ","の","ほん","ですか"]'::jsonb, NULL, NULL, 'Kore wa dare no hon desu ka.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-040005000006', 'b0000026-0000-0000-0000-000000000403', NULL, 'speaking', 'speaking_repeat', 'Tanyakan ''あれ は なん ですか'' (Itu apa?):', '{"romaji":"are wa nan desu ka","audio_text":"あれ は なん ですか","display_text":"あれ は なん ですか"}'::jsonb, '{"expected_transcript":"あれ は なん ですか"}'::jsonb, '[["あれは何ですか"]]'::jsonb, NULL, 'Lafalkan are wa nan desu ka (sebelum です, 何 dibaca なん).', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-040005000007', 'b0000026-0000-0000-0000-000000000403', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat penunjuk posisi ini:', '{"options":[{"id":"opt_1","text":"Itu (jauh) adalah perpustakaan."},{"id":"opt_2","text":"Ini adalah perpustakaan."},{"id":"opt_3","text":"Itu (dekat lawan bicara) adalah perpustakaan."},{"id":"opt_4","text":"Mana perpustakaan?"}],"audio_text":"あれは図書館です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'あれ (are) merujuk pada benda atau tempat yang posisinya jauh dari kedua pembicara.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-040005000008', 'b0000026-0000-0000-0000-000000000403', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat pertanyaan sopan penunjuk ini:', '{"phrase":"これは辞書ですか。","romaji":"Kore wa jisho desu ka.","audio_text":"これは辞書ですか。","translation":"Apakah ini kamus?","display_text":"これは辞書ですか。"}'::jsonb, '{"expected_transcript":"これは辞書ですか。"}'::jsonb, NULL, NULL, 'Lafalkan partikel tanya か di akhir kalimat dengan intonasi naik sedikit.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000040401', 'b0000026-0000-0000-0000-000000000404', NULL, 'reading', 'fill_blank', 'Kontras deret R (ら・る・ろ): pilih ejaan Hiragana yang tepat untuk kata "langit" (sora):', '{"options":["そら","そる","そろ","すら"],"translation":"Langit (sora)"}'::jsonb, '{"selected":"そら"}'::jsonb, NULL, NULL, 'そ (so) + ら (ra) = そら (langit).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000000404', 'b0000026-0000-0000-0000-000000000404', NULL, 'listening', 'listening_choice', 'Dengarkan ungkapan perpisahan berikut:', '{"options":[{"id":"opt_1","text":"Selamat tinggal"},{"id":"opt_2","text":"Selamat pagi"},{"id":"opt_3","text":"Saya adalah guru"},{"id":"opt_4","text":"Terima kasih"}],"audio_text":"さようなら"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'さようなら memadukan deret S, Y, N, dan R.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000040403', 'b0000026-0000-0000-0000-000000000404', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'writing', 'sentence_builder', 'Susun kalimat lengkap: "Saya adalah guru."', '{"romaji":"Watashi wa sensei desu.","tokens":["わたし","は","せんせい","です","それ"],"target_translation":"Saya adalah guru."}'::jsonb, '["わたし","は","せんせい","です"]'::jsonb, NULL, NULL, 'Kalimat utuh dengan 46 Gojūon Hiragana.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000040404', 'b0000026-0000-0000-0000-000000000404', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'speaking', 'speaking_repeat', 'Ucapkan kalimat: "これは ほんです" (Ini adalah buku):', '{"romaji":"kore wa hon desu","audio_text":"これは ほんです","display_text":"これは ほんです"}'::jsonb, '{"expected_transcript":"これは ほんです"}'::jsonb, NULL, NULL, 'Latih pengucapan sengau ん yang bersih pada ほん (hon).', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
