INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-040006000006', 'b0000026-0000-0000-0000-000000000404', NULL, 'listening', 'listening_choice', 'Dengarkan dialog singkat ini:', '{"options":[{"id":"opt_1","text":"Apakah ini tas Anda?"},{"id":"opt_2","text":"Apakah ini buku Anda?"},{"id":"opt_3","text":"Di mana tas Anda?"},{"id":"opt_4","text":"Siapa pemilik tas ini?"}],"audio_text":"これ は あなた の かばん ですか"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'これ は あなた の かばん ですか (Apakah ini tas Anda?).', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
