INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000070101', 'b0000026-0000-0000-0000-000000000701', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'reading', 'fill_blank', 'Review Unit 6 + 8 Kanji Manusia: Kanji untuk "perempuan / wanita" adalah:', '{"options":["女","男","子","父"],"translation":"Wanita itu adalah guru.","sentence_template":"あの [blank] の 人は せんせい です。"}'::jsonb, '{"selected":"女"}'::jsonb, NULL, NULL, '女 dibaca "onna" pada 女の人 (wanita).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000070102', 'b0000026-0000-0000-0000-000000000701', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'listening', 'listening_choice', 'Dengarkan sebutan untuk keluarga sendiri vs orang lain:', '{"options":[{"id":"opt_1","text":"Ayah saya adalah karyawan perusahaan."},{"id":"opt_2","text":"Ayahmu adalah dokter."},{"id":"opt_3","text":"Ibu saya adalah guru."},{"id":"opt_4","text":"Teman saya mahasiswa."}],"audio_text":"ちちは かいしゃいん です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ちち dipakai ketika membicarakan ayah sendiri kepada orang lain.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000070103', 'b0000026-0000-0000-0000-000000000701', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'writing', 'sentence_builder', 'Susun kalimat dengan Kanji 友 (teman) & 母 (ibu):', '{"romaji":"Watashi no haha wa isha desu.","tokens":["わたし","の","母","は","いしゃ","です"],"target_translation":"Ibu saya seorang dokter."}'::jsonb, '["わたし","の","母","は","いしゃ","です"]'::jsonb, NULL, NULL, '母 dibaca haha untuk ibu kandung sendiri.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-070001000004', 'b0000026-0000-0000-0000-000000000701', NULL, 'reading', 'fill_blank', 'Kanji 女 (onna) berarti:', '{"options":["perempuan","laki-laki","anak","orang"],"sentence_template":"Arti kanji 女: [blank]"}'::jsonb, '{"selected":"perempuan"}'::jsonb, NULL, NULL, 'Kanji 女 berarti wanita/perempuan.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
