INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-070001000007', 'b0000026-0000-0000-0000-000000000701', NULL, 'writing', 'fill_blank', 'Lengkapi kanji untuk kata "perempuan / wanita" (おんなのひと):', '{"options":["女","男","子","父"],"translation":"Perempuan/wanita","sentence_template":"[blank] の 人"}'::jsonb, '{"selected":"女"}'::jsonb, NULL, NULL, 'Kanji 女 dibaca おんな (onna) berarti wanita atau perempuan.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-070001000008', 'b0000026-0000-0000-0000-000000000701', NULL, 'reading', 'fill_blank', 'Pilih arti yang tepat untuk kata 家族 (かぞく):', '{"options":["Keluarga","Teman","Tetangga","Saudara"],"translation":"Keluarga saya ada 4 orang.","sentence_template":"私の家族は4人です。Arti 家族: [blank]"}'::jsonb, '{"selected":"Keluarga"}'::jsonb, NULL, NULL, '家族 (kazoku) berarti keluarga.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000070301', 'b0000026-0000-0000-0000-000000000703', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'reading', 'fill_blank', 'Saat menyapa atau menanyakan kabar ayah teman, panggilan sopan yang tepat adalah:', '{"options":["おとうさん","ちち","はは","わたしさん"],"translation":"Apakah ayah Tuan Tanaka sehat?","sentence_template":"たなかさんの [blank] は おげんきですか。"}'::jsonb, '{"selected":"おとうさん"}'::jsonb, NULL, NULL, 'Gunakan おとうさん untuk ayah orang lain; akhiran さん tidak pernah dipakai untuk diri sendiri.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000070302', 'b0000026-0000-0000-0000-000000000703', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'listening', 'listening_choice', 'Dengarkan perkenalan keluarga lengkap:', '{"options":[{"id":"opt_1","text":"Teman saya juga seorang dokter."},{"id":"opt_2","text":"Kakak perempuan saya seorang guru."},{"id":"opt_3","text":"Anak laki-laki itu pelajar."},{"id":"opt_4","text":"Nama ayah saya Tanaka."}],"audio_text":"わたしの ともだちも いしゃ です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Partikel の (kepemilikan) + も (juga) dipadukan dalam satu kalimat.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000070303', 'b0000026-0000-0000-0000-000000000703', '42be31b7-89cc-4d77-a3dc-686767f6a7cd', 'writing', 'sentence_builder', 'Susun kalimat: "Kakak perempuan saya karyawan perusahaan."', '{"romaji":"Watashi no ane wa kaishain desu.","tokens":["わたし","の","あね","は","かいしゃいん","です"],"target_translation":"Kakak perempuan saya karyawan."}'::jsonb, '["わたし","の","あね","は","かいしゃいん","です"]'::jsonb, NULL, NULL, 'あね dipakai untuk kakak perempuan sendiri.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-070005000004', 'b0000026-0000-0000-0000-000000000703', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tanya kerabat ''Apakah beliau guru?'':', '{"options":["ですか","でした","です","ますか"],"translation":"Desu ka","sentence_template":"あのかた は せんせい [blank]"}'::jsonb, '{"selected":"ですか"}'::jsonb, NULL, NULL, 'Pertanyaan sopan diakhiri ですか.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-070005000005', 'b0000026-0000-0000-0000-000000000703', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Beliau siapa?":', '{"romaji":"Ano kata wa donata desu ka","tokens":["あのかた","は","どなた","ですか"],"target_translation":"Beliau siapa?"}'::jsonb, '["あのかた","は","どなた","ですか"]'::jsonb, NULL, NULL, 'Ano kata wa donata desu ka.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-070005000006', 'b0000026-0000-0000-0000-000000000703', NULL, 'speaking', 'speaking_repeat', 'Tanyakan ''あのかた は だれ ですか'':', '{"romaji":"ano kata wa dare desu ka","audio_text":"あのかた は だれ ですか","display_text":"あのかた は だれ ですか"}'::jsonb, '{"expected_transcript":"あのかた は だれ ですか"}'::jsonb, NULL, NULL, 'Lafalkan dengan intonasi sopan.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-070005000007', 'b0000026-0000-0000-0000-000000000703', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat menyebutkan profesi ayah secara sopan:', '{"phrase":"父はエンジニアです。","romaji":"Chichi wa enjinia desu.","audio_text":"父はエンジニアです。","translation":"Ayah saya adalah seorang insinyur.","display_text":"父はエンジニアです。"}'::jsonb, '{"expected_transcript":"父はエンジニアです。"}'::jsonb, NULL, NULL, 'Gunakan 父 (chichi) untuk menyebut ayah kandung sendiri kepada lawan bicara.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-070005000008', 'b0000026-0000-0000-0000-000000000703', NULL, 'listening', 'listening_choice', 'Dengarkan frasa perkenalan keluarga berikut:', '{"options":[{"id":"opt_1","text":"Ibu saya adalah seorang guru."},{"id":"opt_2","text":"Ayah saya adalah dokter."},{"id":"opt_3","text":"Kakak saya murid."},{"id":"opt_4","text":"Ibu saya ibu rumah tangga."}],"audio_text":"母は教師です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '母 (haha) = ibu sendiri, 教師 (kyoushi) = guru/pengajar.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000070401', 'b0000026-0000-0000-0000-000000000704', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'reading', 'fill_blank', 'Baca Kanji keluarga berikut dan lengkapi kalimat untuk "anak laki-laki":', '{"options":["男の子","女の子","おとうさん","おかあさん"],"translation":"Anak laki-laki itu adik saya.","sentence_template":"あの [blank] は わたし の おとうと です。"}'::jsonb, '{"selected":"男の子"}'::jsonb, NULL, NULL, '男 (laki-laki) + の + 子 (anak) = anak laki-laki.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000070402', 'b0000026-0000-0000-0000-000000000704', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'listening', 'listening_choice', 'Dengarkan dialog profesi keluarga:', '{"options":[{"id":"opt_1","text":"Apakah ibumu seorang guru?"},{"id":"opt_2","text":"Apakah ayahmu dokter?"},{"id":"opt_3","text":"Apakah buku ini milikmu?"},{"id":"opt_4","text":"Siapa nama temanmu?"}],"audio_text":"おかあさんは せんせい ですか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menanyakan profesi ibu lawan bicara memakai おかあさん.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000070403', 'b0000026-0000-0000-0000-000000000704', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'writing', 'sentence_builder', 'Susun kalimat tanya sopan: "Apakah ayah Tuan Yamada dokter?"', '{"romaji":"Yamada-san no otousan wa isha desu ka?","tokens":["やまださん","の","おとうさん","は","いしゃ","ですか"],"target_translation":"Apakah ayah Yamada dokter?"}'::jsonb, '["やまださん","の","おとうさん","は","いしゃ","ですか"]'::jsonb, NULL, NULL, 'Selalu gunakan ～さん dan おとうさん ketika merujuk ayah lawan bicara.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
