INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000090302', 'b0000026-0000-0000-0000-000000000903', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'listening', 'listening_choice', 'Dengarkan cara menghitung jumlah orang yang unik:', '{"options":[{"id":"opt_1","text":"Keluarga ber-5; kakak perempuan ada 2 orang."},{"id":"opt_2","text":"Buku bahasa Jepang ada 2 jilid."},{"id":"opt_3","text":"Saya membeli 5 lembar prangko."},{"id":"opt_4","text":"Harga buku ini 5.000 Yen."}],"audio_text":"かぞくは 五人 です。あねが ふたり います。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '1 orang = ひとり, 2 orang = ふたり, 3+ = ～にん.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000090303', 'b0000026-0000-0000-0000-000000000903', NULL, 'writing', 'sentence_builder', 'Susun kalimat memesan jumlah umum: "Tolong 3 buah apel."', '{"romaji":"Ringo o mittsu kudasai.","tokens":["りんご","を","みっつ","ください"],"target_translation":"Tolong 3 buah apel."}'::jsonb, '["りんご","を","みっつ","ください"]'::jsonb, NULL, NULL, 'Hitungan benda umum: ひとつ (1), ふたつ (2), みっつ (3).', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
