INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000090401', 'b0000026-0000-0000-0000-000000000904', NULL, 'reading', 'fill_blank', 'Mana pasangan kata bantu hitung yang BENAR untuk buku & kertas/prangko tipis?', '{"options":["さつ","ぽん","にん","つ"],"translation":"Ada 1 jilid buku dan 1 lembar prangko.","sentence_template":"本が いっ [blank]、きってが いち まい あります。"}'::jsonb, '{"selected":"さつ"}'::jsonb, NULL, NULL, 'Buku memakai ～冊 (いっさつ = 1 jilid); kertas/kartu memakai ～枚.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000090402', 'b0000026-0000-0000-0000-000000000904', NULL, 'listening', 'listening_choice', 'Dengarkan dialog belanja memakai harga besar:', '{"options":[{"id":"opt_1","text":"Semuanya berjumlah 12.000 Yen."},{"id":"opt_2","text":"Semuanya berjumlah 1.200 Yen."},{"id":"opt_3","text":"Ada 2 orang pelanggan."},{"id":"opt_4","text":"Kunci ini harganya 800 Yen."}],"audio_text":"ぜんぶで 一万二千円 です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '一万 (10.000) + 二千 (2.000) = 12.000.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000090403', 'b0000026-0000-0000-0000-000000000904', NULL, 'writing', 'sentence_builder', 'Susun kalimat: "Di rumah ada 2 buah jam tangan."', '{"romaji":"Uchi ni tokei ga futatsu arimasu.","tokens":["うち","に","とけい","が","ふたつ","あります"],"target_translation":"Di rumah ada 2 jam tangan."}'::jsonb, '["うち","に","とけい","が","ふたつ","あります"]'::jsonb, NULL, NULL, 'Gabungan Unit 6 (とけい) + Unit 9 (ふたつ).', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
