INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000100401', 'b0000026-0000-0000-0000-000000001004', '79e54427-faad-401e-b423-a97ff3e695d8', 'reading', 'fill_blank', 'Ujian Tahap 2: manakah waktu yang TIDAK boleh memakai partikel に?', '{"options":["あした (tanpa に)","あした に","七じ に","月よう日 に"],"translation":"Saya besok pergi ke Jepang.","sentence_template":"わたしは [blank] 日本へ いきます。"}'::jsonb, '{"selected":"あした (tanpa に)"}'::jsonb, NULL, NULL, 'Kata waktu relatif (きょう・あした・きのう・まいにち) tidak pernah memakai に.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000100402', 'b0000026-0000-0000-0000-000000001004', '79e54427-faad-401e-b423-a97ff3e695d8', 'listening', 'listening_choice', 'Dengarkan kombinasi Kanji Hari & Jam Tahap 2:', '{"options":[{"id":"opt_1","text":"Setiap pagi bangun 06.30; hari Rabu ada ujian."},{"id":"opt_2","text":"Setiap malam tidur jam 10; hari Jumat libur."},{"id":"opt_3","text":"Kemarin saya pergi ke sekolah."},{"id":"opt_4","text":"Harga kamus ini 3.500 Yen."}],"audio_text":"まいあさ 六じはんに おきます。水よう日に テストが あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '六じはん (06.30) + 水よう日 (hari Rabu) keduanya spesifik sehingga memakai に.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
