INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000100404', 'b0000026-0000-0000-0000-000000001004', '79e54427-faad-401e-b423-a97ff3e695d8', 'speaking', 'speaking_repeat', 'Ucapkan waktu spesifik dalam bahasa Jepang: "いま 七じ はんです" (Sekarang jam 07.30):', '{"romaji":"ima shichiji han desu","audio_text":"いま 七じ はんです","display_text":"いま 七じ はんです"}'::jsonb, '{"expected_transcript":"いま 七じ はんです"}'::jsonb, NULL, NULL, 'Angka 7 jam selalu dibaca "shichi-ji", bukan "nana-ji".', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
