INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000110401', 'b0000026-0000-0000-0000-000000001104', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'reading', 'fill_blank', 'Lengkapi partikel penanda objek makanan langsung sebelum たべます:', '{"options":["を (o)","は (wa)","に (ni)","の (no)"],"translation":"Saya makan sarapan.","sentence_template":"わたしは あさごはん [blank] たべます。"}'::jsonb, '{"selected":"を (o)"}'::jsonb, NULL, NULL, 'Objek langsung dari kata kerja transitif selalu memakai を (dibaca o).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000110402', 'b0000026-0000-0000-0000-000000001104', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'listening', 'listening_choice', 'Dengarkan pesanan makanan memakai counter & を:', '{"options":[{"id":"opt_1","text":"Tolong 2 burger dan 1 cangkir kopi."},{"id":"opt_2","text":"Saya makan nasi dan ikan setiap pagi."},{"id":"opt_3","text":"Kafe ini dibuka jam 9 pagi."},{"id":"opt_4","text":"Apakah kamu minum teh?"}],"audio_text":"ハンバーガーを ふたつと コーヒーを いっぱい ください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ふたつ (2 buah) + いっぱい (1 gelas/cangkir) + ください.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000110403', 'b0000026-0000-0000-0000-000000001104', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'writing', 'sentence_builder', 'Susun kalimat kafe lengkap: "Setiap pagi saya minum kopi."', '{"romaji":"Watashi wa maiasa koohii o nomimasu.","tokens":["わたし","は","まいあさ","コーヒー","を","飲みます"],"target_translation":"Tiap pagi saya minum kopi."}'::jsonb, '["わたし","は","まいあさ","コーヒー","を","飲みます"]'::jsonb, NULL, NULL, 'まいあさ tidak memakai に; コーヒー sebagai objek memakai を.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000110404', 'b0000026-0000-0000-0000-000000001104', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'speaking', 'speaking_repeat', 'Ucapkan pesanan di kafe: "コーヒーを ください" (Tolong kopi):', '{"romaji":"koohii o kudasai","audio_text":"コーヒーを ください","display_text":"コーヒーを ください"}'::jsonb, '{"expected_transcript":"コーヒーを ください"}'::jsonb, NULL, NULL, 'Pastikan を dibaca "o" murni dan vokal panjang コーヒー terasa jelas.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
