INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000120401', 'b0000026-0000-0000-0000-000000001204', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'reading', 'fill_blank', 'Kontras negatif: untuk verba, negasi "tidak minum" (nomimasu) adalah:', '{"options":["のみません","のみではありません","のみない desu","のみました"],"translation":"Saya tidak minum alkohol.","sentence_template":"わたしは おさけを [blank]。"}'::jsonb, '{"selected":"のみません"}'::jsonb, NULL, NULL, 'Kata benda memakai ではありません; kata kerja sopan memakai ～ません.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000120402', 'b0000026-0000-0000-0000-000000001204', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'listening', 'listening_choice', 'Dengarkan gabungan waktu spesifik (に) & aktivitas rutin:', '{"options":[{"id":"opt_1","text":"Setiap pagi bangun jam 7 dan baca koran."},{"id":"opt_2","text":"Setiap malam tidur jam 11."},{"id":"opt_3","text":"Saya sama sekali tidak membaca buku."},{"id":"opt_4","text":"Apakah kamu menulis email?"}],"audio_text":"まいあさ 七じに おきて、しんぶんを 読みます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '七じに memadukan waktu spesifik Unit 10 dengan verba rutin Unit 12.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000120403', 'b0000026-0000-0000-0000-000000001204', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'writing', 'sentence_builder', 'Susun kalimat kebiasaan negatif total: "Saya sama sekali tidak minum teh."', '{"romaji":"Watashi wa zenzen ocha o nomimasen.","tokens":["わたし","は","ぜんぜん","おちゃを","飲みません"],"target_translation":"Sama sekali tidak minum teh."}'::jsonb, '["わたし","は","ぜんぜん","おちゃを","飲みません"]'::jsonb, NULL, NULL, 'ぜんぜん (sama sekali) wajib ditutup bentuk negatif 飲みません.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000120404', 'b0000026-0000-0000-0000-000000001204', 'e612bfa2-c788-4a37-bfb2-06d24ea5a108', 'speaking', 'speaking_repeat', 'Ucapkan kebiasaan harianmu: "まいにち にほんごを べんきょうします":', '{"romaji":"mainichi nihongo o benkyou shimasu","audio_text":"まいにち にほんごを べんきょうします","display_text":"まいにち にほんごを べんきょうします"}'::jsonb, '{"expected_transcript":"まいにち にほんごを べんきょうします"}'::jsonb, NULL, NULL, 'Ucapkan まいにち tanpa partikel に karena menyatakan frekuensi rutin.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
