INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-130002000008', 'b0000026-0000-0000-0000-000000001302', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat alat transportasi ini:', '{"options":[{"id":"opt_1","text":"Menggunting kertas dengan gunting."},{"id":"opt_2","text":"Menulis di kertas dengan pena."},{"id":"opt_3","text":"Melipat kertas origami."},{"id":"opt_4","text":"Membeli gunting di toko."}],"audio_text":"ハサミで紙を切ります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ハサミで (hasami de) = dengan gunting, 紙を切ります = memotong kertas.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000130301', 'b0000026-0000-0000-0000-000000001303', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'reading', 'fill_blank', 'Pilih partikel lokasi aktivitas yang tepat untuk kalimat "Minum kopi di kafe":', '{"options":["で","に","を","も"],"translation":"Minum kopi di kafe.","sentence_template":"カフェ [blank] コーヒーを のみます。"}'::jsonb, '{"selected":"で"}'::jsonb, NULL, NULL, 'Kafe adalah lokasi aktivitas -> pakai で; jam 9 adalah waktu -> pakai に.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000130302', 'b0000026-0000-0000-0000-000000001303', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'listening', 'listening_choice', 'Dengarkan kalimat lengkap ber-4 partikel berikut:', '{"options":[{"id":"opt_1","text":"Setiap hari saya berbicara bhs Jepang di sekolah."},{"id":"opt_2","text":"Setiap pagi makan roti dengan garpu."},{"id":"opt_3","text":"Saya membaca buku di perpustakaan kemarin."},{"id":"opt_4","text":"Apakah kantor ini buka hari Sabtu?"}],"audio_text":"わたしは まいにち 学校で 日本語で はなします。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Satu kalimat memakai は (topik), 学校で (lokasi), dan 日本語で (bahasa).', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000130303', 'b0000026-0000-0000-0000-000000001303', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'writing', 'sentence_builder', 'Susun kalimat dengan waktu + lokasi aksi: "Jam 8 makan di kantin."', '{"romaji":"Hachiji ni shokudou de gohan o tabemasu.","tokens":["八じに","しょくどう","で","ごはんを","食べます"],"target_translation":"Jam 8 makan di kantin."}'::jsonb, '["八じに","しょくどう","で","ごはんを","食べます"]'::jsonb, NULL, NULL, 'に untuk jam spesifik; で untuk kantin tempat makan; を untuk nasi.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-130005000004', 'b0000026-0000-0000-0000-000000001303', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kontras ''Di kelas ada murid'':', '{"options":["います","あります","します","です"],"translation":"Imasu","sentence_template":"教室 に 学生 が [blank]"}'::jsonb, '{"selected":"います"}'::jsonb, NULL, NULL, 'Makhluk hidup di tempat menggunakan います.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-130005000005', 'b0000026-0000-0000-0000-000000001303', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Belajar di kelas":', '{"romaji":"Kyoushitsu de benkyoushimasu","tokens":["きょうしつ","で","べんきょうします"],"target_translation":"Belajar di kelas"}'::jsonb, '["きょうしつ","で","べんきょうします"]'::jsonb, NULL, NULL, 'Kyoushitsu de benkyoushimasu.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-130005000006', 'b0000026-0000-0000-0000-000000001303', NULL, 'writing', 'fill_blank', 'Pilih partikel yang tepat untuk tujuan perpindahan (pergi ke):', '{"options":["に","で","を","から"],"translation":"Besok saya pergi ke Tokyo.","sentence_template":"明日東京 [blank] 行きます。"}'::jsonb, '{"selected":"に"}'::jsonb, NULL, NULL, 'Partikel に (atau へ) menandai tujuan arah perpindahan.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-130005000007', 'b0000026-0000-0000-0000-000000001303', NULL, 'reading', 'fill_blank', 'Pilih kalimat yang benar secara gramatika:', '{"options":["で","に","へ","を"],"translation":"Belajar di perpustakaan.","sentence_template":"図書館 [blank] 勉強します。(Aktivitas di perpustakaan)"}'::jsonb, '{"selected":"で"}'::jsonb, NULL, NULL, 'Karena 勉強します adalah tindakan aktif, tempat ditandai dengan で.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-130005000008', 'b0000026-0000-0000-0000-000000001303', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat multi-partikel lengkap ini:', '{"phrase":"友達とカフェでコーヒーを飲みます。","romaji":"Tomodachi to kafe de koohii o nomimasu.","audio_text":"友達とカフェでコーヒーを飲みます。","translation":"Minum kopi di kafe bersama teman.","display_text":"友達とカフェでコーヒーを飲みます。"}'::jsonb, '{"expected_transcript":"友達とカフェでコーヒーを飲みます。"}'::jsonb, NULL, NULL, 'Perhatikan 3 partikel: と (teman), で (lokasi aksi), を (objek kopi).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000130401', 'b0000026-0000-0000-0000-000000001304', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'reading', 'fill_blank', 'Jika ada seseorang menulis laporan "dengan komputer", partikel yang tepat ialah:', '{"options":["で","に","を","は"],"translation":"Menulis laporan memakai laptop.","sentence_template":"パソコン [blank] レポートを 書きます。"}'::jsonb, '{"selected":"で"}'::jsonb, NULL, NULL, 'Perangkat atau alat bantu kerja selalu memakai partikel で.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000130402', 'b0000026-0000-0000-0000-000000001304', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'listening', 'listening_choice', 'Dengarkan cara makan hidangan berikut:', '{"options":[{"id":"opt_1","text":"Makan memakai sendok dan garpu."},{"id":"opt_2","text":"Membeli sendok dan piring di toko."},{"id":"opt_3","text":"Makan roti tiap jam 7 pagi."},{"id":"opt_4","text":"Minum kopi pahit di kafe."}],"audio_text":"スプーンと フォークで たべます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'スプーンと フォークで menggabungkan dua alat memakai と lalu ditutup で.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000130403', 'b0000026-0000-0000-0000-000000001304', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'writing', 'sentence_builder', 'Susun kalimat: "Di rumah menonton film."', '{"romaji":"Uchi de eiga o mimasu.","tokens":["うち","で","えいが","を","見ます"],"target_translation":"Di rumah menonton film."}'::jsonb, '["うち","で","えいが","を","見ます"]'::jsonb, NULL, NULL, 'うちで (di rumah beraktivitas) + えいがを (objek) + 見ます.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000130404', 'b0000026-0000-0000-0000-000000001304', '33006568-75f9-4aa3-8d11-4b029168a7d4', 'speaking', 'speaking_repeat', 'Ucapkan kalimat aktivitas: "としょかんで 本を 読みます" (Membaca buku di perpustakaan):', '{"romaji":"toshokan de hon o yomimasu","audio_text":"としょかんで 本を 読みます","display_text":"としょかんで 本を 読みます"}'::jsonb, '{"expected_transcript":"としょかんで 本を 読みます"}'::jsonb, NULL, NULL, 'Perhatikan perpaduan partikel で (lokasi) dan を (objek).', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-130006000005', 'b0000026-0000-0000-0000-000000001304', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat aksi ''Mengambil foto di taman'':', '{"options":["とり","み","たべ","きき"],"translation":"Torimasu","sentence_template":"こうえん で しゃしん を [blank] ます"}'::jsonb, '{"selected":"とり"}'::jsonb, NULL, NULL, 'しゃしん を とります = mengambil foto.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-130006000006', 'b0000026-0000-0000-0000-000000001304', NULL, 'listening', 'listening_choice', 'Dengarkan dialog aktivitas luar ruangan:', '{"options":[{"id":"opt_1","text":"Kita bertemu di mana?"},{"id":"opt_2","text":"Jam berapa kita bertemu?"},{"id":"opt_3","text":"Apakah Anda mau bertemu?"},{"id":"opt_4","text":"Siapa yang akan bertemu?"}],"audio_text":"どこ で あいましょうか"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'どこ で あいましょうか (Bertemu di mana?).', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-130006000007', 'b0000026-0000-0000-0000-000000001304', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Mari bertemu di stasiun":', '{"romaji":"Eki de aimashou","tokens":["えき","で","あいましょう"],"target_translation":"Mari bertemu di stasiun"}'::jsonb, '["えき","で","あいましょう"]'::jsonb, NULL, NULL, 'Eki de aimashou.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-130006000008', 'b0000026-0000-0000-0000-000000001304', NULL, 'speaking', 'speaking_repeat', 'Ajak rekan Anda ''えき で あいましょう'':', '{"romaji":"eki de aimashou","audio_text":"えき で あいましょう","display_text":"えき で あいましょう"}'::jsonb, '{"expected_transcript":"えき で あいましょう"}'::jsonb, NULL, NULL, 'Lafalkan eki de aimashou.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000140101', 'b0000026-0000-0000-0000-000000001401', 'a830983b-40e2-4080-a8a5-416276586f1a', 'reading', 'fill_blank', 'Review Unit 13 + Ajakan: untuk mengajak teman dengan sopan ("Maukah pergi bersama?"), akhiran yang dipakai ialah:', '{"options":["ませんか","ましょう","ました","ません"],"translation":"Maukah minum kopi bersama?","sentence_template":"いっしょに コーヒーを 飲み [blank]。"}'::jsonb, '{"selected":"ませんか"}'::jsonb, NULL, NULL, '～ませんか = ajakan sopan menanyakan kesediaan lawan bicara.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000140102', 'b0000026-0000-0000-0000-000000001401', 'a830983b-40e2-4080-a8a5-416276586f1a', 'listening', 'listening_choice', 'Dengarkan respon antusias ajakan ("Ayo!"): ', '{"options":[{"id":"opt_1","text":"Ya, ayo makan bersama!"},{"id":"opt_2","text":"Maaf, saya agak sibuk hari ini."},{"id":"opt_3","text":"Saya jarang makan siang."},{"id":"opt_4","text":"Apakah kamu makan di kafe?"}],"audio_text":"ええ、いっしょに 食べましょう！"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '～ましょう berarti "Ayo kita lakukan!".', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000140103', 'b0000026-0000-0000-0000-000000001401', 'a830983b-40e2-4080-a8a5-416276586f1a', 'writing', 'sentence_builder', 'Susun kalimat ajakan: "Ayo beristirahat sebentar."', '{"romaji":"Sukoshi yasumimashou.","tokens":["すこし","休みましょう"],"target_translation":"Ayo istirahat sebentar."}'::jsonb, '["すこし","休みましょう"]'::jsonb, NULL, NULL, 'やすみます -> やすみましょう.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140001000004', 'b0000026-0000-0000-0000-000000001401', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ajakan menonton bioskop:', '{"options":["み","きき","たべ","よみ"],"translation":"Mimasenka","sentence_template":"えいが を [blank] ませんか"}'::jsonb, '{"selected":"み"}'::jsonb, NULL, NULL, 'えいが を みませんか (Maukah menonton film?).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140001000005', 'b0000026-0000-0000-0000-000000001401', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Ayo nonton film":', '{"romaji":"Eiga o mimashou","tokens":["えいが","を","見ましょう"],"target_translation":"Ayo nonton film"}'::jsonb, '["えいが","を","見ましょう"]'::jsonb, NULL, NULL, 'Eiga o mimashou.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140001000006', 'b0000026-0000-0000-0000-000000001401', NULL, 'speaking', 'speaking_repeat', 'Ajak teman ''えいが を みに行きませんか'':', '{"romaji":"eiga o mi ni ikimasen ka","audio_text":"えいが を みに行きませんか","display_text":"えいが を みに行きませんか"}'::jsonb, '{"expected_transcript":"えいが を みに行きませんか"}'::jsonb, NULL, NULL, 'Lafalkan dengan nada ramah.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140001000007', 'b0000026-0000-0000-0000-000000001401', NULL, 'listening', 'listening_choice', 'Dengarkan ajakan santai berikut:', '{"options":[{"id":"opt_1","text":"Maukah menonton film bersama?"},{"id":"opt_2","text":"Apakah kamu sudah menonton film?"},{"id":"opt_3","text":"Saya ingin menonton bioskop sendirian."},{"id":"opt_4","text":"Kapan bioskopnya buka?"}],"audio_text":"一緒に映画を見ませんか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '～ませんか (~masen ka) adalah pola sopan untuk mengajak lawan bicara.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140001000008', 'b0000026-0000-0000-0000-000000001401', NULL, 'speaking', 'speaking_repeat', 'Ucapkan respons menerima ajakan makan siang:', '{"phrase":"ええ、行きましょう。","romaji":"Ee, ikimashou.","audio_text":"ええ、行きましょう。","translation":"Ya, ayo kita pergi.","display_text":"ええ、行きましょう。"}'::jsonb, '{"expected_transcript":"ええ、行きましょう。"}'::jsonb, NULL, NULL, 'Gunakan ～ましょう (~mashou) untuk mengiyakan ajakan dengan antusias.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000140201', 'b0000026-0000-0000-0000-000000001402', 'a830983b-40e2-4080-a8a5-416276586f1a', 'reading', 'fill_blank', 'Kontras ～ましょう vs ～ましょうか: menawarkan bantuan ("Biar saya bawakan tasnya?") memakai:', '{"options":["ましょうか","ませんか","ません","ます"],"translation":"Mari saya bantu bawakan tasnya?","sentence_template":"かばんを もち [blank]。"}'::jsonb, '{"selected":"ましょうか"}'::jsonb, NULL, NULL, '～ましょうか diucapkan oleh penawar bantuan untuk menanyakan apakah lawan mau dibantu.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000140202', 'b0000026-0000-0000-0000-000000001402', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat berangkai menggunakan そして & それから:', '{"options":[{"id":"opt_1","text":"Kemarin pergi ke dept. store. Setelah itu nonton film."},{"id":"opt_2","text":"Saya tidak jadi nonton karena hujan."},{"id":"opt_3","text":"Setiap hari pergi ke kantor."},{"id":"opt_4","text":"Di bioskop ada banyak orang."}],"audio_text":"きのう デパートへ 行きました。それから、えいがを 見ました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'それから merangkai urutan kejadian setelah aksi pertama selesai.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000140203', 'b0000026-0000-0000-0000-000000001402', NULL, 'writing', 'sentence_builder', 'Susun penolakan sopan ala Jepang: "Maaf, hari ini agak..."', '{"romaji":"Sumimasen, kyou wa chotto...","tokens":["すみません","、","きょうは","ちょっと…"],"target_translation":"Maaf, hari ini agak (sibuk)..."}'::jsonb, '["すみません","、","きょうは","ちょっと…"]'::jsonb, NULL, NULL, 'Orang Jepang menolak halus tanpa langsung berkata Tidak dengan ちょっと....', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140002000004', 'b0000026-0000-0000-0000-000000001402', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat penolakan ajakan secara halus ''Maaf, hari Minggu agak sedikit repot...'':', '{"options":["都合がわるいです","いいです","すきです","ひまです"],"translation":"Chotto...","sentence_template":"日曜日 は ちょっと [blank]"}'::jsonb, '{"selected":"都合がわるいです"}'::jsonb, NULL, NULL, 'ちょっと都合がわるいです (Maaf agak berhalangan).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140002000005', 'b0000026-0000-0000-0000-000000001402', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Lain kali ya":', '{"romaji":"Mata kondo onegaishimasu","tokens":["また","今度","おねがいします"],"target_translation":"Lain kali ya"}'::jsonb, '["また","今度","おねがいします"]'::jsonb, NULL, NULL, 'Mata kondo onegaishimasu.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140002000006', 'b0000026-0000-0000-0000-000000001402', NULL, 'reading', 'fill_blank', 'Pilih kata sambung "oleh karena itu / jadi":', '{"options":["ですから","でも","そして","それから"],"translation":"Hujan. Oleh karena itu, pergi naik taksi.","sentence_template":"雨です。[blank]、タクシーで行きます。"}'::jsonb, '{"selected":"ですから"}'::jsonb, NULL, NULL, 'ですから (desu kara) berarti "karena itu / jadi" menyatakan alasan.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140002000007', 'b0000026-0000-0000-0000-000000001402', NULL, 'writing', 'fill_blank', 'Lengkapi ungkapan menawarkan bantuan:', '{"options":["持ち","買い","食べ","飲み"],"translation":"Boleh saya bawakan barangnya?","sentence_template":"荷物を [blank] ましょうか。(Membawakan barang)"}'::jsonb, '{"selected":"持ち"}'::jsonb, NULL, NULL, '持ちましょうか (mochimashou ka) = bagaimana kalau saya bawakan?', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140002000008', 'b0000026-0000-0000-0000-000000001402', NULL, 'listening', 'listening_choice', 'Dengarkan tawaran bantuan berikut:', '{"options":[{"id":"opt_1","text":"Boleh saya tutupkan jendelanya?"},{"id":"opt_2","text":"Bolehkah saya buka pintunya?"},{"id":"opt_3","text":"Tolong tutup jendelanya."},{"id":"opt_4","text":"Jendelanya terbuka lebar."}],"audio_text":"窓を閉めましょうか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '窓を閉めましょうか (mado o shimemashou ka) = tawaran sukarela menutup jendela.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000140401', 'b0000026-0000-0000-0000-000000001404', NULL, 'reading', 'fill_blank', 'Kata sambung berlawanan ("tetapi / namun") di awal kalimat kedua adalah:', '{"options":["でも","そして","それから","いっしょに"],"translation":"Bahasa Jepang sulit. Tetapi menarik.","sentence_template":"にほんごは むずかしいです。[blank]、おもしろいです。"}'::jsonb, '{"selected":"でも"}'::jsonb, NULL, NULL, 'でも menyatakan kontras antar kalimat.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000140402', 'b0000026-0000-0000-0000-000000001404', 'a830983b-40e2-4080-a8a5-416276586f1a', 'listening', 'listening_choice', 'Dengarkan dialog lengkap ajakan akhir pekan:', '{"options":[{"id":"opt_1","text":"Maukah bermain tenis bersama hari Sabtu?"},{"id":"opt_2","text":"Hari Minggu saya beristirahat di rumah."},{"id":"opt_3","text":"Saya bisa bermain tenis setiap hari."},{"id":"opt_4","text":"Tolong pinjamkan buku bahasa Jepang."}],"audio_text":"どよう日に いっしょに テニスを しませんか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menggabungkan hari (どよう日に) + いっしょに + ～ませんか.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000140403', 'b0000026-0000-0000-0000-000000001404', 'a830983b-40e2-4080-a8a5-416276586f1a', 'writing', 'sentence_builder', 'Susun kalimat ajakan makan siang bersama di kantin:', '{"romaji":"Issho ni shokudou de hirugohan o tabemasen ka?","tokens":["いっしょに","しょくどうで","ひるごはんを","食べませんか"],"target_translation":"Maukah makan siang bersama di kantin?"}'::jsonb, '["いっしょに","しょくどうで","ひるごはんを","食べませんか"]'::jsonb, NULL, NULL, 'Menggabungkan Unit 13 (しょくどうで) dan Unit 14 (食べませんか).', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000140404', 'b0000026-0000-0000-0000-000000001404', 'a830983b-40e2-4080-a8a5-416276586f1a', 'speaking', 'speaking_repeat', 'Ucapkan ajakan ramah: "いっしょに ひるごはんを たべませんか":', '{"romaji":"issho ni hirugohan o tabemasen ka","audio_text":"いっしょに ひるごはんを たべませんか","display_text":"いっしょに ひるごはんを たべませんか"}'::jsonb, '{"expected_transcript":"いっしょに ひるごはんを たべませんか"}'::jsonb, NULL, NULL, 'Naikkan sedikit intonasi di akhir kalimat tanya か.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140006000005', 'b0000026-0000-0000-0000-000000001404', NULL, 'reading', 'fill_blank', 'Pilih kata seru saat mendapat ide bagus:', '{"options":["いい","わるい","たかい","やすい"],"sentence_template":"[blank] ですね! そうしましょう!"}'::jsonb, '{"selected":"いい"}'::jsonb, NULL, NULL, 'いいですね (Ide bagus ya!).', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140006000006', 'b0000026-0000-0000-0000-000000001404', NULL, 'listening', 'listening_choice', 'Dengarkan dialog perencanaan akhir pekan:', '{"options":[{"id":"opt_1","text":"Hari Sabtu maukah pergi ke mall bersama?"},{"id":"opt_2","text":"Hari Minggu maukah ke mall?"},{"id":"opt_3","text":"Apakah mall buka hari Sabtu?"},{"id":"opt_4","text":"Mall mana yang bagus?"}],"audio_text":"土曜日 いっしょ に デパート へ いきませんか"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '土曜日 いっしょ に デパート へ いきませんか.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140006000007', 'b0000026-0000-0000-0000-000000001404', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Ya, tentu ayo pergi":', '{"romaji":"Hai, zehi ikimashou","tokens":["はい","、","ぜひ","行きましょう"],"target_translation":"Ya, tentu ayo pergi"}'::jsonb, '["はい","、","ぜひ","行きましょう"]'::jsonb, NULL, NULL, 'Hai, zehi ikimashou.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-140006000008', 'b0000026-0000-0000-0000-000000001404', NULL, 'speaking', 'speaking_repeat', 'Ucapkan respon antusias ''はい、ぜひ 行きましょう'':', '{"romaji":"hai, zehi ikimashou","audio_text":"はい、ぜひ 行きましょう","display_text":"はい、ぜひ 行きましょう"}'::jsonb, '{"expected_transcript":"はい、ぜひ 行きましょう"}'::jsonb, NULL, NULL, 'Lafalkan hai, zehi ikimashou.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000150401', 'b0000026-0000-0000-0000-000000001504', '05ca9c23-60a3-4eb9-bc58-259bbf0033c9', 'reading', 'fill_blank', 'Ujian Tahap 3: huruf manakah yang dipakai untuk pergi jalan kaki (tanpa partikel で)?', '{"options":["歩いて (aruite)","歩いて で","でんしゃ で","バス に"],"translation":"Pergi ke stasiun dengan berjalan kaki.","sentence_template":"えきまで [blank] 行きます。"}'::jsonb, '{"selected":"歩いて (aruite)"}'::jsonb, NULL, NULL, 'Kendaraan memakai で (でんしゃで), sedangkan berjalan kaki (あるいて) tidak memakai で.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000150402', 'b0000026-0000-0000-0000-000000001504', '05ca9c23-60a3-4eb9-bc58-259bbf0033c9', 'listening', 'listening_choice', 'Dengarkan rute perjalanan & rentang waktu Tahap 3:', '{"options":[{"id":"opt_1","text":"Tiap pagi pergi ke kantor naik kereta jam 8 sampai 9."},{"id":"opt_2","text":"Saya membaca koran di stasiun jam 8."},{"id":"opt_3","text":"Kemarin saya tidak pergi ke mana-mana."},{"id":"opt_4","text":"Ayo makan siang bersama di restoran."}],"audio_text":"まいあさ 八じから 九じまで 電車で かいしゃへ 行きます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '八じから 九じまで (rentang jam) + 電車で (kendaraan) + かいしゃへ (arah).', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000150403', 'b0000026-0000-0000-0000-000000001504', '05ca9c23-60a3-4eb9-bc58-259bbf0033c9', 'writing', 'sentence_builder', 'Susun kalimat negatif total perjalanan: "Besok tidak pergi ke mana pun."', '{"romaji":"Ashita doko e mo ikimasen.","tokens":["あした","どこへも","行きません"],"target_translation":"Besok tak pergi ke mana pun."}'::jsonb, '["あした","どこへも","行きません"]'::jsonb, NULL, NULL, 'どこ + partikel + も + verba negatif = tidak pergi ke mana pun.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000150404', 'b0000026-0000-0000-0000-000000001504', '05ca9c23-60a3-4eb9-bc58-259bbf0033c9', 'speaking', 'speaking_repeat', 'Ucapkan kalimat perjalanan lengkap: "ともだちと でんしゃで 東京へ 行きます":', '{"romaji":"tomodachi to densha de Toukyou e ikimasu","audio_text":"ともだちと でんしゃで 東京へ 行きます","display_text":"ともだちと でんしゃで 東京へ 行きます"}'::jsonb, '{"expected_transcript":"ともだちと でんしゃで 東京へ 行きます"}'::jsonb, NULL, NULL, 'Ingat: partikel arah へ diucapkan sebagai "e"!', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-150007000005', 'b0000026-0000-0000-0000-000000001504', NULL, 'reading', 'fill_blank', 'Ujian Tahap 3 (Soal 5): Partikel yang tepat untuk sarana transportasi adalah:', '{"options":["で","に","へ","を"],"sentence_template":"タクシー [blank] かえります"}'::jsonb, '{"selected":"で"}'::jsonb, NULL, NULL, 'タクシー で (dengan taksi).', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-150007000006', 'b0000026-0000-0000-0000-000000001504', NULL, 'listening', 'listening_choice', 'Ujian Tahap 3 (Soal 6): Dengarkan durasi waktu ini:', '{"options":[{"id":"opt_1","text":"Perlu waktu 2 jam dengan Shinkansen"},{"id":"opt_2","text":"Berangkat jam 2 dengan Shinkansen"},{"id":"opt_3","text":"Tiket Shinkansen 2.000 Yen"},{"id":"opt_4","text":"Naik Shinkansen nomor 2"}],"audio_text":"しんかんせん で にじかん かかります"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'にじかん かかります (Memakan waktu 2 jam).', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-150007000007', 'b0000026-0000-0000-0000-000000001504', NULL, 'writing', 'sentence_builder', 'Ujian Tahap 3 (Soal 7): Susun potongan kata menjadi kalimat "Ke Jepang sendirian":', '{"romaji":"Hitori de Nihon e ikimashita","tokens":["ひとりで","日本","へ","行きました"],"target_translation":"Ke Jepang sendirian"}'::jsonb, '["ひとりで","日本","へ","行きました"]'::jsonb, NULL, NULL, 'Hitori de Nihon e ikimashita.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-150007000008', 'b0000026-0000-0000-0000-000000001504', NULL, 'reading', 'fill_blank', 'Ujian Tahap 3 (Soal 8): Manakah partikel yang tepat untuk tujuan pulang ''Pulang ke rumah''?', '{"options":["へ","で","を","から"],"sentence_template":"うち [blank] かえります"}'::jsonb, '{"selected":"へ"}'::jsonb, NULL, NULL, 'うち へ かえります (Pulang ke rumah).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-150007000009', 'b0000026-0000-0000-0000-000000001504', NULL, 'listening', 'listening_choice', 'Ujian Tahap 3 (Soal 9): Dengarkan percakapan rute perjalanan ini:', '{"options":[{"id":"opt_1","text":"Naik apa pergi ke Kyoto?"},{"id":"opt_2","text":"Mengapa Anda ke Kyoto?"},{"id":"opt_3","text":"Kapan Anda pergi ke Kyoto?"},{"id":"opt_4","text":"Dengan siapa ke Kyoto?"}],"audio_text":"なん で きょうと へ いきますか"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'なん で (naik kendaraan apa) きょうと へ いきますか.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-150007000010', 'b0000026-0000-0000-0000-000000001504', NULL, 'speaking', 'speaking_repeat', 'Ujian Tahap 3 (Soal 10): Lafalkan kalimat komprehensif perjalanan ''らいしゅう ともだち と ひこうき で にほん へ いきます'':', '{"romaji":"raishuu tomodachi to hikouki de Nihon e ikimasu","audio_text":"らいしゅう ともだち と ひこうき で にほん へ いきます","display_text":"らいしゅう ともだち と ひこうき で にほん へ いきます"}'::jsonb, '{"expected_transcript":"らいしゅう ともだち と ひこうき で にほん へ いきます"}'::jsonb, NULL, NULL, 'Lafalkan kalimat pamungkas Tahap 3 dengan intonasi sempurna.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
