INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000160103', 'b0000026-0000-0000-0000-000000001601', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat keberadaan fasilitas: "Di dekat stasiun ada hotel."', '{"romaji":"Eki no chikaku ni hoteru ga arimasu.","tokens":["えきの","ちかくに","ホテルが","あります"],"target_translation":"Dekat stasiun ada hotel."}'::jsonb, '["えきの","ちかくに","ホテルが","あります"]'::jsonb, NULL, NULL, 'Hotel adalah benda tidak bergerak -> gunakan あります dengan penanda が.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-160001000004', 'b0000026-0000-0000-0000-000000001601', NULL, 'reading', 'fill_blank', 'Pilih Katakana deret M untuk bunyi ''mu'':', '{"options":["ム","マ","ミ","メ"],"translation":"Katakana MU","sentence_template":"Katakana MU: [blank]"}'::jsonb, '{"selected":"ム"}'::jsonb, NULL, NULL, 'ム adalah Katakana mu.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
