INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-160001000008', 'b0000026-0000-0000-0000-000000001601', NULL, 'reading', 'fill_blank', 'Pilih arti kata Katakana berikut: レストラン', '{"options":["Restoran","Toko roti","Hotel","Supermarket"],"translation":"Makan di restoran depan stasiun.","sentence_template":"駅前の [blank] で食事します。(Resutoran)"}'::jsonb, '{"selected":"Restoran"}'::jsonb, NULL, NULL, 'レストラン (resutoran) berasal dari kata serapan Restaurant.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000160401', 'b0000026-0000-0000-0000-000000001604', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Kontras あります vs います: di depan kata benda kucing (ねこ) memakai:', '{"options":["います","あります","です","ます"],"translation":"Di halaman ada kucing.","sentence_template":"にわに ねこが [blank]。"}'::jsonb, '{"selected":"います"}'::jsonb, NULL, NULL, 'Makhluk hidup yang bergerak sendiri (manusia & hewan) selalu memakai います.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000160402', 'b0000026-0000-0000-0000-000000001604', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan kontras keberadaan (に) vs lokasi aktivitas (で):', '{"options":[{"id":"opt_1","text":"Di stasiun ada minimarket. Saya beli air di sana."},{"id":"opt_2","text":"Di taman ada anak anjing."},{"id":"opt_3","text":"Saya pergi ke restoran naik bus."},{"id":"opt_4","text":"Apakah kamu tinggal di apartemen?"}],"audio_text":"えきに コンビニが あります。わたしは コンビニで 水を 買いました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'あります (ada di stasiun) pakai に; 買いました (bertransaksi) pakai で.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000160403', 'b0000026-0000-0000-0000-000000001604', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat keberadaan anggota keluarga: "Di kantor ada Tuan Sato."', '{"romaji":"Jimusho ni Satou-san ga imasu.","tokens":["じむしょ","に","さとうさん","が","います"],"target_translation":"Di kantor ada Tuan Sato."}'::jsonb, '["じむしょ","に","さとうさん","が","います"]'::jsonb, NULL, NULL, 'Keberadaan orang menggunakan [Tempat]に [Orang]が います.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000160404', 'b0000026-0000-0000-0000-000000001604', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan lokasi fasilitas: "すみません、トイレは どこに ありますか":', '{"romaji":"sumimasen, toire wa doko ni arimasu ka","audio_text":"すみません、トイレは どこに ありますか","display_text":"すみません、トイレは どこに ありますか"}'::jsonb, '{"expected_transcript":"すみません、トイレは どこに ありますか"}'::jsonb, NULL, NULL, 'Sangat berguna saat mencari toilet di tempat umum Jepang.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-160006000005', 'b0000026-0000-0000-0000-000000001604', NULL, 'reading', 'fill_blank', 'Lengkapi pertanyaan di toko ''Apakah ada baterai?'':', '{"options":["ありますか","いますか","ですか","でした"],"translation":"Arimasu ka","sentence_template":"でんち は [blank]"}'::jsonb, '{"selected":"ありますか"}'::jsonb, NULL, NULL, 'Baterai = benda mati -> ありますか.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-160006000006', 'b0000026-0000-0000-0000-000000001604', NULL, 'listening', 'listening_choice', 'Dengarkan konfirmasi petugas toko:', '{"options":[{"id":"opt_1","text":"Ya, ada di sebelah sana"},{"id":"opt_2","text":"Tidak ada baterai"},{"id":"opt_3","text":"Harganya 100 Yen"},{"id":"opt_4","text":"Silakan beli yang lain"}],"audio_text":"はい、あそこ に あります"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'はい、あそこ に あります (Ya, ada di sana).', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-160006000007', 'b0000026-0000-0000-0000-000000001604', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Ada di sebelah sana":', '{"romaji":"Asoko ni arimasu","tokens":["あそこ","に","あります"],"target_translation":"Ada di sebelah sana"}'::jsonb, '["あそこ","に","あります"]'::jsonb, NULL, NULL, 'Asoko ni arimasu.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-160006000008', 'b0000026-0000-0000-0000-000000001604', NULL, 'speaking', 'speaking_repeat', 'Tanyakan di toko ''これ は ありますか'' (Apakah barang ini ada?):', '{"romaji":"kore wa arimasu ka","audio_text":"これ は ありますか","display_text":"これ は ありますか"}'::jsonb, '{"expected_transcript":"これ は ありますか"}'::jsonb, NULL, NULL, 'Lafalkan kore wa arimasu ka.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000170101', 'b0000026-0000-0000-0000-000000001701', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'reading', 'fill_blank', 'Review Keberadaan + Kanji Posisi: lengkapi kalimat dengan Kanji yang berarti "sebelah kiri":', '{"options":["左 (hidari)","右 (migi)","上 (ue)","下 (shita)"],"translation":"Bank ada di sebelah kiri stasiun.","sentence_template":"銀行は 駅の [blank] に あります。(sebelah kiri)"}'::jsonb, '{"selected":"左 (hidari)"}'::jsonb, NULL, NULL, '右 = migi (kanan); 左 = hidari (kiri).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000170102', 'b0000026-0000-0000-0000-000000001701', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'listening', 'listening_choice', 'Dengarkan letak benda memakai Kanji 上・下・中:', '{"options":[{"id":"opt_1","text":"Di dalam tas ada kunci dan dompet."},{"id":"opt_2","text":"Di atas meja ada laptop."},{"id":"opt_3","text":"Di belakang gedung ada taman."},{"id":"opt_4","text":"Di antara bank dan kantor pos."}],"audio_text":"かばんの中に かぎと さいふが あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '中 (naka) berarti bagian dalam.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000170103', 'b0000026-0000-0000-0000-000000001701', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'writing', 'sentence_builder', 'Susun kalimat letak gedung: "Di sebelah bank ada kafe."', '{"romaji":"Ginkou no tonari ni kafe ga arimasu.","tokens":["ぎんこう","の","となり","に","カフェが","あります"],"target_translation":"Di sebelah bank ada kafe."}'::jsonb, '["ぎんこう","の","となり","に","カフェが","あります"]'::jsonb, NULL, NULL, 'Rumus posisi: [Acuan] の [Posisi] に [Benda] が あります.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
