INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-170001000007', 'b0000026-0000-0000-0000-000000001701', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat posisi benda ini:', '{"options":[{"id":"opt_1","text":"Kunci ada di atas meja."},{"id":"opt_2","text":"Buku ada di bawah kursi."},{"id":"opt_3","text":"Kunci ada di dalam tas."},{"id":"opt_4","text":"Meja ada di sebelah lemari."}],"audio_text":"机の上に鍵があります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '机の上 (tsukue no ue) = di atas meja, 鍵 (kagi) = kunci.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-170001000008', 'b0000026-0000-0000-0000-000000001701', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat keberadaan hewan peliharaan:', '{"phrase":"庭に犬がいます。","romaji":"Niwa ni inu ga imasu.","audio_text":"庭に犬がいます。","translation":"Ada anjing di halaman.","display_text":"庭に犬がいます。"}'::jsonb, '{"expected_transcript":"庭に犬がいます。"}'::jsonb, NULL, NULL, 'Untuk makhluk hidup bernyawa (anjing, manusia) gunakan verba います (imasu).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000170401', 'b0000026-0000-0000-0000-000000001704', 'dd9fe2c9-ae3f-438c-9f46-0fdd53524078', 'reading', 'fill_blank', 'Kontras と vs や: untuk menyebutkan contoh barang tidak lengkap ("seperti buku, pulpen, dll") memakai:', '{"options":["や","と","の","に"],"translation":"Di tas ada buku, pulpen, dsb.","sentence_template":"かばんに 本 [blank] ペンなどが あります。"}'::jsonb, '{"selected":"や"}'::jsonb, NULL, NULL, 'と mendaftar semua item secara tuntas; や (sering bersama など) menyebut contoh sebagian.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000170402', 'b0000026-0000-0000-0000-000000001704', 'dd9fe2c9-ae3f-438c-9f46-0fdd53524078', 'listening', 'listening_choice', 'Dengarkan lokasi bangunan di antara dua tempat:', '{"options":[{"id":"opt_1","text":"Toko roti ada di antara toko buku dan toko bunga."},{"id":"opt_2","text":"Toko buku di depan stasiun."},{"id":"opt_3","text":"Di dalam kelas hanya ada kursi."},{"id":"opt_4","text":"Di atas lemari ada foto keluarga."}],"audio_text":"パン屋は ほん屋と 花屋の あいだに あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Pola "di antara A dan B": Aと Bの あいだに.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000170403', 'b0000026-0000-0000-0000-000000001704', 'dd9fe2c9-ae3f-438c-9f46-0fdd53524078', 'writing', 'sentence_builder', 'Susun kalimat posisi: "Di depan sekolah ada taman."', '{"romaji":"Gakkou no mae ni kouen ga arimasu.","tokens":["学校","の","前","に","こうえん","が","あります"],"target_translation":"Di depan sekolah ada taman."}'::jsonb, '["学校","の","前","に","こうえん","が","あります"]'::jsonb, NULL, NULL, '前 (mae) berarti depan.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000170404', 'b0000026-0000-0000-0000-000000001704', 'dda49c88-24d5-4407-9778-faaec686ad7f', 'speaking', 'speaking_repeat', 'Ucapkan deskripsi letak benda: "つくえの うえに 本が あります":', '{"romaji":"tsukue no ue ni hon ga arimasu","audio_text":"つくえの うえに 本が あります","display_text":"つくえの うえに 本が あります"}'::jsonb, '{"expected_transcript":"つくえの うえに 本が あります"}'::jsonb, NULL, NULL, 'Latih gabungan のうえに secara lancar.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-170006000005', 'b0000026-0000-0000-0000-000000001704', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tanya lokasi ''Di mana stasiun terdekat?'':', '{"options":["ありますか","いますか","ですか","でした"],"translation":"Arimasu ka","sentence_template":"ちかく に えき が [blank]"}'::jsonb, '{"selected":"ありますか"}'::jsonb, NULL, NULL, 'Stasiun = benda mati -> ありますか.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-170006000006', 'b0000026-0000-0000-0000-000000001704', NULL, 'listening', 'listening_choice', 'Dengarkan petunjuk lokasi jalan ini:', '{"options":[{"id":"opt_1","text":"Tolong belok ke kanan di lampu lalu lintas"},{"id":"opt_2","text":"Tolong belok ke kiri di lampu lalu lintas"},{"id":"opt_3","text":"Lampu lalu lintas ada di kanan"},{"id":"opt_4","text":"Tolong jalan lurus"}],"audio_text":"しんごう を みぎ へ まがってください"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'しんごう を みぎ へ まがってください.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-170006000007', 'b0000026-0000-0000-0000-000000001704', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Belok kanan":', '{"romaji":"Migi e magarimasu","tokens":["右","へ","曲がります"],"target_translation":"Belok kanan"}'::jsonb, '["右","へ","曲がります"]'::jsonb, NULL, NULL, 'Migi e magarimasu.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-170006000008', 'b0000026-0000-0000-0000-000000001704', NULL, 'speaking', 'speaking_repeat', 'Ucapkan arah belok ''右 へ まがってください'':', '{"romaji":"migi e magatte kudasai","audio_text":"右 へ まがってください","display_text":"右 へ まがってください"}'::jsonb, '{"expected_transcript":"右 へ まがってください"}'::jsonb, NULL, NULL, 'Lafalkan migi e magatte kudasai.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000180101', 'b0000026-0000-0000-0000-000000001801', NULL, 'reading', 'fill_blank', 'Lengkapi huruf kecil (yoon) Katakana yang tepat pada kata "kaus" (shatsu):', '{"options":["ャ","ュ","ョ","ン"],"translation":"Kaus (shatsu)","sentence_template":"シ [blank] ツ"}'::jsonb, '{"selected":"ャ"}'::jsonb, NULL, NULL, 'Huruf kecil ャ (ya) digabung setelah シ (shi) membentuk bunyi "sha" pada kata シャツ (shatsu = kaus).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000180102', 'b0000026-0000-0000-0000-000000001801', NULL, 'listening', 'listening_choice', 'Dengarkan kata modern Katakana 4:', '{"options":[{"id":"opt_1","text":"Ponsel pintar"},{"id":"opt_2","text":"Minimarket"},{"id":"opt_3","text":"Pancuran air"},{"id":"opt_4","text":"Kaos kaki"}],"audio_text":"スマートフォン"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'フォ melambangkan bunyi "fo" modern dalam Katakana.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000180103', 'b0000026-0000-0000-0000-000000001801', NULL, 'writing', 'sentence_builder', 'Susun huruf menjadi kata "Anggur / Wine (wain)":', '{"romaji":"Wain","tokens":["ワ","イ","ン","ソ"],"target_translation":"Anggur / Wine (wain)"}'::jsonb, '["ワ","イ","ン"]'::jsonb, NULL, NULL, 'ワ=wa, イ=i, ン=n (garis menyapu naik dari bawah ke kanan atas).', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180001000004', 'b0000026-0000-0000-0000-000000001801', NULL, 'reading', 'fill_blank', 'Pilih Katakana untuk vokal ''o'' berhuruf tunggal:', '{"options":["オ","ア","ウ","エ"],"translation":"Katakana O","sentence_template":"Katakana O: [blank]"}'::jsonb, '{"selected":"オ"}'::jsonb, NULL, NULL, 'オ adalah Katakana o.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180001000005', 'b0000026-0000-0000-0000-000000001801', NULL, 'writing', 'sentence_builder', 'Susun huruf menjadi kata "Hotel":', '{"romaji":"Hoteru","tokens":["ホ","テ","ル"],"target_translation":"Hotel"}'::jsonb, '["ホ","テ","ル"]'::jsonb, NULL, NULL, 'Hoteru.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180001000006', 'b0000026-0000-0000-0000-000000001801', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kata ''ホテル'' (hotel):', '{"romaji":"hoteru","audio_text":"ホテル","display_text":"ホテル"}'::jsonb, '{"expected_transcript":"ホテル"}'::jsonb, NULL, NULL, 'Lafalkan ho-te-ru.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180001000007', 'b0000026-0000-0000-0000-000000001801', NULL, 'reading', 'fill_blank', 'Bedakan Katakana シ (shi) dan ツ (tsu):', '{"options":["シ","ツ","ソ","ン"],"translation":"Kemeja (shatsu)","sentence_template":"Kata \"Kemeja\" ditulis [blank] ャツ (shatsu)"}'::jsonb, '{"selected":"シ"}'::jsonb, NULL, NULL, 'Kemeja adalah シャツ dengan huruf シ (shi).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180001000008', 'b0000026-0000-0000-0000-000000001801', NULL, 'writing', 'fill_blank', 'Lengkapi kanji antonim posisi "depan" vs "belakang":', '{"options":["後","右","左","下"],"translation":"Lawan kata depan adalah belakang (ushiro)","sentence_template":"前 (depan) lawan katanya adalah [blank] (belakang)"}'::jsonb, '{"selected":"後"}'::jsonb, NULL, NULL, 'Kanji 後 dibaca うしろ (ushiro) yang berarti belakang.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000180201', 'b0000026-0000-0000-0000-000000001802', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Lawan kata dari おおきい (besar) adalah:', '{"options":["ちいさい","やすい","ふるい","さむい"],"translation":"Kamar ini kecil.","sentence_template":"この へやは [blank] です。(kecil)"}'::jsonb, '{"selected":"ちいさい"}'::jsonb, NULL, NULL, 'Pasangan antonim: おおきい (besar) vs ちいさい (kecil).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000180202', 'b0000026-0000-0000-0000-000000001802', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'listening', 'listening_choice', 'Dengarkan penilaian rasa makanan:', '{"options":[{"id":"opt_1","text":"Ramen ini murah dan enak."},{"id":"opt_2","text":"Kopi ini pahit dan dingin."},{"id":"opt_3","text":"Kemeja ini baru dan besar."},{"id":"opt_4","text":"Buku ini lama tapi menarik."}],"audio_text":"この ラーメンは やすくて おいしい です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'やすい = murah, おいしい = enak.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000180203', 'b0000026-0000-0000-0000-000000001802', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Ini laptop baru.":', '{"romaji":"Kore wa atarashii pasokon desu.","tokens":["これ","は","あたらしい","パソコン","です"],"target_translation":"Ini laptop baru."}'::jsonb, '["これ","は","あたらしい","パソコン","です"]'::jsonb, NULL, NULL, 'Sifat-I langsung menempel di depan kata benda tanpa partikel な atau の.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180002000004', 'b0000026-0000-0000-0000-000000001802', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Buku ini menarik'':', '{"options":["おもしろい","おいしい","たかい","ひろい"],"translation":"Omoshiroi","sentence_template":"この ほん は [blank] です"}'::jsonb, '{"selected":"おもしろい"}'::jsonb, NULL, NULL, 'おもしろい (omoshiroi) = menarik.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180002000005', 'b0000026-0000-0000-0000-000000001802', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Buku ini menarik":', '{"romaji":"Kono hon wa omoshiroi desu","tokens":["この","本は","おもしろい","です"],"target_translation":"Buku ini menarik"}'::jsonb, '["この","本は","おもしろい","です"]'::jsonb, NULL, NULL, 'Kono hon wa omoshiroi desu.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180002000006', 'b0000026-0000-0000-0000-000000001802', NULL, 'listening', 'listening_choice', 'Dengarkan opini sifat rasa makanan ini:', '{"options":[{"id":"opt_1","text":"Ramen ini sangat lezat."},{"id":"opt_2","text":"Ramen ini sangat asin."},{"id":"opt_3","text":"Ramen ini tidak enak."},{"id":"opt_4","text":"Ramen ini sangat mahal."}],"audio_text":"このラーメンはとてもおいしいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'おいしい (oishii) = lezat/enak, とても (totemo) = sangat.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180002000007', 'b0000026-0000-0000-0000-000000001802', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat menyangkal sifat (bentuk negatif):', '{"phrase":"この部屋は寒くないです。","romaji":"Kono heya wa samukunai desu.","audio_text":"この部屋は寒くないです。","translation":"Kamar ini tidak dingin.","display_text":"この部屋は寒くないです。"}'::jsonb, '{"expected_transcript":"この部屋は寒くないです。"}'::jsonb, NULL, NULL, 'Bentuk negatif kata sifat-i: hilangkan い dan tambahkan くない (samui -> samukunai).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180002000008', 'b0000026-0000-0000-0000-000000001802', NULL, 'reading', 'fill_blank', 'Pilih antonim kata sifat 高い (takai = mahal/tinggi):', '{"options":["安い","新しい","古い","大きい"],"translation":"Murah (yasui)","sentence_template":"高い (mahal) >< [blank] (murah)"}'::jsonb, '{"selected":"安い"}'::jsonb, NULL, NULL, '安い (yasui) adalah antonim dari 高い (takai).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000180401', 'b0000026-0000-0000-0000-000000001804', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Pengecualian Sifat-I "baik" (いい / よい): jika diubah menjadi negatif ("tidak bagus") menjadi:', '{"options":["よくない です","いくない です","いい ません","い ではありません"],"translation":"Hari ini cuacanya tidak bagus.","sentence_template":"きょうは てんきが [blank]。"}'::jsonb, '{"selected":"よくない です"}'::jsonb, NULL, NULL, 'Kata いい selalu menggunakan akar "よ-" saat dikonjugasikan: よくないです / よかったです.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000180402', 'b0000026-0000-0000-0000-000000001804', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'listening', 'listening_choice', 'Dengarkan kontras negasi Sifat-I berikut:', '{"options":[{"id":"opt_1","text":"Kamera ini tidak mahal. Harganya murah."},{"id":"opt_2","text":"Tas ini berat dan besar."},{"id":"opt_3","text":"Saya tidak membeli kamera ini."},{"id":"opt_4","text":"Di konbini tidak ada kopi panas."}],"audio_text":"この カメラは 高くない です。安いです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '高い -> buang い tambah くない = 高くない (tidak mahal).', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000180403', 'b0000026-0000-0000-0000-000000001804', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'writing', 'sentence_builder', 'Susun kalimat negatif Sifat-I: "Hari ini tidak dingin."', '{"romaji":"Kyou wa samukunai desu.","tokens":["きょう","は","さむくない","です"],"target_translation":"Hari ini tidak dingin."}'::jsonb, '["きょう","は","さむくない","です"]'::jsonb, NULL, NULL, 'さむい -> さむくないです.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000180404', 'b0000026-0000-0000-0000-000000001804', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'speaking', 'speaking_repeat', 'Ucapkan dengan ekspresi: "この パンは とても おいしいです" (Roti ini sangat enak):', '{"romaji":"kono pan wa totemo oishii desu","audio_text":"この パンは とても おいしいです","display_text":"この パンは とても おいしいです"}'::jsonb, '{"expected_transcript":"この パンは とても おいしいです"}'::jsonb, NULL, NULL, 'とても artinya "sangat" dan berpasangan dengan Sifat positif.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
