INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180006000006', 'b0000026-0000-0000-0000-000000001804', NULL, 'listening', 'listening_choice', 'Dengarkan kesan perjalanan wisata ini:', '{"options":[{"id":"opt_1","text":"Tokyo sangat ramai"},{"id":"opt_2","text":"Tokyo sangat tenang"},{"id":"opt_3","text":"Tokyo sangat mahal"},{"id":"opt_4","text":"Tokyo sangat dingin"}],"audio_text":"とうきょう は とても にぎやか です"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'とうきょう は とても にぎやか です.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
