INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-180006000008', 'b0000026-0000-0000-0000-000000001804', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kesan ''とても おいしい です'' (Sangat enak):', '{"romaji":"totemo oishii desu","audio_text":"とても おいしい です","display_text":"とても おいしい です"}'::jsonb, '{"expected_transcript":"とても おいしい です"}'::jsonb, NULL, NULL, 'Lafalkan totemo oishii desu.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000190101', 'b0000026-0000-0000-0000-000000001901', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Review Sifat-I + Kanji Warna: lengkapi kalimat dengan Kanji warna yang berarti "putih":', '{"options":["白い (shiroi)","黒い (kuroi)","赤い (akai)","青い (aoi)"],"translation":"Saya membeli sepatu putih.","sentence_template":"わたしは [blank] くつを 買いました。(putih)"}'::jsonb, '{"selected":"白い (shiroi)"}'::jsonb, NULL, NULL, '赤=merah, 青=biru, 白=putih, 黒=hitam.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000190102', 'b0000026-0000-0000-0000-000000001901', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'listening', 'listening_choice', 'Dengarkan dialog membandingkan barang baru vs lama:', '{"options":[{"id":"opt_1","text":"Sepeda lama kurang bagus. Akan beli yang baru."},{"id":"opt_2","text":"Kemeja biru ini sangat mahal."},{"id":"opt_3","text":"Saya tidak suka warna hitam."},{"id":"opt_4","text":"Di depan toko ada topi merah."}],"audio_text":"古い 自転車は あまり よくないです。新しいのを 買います。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '古い = lama/tua, 新しい = baru.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000190103', 'b0000026-0000-0000-0000-000000001901', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'writing', 'sentence_builder', 'Susun kalimat warna baju: "Kemeja putih itu murah."', '{"romaji":"Ano shiroi shatsu wa yasui desu.","tokens":["あの","白い","シャツ","は","安いです"],"target_translation":"Kemeja putih itu murah."}'::jsonb, '["あの","白い","シャツ","は","安いです"]'::jsonb, NULL, NULL, '白い (putih) menempel sebelum kata benda シャツ.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-190001000004', 'b0000026-0000-0000-0000-000000001901', NULL, 'reading', 'fill_blank', 'Kanji 青 dibaca ''aoi'' yang melambangkan warna:', '{"options":["biru","merah","kuning","hijau"],"sentence_template":"Kanji 青: [blank]"}'::jsonb, '{"selected":"biru"}'::jsonb, NULL, NULL, 'Kanji 青 berarti biru (aoi, sei).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
