INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-190001000008', 'b0000026-0000-0000-0000-000000001901', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat warna baju ini:', '{"options":[{"id":"opt_1","text":"Saya membeli kemeja biru."},{"id":"opt_2","text":"Saya menjual kemeja putih."},{"id":"opt_3","text":"Saya memakai celana hitam."},{"id":"opt_4","text":"Saya melihat topi merah."}],"audio_text":"青いシャツを買いました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '青い (aoi) = biru, シャツ (shatsu) = kemeja.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000190201', 'b0000026-0000-0000-0000-000000001902', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'reading', 'fill_blank', 'Contrastive Verba Pakaian: untuk memakai sepatu atau celana dari bawah dipakai verba:', '{"options":["履きます (hakimasu)","着ます (kimasu)","かぶります (kaburimasu)","かけます (kakemasu)"],"translation":"Besok akan memakai sepatu baru.","sentence_template":"あした あたらしい くつを [blank]。"}'::jsonb, '{"selected":"履きます (hakimasu)"}'::jsonb, NULL, NULL, 'Atasan/baju = 着ます; Bawahan/sepatu = 履きます; Topi = かぶります; Kacamata = かけます.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000190202', 'b0000026-0000-0000-0000-000000001902', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'listening', 'listening_choice', 'Dengarkan cara memakai kemeja & kacamata:', '{"options":[{"id":"opt_1","text":"Setiap pagi memakai kemeja putih dan berkacamata."},{"id":"opt_2","text":"Setiap pagi memakai topi dan sepatu olahraga."},{"id":"opt_3","text":"Saya membeli celana hitam kemarin."},{"id":"opt_4","text":"Apakah kamu punya jaket biru?"}],"audio_text":"まいあさ 白い シャツを 着ます。めがねも かけます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '着ます dipakai untuk atasan (シャツ), かけます untuk kacamata (めがね).', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000190203', 'b0000026-0000-0000-0000-000000001902', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'writing', 'sentence_builder', 'Susun kalimat memakai topi merah:', '{"romaji":"Akai boushi o kaburimasu.","tokens":["あかい","ぼうし","を","かぶります"],"target_translation":"Memakai topi merah."}'::jsonb, '["あかい","ぼうし","を","かぶります"]'::jsonb, NULL, NULL, 'Benda yang ditaruh di kepala memakai かぶります.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-190002000004', 'b0000026-0000-0000-0000-000000001902', NULL, 'reading', 'fill_blank', 'Kanji 白 dibaca ''shiroi'' yang melambangkan warna:', '{"options":["putih","hitam","merah","biru"],"sentence_template":"Kanji 白: [blank]"}'::jsonb, '{"selected":"putih"}'::jsonb, NULL, NULL, 'Kanji 白 berarti putih (shiroi, haku).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
