INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-190002000006', 'b0000026-0000-0000-0000-000000001902', NULL, 'reading', 'fill_blank', 'Pilih verba memakai untuk celana atau sepatu (bagian bawah tubuh):', '{"options":["はき","き","かぶり","かけ"],"translation":"Memakai sepatu","sentence_template":"靴を [blank] ます。(memakai sepatu)"}'::jsonb, '{"selected":"はき"}'::jsonb, NULL, NULL, 'Untuk alas kaki dan celana (bagian pinggang ke bawah), gunakan verba 履きます (hakimasu).', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
