INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-190002000008', 'b0000026-0000-0000-0000-000000001902', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat mengenakan kacamata:', '{"phrase":"眼鏡をかけています。","romaji":"Megane o kakete imasu.","audio_text":"眼鏡をかけています。","translation":"Sedang memakai kacamata.","display_text":"眼鏡をかけています。"}'::jsonb, '{"expected_transcript":"眼鏡をかけています。"}'::jsonb, NULL, NULL, 'Untuk kacamata, gunakan verba かけます (kakemasu).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000190401', 'b0000026-0000-0000-0000-000000001904', 'b24507cb-1868-40ca-b1b9-3288ae4b0640', 'reading', 'fill_blank', 'Kontras どれ vs どの vs どんな: menanyakan jenis atau kriteria baju ("Baju yang seperti apa?") memakai:', '{"options":["どんな","どの","どれ","だれ"],"translation":"Baju yang seperti apa yang bagus?","sentence_template":"[blank] ふくが いいですか。"}'::jsonb, '{"selected":"どんな"}'::jsonb, NULL, NULL, 'どんな [Benda] menanyakan ciri/kriteria; どの memilih dari 3+ barang terlihat.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000190402', 'b0000026-0000-0000-0000-000000001904', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'listening', 'listening_choice', 'Dengarkan percakapan belanja baju di toko:', '{"options":[{"id":"opt_1","text":"Permisi, apakah ada kemeja yang lebih murah?"},{"id":"opt_2","text":"Saya memakai sepatu ukuran 42."},{"id":"opt_3","text":"Sepatu hitam itu 5.000 Yen."},{"id":"opt_4","text":"Topi ini milik adik perempuan saya."}],"audio_text":"すみません、もっと やすい シャツは ありますか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '"もっと [Sifat] [Benda] は ありますか" sangat praktis saat menawar/meminta variasi.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000190403', 'b0000026-0000-0000-0000-000000001904', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'writing', 'sentence_builder', 'Susun kalimat memilih warna: "Saya suka tas warna hitam."', '{"romaji":"Watashi wa kuroi kaban ga suki desu.","tokens":["わたし","は","くろい","かばん","が","すきです"],"target_translation":"Saya suka tas hitam."}'::jsonb, '["わたし","は","くろい","かばん","が","すきです"]'::jsonb, NULL, NULL, 'Kesukaan memakai partikel が sebelum すきです.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000190404', 'b0000026-0000-0000-0000-000000001904', '56f9b781-8683-4704-beba-3643ccc0fd9e', 'speaking', 'speaking_repeat', 'Ucapkan pertanyaan sopan saat belanja: "すみません、これを 見ても いいですか":', '{"romaji":"sumimasen, kore o mite mo ii desu ka","audio_text":"すみません、これを 見ても いいですか","display_text":"すみません、これを 見ても いいですか"}'::jsonb, '{"expected_transcript":"すみません、これを 見ても いいですか"}'::jsonb, NULL, NULL, 'Meminta izin melihat/memegang barang dagangan.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-190006000005', 'b0000026-0000-0000-0000-000000001904', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tanya di butik pakaian ''Apakah ada ukuran lain?'':', '{"options":["ありますか","いますか","ですか","でした"],"translation":"Arimasu ka","sentence_template":"ほか の サイズ は [blank]"}'::jsonb, '{"selected":"ありますか"}'::jsonb, NULL, NULL, 'Benda ukuran = ありますか.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-190006000006', 'b0000026-0000-0000-0000-000000001904', NULL, 'listening', 'listening_choice', 'Dengarkan pelayan butik pakaian:', '{"options":[{"id":"opt_1","text":"Bagaimana menurut Anda? / Cocok?"},{"id":"opt_2","text":"Berapa harganya?"},{"id":"opt_3","text":"Apakah mau dibungkus?"},{"id":"opt_4","text":"Berapa banyak yang dibeli?"}],"audio_text":"いかが ですか"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'いかが ですか (Bagaimana pendapat Anda? Cocokkah?).', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-190006000007', 'b0000026-0000-0000-0000-000000001904', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Pas sekali":', '{"romaji":"Choudo ii desu","tokens":["ちょうど","いい","です"],"target_translation":"Pas sekali"}'::jsonb, '["ちょうど","いい","です"]'::jsonb, NULL, NULL, 'Choudo ii desu.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-190006000008', 'b0000026-0000-0000-0000-000000001904', NULL, 'speaking', 'speaking_repeat', 'Ucapkan di ruang pas ''ちょうど いい です'' (Pas dan cocok):', '{"romaji":"choudo ii desu","audio_text":"ちょうど いい です","display_text":"ちょうど いい です"}'::jsonb, '{"expected_transcript":"ちょうど いい です"}'::jsonb, NULL, NULL, 'Lafalkan choudo ii desu.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000210201', 'b0000026-0000-0000-0000-000000002102', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Kosakata Arah Jalan: arti kata "まっすぐ 行って、みぎへ まがる" adalah:', '{"options":["まがっ","わたっ","いっ","とまっ"],"translation":"Tolong belok ke kanan di belokan berikutnya.","sentence_template":"つぎの かどを みぎへ [blank] て ください。"}'::jsonb, '{"selected":"まがっ"}'::jsonb, NULL, NULL, 'まがります (Grup 1 berakhiran り) -> まがってください (beloklah).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000210202', 'b0000026-0000-0000-0000-000000002102', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan instruksi menyeberangi jalan & belok:', '{"options":[{"id":"opt_1","text":"Seberangi lampu merah itu, lalu belok ke kiri."},{"id":"opt_2","text":"Jalan lurus sampai depan stasiun."},{"id":"opt_3","text":"Berhenti sebentar di depan bank."},{"id":"opt_4","text":"Perlihatkan peta kota di meja."}],"audio_text":"あの しんごうを わたって、ひだりへ まがってください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'しんごう (lampu lalu lintas) + わたって (seberangi) + まがって (belok).', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000210203', 'b0000026-0000-0000-0000-000000002102', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun petunjuk arah: "Jalanlah lurus dari sini."', '{"romaji":"Koko kara massugu itte kudasai.","tokens":["ここ","から","まっすぐ","行って","ください"],"target_translation":"Jalan lurus dari sini."}'::jsonb, '["ここ","から","まっすぐ","行って","ください"]'::jsonb, NULL, NULL, '行きます (pergi) bentuk-TE pengecualian menjadi 行って (itte).', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210002000004', 'b0000026-0000-0000-0000-000000002102', NULL, 'reading', 'fill_blank', 'Bentuk-TE dari verba あけます (membuka pintu) adalah:', '{"options":["あけて","あかて","あけって","あけいで"],"translation":"Akete","sentence_template":"あけます -> [blank]"}'::jsonb, '{"selected":"あけて"}'::jsonb, NULL, NULL, 'Grup 2: あけます -> あけて (akete).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210002000005', 'b0000026-0000-0000-0000-000000002102', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Tolong buka pintu":', '{"romaji":"Doa o akete kudasai","tokens":["ドア","を","開けて","ください"],"target_translation":"Tolong buka pintu"}'::jsonb, '["ドア","を","開けて","ください"]'::jsonb, NULL, NULL, 'Doa o akete kudasai.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210002000006', 'b0000026-0000-0000-0000-000000002102', NULL, 'listening', 'listening_choice', 'Dengarkan arahan jalan di perempatan:', '{"options":[{"id":"opt_1","text":"Tolong belok ke kanan di sudut/tikungan berikutnya."},{"id":"opt_2","text":"Tolong belok kiri di perempatan depan."},{"id":"opt_3","text":"Tolong jalan lurus terus."},{"id":"opt_4","text":"Tolong seberangi jembatan itu."}],"audio_text":"次の角を右に曲がってください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '次の角 (tsugi no kado) = sudut berikutnya, 右に曲がってください = tolong belok kanan.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210002000007', 'b0000026-0000-0000-0000-000000002102', NULL, 'reading', 'fill_blank', 'Pilih partikel yang tepat untuk menyeberang jembatan:', '{"options":["を","で","に","へ"],"translation":"Menyeberangi jembatan.","sentence_template":"橋 [blank] わたります。"}'::jsonb, '{"selected":"を"}'::jsonb, NULL, NULL, 'Verba perpindahan melintasi ruang/jalan/jembatan ditandai dengan partikel を (hashi o watarimasu).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210002000008', 'b0000026-0000-0000-0000-000000002102', NULL, 'speaking', 'speaking_repeat', 'Ucapkan instruksi jalan lurus:', '{"phrase":"まっすぐ行ってください。","romaji":"Massugu itte kudasai.","audio_text":"まっすぐ行ってください。","translation":"Tolong jalan lurus terus.","display_text":"まっすぐ行ってください。"}'::jsonb, '{"expected_transcript":"まっすぐ行ってください。"}'::jsonb, NULL, NULL, 'まっすぐ (massugu) = lurus terus.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000210401', 'b0000026-0000-0000-0000-000000002104', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Pengecualian Konjugasi Bentuk-TE Grup 1: bentuk-TE dari 行きます ("pergi") adalah:', '{"options":["行って (itte)","行いて (iite)","行んで (inde)","行して (ishite)"],"translation":"Tolong cepat pergi ke stasiun.","sentence_template":"いそいで えきへ [blank] ください。"}'::jsonb, '{"selected":"行って (itte)"}'::jsonb, NULL, NULL, 'き biasanya menjadi いて (kaku->kaite), KECUALI 行きます menjadi 行って.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000210402', 'b0000026-0000-0000-0000-000000002104', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan permintaan sopan di kelas:', '{"options":[{"id":"opt_1","text":"Maaf, tolong ucapkan pelan-pelan sekali lagi."},{"id":"opt_2","text":"Tolong tulis nama di buku."},{"id":"opt_3","text":"Silakan duduk di kursi itu."},{"id":"opt_4","text":"Mari kita belajar bersama."}],"audio_text":"すみませんが、もう いちど ゆっくり 言って ください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '言います (mengatakan) -> 言って (itte) + ください.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000210403', 'b0000026-0000-0000-0000-000000002104', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat sopan: "Tolong tulis nama Anda di sini."', '{"romaji":"Koko ni namae o kaite kudasai.","tokens":["ここ","に","名前","を","書いて","ください"],"target_translation":"Tolong tulis nama di sini."}'::jsonb, '["ここ","に","名前","を","書いて","ください"]'::jsonb, NULL, NULL, '書きます -> 書いて + ください.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000210404', 'b0000026-0000-0000-0000-000000002104', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'speaking', 'speaking_repeat', 'Ucapkan instruksi kepada supir atau teman: "つぎの かどを みぎへ まがってください":', '{"romaji":"tsugi no kado o migi e magatte kudasai","audio_text":"つぎの かどを みぎへ まがってください","display_text":"つぎの かどを みぎへ まがってください"}'::jsonb, '{"expected_transcript":"つぎの かどを みぎへ まがってください"}'::jsonb, NULL, NULL, 'Latih gabungan รูป Bentuk-TE dan partikel へ.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210006000005', 'b0000026-0000-0000-0000-000000002104', NULL, 'reading', 'fill_blank', 'Lengkapi sapaan saat bertanya jalan ''Permisi, stasiun ada di mana?'':', '{"options":["どこ","だれ","なに","いくら"],"translation":"Doko","sentence_template":"すみません、えき は [blank] ですか"}'::jsonb, '{"selected":"どこ"}'::jsonb, NULL, NULL, 'えき は どこ ですか.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210006000006', 'b0000026-0000-0000-0000-000000002104', NULL, 'listening', 'listening_choice', 'Dengarkan petunjuk jalan dari warga lokal:', '{"options":[{"id":"opt_1","text":"Ada gedung tinggi di sana kan? Ada di sebelahnya"},{"id":"opt_2","text":"Gedung tingginya tutup"},{"id":"opt_3","text":"Stasiunnya masih sangat jauh"},{"id":"opt_4","text":"Harus naik taksi"}],"audio_text":"あそこ に たかい ビル が ありますね。その となり です"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'あそこ に たかい ビル が ありますね。その となり です.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210006000007', 'b0000026-0000-0000-0000-000000002104', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Terima kasih banyak":', '{"romaji":"Doumo arigatou gozaimasu","tokens":["どうも","ありがとう","ございます"],"target_translation":"Terima kasih banyak"}'::jsonb, '["どうも","ありがとう","ございます"]'::jsonb, NULL, NULL, 'Doumo arigatou gozaimasu.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-210006000008', 'b0000026-0000-0000-0000-000000002104', NULL, 'speaking', 'speaking_repeat', 'Tanyakan arah di jalan ''すみません、ぎんこう は どこ ですか'':', '{"romaji":"sumimasen, ginkou wa doko desu ka","audio_text":"すみません、銀行 は どこ ですか","display_text":"すみません、銀行 は どこ ですか"}'::jsonb, '{"expected_transcript":"すみません、銀行 は どこ ですか"}'::jsonb, NULL, NULL, 'Lafalkan sumimasen, ginkou wa doko desu ka.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000220101', 'b0000026-0000-0000-0000-000000002201', '713b3950-cd77-436e-9e0e-d131b205008e', 'reading', 'fill_blank', 'Review Bentuk-TE + Verba Status: jawab negasi dari 知っています ("Saya tidak tahu"):', '{"options":["しりません","しっていません","しりませんでした","しらない ください"],"translation":"Tidak, saya tidak tahu nomor teleponnya.","sentence_template":"いいえ、でんわばんごうを [blank]。"}'::jsonb, '{"selected":"しりません"}'::jsonb, NULL, NULL, 'Jebakan N5: bentuk positif memakai しっています, sedangkan negatifnya langsung しりません!', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000220102', 'b0000026-0000-0000-0000-000000002201', '713b3950-cd77-436e-9e0e-d131b205008e', 'listening', 'listening_choice', 'Dengarkan pernyataan status tempat tinggal (住んでいます):', '{"options":[{"id":"opt_1","text":"Saya tinggal di Jakarta bersama keluarga."},{"id":"opt_2","text":"Saya sedang pergi ke Jakarta."},{"id":"opt_3","text":"Besok keluarga datang dari Jakarta."},{"id":"opt_4","text":"Saya bekerja di perusahaan Jakarta."}],"audio_text":"わたしは かぞくと ジャカルタに 住んでいます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '住みます diubah menjadi 住んでいます untuk menyatakan kondisi menetap berkelanjutan.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000220103', 'b0000026-0000-0000-0000-000000002201', '713b3950-cd77-436e-9e0e-d131b205008e', 'writing', 'sentence_builder', 'Susun kalimat kepemilikan status: "Saya membawa kamus."', '{"romaji":"Watashi wa jisho o motte imasu.","tokens":["わたし","は","じしょ","を","もっています"],"target_translation":"Saya punya/membawa kamus."}'::jsonb, '["わたし","は","じしょ","を","もっています"]'::jsonb, NULL, NULL, 'もちます (つ -> って) menjadi もっています (memiliki/membawa).', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220001000004', 'b0000026-0000-0000-0000-000000002201', NULL, 'reading', 'fill_blank', 'Verba 持っています (motte imasu) menyatakan:', '{"options":["memiliki","menjual","membeli","meminjam"],"translation":"Memiliki / membawa","sentence_template":"Makna もっています: [blank]"}'::jsonb, '{"selected":"memiliki"}'::jsonb, NULL, NULL, '持っています = membawa / mempunyai.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220001000005', 'b0000026-0000-0000-0000-000000002201', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Membawa payung":', '{"romaji":"Kasa o motte imasu","tokens":["傘","を","持って","います"],"target_translation":"Membawa payung"}'::jsonb, '["傘","を","持って","います"]'::jsonb, NULL, NULL, 'Kasa o motte imasu.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220001000006', 'b0000026-0000-0000-0000-000000002201', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kepemilikan ''くるま を もって います'':', '{"romaji":"kuruma o motte imasu","audio_text":"車 を 持って います","display_text":"車 を 持って います"}'::jsonb, '{"expected_transcript":"車 を 持って います"}'::jsonb, NULL, NULL, 'Lafalkan kuruma o motte imasu.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220001000007', 'b0000026-0000-0000-0000-000000002201', NULL, 'writing', 'fill_blank', 'Lengkapi bentuk-TE dari verba "tahu/kenal" (知ります):', '{"options":["って","いて","ちて","んで"],"translation":"Saya mengenal orang itu (status tahu).","sentence_template":"その人を知 [blank] います。"}'::jsonb, '{"selected":"って"}'::jsonb, NULL, NULL, '知ります (Grup 1 berakhiran ri) berubah menjadi 知って (shitte).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220001000008', 'b0000026-0000-0000-0000-000000002201', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat status tempat tinggal ini:', '{"options":[{"id":"opt_1","text":"Saya tinggal di Tokyo."},{"id":"opt_2","text":"Saya bekerja di Tokyo."},{"id":"opt_3","text":"Saya berlibur ke Tokyo."},{"id":"opt_4","text":"Saya pindah dari Tokyo."}],"audio_text":"東京に住んでいます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '住んでいます (sunde imasu) menyatakan kondisi tempat tinggal tetap.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000220401', 'b0000026-0000-0000-0000-000000002204', '713b3950-cd77-436e-9e0e-d131b205008e', 'reading', 'fill_blank', 'Kontras てから vs ています: pilih bentuk untuk "Setelah selesai makan siang, pulang":', '{"options":["食べてから","食べています","食べて ください","食べません"],"translation":"Setelah makan siang, pulang.","sentence_template":"ひるごはんを [blank] かえります。"}'::jsonb, '{"selected":"食べてから"}'::jsonb, NULL, NULL, '[Aてから B] menegaskan aksi A tuntas lebih dulu sebelum aksi B terjadi.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000220402', 'b0000026-0000-0000-0000-000000002204', '713b3950-cd77-436e-9e0e-d131b205008e', 'listening', 'listening_choice', 'Dengarkan aktivitas yang sedang berlangsung saat ini:', '{"options":[{"id":"opt_1","text":"Sekarang sedang minum kopi di kafe bersama teman."},{"id":"opt_2","text":"Setiap hari saya minum kopi di rumah."},{"id":"opt_3","text":"Tolong minum kopinya sekarang."},{"id":"opt_4","text":"Setelah minum kopi saya pulang."}],"audio_text":"いま ともだちと カフェで コーヒーを 飲んでいます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'いま + Vて + います = sedang berlangsung sekarang.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000220403', 'b0000026-0000-0000-0000-000000002204', '713b3950-cd77-436e-9e0e-d131b205008e', 'writing', 'sentence_builder', 'Susun kalimat berurutan pagi: "Setelah bangun tidur, minum air."', '{"romaji":"Okite kara, mizu o nomimasu.","tokens":["おきて","から","、","みずを","飲みます"],"target_translation":"Setelah bangun, minum air."}'::jsonb, '["おきて","から","、","みずを","飲みます"]'::jsonb, NULL, NULL, 'おきます (Grup 2) -> おきて + から.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000220404', 'b0000026-0000-0000-0000-000000002204', '713b3950-cd77-436e-9e0e-d131b205008e', 'speaking', 'speaking_repeat', 'Ucapkan kondisi dirimu saat ini: "いま にほんごを べんきょうしています":', '{"romaji":"ima nihongo o benkyou shite imasu","audio_text":"いま にほんごを べんきょうしています","display_text":"いま にほんごを べんきょうしています"}'::jsonb, '{"expected_transcript":"いま にほんごを べんきょうしています"}'::jsonb, NULL, NULL, 'します menjadi しています.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220006000005', 'b0000026-0000-0000-0000-000000002204', NULL, 'reading', 'fill_blank', 'Lengkapi pertanyaan ''Sekarang hujan sedang turun kah?'':', '{"options":["います","あります","します","です"],"translation":"Imasu","sentence_template":"あめ が ふって [blank] か"}'::jsonb, '{"selected":"います"}'::jsonb, NULL, NULL, 'ふっていますか (Apakah sedang hujan?).', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220006000006', 'b0000026-0000-0000-0000-000000002204', NULL, 'listening', 'listening_choice', 'Dengarkan laporan cuaca saat ini:', '{"options":[{"id":"opt_1","text":"Sekarang salju sedang turun"},{"id":"opt_2","text":"Sekarang hujan deras"},{"id":"opt_3","text":"Cuacanya cerah"},{"id":"opt_4","text":"Besok akan turun salju"}],"audio_text":"いま ゆき が ふって います"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ゆき が ふって います = salju sedang turun.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220006000007', 'b0000026-0000-0000-0000-000000002204', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Sedang hujan":', '{"romaji":"Ame ga futte imasu","tokens":["雨が","降って","います"],"target_translation":"Sedang hujan"}'::jsonb, '["雨が","降って","います"]'::jsonb, NULL, NULL, 'Ame ga futte imasu.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-220006000008', 'b0000026-0000-0000-0000-000000002204', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kondisi cuaca saat ini ''いま 雨 が 降って います'':', '{"romaji":"ima ame ga futte imasu","audio_text":"いま 雨 が 降って います","display_text":"いま 雨 が 降って います"}'::jsonb, '{"expected_transcript":"いま 雨 が 降って います"}'::jsonb, NULL, NULL, 'Lafalkan ima ame ga futte imasu.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000230101', 'b0000026-0000-0000-0000-000000002301', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Review ～ています + Bentuk-NAI: perubahan kata kerja かいます ("membeli") ke Bentuk-NAI adalah:', '{"options":["かわない","かあない","かって","かいません"],"translation":"Hari ini pulang tanpa membeli apa pun.","sentence_template":"きょうは 何も [blank] で 帰ります。"}'::jsonb, '{"selected":"かわない"}'::jsonb, NULL, NULL, 'Jika sebelum ます adalah vokal い murni (かいます), di Bentuk-NAI berubah jadi わ (かわない)!', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000230102', 'b0000026-0000-0000-0000-000000002301', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan perubahan Grup 3 ke Bentuk-NAI + でください:', '{"options":[{"id":"opt_1","text":"Besok tolong jangan terlambat masuk kelas."},{"id":"opt_2","text":"Besok boleh datang jam 10 pagi."},{"id":"opt_3","text":"Di kelas dilarang makan siang."},{"id":"opt_4","text":"Apakah kamu membawa kamus hari ini?"}],"audio_text":"あした じゅぎょうに おくれないで ください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'おくれます (Grup 2) -> おくれない + でください.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000230103', 'b0000026-0000-0000-0000-000000002301', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun larangan halus: "Tolong jangan lupa paspor Anda."', '{"romaji":"Pasupooto o wasurenaide kudasai.","tokens":["パスポート","を","わすれないで","ください"],"target_translation":"Tolong jgn lupa paspor."}'::jsonb, '["パスポート","を","わすれないで","ください"]'::jsonb, NULL, NULL, 'わすれます (Grup 2) -> わすれないで + ください.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-230001000004', 'b0000026-0000-0000-0000-000000002301', NULL, 'reading', 'fill_blank', 'Bentuk-NAI dari verba 飲みます (minum) adalah:', '{"options":["のまない","のみない","のめない","のまないで"],"translation":"Nomanai","sentence_template":"のみます -> [blank]"}'::jsonb, '{"selected":"のまない"}'::jsonb, NULL, NULL, 'Grup 1: 飲みます -> 飲まない (nomanai).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-230001000005', 'b0000026-0000-0000-0000-000000002301', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Jangan minum alkohol":', '{"romaji":"Osake o nomanaide kudasai","tokens":["お酒","を","飲まないで","ください"],"target_translation":"Jangan minum alkohol"}'::jsonb, '["お酒","を","飲まないで","ください"]'::jsonb, NULL, NULL, 'Osake o nomanaide kudasai.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-230001000006', 'b0000026-0000-0000-0000-000000002301', NULL, 'speaking', 'speaking_repeat', 'Ucapkan larangan ''たばこ を すっては いけません'':', '{"romaji":"tabako o sutte wa ikemasen","audio_text":"たばこ を 吸っては いけません","display_text":"たばこ を 吸っては いけません"}'::jsonb, '{"expected_transcript":"たばこ を 吸っては いけません"}'::jsonb, NULL, NULL, 'Lafalkan tabako o sutte wa ikemasen.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-230001000007', 'b0000026-0000-0000-0000-000000002301', NULL, 'reading', 'fill_blank', 'Pilih bentuk-NAI dari verba "menulis" (書きます):', '{"options":["書かない","書けない","書きない","書くない"],"translation":"Bentuk negatif kasual menulis","sentence_template":"書きます -> [blank]"}'::jsonb, '{"selected":"書かない"}'::jsonb, NULL, NULL, 'Verba Grup 1: vokal "i" sebelum masu berubah ke baris "a" + nai (kaki -> kaka-nai).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-230001000008', 'b0000026-0000-0000-0000-000000002301', NULL, 'speaking', 'speaking_repeat', 'Ucapkan larangan merokok secara sopan:', '{"phrase":"ここでたばこを吸わないでください。","romaji":"Koko de tabako o suwanaide kudasai.","audio_text":"ここでたばこを吸わないでください。","translation":"Tolong jangan merokok di sini.","display_text":"ここでたばこを吸わないでください。"}'::jsonb, '{"expected_transcript":"ここでたばこを吸わないでください。"}'::jsonb, NULL, NULL, 'Bentuk-NAI + でください adalah rumus sopan untuk menyatakan permohonan larangan.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000230401', 'b0000026-0000-0000-0000-000000002304', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Kontras 4 pola etika: "Di museum ini dilarang memotret" memakai akhiran:', '{"options":["はいけません","もいいです","ください","いません"],"translation":"Dilarang memotret di sini.","sentence_template":"ここで しゃしんを とって [blank]。"}'::jsonb, '{"selected":"はいけません"}'::jsonb, NULL, NULL, 'Bentuk-TE + はいけません = dilarang melakukannya.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000230402', 'b0000026-0000-0000-0000-000000002304', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan dialog meminta izin di ruang kantor:', '{"options":[{"id":"opt_1","text":"Permisi, bolehkah saya memakai pulpen ini?"},{"id":"opt_2","text":"Dilarang memakai pulpen merah di sini."},{"id":"opt_3","text":"Tolong jangan mengambil buku itu."},{"id":"opt_4","text":"Apakah pulpen ini milikmu?"}],"audio_text":"すみません、この ペンを つかっても いいですか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Bentuk-TE + もいいですか dipakai untuk meminta izin.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000230403', 'b0000026-0000-0000-0000-000000002304', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun izin masuk ruangan: "Bolehkah saya masuk ke kamar?"', '{"romaji":"Heya ni haitte mo ii desu ka?","tokens":["へや","に","入っても","いい","ですか"],"target_translation":"Bolehkah masuk kamar?"}'::jsonb, '["へや","に","入っても","いい","ですか"]'::jsonb, NULL, NULL, '入ります (Grup 1) -> 入って + もいいですか.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000230404', 'b0000026-0000-0000-0000-000000002304', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'speaking', 'speaking_repeat', 'Ucapkan permintaan sopan: "ここで たばこを すわないで ください":', '{"romaji":"koko de tabako o suwanaide kudasai","audio_text":"ここで たばこを すわないで ください","display_text":"ここで たばこを すわないで ください"}'::jsonb, '{"expected_transcript":"ここで たばこを すわないで ください"}'::jsonb, NULL, NULL, 'すいます berubah menjadi すわない sebelum でください.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
