INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-230006000007', 'b0000026-0000-0000-0000-000000002304', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Silakan masuk":', '{"romaji":"Douzo ohairi kudasai","tokens":["どうぞ","お入り","ください"],"target_translation":"Silakan masuk"}'::jsonb, '["どうぞ","お入り","ください"]'::jsonb, NULL, NULL, 'Douzo ohairi kudasai.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-230006000008', 'b0000026-0000-0000-0000-000000002304', NULL, 'speaking', 'speaking_repeat', 'Silakan rekan Anda masuk ''どうぞ お入り ください'':', '{"romaji":"douzo ohairi kudasai","audio_text":"どうぞ お入り ください","display_text":"どうぞ お入り ください"}'::jsonb, '{"expected_transcript":"どうぞ お入り ください"}'::jsonb, NULL, NULL, 'Lafalkan douzo ohairi kudasai.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240101', 'b0000026-0000-0000-0000-000000002401', NULL, 'reading', 'fill_blank', 'Review Bentuk-NAI + Kanji Tubuh: pilih Kanji yang berarti "tangan" untuk melengkapi kalimat berikut:', '{"options":["手 (te)","足 (ashi)","目 (me)","耳 (mimi)"],"translation":"Mencuci tangan sebelum kerja.","sentence_template":"しごとの まえに [blank] を あらいます。(tangan)"}'::jsonb, '{"selected":"手 (te)"}'::jsonb, NULL, NULL, '手=tangan, 足=kaki, 目=mata, 耳=telinga, 口=mulut.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240102', 'b0000026-0000-0000-0000-000000002401', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan instruksi dokter menggunakan Bentuk-NAI:', '{"options":[{"id":"opt_1","text":"Hari ini tolong jangan berendam/mandi dulu."},{"id":"opt_2","text":"Besok datang lagi ke rumah sakit."},{"id":"opt_3","text":"Minum obat setelah makan malam."},{"id":"opt_4","text":"Apakah kamu demam tinggi?"}],"audio_text":"きょうは おふろに 入らないで ください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '入らないで ください meminta pasien agar tidak melakukan hal itu.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240103', 'b0000026-0000-0000-0000-000000002401', NULL, 'writing', 'sentence_builder', 'Susun frasa rumah sakit dengan Kanji 病 & 院:', '{"romaji":"Ashita byouin e ikimasu.","tokens":["あした","病院","へ","行きます"],"target_translation":"Besok pergi ke rumah sakit."}'::jsonb, '["あした","病院","へ","行きます"]'::jsonb, NULL, NULL, '病院 (byouin) = rumah sakit.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240001000004', 'b0000026-0000-0000-0000-000000002401', NULL, 'reading', 'fill_blank', 'Kanji 足 (ashi) berarti:', '{"options":["kaki","tangan","mata","kepala"],"sentence_template":"Kanji 足: [blank]"}'::jsonb, '{"selected":"kaki"}'::jsonb, NULL, NULL, 'Kanji 足 berarti kaki (ashi, soku).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240001000005', 'b0000026-0000-0000-0000-000000002401', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Kaki sakit":', '{"romaji":"Ashi ga itai desu","tokens":["足が","痛いです"],"target_translation":"Kaki sakit"}'::jsonb, '["足が","痛いです"]'::jsonb, NULL, NULL, 'Ashi ga itai desu.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240001000006', 'b0000026-0000-0000-0000-000000002401', NULL, 'speaking', 'speaking_repeat', 'Ucapkan keluhan ''足 が 痛い です'':', '{"romaji":"ashi ga itai desu","audio_text":"足 が 痛い です","display_text":"足 が 痛い です"}'::jsonb, '{"expected_transcript":"足 が 痛い です"}'::jsonb, NULL, NULL, 'Lafalkan ashi ga itai desu.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240001000007', 'b0000026-0000-0000-0000-000000002401', NULL, 'writing', 'fill_blank', 'Lengkapi kanji untuk kata "rumah sakit" (びょういん):', '{"options":["病","体","医","手"],"translation":"Rumah sakit","sentence_template":"[blank] 院 (byouin)"}'::jsonb, '{"selected":"病"}'::jsonb, NULL, NULL, 'Rumah sakit ditulis 病院 (byouin).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240001000008', 'b0000026-0000-0000-0000-000000002401', NULL, 'listening', 'listening_choice', 'Dengarkan bagian tubuh yang dikeluhkan:', '{"options":[{"id":"opt_1","text":"Mata saya sakit sejak kemarin."},{"id":"opt_2","text":"Tangan saya sakit sejak kemarin."},{"id":"opt_3","text":"Kaki saya terluka."},{"id":"opt_4","text":"Gigi saya ngilu."}],"audio_text":"昨日から目が痛いです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '目 (me) = mata, 痛い (itai) = sakit.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240201', 'b0000026-0000-0000-0000-000000002402', NULL, 'reading', 'fill_blank', 'Ungkapan sakit di bagian tubuh ("kepala pusing/sakit"): partikel sebelum いたい ialah:', '{"options":["が","を","で","へ"],"translation":"Kepala saya sakit.","sentence_template":"あたま [blank] いたいです。"}'::jsonb, '{"selected":"が"}'::jsonb, NULL, NULL, '[Bagian tubuh] が いたいです dipakai untuk menyampaikan bagian mana yang sakit.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240202', 'b0000026-0000-0000-0000-000000002402', NULL, 'listening', 'listening_choice', 'Dengarkan keluhan pasien masuk angin berikut:', '{"options":[{"id":"opt_1","text":"Sejak kemarin demam dan perut juga sakit."},{"id":"opt_2","text":"Tangan saya sehat dan kuat."},{"id":"opt_3","text":"Rumah sakit buka jam 8 pagi."},{"id":"opt_4","text":"Sudah sembuh dari masuk angin."}],"audio_text":"きのうから ねつが あって、おなかも いたいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'ねつがある = demam; おなかがいたい = sakit perut.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240203', 'b0000026-0000-0000-0000-000000002402', NULL, 'writing', 'sentence_builder', 'Susun kalimat masuk angin: "Sepertinya masuk angin."', '{"romaji":"Kaze o hikimashita.","tokens":["かぜ","を","ひきました"],"target_translation":"Saya kena masuk angin."}'::jsonb, '["かぜ","を","ひきました"]'::jsonb, NULL, NULL, 'Idiom N5: かぜを ひきます = terkena flu/masuk angin.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240002000004', 'b0000026-0000-0000-0000-000000002402', NULL, 'reading', 'fill_blank', 'Pada kata 病院 (byouin = rumah sakit), 病 berarti sakit. Apa makna Kanji 院?', '{"options":["institusi","sakit","obat","dokter"],"sentence_template":"Kanji 院: [blank]"}'::jsonb, '{"selected":"institusi"}'::jsonb, NULL, NULL, '病院 = rumah sakit; 大学院 = pascasarjana.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240002000005', 'b0000026-0000-0000-0000-000000002402', NULL, 'writing', 'sentence_builder', 'Susun huruf menjadi kata "Rumah sakit":', '{"romaji":"Byouin","tokens":["病","院"],"target_translation":"Rumah sakit"}'::jsonb, '["病","院"]'::jsonb, NULL, NULL, '病院.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240002000006', 'b0000026-0000-0000-0000-000000002402', NULL, 'reading', 'fill_blank', 'Pilih keluhan demam panas tinggi dalam bahasa Jepang:', '{"options":["熱","風邪","咳","頭"],"translation":"Ada demam panas","sentence_template":"[blank] があります。(Demam)"}'::jsonb, '{"selected":"熱"}'::jsonb, NULL, NULL, '熱 (netsu) = demam/panas badan.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240002000007', 'b0000026-0000-0000-0000-000000002402', NULL, 'speaking', 'speaking_repeat', 'Ucapkan instruksi meminum obat sesudah makan:', '{"phrase":"食後に薬を飲んでください。","romaji":"Shokugo ni kusuri o nonde kudasai.","audio_text":"食後に薬を飲んでください。","translation":"Tolong minum obat setelah makan.","display_text":"食後に薬を飲んでください。"}'::jsonb, '{"expected_transcript":"食後に薬を飲んでください。"}'::jsonb, NULL, NULL, '食後 (shokugo) = setelah makan, 薬を飲みます = minum obat.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240002000008', 'b0000026-0000-0000-0000-000000002402', NULL, 'writing', 'fill_blank', 'Lengkapi kanji "kaki" (あし):', '{"options":["足","手","口","耳"],"translation":"Kaki sakit","sentence_template":"[blank] が痛いです。(Kaki sakit)"}'::jsonb, '{"selected":"足"}'::jsonb, NULL, NULL, 'Kanji 足 dibaca あし (ashi) yang berarti kaki.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240301', 'b0000026-0000-0000-0000-000000002403', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Kewajiban ("Harus minum obat"): akhiran dari Bentuk-NAI のまない -> のま[blank]:', '{"options":["なければ なりません","なくても いいです","ないで ください","ては いけません"],"translation":"Setiap hari harus minum obat.","sentence_template":"まいにち くすりを のま [blank]。"}'::jsonb, '{"selected":"なければ なりません"}'::jsonb, NULL, NULL, 'Ambil Bentuk-NAI tanpa い akhir + ければなりません = harus.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240302', 'b0000026-0000-0000-0000-000000002403', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'listening', 'listening_choice', 'Dengarkan kalimat ketidakharusan ("tidak usah/boleh tidak"): ', '{"options":[{"id":"opt_1","text":"Karena besok libur, tidak usah bangun pagi."},{"id":"opt_2","text":"Besok dilarang tidur larut malam."},{"id":"opt_3","text":"Harus pergi ke kantor pagi-pagi."},{"id":"opt_4","text":"Bolehkah saya pulang ke rumah?"}],"audio_text":"あしたは やすみですから、早く おきなくても いいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '[Bentuk-NAI tanpa い] + くてもいいです artinya tidak perlu / boleh tidak.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240303', 'b0000026-0000-0000-0000-000000002403', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat aturan lepas sepatu: "Di dalam ruangan harus melepas sepatu."', '{"romaji":"Heya de kutsu o nuganakereba narimasen.","tokens":["へやで","くつを","ぬがなければ","なりません"],"target_translation":"Harus melepas sepatu di kamar."}'::jsonb, '["へやで","くつを","ぬがなければ","なりません"]'::jsonb, NULL, NULL, 'ぬぎます -> ぬがない -> ぬがなければなりません.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240005000004', 'b0000026-0000-0000-0000-000000002403', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Besok harus bangun pagi'':', '{"options":["なければ","なくては","ないと","ないで"],"translation":"Nakereba","sentence_template":"あした はやく おき [blank] なりません"}'::jsonb, '{"selected":"なければ"}'::jsonb, NULL, NULL, 'おきなければ なりません.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240005000005', 'b0000026-0000-0000-0000-000000002403', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Harus bangun cepat":', '{"romaji":"Hayaku okinakereba narimasen","tokens":["早く","起きなければ","なりません"],"target_translation":"Harus bangun cepat"}'::jsonb, '["早く","起きなければ","なりません"]'::jsonb, NULL, NULL, 'Hayaku okinakereba narimasen.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240005000006', 'b0000026-0000-0000-0000-000000002403', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat kewajiban harian ini:', '{"options":[{"id":"opt_1","text":"Besok harus bangun pagi-pagi."},{"id":"opt_2","text":"Besok tidak boleh bangun pagi."},{"id":"opt_3","text":"Besok ingin tidur larut malam."},{"id":"opt_4","text":"Besok saya tidak ada kelas."}],"audio_text":"明日早く起きなければなりません。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '～なければなりません (nakereba narimasen) berarti "harus / wajib".', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240005000007', 'b0000026-0000-0000-0000-000000002403', NULL, 'reading', 'fill_blank', 'Pilih rumus kalimat "tidak perlu / boleh tidak":', '{"options":["行かなくても","行かないで","行かなければ","行かなくて"],"translation":"Hari Minggu tidak perlu pergi ke sekolah.","sentence_template":"日曜日は学校へ [blank] いいです。(Tidak wajib pergi)"}'::jsonb, '{"selected":"行かなくても"}'::jsonb, NULL, NULL, 'Rumus: Bentuk-NAI (buang i) + くてもいいです menyatakan hal yang tidak wajib dilakukan.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240005000008', 'b0000026-0000-0000-0000-000000002403', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat menunjukkan kartu identitas:', '{"phrase":"パスポートを見せなければなりません。","romaji":"Pasupooto o misenakereba narimasen.","audio_text":"パスポートを見せなければなりません。","translation":"Harus menunjukkan paspor.","display_text":"パスポートを見せなければなりません。"}'::jsonb, '{"expected_transcript":"パスポートを見せなければなりません。"}'::jsonb, NULL, NULL, '見せます (misemasu) -> 見せない -> 見せなければなりません.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240401', 'b0000026-0000-0000-0000-000000002404', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'reading', 'fill_blank', 'Kontras てはいけません vs なくてもいいです: "Karena besok tidak ada ujian, tidak usah belajar malam ini":', '{"options":["しなくても いい","しては いけない","しなければ ならない","して ください"],"translation":"Malam ini tidak perlu belajar.","sentence_template":"こんや 勉強 [blank] です。"}'::jsonb, '{"selected":"しなくても いい"}'::jsonb, NULL, NULL, 'します -> Bentuk-NAI しない -> しなくてもいい.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240402', 'b0000026-0000-0000-0000-000000002404', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan dokter & pasien:', '{"options":[{"id":"opt_1","text":"Ada keluhan apa? Tenggorokan sakit dan demam."},{"id":"opt_2","text":"Bolehkah saya minum kopi dingin?"},{"id":"opt_3","text":"Saya tinggal dekat rumah sakit."},{"id":"opt_4","text":"Apakah kamu bawa kartu asuransi?"}],"audio_text":"どうしましたか。ー のどが いたくて、ねつが あります。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'どうしましたか adalah pertanyaan dokter: Ada keluhan apa?', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240403', 'b0000026-0000-0000-0000-000000002404', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat saran klinik: "Karena demam, harus istirahat."', '{"romaji":"Netsu ga arimasu kara, yasumanakereba narimasen.","tokens":["ねつが","ありますから","、","休まなければ","なりません"],"target_translation":"Karena demam, harus istirahat."}'::jsonb, '["ねつが","ありますから","、","休まなければ","なりません"]'::jsonb, NULL, NULL, 'やすみます -> やすまない -> やすまなければなりません.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000240404', 'b0000026-0000-0000-0000-000000002404', NULL, 'speaking', 'speaking_repeat', 'Ucapkan keluhan kesehatanmu: "あたまが いたくて、ねつが あります":', '{"romaji":"atama ga itakute, netsu ga arimasu","audio_text":"あたまが いたくて、ねつが あります","display_text":"あたまが いたくて、ねつが あります"}'::jsonb, '{"expected_transcript":"あたまが いたくて、ねつが あります"}'::jsonb, NULL, NULL, 'Menyambung dua gejala sekaligus memakai bentuk いたくて.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240006000005', 'b0000026-0000-0000-0000-000000002404', NULL, 'reading', 'fill_blank', 'Lengkapi ucapan salam kepada orang sakit ''Semoga lekas sembuh'':', '{"options":["おだいじ","おげんき","よろしく","ありがとう"],"translation":"Odaiji","sentence_template":"どうぞ [blank] に"}'::jsonb, '{"selected":"おだいじ"}'::jsonb, NULL, NULL, 'どうぞ おだいじに.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240006000006', 'b0000026-0000-0000-0000-000000002404', NULL, 'listening', 'listening_choice', 'Dengarkan instruksi minum obat dari apoteker:', '{"options":[{"id":"opt_1","text":"Minumlah 3 kali sehari"},{"id":"opt_2","text":"Minumlah 2 kali sehari"},{"id":"opt_3","text":"Minumlah sebelum tidur"},{"id":"opt_4","text":"Minumlah setelah makan"}],"audio_text":"いちにち に さんかい のんで ください"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'いちにち に さんかい (3 kali sehari) のんで ください.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
