INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-240006000008', 'b0000026-0000-0000-0000-000000002404', NULL, 'speaking', 'speaking_repeat', 'Ucapkan ke rekan yang sakit ''どうぞ お大事に'':', '{"romaji":"douzo odaiji ni","audio_text":"どうぞ お大事に","display_text":"どうぞ お大事に"}'::jsonb, '{"expected_transcript":"どうぞ お大事に"}'::jsonb, NULL, NULL, 'Lafalkan douzo odaiji ni dengan hangat.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250101', 'b0000026-0000-0000-0000-000000002501', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Review Klinik + Sambung Sifat-I: gabungkan 安い (murah) + おいしい (enak):', '{"options":["安くて","安いで","安いと","安かった"],"translation":"Toko itu murah dan enak.","sentence_template":"あの 店は [blank] おいしい です。"}'::jsonb, '{"selected":"安くて"}'::jsonb, NULL, NULL, 'Sifat-I buang い akhir lalu tambah くて (安くて).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250102', 'b0000026-0000-0000-0000-000000002501', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'listening', 'listening_choice', 'Dengarkan gabungan dua Sifat-Na & Nomina:', '{"options":[{"id":"opt_1","text":"Kota ini tenang dan indah."},{"id":"opt_2","text":"Kamar ini mahal tapi sempit."},{"id":"opt_3","text":"Bahasa Jepang sulit tapi seru."},{"id":"opt_4","text":"Dia ramah dan pintar."}],"audio_text":"この まちは しずかで きれいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Sifat-Na & Nomina disambung memakai で (しずかで きれい).', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250103', 'b0000026-0000-0000-0000-000000002501', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'writing', 'sentence_builder', 'Susun kalimat deskripsi dua sifat: "Kamar ini terang dan luas."', '{"romaji":"Kono heya wa akarukute hiroi desu.","tokens":["この","へやは","明るくて","ひろい","です"],"target_translation":"Kamar ini terang dan luas."}'::jsonb, '["この","へやは","明るくて","ひろい","です"]'::jsonb, NULL, NULL, 'あかるい (Sifat-I) -> あかるくて + ひろいです.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250001000004', 'b0000026-0000-0000-0000-000000002501', NULL, 'reading', 'fill_blank', 'Bentuk sambung sifat-I dari あかるい (terang) adalah:', '{"options":["あかるくて","あかるいで","あかるくては","あかるく"],"translation":"Akarukute","sentence_template":"あかるい -> [blank]"}'::jsonb, '{"selected":"あかるくて"}'::jsonb, NULL, NULL, 'あかるくて (terang dan...).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250001000005', 'b0000026-0000-0000-0000-000000002501', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Terang dan luas":', '{"romaji":"Akarukute hiroi","tokens":["明るくて","広い"],"target_translation":"Terang dan luas"}'::jsonb, '["明るくて","広い"]'::jsonb, NULL, NULL, '明るくて 広い.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250001000006', 'b0000026-0000-0000-0000-000000002501', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kondisi kamar ''あかるくて ひろい へや です'':', '{"romaji":"akarukute hiroi heya desu","audio_text":"明るくて 広い 部屋 です","display_text":"明るくて 広い 部屋 です"}'::jsonb, '{"expected_transcript":"明るくて 広い 部屋 です"}'::jsonb, NULL, NULL, 'Lafalkan akarukute hiroi heya desu.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250001000007', 'b0000026-0000-0000-0000-000000002501', NULL, 'writing', 'fill_blank', 'Lengkapi penyambungan dua kata sifat-i (murah dan enak):', '{"options":["くて","いで","て","く"],"translation":"Murah dan lezat.","sentence_template":"安 [blank]、おいしいです。"}'::jsonb, '{"selected":"くて"}'::jsonb, NULL, NULL, 'Kata sifat-i disambung dengan mengganti い terakhir menjadi くて (yasui -> yasukute).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250001000008', 'b0000026-0000-0000-0000-000000002501', NULL, 'listening', 'listening_choice', 'Dengarkan sambungan sifat kota ini:', '{"options":[{"id":"opt_1","text":"Kyoto tenang dan indah."},{"id":"opt_2","text":"Kyoto ramai dan modern."},{"id":"opt_3","text":"Kyoto sepi dan membosankan."},{"id":"opt_4","text":"Kyoto kuno dan sempit."}],"audio_text":"京都は静かで、きれいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Kata sifat-na (静か) disambung dengan menambahkan で (shizuka de, kirei desu).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250201', 'b0000026-0000-0000-0000-000000002502', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'reading', 'fill_blank', 'Pilih sambungan kata benda yang tepat ("Dia adalah pelajar, dan tinggal di Tokyo"):', '{"options":["で","くて","と","に"],"translation":"Ali adalah mahasiswa dan orang Indonesia.","sentence_template":"アリさんは がくせい [blank]、インドネシアじん です。"}'::jsonb, '{"selected":"で"}'::jsonb, NULL, NULL, 'Menyambung predikat nomina menjadi 1 kalimat memakai で (bukan です).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250202', 'b0000026-0000-0000-0000-000000002502', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'listening', 'listening_choice', 'Dengarkan gabungan Sifat-I berlawanan nuansa memakai が:', '{"options":[{"id":"opt_1","text":"Kanjinya sulit, tetapi bahasa Jepang menarik."},{"id":"opt_2","text":"Buku ini baru dan murah sekali."},{"id":"opt_3","text":"Musim panas di Jepang panas dan lembap."},{"id":"opt_4","text":"Apakah kamu suka belajar Kanji?"}],"audio_text":"日本語は かんじが むずかしいですが、おもしろいです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Untuk sifat kontras positif-negatif gunakan [～ですが] ("tetapi").', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250203', 'b0000026-0000-0000-0000-000000002502', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'writing', 'sentence_builder', 'Susun kalimat deskripsi orang: "Guru itu ramah dan ceria."', '{"romaji":"Sensei wa yasashikute genki desu.","tokens":["先生","は","やさしくて","げんき","です"],"target_translation":"Guru itu ramah & ceria."}'::jsonb, '["先生","は","やさしくて","げんき","です"]'::jsonb, NULL, NULL, 'やさしい (Sifat-I) -> やさしくて + げんきです.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250002000004', 'b0000026-0000-0000-0000-000000002502', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Menjadi malam'':', '{"options":["なり","し","き","いき"],"translation":"Nari","sentence_template":"暗く [blank] ました (Menjadi gelap)"}'::jsonb, '{"selected":"なり"}'::jsonb, NULL, NULL, 'くらく なりました = menjadi gelap.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250002000005', 'b0000026-0000-0000-0000-000000002502', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Menjadi gelap":', '{"romaji":"Kuraku narimashita","tokens":["暗く","なりました"],"target_translation":"Menjadi gelap"}'::jsonb, '["暗く","なりました"]'::jsonb, NULL, NULL, 'Kuraku narimashita.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250002000006', 'b0000026-0000-0000-0000-000000002502', NULL, 'reading', 'fill_blank', 'Pilih kata sifat untuk orang yang ramah/baik hati:', '{"options":["親切な","にぎやかな","便利な","有名な"],"translation":"Tanaka adalah orang yang sangat baik hati.","sentence_template":"田中さんはとても [blank] 人です。"}'::jsonb, '{"selected":"親切な"}'::jsonb, NULL, NULL, '親切な (shinsetsu na) berarti baik hati / ramah.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250002000007', 'b0000026-0000-0000-0000-000000002502', NULL, 'speaking', 'speaking_repeat', 'Ucapkan deskripsi kamar yang terang dan luas:', '{"phrase":"この部屋は明るくて広いです。","romaji":"Kono heya wa akarukute hiroi desu.","audio_text":"この部屋は明るくて広いです。","translation":"Kamar ini terang dan luas.","display_text":"この部屋は明るくて広いです。"}'::jsonb, '{"expected_transcript":"この部屋は明るくて広いです。"}'::jsonb, NULL, NULL, '明るい (terang) disambung menjadi 明るくて, lalu diikuti 広い (luas).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250002000008', 'b0000026-0000-0000-0000-000000002502', NULL, 'writing', 'fill_blank', 'Lengkapi kata sifat "mudah digunakan":', '{"options":["便利","元気","上手","暇"],"translation":"Kamus ini praktis dan bagus.","sentence_template":"この辞書は [blank] で、いいです。(Praktis/nyaman)"}'::jsonb, '{"selected":"便利"}'::jsonb, NULL, NULL, '便利 (benri) = praktis/nyaman.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250301', 'b0000026-0000-0000-0000-000000002503', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Perubahan keadaan ("Udara menjadi hangat"): bentuk Sifat-I あたたかい di depan なります adalah:', '{"options":["あたたかく","あたたかに","あたたかくて","あたたかい"],"translation":"Sudah masuk musim semi. Menjadi hangat ya.","sentence_template":"春になりました。[blank] なりましたね。"}'::jsonb, '{"selected":"あたたかく"}'::jsonb, NULL, NULL, 'Sifat-I -> ～くなります; Sifat-Na & Nomina -> ～になります.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250302', 'b0000026-0000-0000-0000-000000002503', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'listening', 'listening_choice', 'Dengarkan perubahan kemampuan dengan Sifat-Na:', '{"options":[{"id":"opt_1","text":"Belajar tiap hari, bhs Jepang menjadi mahir."},{"id":"opt_2","text":"Udara malam hari menjadi dingin."},{"id":"opt_3","text":"Adik ingin menjadi dokter kelak."},{"id":"opt_4","text":"Kamar menjadi bersih setelah dirapikan."}],"audio_text":"まいにち べんきょうして、日本語が じょうずに なりました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'じょうず (Sifat-Na) memakai に なります.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250303', 'b0000026-0000-0000-0000-000000002503', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'writing', 'sentence_builder', 'Susun kalimat perubahan profesi: "Adik laki-laki saya menjadi dokter."', '{"romaji":"Otouto wa isha ni narimashita.","tokens":["おとうと","は","いしゃ","に","なりました"],"target_translation":"Adik saya menjadi dokter."}'::jsonb, '["おとうと","は","いしゃ","に","なりました"]'::jsonb, NULL, NULL, 'Kata benda (いしゃ) menjadi "...menjadi X" dengan に なりました.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250005000004', 'b0000026-0000-0000-0000-000000002503', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Kota ini menjadi ramai'':', '{"options":["に","く","で","な"],"sentence_template":"にぎやか [blank] なりました"}'::jsonb, '{"selected":"に"}'::jsonb, NULL, NULL, 'にぎやか に なりました.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250005000005', 'b0000026-0000-0000-0000-000000002503', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Menjadi ramai":', '{"romaji":"Nigiyaka ni narimashita","tokens":["にぎやかに","なりました"],"target_translation":"Menjadi ramai"}'::jsonb, '["にぎやかに","なりました"]'::jsonb, NULL, NULL, 'Nigiyaka ni narimashita.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250005000006', 'b0000026-0000-0000-0000-000000002503', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat perubahan cuaca:', '{"options":[{"id":"opt_1","text":"Perlahan-lahan sudah menjadi hangat."},{"id":"opt_2","text":"Cuaca tiba-tiba menjadi dingin."},{"id":"opt_3","text":"Besok cuacanya panas."},{"id":"opt_4","text":"Kemarin angin berhembus kencang."}],"audio_text":"だんだん暖かくなりました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '暖かくなります (atatakaku narimasu) menyatakan perubahan status menjadi hangat.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250005000007', 'b0000026-0000-0000-0000-000000002503', NULL, 'reading', 'fill_blank', 'Pilih bentuk perubahan untuk kata sifat-na (pandai/mahir):', '{"options":["上手に","上手く","上手な","上手で"],"translation":"Sudah menjadi mahir bahasa Jepang.","sentence_template":"日本語が [blank] なりました。(Menjadi mahir)"}'::jsonb, '{"selected":"上手に"}'::jsonb, NULL, NULL, 'Kata sifat-na + に + なります (jouzu ni narimasu).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250005000008', 'b0000026-0000-0000-0000-000000002503', NULL, 'speaking', 'speaking_repeat', 'Ucapkan cita-cita profesi masa depan:', '{"phrase":"将来医者になりたいです。","romaji":"Shourai isha ni naritai desu.","audio_text":"将来医者になりたいです。","translation":"Di masa depan saya ingin menjadi dokter.","display_text":"将来医者になりたいです。"}'::jsonb, '{"expected_transcript":"将来医者になりたいです。"}'::jsonb, NULL, NULL, 'Kata benda profesi + になります menyatakan menjadi/berprofesi.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250401', 'b0000026-0000-0000-0000-000000002504', 'eae4f656-7049-4859-b696-ebe9a71c4814', 'reading', 'fill_blank', 'Ujian Tahap 5: pilih perubahan yang benar untuk Sifat-I 暗い ("Kamar menjadi gelap"):', '{"options":["暗く (kuraku)","暗に (kurani)","暗くて (kurakute)","暗い (kurai)"],"translation":"Malam tiba, kamar menjadi gelap.","sentence_template":"よるに なって、へやが [blank] なりました。"}'::jsonb, '{"selected":"暗く (kuraku)"}'::jsonb, NULL, NULL, '暗い berakhiran -い (Sifat-I), sehingga berubah menjadi 暗くなります.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250402', 'b0000026-0000-0000-0000-000000002504', '713b3950-cd77-436e-9e0e-d131b205008e', 'listening', 'listening_choice', 'Dengarkan gabungan izin + alasan sakit Tahap 5:', '{"options":[{"id":"opt_1","text":"Karena sakit perut, bolehkah saya pulang duluan?"},{"id":"opt_2","text":"Besok tidak perlu pergi ke rumah sakit."},{"id":"opt_3","text":"Harus istirahat di kamar tidur."},{"id":"opt_4","text":"Dilarang berbicara keras di klinik."}],"audio_text":"おなかが いたいですから、さきに 帰っても いいですか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Memadukan gejala Unit 24 dengan ～てもいいですか Unit 23.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250403', 'b0000026-0000-0000-0000-000000002504', '2daba56c-c5f5-4d22-b973-6a40dcefc8e3', 'writing', 'sentence_builder', 'Susun kalimat lintas Unit 21-25: "Setelah minum obat, tolong istirahat."', '{"romaji":"Kusuri o nonde kara yasunde kudasai.","tokens":["くすり","を","飲んで","から","休んで","ください"],"target_translation":"Setelah minum obat, tolong istirahat."}'::jsonb, '["くすり","を","飲んで","から","休んで","ください"]'::jsonb, NULL, NULL, 'Menggabungkan 飲んでから dan 休んでください.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000250404', 'b0000026-0000-0000-0000-000000002504', '89ccd0b9-f9ae-4cae-ae1f-c1cd8e00daa9', 'speaking', 'speaking_repeat', 'Ucapkan deskripsi keadaan: "日本語が すこし じょうずに なりました":', '{"romaji":"nihongo ga sukoshi jouzu ni narimashita","audio_text":"日本語が すこし じょうずに なりました","display_text":"日本語が すこし じょうずに なりました"}'::jsonb, '{"expected_transcript":"日本語が すこし じょうずに なりました"}'::jsonb, NULL, NULL, 'Selamat! Kalimat perubahan Sifat-Na + なりました.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250007000005', 'b0000026-0000-0000-0000-000000002504', NULL, 'reading', 'fill_blank', 'Ujian Tahap 5 (Soal 5): Bentuk-TE dari verba かえります (pulang) adalah:', '{"options":["かえって","かえりて","かえんで","かえいて"],"sentence_template":"かえります -> [blank]"}'::jsonb, '{"selected":"かえって"}'::jsonb, NULL, NULL, 'Verba ri -> って: かえって (kaette).', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250007000006', 'b0000026-0000-0000-0000-000000002504', NULL, 'listening', 'listening_choice', 'Ujian Tahap 5 (Soal 6): Dengarkan kewajiban waktu ini:', '{"options":[{"id":"opt_1","text":"Harus pulang paling lambat jam 10"},{"id":"opt_2","text":"Boleh pulang jam 10"},{"id":"opt_3","text":"Tidak perlu pulang jam 10"},{"id":"opt_4","text":"Pulang jam 10 malam kemarin"}],"audio_text":"じゅうじ まで に かえらなければ なりません"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'じゅうじ まで に かえらなければ なりません.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250007000007', 'b0000026-0000-0000-0000-000000002504', NULL, 'writing', 'sentence_builder', 'Ujian Tahap 5 (Soal 7): Susun potongan kata menjadi kalimat "Kamar sempit dan gelap":', '{"romaji":"Kono heya wa semakute kurai desu","tokens":["この部屋は","狭くて","暗いです"],"target_translation":"Kamar sempit dan gelap"}'::jsonb, '["この部屋は","狭くて","暗いです"]'::jsonb, NULL, NULL, 'Kono heya wa semakute kurai desu.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250007000008', 'b0000026-0000-0000-0000-000000002504', NULL, 'reading', 'fill_blank', 'Ujian Tahap 5 (Soal 8): Manakah rumus perubahan keadaan yang benar untuk kata benda?', '{"options":["に","く","で","を"],"sentence_template":"Nomina + [blank] なります"}'::jsonb, '{"selected":"に"}'::jsonb, NULL, NULL, 'Nomina + に なります.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
