INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-250007000010', 'b0000026-0000-0000-0000-000000002504', NULL, 'speaking', 'speaking_repeat', 'Ujian Tahap 5 (Soal 10): Lafalkan kalimat pamungkas Tahap 5 ''まいにち べんきょうして、日本語 が 上手に なりました'':', '{"romaji":"mainichi benkyoushite, nihongo ga jouzu ni narimashita","audio_text":"毎日 勉強して、日本語 が 上手に なりました","display_text":"毎日 勉強して、日本語 が 上手に なりました"}'::jsonb, '{"expected_transcript":"毎日 勉強して、日本語 が 上手に なりました"}'::jsonb, NULL, NULL, 'Lafalkan kalimat pamungkas Tahap 5 dengan intonasi sempurna.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000260401', 'b0000026-0000-0000-0000-000000002604', '713b3950-cd77-436e-9e0e-d131b205008e', 'reading', 'fill_blank', 'Kontras ～ました vs ～たことがある: menyatakan pengalaman hidup ("Saya pernah mendaki Gunung Fuji"):', '{"options":["のぼった ことが あります","のぼりました ことが あります","のぼって ことが あります","のぼる ことが あります"],"translation":"Saya pernah mendaki Gunung Fuji.","sentence_template":"わたしは 富士山に [blank]。"}'::jsonb, '{"selected":"のぼった ことが あります"}'::jsonb, NULL, NULL, 'Pengalaman hidup memakai [Bentuk-TA] + ことがあります.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000260402', 'b0000026-0000-0000-0000-000000002604', '713b3950-cd77-436e-9e0e-d131b205008e', 'listening', 'listening_choice', 'Dengarkan cerita akhir pekan dengan pola ～たり～たりします:', '{"options":[{"id":"opt_1","text":"Hari Minggu membaca buku, menonton film, dll."},{"id":"opt_2","text":"Setiap hari saya pergi bekerja ke kota."},{"id":"opt_3","text":"Saya belum pernah pergi ke Kyoto."},{"id":"opt_4","text":"Setelah makan saya tidur jam 10."}],"audio_text":"にちよう日は 本を 読んだり、えいがを 見たり しました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '～たり ～たり しました menyebutkan contoh kegiatan tidak berurutan.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000260403', 'b0000026-0000-0000-0000-000000002604', '713b3950-cd77-436e-9e0e-d131b205008e', 'writing', 'sentence_builder', 'Susun kalimat urutan lampau: "Setelah bekerja, bertemu teman."', '{"romaji":"Shigoto ga owatta ato de, tomodachi ni aimashita.","tokens":["仕事が","終わった","あとで","、","友だちに","会いました"],"target_translation":"Setelah selesai kerja, bertemu teman."}'::jsonb, '["仕事が","終わった","あとで","、","友だちに","会いました"]'::jsonb, NULL, NULL, '[Bentuk-TA] + あとで menyatakan setelah kejadian selesai.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000260404', 'b0000026-0000-0000-0000-000000002604', '713b3950-cd77-436e-9e0e-d131b205008e', 'speaking', 'speaking_repeat', 'Ucapkan pengalaman wisata: "日本へ 行った ことが あります" (Saya pernah pergi ke Jepang):', '{"romaji":"Nihon e itta koto ga arimasu","audio_text":"日本へ 行った ことが あります","display_text":"日本へ 行った ことが あります"}'::jsonb, '{"expected_transcript":"日本へ 行った ことが あります"}'::jsonb, NULL, NULL, '行った berasal dari 行って -> tukar て menjadi た.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260006000005', 'b0000026-0000-0000-0000-000000002604', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat cerita akhir pekan ''Bermain dengan teman, nonton TV, dll'':', '{"options":["だり・たり","たり・たり","て・て","たら・たら"],"translation":"Dari... tari","sentence_template":"あそん [blank]、テレビ を み [blank] しました"}'::jsonb, '{"selected":"だり・たり"}'::jsonb, NULL, NULL, 'あそびます (b) -> あそんだり; みます -> みたり しました.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260006000006', 'b0000026-0000-0000-0000-000000002604', NULL, 'listening', 'listening_choice', 'Dengarkan cerita liburan musim panas:', '{"options":[{"id":"opt_1","text":"Pergi ke laut, mendaki gunung, dan lain-lain"},{"id":"opt_2","text":"Hanya pergi ke pantai"},{"id":"opt_3","text":"Tidur di rumah saja"},{"id":"opt_4","text":"Pergi ke luar negeri"}],"audio_text":"うみ へ いったり、やま に のぼったり しました"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'うみ へ いったり、やま に のぼったり しました.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260006000007', 'b0000026-0000-0000-0000-000000002604', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Ke pantai dan gunung":', '{"romaji":"Umi e ittari yama e nobottari shimashita","tokens":["海へ行ったり","山へ登ったり","しました"],"target_translation":"Ke pantai dan gunung"}'::jsonb, '["海へ行ったり","山へ登ったり","しました"]'::jsonb, NULL, NULL, 'Umi e ittari yama e nobottari shimashita.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260006000008', 'b0000026-0000-0000-0000-000000002604', NULL, 'speaking', 'speaking_repeat', 'Ucapkan cerita liburan ''海 へ 行ったり しました'':', '{"romaji":"umi e ittari shimashita","audio_text":"海 へ 行ったり しました","display_text":"海 へ 行ったり しました"}'::jsonb, '{"expected_transcript":"海 へ 行ったり しました"}'::jsonb, NULL, NULL, 'Lafalkan umi e ittari shimashita.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000270201', 'b0000026-0000-0000-0000-000000002702', NULL, 'reading', 'fill_blank', 'Nominalisasi Hobi: "Hobi saya adalah menonton film" memakai pola [Kamus] こと:', '{"options":["見ること です","見たこと です","見ますこと です","見てこと です"],"translation":"Hobi saya adalah menonton film.","sentence_template":"わたしの しゅみは えいがを [blank]。"}'::jsonb, '{"selected":"見ること です"}'::jsonb, NULL, NULL, '[Bentuk Kamus] + ことです digunakan untuk menyatakan hobi.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000270202', 'b0000026-0000-0000-0000-000000002702', NULL, 'listening', 'listening_choice', 'Dengarkan kemampuan menggunakan Bentuk Kamus + ことができます:', '{"options":[{"id":"opt_1","text":"Saya bisa menulis Hiragana dan Katakana."},{"id":"opt_2","text":"Saya belum bisa membaca Kanji sulit."},{"id":"opt_3","text":"Saya pernah belajar di Tokyo."},{"id":"opt_4","text":"Sebelum tidur saya mendengar lagu."}],"audio_text":"わたしは ひらがなと カタカナを 書くことが できます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '書く (Kamus dari 書きます) + ことができます = dapat menulis.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000270203', 'b0000026-0000-0000-0000-000000002702', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Saya suka berenang.":', '{"romaji":"Watashi wa oyogu no ga suki desu.","tokens":["わたし","は","およぐ","の","が","好き","です"],"target_translation":"Saya suka berenang."}'::jsonb, '["わたし","は","およぐ","の","が","好き","です"]'::jsonb, NULL, NULL, 'およぎます -> Bentuk Kamus およぐ + のが好きです.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270002000004', 'b0000026-0000-0000-0000-000000002702', NULL, 'reading', 'fill_blank', 'Lengkapi hobi ''Hobi saya adalah mengambil foto'':', '{"options":["とる","とります","とった","とり"],"translation":"Toru","sentence_template":"しゃしん を [blank] こと です"}'::jsonb, '{"selected":"とる"}'::jsonb, NULL, NULL, 'とる こと です (bentuk kamus).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270002000005', 'b0000026-0000-0000-0000-000000002702', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Hobi memotret":', '{"romaji":"Shashin o toru koto desu","tokens":["写真を","撮る","ことです"],"target_translation":"Hobi memotret"}'::jsonb, '["写真を","撮る","ことです"]'::jsonb, NULL, NULL, 'Shashin o toru koto desu.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270002000006', 'b0000026-0000-0000-0000-000000002702', NULL, 'reading', 'fill_blank', 'Pilih bentuk verba sebelum ことができます (dapat/mampu):', '{"options":["読む","読み","読んだ","読ま"],"translation":"Bisa membaca kanji.","sentence_template":"漢字を [blank] ことができます。(Bisa membaca)"}'::jsonb, '{"selected":"読む"}'::jsonb, NULL, NULL, 'Rumus: Bentuk Kamus (Jishokei) + ことができます menyatakan kemampuan/bisa.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270002000007', 'b0000026-0000-0000-0000-000000002702', NULL, 'listening', 'listening_choice', 'Dengarkan hobi yang diucapkan pembicara:', '{"options":[{"id":"opt_1","text":"Hobi saya adalah memotret foto."},{"id":"opt_2","text":"Hobi saya adalah menggambar lukisan."},{"id":"opt_3","text":"Hobi saya adalah jalan-jalan ke gunung."},{"id":"opt_4","text":"Hobi saya adalah mendengarkan lagu."}],"audio_text":"私の趣味は写真を撮ることです。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '写真を撮ること (shashin o toru koto) = hal memotret foto.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270002000008', 'b0000026-0000-0000-0000-000000002702', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kemampuan berenang 100 meter:', '{"phrase":"百メートル泳ぐことができます。","romaji":"Hyaku meetoru oyogu koto ga dekimasu.","audio_text":"百メートル泳ぐことができます。","translation":"Saya bisa berenang 100 meter.","display_text":"百メートル泳ぐことができます。"}'::jsonb, '{"expected_transcript":"百メートル泳ぐことができます。"}'::jsonb, NULL, NULL, '泳ぐ (oyogu) = berenang (bentuk kamus).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000270301', 'b0000026-0000-0000-0000-000000002703', NULL, 'reading', 'fill_blank', 'Di depan kata まえに ("sebelum ..."), verba WAJIB memakai Bentuk Kamus:', '{"options":["食べる (Kamus)","食べた (Lampau)","食べて (Bentuk-TE)","食べます (Sopan)"],"translation":"Sebelum makan, mencuci tangan.","sentence_template":"[blank] まえに、手を あらいます。"}'::jsonb, '{"selected":"食べる (Kamus)"}'::jsonb, NULL, NULL, 'Aturan wajib: [Bentuk Kamus] まえに; berlawanan dengan [Bentuk-TA] あとで.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000270302', 'b0000026-0000-0000-0000-000000002703', NULL, 'listening', 'listening_choice', 'Dengarkan klausa waktu とき ("ketika/saat") berikut:', '{"options":[{"id":"opt_1","text":"Ketika sudah tiba di Jepang, saya mendapat teman."},{"id":"opt_2","text":"Sebelum pergi ke Jepang, membeli tiket."},{"id":"opt_3","text":"Saya bisa berbahasa Jepang sedikit."},{"id":"opt_4","text":"Apakah kamu punya hobi membaca?"}],"audio_text":"日本へ 来た とき、友だちが できました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '来た とき menandai kondisi setelah tiba di lokasi.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000270303', 'b0000026-0000-0000-0000-000000002703', NULL, 'writing', 'sentence_builder', 'Susun kalimat sebelum tidur: "Sebelum tidur, menggosok gigi."', '{"romaji":"Neru mae ni, ha o migakimasu.","tokens":["ねる","まえに","、","はを","みがきます"],"target_translation":"Sebelum tidur, gosok gigi."}'::jsonb, '["ねる","まえに","、","はを","みがきます"]'::jsonb, NULL, NULL, 'ねます (Grup 2) -> Kamus ねる + まえに.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270005000004', 'b0000026-0000-0000-0000-000000002703', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Sebelum pulang, menelepon'':', '{"options":["まえに","あとで","ときに","から"],"translation":"Maeni","sentence_template":"うち へ かえる [blank]、でんわ を かけます"}'::jsonb, '{"selected":"まえに"}'::jsonb, NULL, NULL, 'かえる まえに (sebelum pulang).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270005000005', 'b0000026-0000-0000-0000-000000002703', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Sebelum pulang menelepon":', '{"romaji":"Kaeru mae ni denwashimasu","tokens":["帰るまえに","電話します"],"target_translation":"Sebelum pulang menelepon"}'::jsonb, '["帰るまえに","電話します"]'::jsonb, NULL, NULL, 'Kaeru mae ni denwashimasu.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270005000006', 'b0000026-0000-0000-0000-000000002703', NULL, 'writing', 'fill_blank', 'Pilih bentuk kalimat sebelum makan (cuci tangan):', '{"options":["食べる","食べた","食べ","食べない"],"translation":"Sebelum makan, mencuci tangan.","sentence_template":"ご飯を [blank] まえに、手を洗います。"}'::jsonb, '{"selected":"食べる"}'::jsonb, NULL, NULL, 'Sebelum まえに, kata kerja selalu dalam Bentuk Kamus dasar.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270005000007', 'b0000026-0000-0000-0000-000000002703', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat alasan sebab-akibat (から) ini dan pilih arti yang tepat:', '{"options":[{"id":"opt_1","text":"Karena tidak ada waktu, saya pergi naik taksi."},{"id":"opt_2","text":"Ketika ada waktu, saya naik bus."},{"id":"opt_3","text":"Sebelum pergi, saya cek jam."},{"id":"opt_4","text":"Waktu di stasiun sangat sempit."}],"audio_text":"時間がありませんから、タクシーで行きます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'から menandai alasan logis.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270005000008', 'b0000026-0000-0000-0000-000000002703', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat ketika sakit minum obat:', '{"phrase":"頭が痛いとき、この薬を飲みます。","romaji":"Atama ga itai toki, kono kusuri o nomimasu.","audio_text":"頭が痛いとき、この薬を飲みます。","translation":"Ketika kepala sakit, saya minum obat ini.","display_text":"頭が痛いとき、この薬を飲みます。"}'::jsonb, '{"expected_transcript":"頭が痛いとき、この薬を飲みます。"}'::jsonb, NULL, NULL, 'Kata sifat-i + とき menyatakan "pada saat/ketika kondisi tersebut".', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000270401', 'b0000026-0000-0000-0000-000000002704', NULL, 'reading', 'fill_blank', 'Kontras まえに vs あとで: "Sesudah belajar (べんきょうした), minum kopi":', '{"options":["あとで","まえに","とき","から"],"translation":"Sesudah belajar, minum kopi.","sentence_template":"勉強した [blank]、コーヒーを 飲みました。"}'::jsonb, '{"selected":"あとで"}'::jsonb, NULL, NULL, 'Di depan あとで memakai Bentuk-TA (勉強した).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000270402', 'b0000026-0000-0000-0000-000000002704', NULL, 'listening', 'listening_choice', 'Dengarkan klausa kemampuan + kuantitas Kanji:', '{"options":[{"id":"opt_1","text":"Saya bisa menulis sekitar 100 Kanji."},{"id":"opt_2","text":"Saya ingin pergi ke toko buku."},{"id":"opt_3","text":"Sebelum tidur saya menulis catatan."},{"id":"opt_4","text":"Apakah kamu suka bermain piano?"}],"audio_text":"わたしは かんじを 百くらい 書くことが できます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '[Bentuk Kamus] ことができます menyatakan kecakapan/kemampuan.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000270403', 'b0000026-0000-0000-0000-000000002704', NULL, 'writing', 'sentence_builder', 'Susun kalimat kemampuan bahasa: "Saya bisa berbicara sedikit bahasa Jepang."', '{"romaji":"Nihongo o sukoshi hanasu koto ga dekimasu.","tokens":["日本語","を","すこし","はなす","ことが","できます"],"target_translation":"Bisa bicara bhs Jepang sedikit."}'::jsonb, '["日本語","を","すこし","はなす","ことが","できます"]'::jsonb, NULL, NULL, 'はなします -> Bentuk Kamus はなす + ことができます.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000270404', 'b0000026-0000-0000-0000-000000002704', NULL, 'speaking', 'speaking_repeat', 'Ucapkan hobi & kemampuanmu: "ピアノを ひくことが できます" (Saya bisa main piano):', '{"romaji":"piano o hiku koto ga dekimasu","audio_text":"ピアノを ひくことが できます","display_text":"ピアノを ひくことが できます"}'::jsonb, '{"expected_transcript":"ピアノを ひくことが できます"}'::jsonb, NULL, NULL, 'Latih gabungan Bentuk Kamus ひく dengan ことができます.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270006000005', 'b0000026-0000-0000-0000-000000002704', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Saat anak-anak, tinggal di Osaka'':', '{"options":["とき","まえに","あとで","から"],"translation":"Toki","sentence_template":"こどもの [blank]、大阪 に 住んでいました"}'::jsonb, '{"selected":"とき"}'::jsonb, NULL, NULL, 'こどもの とき (saat anak-anak).', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270006000006', 'b0000026-0000-0000-0000-000000002704', NULL, 'listening', 'listening_choice', 'Dengarkan situasi waktu muda ini:', '{"options":[{"id":"opt_1","text":"Saat masih muda, sering bepergian wisata"},{"id":"opt_2","text":"Saat muda tidak pernah liburan"},{"id":"opt_3","text":"Ingin bepergian sekarang"},{"id":"opt_4","text":"Jepang sangat indah"}],"audio_text":"わかい とき、よく りょこう を しました"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'わかい とき (ketika masih muda) よく りょこう を しました.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270006000007', 'b0000026-0000-0000-0000-000000002704', NULL, 'writing', 'sentence_builder', 'Susun kalimat bahasa Jepang untuk "Saat senggang dengar musik":', '{"romaji":"Himana toki ongaku o kikimasu","tokens":["暇なとき","音楽を","聞きます"],"target_translation":"Saat senggang dengar musik"}'::jsonb, '["暇なとき","音楽を","聞きます"]'::jsonb, NULL, NULL, 'Himana toki ongaku o kikimasu.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-270006000008', 'b0000026-0000-0000-0000-000000002704', NULL, 'speaking', 'speaking_repeat', 'Ucapkan hobi saat luang ''暇な とき、本 を 読みます'':', '{"romaji":"himana toki, hon o yomimasu","audio_text":"暇な とき、本 を 読みます","display_text":"暇な とき、本 を 読みます"}'::jsonb, '{"expected_transcript":"暇な とき、本 を 読みます"}'::jsonb, NULL, NULL, 'Lafalkan himana toki, hon o yomimasu.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280101', 'b0000026-0000-0000-0000-000000002801', NULL, 'reading', 'fill_blank', 'Review Bentuk Kamus + Gaya Biasa: sebelum と思います, nomina & Sifat-Na memakai kopula:', '{"options":["だ","です","に","を"],"translation":"Saya kira besok hujan.","sentence_template":"あしたは 雨 [blank] と思います。"}'::jsonb, '{"selected":"だ"}'::jsonb, NULL, NULL, 'Nomina & Sifat-Na wajib memakai Bentuk Biasa だ sebelum と思います.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280102', 'b0000026-0000-0000-0000-000000002801', NULL, 'listening', 'listening_choice', 'Dengarkan contoh percakapan akrab kasual antar sahabat:', '{"options":[{"id":"opt_1","text":"Besok datang ke rumahku? - Iya, aku datang."},{"id":"opt_2","text":"Besok Anda mau pergi ke mana?"},{"id":"opt_3","text":"Saya tidak bisa pergi besok."},{"id":"opt_4","text":"Apakah kemarin hujan turun?"}],"audio_text":"あした うちに 来る？ ー うん、行くよ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Gaya kasual memakai Bentuk Kamus (来る?/行く) dan うん/ううん.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280103', 'b0000026-0000-0000-0000-000000002801', NULL, 'writing', 'sentence_builder', 'Susun kalimat opini: "Saya rasa film ini menarik."', '{"romaji":"Kono eiga wa omoshiroi to omoimasu.","tokens":["この","えいが","は","おもしろい","と","思います"],"target_translation":"Saya rasa film ini menarik."}'::jsonb, '["この","えいが","は","おもしろい","と","思います"]'::jsonb, NULL, NULL, 'Sifat-I kasual langsung buang です sebelum と思います.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280001000004', 'b0000026-0000-0000-0000-000000002801', NULL, 'reading', 'fill_blank', 'Bentuk kasual dari verba 食べません (tidak makan) adalah:', '{"options":["たべない","たべる","たべた","たべなかった"],"translation":"Tabenai","sentence_template":"たべません -> [blank]"}'::jsonb, '{"selected":"たべない"}'::jsonb, NULL, NULL, 'Kasual negatif = 形-NAI: 食べない.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280001000005', 'b0000026-0000-0000-0000-000000002801', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Makan ini?":', '{"romaji":"Kore taberu?","tokens":["これ","食べる？"],"target_translation":"Makan ini?"}'::jsonb, '["これ","食べる？"]'::jsonb, NULL, NULL, 'Kore taberu?', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280001000006', 'b0000026-0000-0000-0000-000000002801', NULL, 'speaking', 'speaking_repeat', 'Ucapkan obrolan kasual ''これ おいしい ね'':', '{"romaji":"kore oishii ne","audio_text":"これ おいしい ね","display_text":"これ おいしい ね"}'::jsonb, '{"expected_transcript":"これ おいしい ね"}'::jsonb, NULL, NULL, 'Lafalkan kore oishii ne secara akrab.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280001000007', 'b0000026-0000-0000-0000-000000002801', NULL, 'reading', 'fill_blank', 'Pilih padanan gaya kasual dari 食べません (tidak makan):', '{"options":["食べない","食べる","食べた","食べなかった"],"translation":"Bentuk biasa negatif makan","sentence_template":"食べません (sopan) -> [blank] (kasual)"}'::jsonb, '{"selected":"食べない"}'::jsonb, NULL, NULL, 'Gaya kasual (Futsuukei) negatif sekarang adalah bentuk-NAI (tabenai).', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280001000008', 'b0000026-0000-0000-0000-000000002801', NULL, 'writing', 'fill_blank', 'Lengkapi bentuk lampau kasual dari 行きました (telah pergi):', '{"options":["行った","行く","行かない","行くだ"],"translation":"Bentuk lampau kasual pergi","sentence_template":"行きました -> [blank]"}'::jsonb, '{"selected":"行った"}'::jsonb, NULL, NULL, 'Bentuk lampau kasual verba adalah Bentuk-TA (itta).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280201', 'b0000026-0000-0000-0000-000000002802', NULL, 'reading', 'fill_blank', 'Mana bentuk lampau negatif kasual yang benar untuk "tidak pergi" (行きませんでした)?', '{"options":["行かなかった","行きなかった","行かない","行かなかっただ"],"translation":"Dia berkata kemarin tidak pergi ke mana pun.","sentence_template":"きのう どこへも [blank] と 言いました。"}'::jsonb, '{"selected":"行かなかった"}'::jsonb, NULL, NULL, 'Negatif biasa 行かない diubah lampau menjadi 行かなかった.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280202', 'b0000026-0000-0000-0000-000000002802', NULL, 'listening', 'listening_choice', 'Dengarkan kutipan tidak langsung (～と言いました):', '{"options":[{"id":"opt_1","text":"Tanaka berkata kemarin ia pergi ke Tokyo."},{"id":"opt_2","text":"Tanaka bertanya jalan ke stasiun."},{"id":"opt_3","text":"Saya kira Tanaka tinggal di Tokyo."},{"id":"opt_4","text":"Apakah kamu akan pergi ke Kyoto?"}],"audio_text":"田中さんは きのう 東京へ 行った と言いました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Mengutip ucapan orang memakai [Bentuk Biasa] と言いました.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280203', 'b0000026-0000-0000-0000-000000002802', NULL, 'writing', 'sentence_builder', 'Susun kalimat opini Sifat-Na: "Saya kira Tokyo ramai."', '{"romaji":"Toukyou wa nigiyaka da to omoimasu.","tokens":["東京","は","にぎやか","だ","と思います"],"target_translation":"Saya rasa Tokyo ramai."}'::jsonb, '["東京","は","にぎやか","だ","と思います"]'::jsonb, NULL, NULL, 'Sifat-Na にぎやか wajib memakai だ tepat sebelum と思います.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280002000004', 'b0000026-0000-0000-0000-000000002802', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ''Buku yang dibeli kemarin'':', '{"options":["かった","かいます","かう","かって"],"translation":"Katta","sentence_template":"きのう [blank] ほん"}'::jsonb, '{"selected":"かった"}'::jsonb, NULL, NULL, 'きのう 買った 本 (buku yang dibeli kemarin).', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280002000005', 'b0000026-0000-0000-0000-000000002802', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Buku yang dibeli kemarin":', '{"romaji":"Kinou katta hon","tokens":["昨日","買った","本"],"target_translation":"Buku yang dibeli kemarin"}'::jsonb, '["昨日","買った","本"]'::jsonb, NULL, NULL, '昨日 買った 本.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280002000006', 'b0000026-0000-0000-0000-000000002802', NULL, 'listening', 'listening_choice', 'Dengarkan opini pembicara mengenai harga barang:', '{"options":[{"id":"opt_1","text":"Saya rasa harga barang di Jepang mahal."},{"id":"opt_2","text":"Saya rasa Jepang sangat aman."},{"id":"opt_3","text":"Saya rasa orang Jepang sangat sibuk."},{"id":"opt_4","text":"Harga barang di toko itu murah."}],"audio_text":"日本は物価が高いと思います。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '～と思います (to omoimasu) menyatakan pendapat/opini pribadi.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280002000007', 'b0000026-0000-0000-0000-000000002802', NULL, 'reading', 'fill_blank', 'Pilih kalimat kutipan langsung perkataan dokter:', '{"options":["休んで","休み","休む","休んだ"],"translation":"Dokter berkata \"Besok tolong istirahat.\"","sentence_template":"医者は「明日 [blank] ください」と言いました。"}'::jsonb, '{"selected":"休んで"}'::jsonb, NULL, NULL, 'Dalam tanda kurung siku 「」 dapat berupa kalimat perintah/sopan apa adanya.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280002000008', 'b0000026-0000-0000-0000-000000002802', NULL, 'speaking', 'speaking_repeat', 'Ucapkan opini mengenai cuaca esok hari:', '{"phrase":"明日は雨が降ると思います。","romaji":"Ashita wa ame ga furu to omoimasu.","audio_text":"明日は雨が降ると思います。","translation":"Saya rasa besok akan turun hujan.","display_text":"明日は雨が降ると思います。"}'::jsonb, '{"expected_transcript":"明日は雨が降ると思います。"}'::jsonb, NULL, NULL, 'Sebelum と思います gunakan bentuk biasa kasual (furu).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280301', 'b0000026-0000-0000-0000-000000002803', NULL, 'reading', 'fill_blank', 'Bentuk yang BENAR pada anak kalimat penjelas benda ("Kue yang dibuat Ibu"):', '{"options":["作った (普通形)","作りました (です/ます)","作って","作ります"],"translation":"Ini kue yang dibuat Ibu.","sentence_template":"これは 母が [blank] ケーキ です。"}'::jsonb, '{"selected":"作った (普通形)"}'::jsonb, NULL, NULL, 'Predikat anak kalimat sebelum kata benda WAJIB memakai Gaya Kasual (普通形) + subjeknya pakai が.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280302', 'b0000026-0000-0000-0000-000000002803', NULL, 'listening', 'listening_choice', 'Dengarkan cara menggambarkan seseorang dengan anak kalimat penjelas:', '{"options":[{"id":"opt_1","text":"Orang yang sedang memakai kacamata adalah Sato."},{"id":"opt_2","text":"Kacamata ini milik Tuan Sato."},{"id":"opt_3","text":"Saya pergi ke dokter mata bersama Sato."},{"id":"opt_4","text":"Apakah Sato suka kopi hitam?"}],"audio_text":"めがねを かけている 人は 佐藤さん です。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '"めがねを かけている" menerangkan kata benda "人".', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280303', 'b0000026-0000-0000-0000-000000002803', NULL, 'writing', 'sentence_builder', 'Susun frasa anak kalimat benda: "Buku yang kubeli kemarin mahal."', '{"romaji":"Kinou katta hon wa takakatta desu.","tokens":["きのう","買った","本","は","高かった","です"],"target_translation":"Buku yg kubeli kemarin mahal."}'::jsonb, '["きのう","買った","本","は","高かった","です"]'::jsonb, NULL, NULL, 'きのう買った menerangkan 本 sebagai topik utama kalimat.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280005000004', 'b0000026-0000-0000-0000-000000002803', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat opini ''Saya rasa Tanaka tidak akan datang'':', '{"options":["と","を","に","が"],"sentence_template":"たなかさん は こない [blank] おもいます"}'::jsonb, '{"selected":"と"}'::jsonb, NULL, NULL, 'こない と おもいます.', 4, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280005000005', 'b0000026-0000-0000-0000-000000002803', NULL, 'writing', 'sentence_builder', 'Susun potongan kata menjadi kalimat "Saya rasa tidak datang":', '{"romaji":"Konai to omoimasu","tokens":["来ないと","思います"],"target_translation":"Saya rasa tidak datang"}'::jsonb, '["来ないと","思います"]'::jsonb, NULL, NULL, 'Konai to omoimasu.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280005000006', 'b0000026-0000-0000-0000-000000002803', NULL, 'writing', 'fill_blank', 'Lengkapi frasa benda penjelas "kue yang dibuat ibu":', '{"options":["作った","作ります","作って","作ろう"],"translation":"Kue yang dibuat oleh ibu enak.","sentence_template":"母が [blank] ケーキはおいしいです。"}'::jsonb, '{"selected":"作った"}'::jsonb, NULL, NULL, 'Klausul yang memodifikasi kata benda menggunakan bentuk biasa/kasual (tsukutta keeki).', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280005000007', 'b0000026-0000-0000-0000-000000002803', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat penjelas orang berikut:', '{"options":[{"id":"opt_1","text":"Siapakah orang yang sedang membaca buku di sana itu?"},{"id":"opt_2","text":"Siapakah orang yang berdiri di dekat pintu?"},{"id":"opt_3","text":"Apakah kamu mengenal guru itu?"},{"id":"opt_4","text":"Buku apa yang sedang kamu baca?"}],"audio_text":"あそこで本を読んでいる人は誰ですか。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'あそこで本を読んでいる人 = orang yang sedang membaca buku di sebelah sana.', 7, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280005000008', 'b0000026-0000-0000-0000-000000002803', NULL, 'speaking', 'speaking_repeat', 'Ucapkan kalimat menjelaskan tempat yang ingin dikunjungi:', '{"phrase":"私が行きたい所は京都です。","romaji":"Watashi ga ikitai tokoro wa Kyouto desu.","audio_text":"私が行きたい所は京都です。","translation":"Tempat yang ingin saya kunjungi adalah Kyoto.","display_text":"私が行きたい所は京都です。"}'::jsonb, '{"expected_transcript":"私が行きたい所は京都です。"}'::jsonb, NULL, NULL, '行きたい所 (ikitai tokoro) = tempat yang ingin dikunjungi.', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280401', 'b0000026-0000-0000-0000-000000002804', NULL, 'reading', 'fill_blank', 'Ujian Tahap 6: "Kota tempat saya tinggal (watashi ga sunde iru)" yang tepat adalah:', '{"options":["が","は","を","で"],"translation":"Ini kota tempat saya tinggal.","sentence_template":"これは わたし [blank] 住んでいる まち です。"}'::jsonb, '{"selected":"が"}'::jsonb, NULL, NULL, 'Subjek di dalam anak kalimat penjelas benda ditandai memakai が (atau の), bukan は.', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280402', 'b0000026-0000-0000-0000-000000002804', NULL, 'listening', 'listening_choice', 'Dengarkan kalimat gabungan Kamus + Anak Kalimat Tahap 6:', '{"options":[{"id":"opt_1","text":"Sebelum pergi ke Jepang, kupinjamkan buku yg kubaca."},{"id":"opt_2","text":"Sesudah dari Jepang, saya menulis cerita."},{"id":"opt_3","text":"Saya kira Jepang negara yang nyaman."},{"id":"opt_4","text":"Apakah kamu pernah baca buku itu?"}],"audio_text":"にほんへ 行く まえに、わたしが 読んだ 本を かします。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menggabungkan 行くまえに dan anak kalimat わたしが読んだ本.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280403', 'b0000026-0000-0000-0000-000000002804', NULL, 'writing', 'sentence_builder', 'Susun kalimat opini & perbandingan Tahap 6: "Saya kira Tokyo lebih ramai dari Kyoto."', '{"romaji":"Toukyou wa Kyouto yori nigiyaka da to omoimasu.","tokens":["東京","は","京都","より","にぎやか","だ","と思います"],"target_translation":"Saya rasa Tokyo lebih ramai dr Kyoto."}'::jsonb, '["東京","は","京都","より","にぎやか","だ","と思います"]'::jsonb, NULL, NULL, 'Perpaduan perbandingan より dengan Gaya Biasa + と思います.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000280404', 'b0000026-0000-0000-0000-000000002804', NULL, 'speaking', 'speaking_repeat', 'Ucapkan pendapatmu: "日本語は とても おもしろい と思います":', '{"romaji":"nihongo wa totemo omoshiroi to omoimasu","audio_text":"日本語は とても おもしろい と思います","display_text":"日本語は とても おもしろい と思います"}'::jsonb, '{"expected_transcript":"日本語は とても おもしろい と思います"}'::jsonb, NULL, NULL, 'Jangan menyelipkan です sebelum と思います!', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280007000005', 'b0000026-0000-0000-0000-000000002804', NULL, 'reading', 'fill_blank', 'Ujian Tahap 6 (Soal 5): Bentuk kasual lampau dari verba 行きました (sudah pergi) adalah:', '{"options":["いった","いく","いかない","いかなかった"],"sentence_template":"いきました -> [blank]"}'::jsonb, '{"selected":"いった"}'::jsonb, NULL, NULL, 'Bentuk kasual lampau afirmatif = 形-TA: 行った (itta).', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280007000006', 'b0000026-0000-0000-0000-000000002804', NULL, 'listening', 'listening_choice', 'Ujian Tahap 6 (Soal 6): Dengarkan kutipan berita ini:', '{"options":[{"id":"opt_1","text":"Tadi dikatakan bahwa besok akan hujan"},{"id":"opt_2","text":"Besok tidak akan hujan"},{"id":"opt_3","text":"Kemarin hujan deras"},{"id":"opt_4","text":"Kapan hujan akan berhenti?"}],"audio_text":"あした は あめ だ と いいました"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'あめ だ と いいました.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
