INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280007000008', 'b0000026-0000-0000-0000-000000002804', NULL, 'reading', 'fill_blank', 'Ujian Tahap 6 (Soal 8): Dalam gaya kasual afirmatif masa kini, kata benda 学生 です berubah menjadi:', '{"options":["学生 だ","学生 な","学生 で","学生 に"],"translation":"Gakusei da","sentence_template":"がくせい です -> [blank]"}'::jsonb, '{"selected":"学生 だ"}'::jsonb, NULL, NULL, 'Nomina kasual afirmatif = だ (gakusei da).', 8, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280007000009', 'b0000026-0000-0000-0000-000000002804', NULL, 'listening', 'listening_choice', 'Ujian Tahap 6 (Soal 9): Dengarkan pendapat seseorang ini:', '{"options":[{"id":"opt_1","text":"Menurut saya sangat bermanfaat/berguna"},{"id":"opt_2","text":"Menurut saya tidak ada gunanya"},{"id":"opt_3","text":"Barang ini sangat mahal"},{"id":"opt_4","text":"Saya tidak mengerti barang ini"}],"audio_text":"とても やくにたつ と おもいます"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'やくにたつ (bermanfaat) と おもいます.', 9, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-280007000010', 'b0000026-0000-0000-0000-000000002804', NULL, 'speaking', 'speaking_repeat', 'Ujian Tahap 6 (Soal 10): Lafalkan kalimat pamungkas Tahap 6 ''明日 は 雨 が 降る と 思います から、傘 を 持って 行きます'':', '{"romaji":"ashita wa ame ga furu to omoimasu kara, kasa o motte ikimasu","audio_text":"明日 は 雨 が 降る と 思います から、傘 を 持って 行きます","display_text":"明日 は 雨 が 降る と 思います から、傘 を 持って 行きます"}'::jsonb, '{"expected_transcript":"明日 は 雨 が 降る と 思います から、傘 を 持って 行きます"}'::jsonb, NULL, NULL, 'Lafalkan kalimat pamungkas Tahap 6 dengan sempurna.', 10, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000290401', 'b0000026-0000-0000-0000-000000002904', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'reading', 'fill_blank', 'Kontras Pemberi-Penerima: saat teman memberi hadiah KEPADA SAYA, verba wajibnya adalah:', '{"options":["くれました","あげました","もらいました","ほしかったです"],"translation":"Di hari ultah, teman memberi saya hadiah.","sentence_template":"たんじょう日に 友だちが プレゼントを [blank]。"}'::jsonb, '{"selected":"くれました"}'::jsonb, NULL, NULL, 'Jika subjek pemberi adalah orang lain dan penerimanya adalah saya, wajib pakai くれます (bukan あげます).', 1, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000290402', 'b0000026-0000-0000-0000-000000002904', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan niat & tujuan kepergian ke kota:', '{"options":[{"id":"opt_1","text":"Pergi ke dept. store untuk membeli oleh-oleh teman."},{"id":"opt_2","text":"Membeli sepatu karena harganya murah."},{"id":"opt_3","text":"Saya ingin minum kopi bersama teman."},{"id":"opt_4","text":"Apakah kamu pernah menerima hadiah?"}],"audio_text":"デパートへ ともだちの おみやげを 買いに 行きます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '[Tempat]へ [Verba-stem]に 行きます menyatakan tujuan pergi.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000290403', 'b0000026-0000-0000-0000-000000002904', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat keinginan aksi: "Tahun depan saya ingin bekerja di Jepang."', '{"romaji":"Rainen Nihon de hatarakitai desu.","tokens":["らいねん","日本","で","はたらきたい","です"],"target_translation":"Tahun depan ingin bekerja di Jepang."}'::jsonb, '["らいねん","日本","で","はたらきたい","です"]'::jsonb, NULL, NULL, '[Akar Verba -masu] + たいです = ingin melakukan aksi.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000290404', 'b0000026-0000-0000-0000-000000002904', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'speaking', 'speaking_repeat', 'Ucapkan tekadmu: "らいねん 日本へ 行きたいです" (Tahun depan ingin pergi ke Jepang):', '{"romaji":"rainen Nihon e ikitai desu","audio_text":"らいねん 日本へ 行きたいです","display_text":"らいねん 日本へ 行きたいです"}'::jsonb, '{"expected_transcript":"らいねん 日本へ 行きたいです"}'::jsonb, NULL, NULL, 'はたらきたい・いきたい memiliki konjugasi mirip Sifat-I.', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-290006000005', 'b0000026-0000-0000-0000-000000002904', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat memberi bantuan ''Saya bantu ya'':', '{"options":["てつだって","てつだいて","てつだう","てつだわない"],"translation":"Tetsudatte","sentence_template":"わたし が [blank] あげます"}'::jsonb, '{"selected":"てつだって"}'::jsonb, NULL, NULL, '～て あげます (membantu melakukan untuk orang lain).', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
