INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000300402', 'b0000026-0000-0000-0000-000000003004', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'listening', 'listening_choice', 'Dengarkan wacana ringkas JLPT N5 lengkap:', '{"options":[{"id":"opt_1","text":"Saya belajar bhs Jepang tiap hari; meski sulit kurasa menyenangkan."},{"id":"opt_2","text":"Saya belum pernah belajar bahasa Jepang."},{"id":"opt_3","text":"Tahun depan saya ingin membeli mobil baru."},{"id":"opt_4","text":"Kemarin saya pergi ke rumah sakit karena demam."}],"audio_text":"わたしは 毎日 日本語を べんきょうしています。むずかしいですが、とても たのしいと 思います。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'Menggabungkan ～ています, kontras が, dan opini ～と思います.', 2, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000300403', 'b0000026-0000-0000-0000-000000003004', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'writing', 'sentence_builder', 'Susun kalimat final readiness N5: "Sebelum pergi ke Jepang, belajar bahasa Jepang."', '{"romaji":"Nihon e iku mae ni, nihongo o benkyou shimasu.","tokens":["日本へ","行く","まえに","、","日本語を","勉強します"],"target_translation":"Sebelum ke Jepang, belajar bahasa Jepang."}'::jsonb, '["日本へ","行く","まえに","、","日本語を","勉強します"]'::jsonb, NULL, NULL, 'Bentuk Kamus 行く wajib dipakai sebelum まえに.', 3, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000026-0000-0000-0000-000000300404', 'b0000026-0000-0000-0000-000000003004', 'de0cdbef-121a-454b-8f8c-5a4484f858d0', 'speaking', 'speaking_repeat', 'Ucapkan perkenalan komprehensif N5: "はじめまして、日本語の 勉強が すきです":', '{"romaji":"hajimemashite, nihongo no benkyou ga suki desu","audio_text":"はじめまして、日本語の 勉強が すきです","display_text":"はじめまして、日本語の 勉強が すきです"}'::jsonb, '{"expected_transcript":"はじめまして、日本語の 勉強が すきです"}'::jsonb, NULL, NULL, 'Siap menaklukkan Ujian Akhir Kesiapan JLPT N5!', 4, '2026-11-21T07:01:51.705598+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-300007000005', 'b0000026-0000-0000-0000-000000003004', NULL, 'reading', 'fill_blank', 'Simulasi Akhir N5 (Soal 5): Kalimat ''Besok tidak perlu datang'' yang tepat adalah:', '{"options":["来なくても いいです","来ないで ください","来なければ なりません","来ては いけません"],"translation":"Konakutemo ii desu","sentence_template":"あした は [blank]"}'::jsonb, '{"selected":"来なくても いいです"}'::jsonb, NULL, NULL, '来なくても いいです = tidak perlu datang.', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-300007000006', 'b0000026-0000-0000-0000-000000003004', NULL, 'listening', 'listening_choice', 'Simulasi Akhir N5 (Soal 6): Dengarkan percakapan rencana perjalanan ini:', '{"options":[{"id":"opt_1","text":"Bulan depan berencana pergi ke Jepang bersama teman"},{"id":"opt_2","text":"Bulan lalu pergi ke Jepang sendirian"},{"id":"opt_3","text":"Bulan depan teman saya datang dari Jepang"},{"id":"opt_4","text":"Tidak jadi pergi ke Jepang"}],"audio_text":"来月 友だち と 日本 へ 行く つもり です"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '来月 友だち と 日本 へ 行く つもり です.', 6, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
