INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260003000001', 'b0000027-0000-0000-0000-000026000003', NULL, 'reading', 'fill_blank', 'Pola untuk menyebutkan beberapa contoh kegiatan secara acak (tidak berurutan waktu) adalah:', '{"options":["たり・たり","て・て","たら・たら","と・と"],"translation":"Tari... tari","sentence_template":"ほん を よん [blank]、テレビ を み [blank] します"}'::jsonb, '{"selected":"たり・たり"}'::jsonb, NULL, NULL, 'Verba bentuk-TA + り + します menyebutkan contoh kegiatan dari sekian banyak kegiatan.', 1, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260003000002', 'b0000027-0000-0000-0000-000026000003', NULL, 'listening', 'listening_choice', 'Dengarkan kegiatan akhir pekan ini:', '{"options":[{"id":"opt_1","text":"Hari Minggu membaca buku, mendengarkan musik, dan lain-lain"},{"id":"opt_2","text":"Hari Minggu hanya membaca buku"},{"id":"opt_3","text":"Hari Minggu bekerja di kantor"},{"id":"opt_4","text":"Hari Minggu tidur seharian"}],"audio_text":"日曜日 は 本 を 読んだり、音楽 を 聞いたり しました"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '本 を 読んだり、音楽 を 聞いたり しました.', 2, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
