INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0000027-0000-0000-0000-260003000005', 'b0000027-0000-0000-0000-000026000003', NULL, 'listening', 'listening_choice', 'Dengarkan rencana liburan ini:', '{"options":[{"id":"opt_1","text":"Ingin main tenis, nonton film, dan lain-lain"},{"id":"opt_2","text":"Sudah main tenis dan nonton film"},{"id":"opt_3","text":"Hanya ingin nonton film"},{"id":"opt_4","text":"Tidak ingin olahraga"}],"audio_text":"テニス を したり、えいが を みたり したい です"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '～たり したい です (Ingin melakukan hal-hal seperti...).', 5, '2026-11-21T07:57:23.645471+00:00') ON CONFLICT DO NOTHING;
